window.MH_TR["\u05e4\u05e8\u05e700_\u05de\u05d1\u05d5\u05d0_\u05d4\u05de\u05e4\u05d4"]={"t":"\u05de\u05d1\u05d5\u05d0: \u05d4\u05de\u05e4\u05d4","l":[[1.0,"\u05db\u05dc \u05d7\u05dc\u05e7 \u05de\u05ea\u05db\u05ea \u05e9\u05d9\u05d5\u05e6\u05d0 \u05de\u05d4\u05de\u05e4\u05e2\u05dc \u05e2\u05d1\u05e8 \u05d3\u05e8\u05da \u05d0\u05e8\u05d5\u05db\u05d4, \u05de\u05d2\u05d5\u05e9\u05d5 \u05d7\u05d5\u05de\u05e8 \u05d2\u05d5\u05dc\u05de\u05d9 \u05d5\u05e2\u05d3 \u05e6\u05d5\u05e8\u05d4 \u05e1\u05d5\u05e4\u05d9\u05ea \u05d1\u05de\u05d9\u05d3\u05d5\u05ea \u05de\u05d3\u05d5\u05d9\u05e7\u05d5\u05ea."],[9.0,"\u05d1\u05d3\u05e8\u05da \u05d4\u05d6\u05d5 \u05d9\u05e9 \u05d4\u05e8\u05d1\u05d4 \u05ea\u05d7\u05e0\u05d5\u05ea: \u05de\u05d7\u05e8\u05d8\u05d4, \u05db\u05e8\u05e1\u05d5\u05de\u05ea, \u05d4\u05e9\u05d7\u05d6\u05d4, \u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d2\u05dd \u05d7\u05d5\u05d8 \u05d0\u05d5 \u05dc\u05d9\u05d9\u05d6\u05e8."],[17.0,"\u05d1\u05e1\u05d3\u05e8\u05d4 \u05d4\u05d6\u05d5 \u05e0\u05db\u05d9\u05e8 \u05db\u05dc \u05ea\u05d4\u05dc\u05d9\u05da \u05dc\u05e2\u05d5\u05de\u05e7: \u05d0\u05d9\u05da \u05d4\u05d5\u05d0 \u05e2\u05d5\u05d1\u05d3, \u05de\u05d4 \u05d4\u05d5\u05d0 \u05d9\u05d5\u05d3\u05e2 \u05dc\u05ea\u05ea, \u05d5\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8 \u05d0\u05d5\u05ea\u05d5."],[24.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d6\u05d4 \u05e0\u05d1\u05e0\u05d4 \u05d0\u05ea \u05d4\u05de\u05e4\u05d4: \u05d0\u05d9\u05dc\u05d5 \u05de\u05e9\u05e4\u05d7\u05d5\u05ea \u05e9\u05dc \u05ea\u05d4\u05dc\u05d9\u05db\u05d9\u05dd \u05d9\u05e9, \u05d5\u05d0\u05d9\u05da \u05d1\u05d5\u05d7\u05e8\u05d9\u05dd \u05d1\u05d9\u05e0\u05d9\u05d4\u05df."],[31.0,"\u05d9\u05e9 \u05e9\u05dc\u05d5\u05e9 \u05d3\u05e8\u05db\u05d9\u05dd \u05e2\u05d9\u05e7\u05e8\u05d9\u05d5\u05ea \u05dc\u05ea\u05ea \u05e6\u05d5\u05e8\u05d4 \u05dc\u05d7\u05dc\u05e7."],[35.0,"\u05d0\u05e4\u05e9\u05e8 \u05dc\u05e2\u05e6\u05d1 \u05d0\u05d5\u05ea\u05d5: \u05dc\u05d9\u05e6\u05d5\u05e7, \u05dc\u05d7\u05e9\u05dc, \u05dc\u05db\u05d5\u05e4\u05e3. \u05d4\u05d7\u05d5\u05de\u05e8 \u05de\u05e9\u05e0\u05d4 \u05e6\u05d5\u05e8\u05d4, \u05d0\u05d1\u05dc \u05db\u05de\u05e2\u05d8 \u05dc\u05d0 \u05de\u05d5\u05e1\u05e8\u05d9\u05dd \u05de\u05de\u05e0\u05d5."],[43.0,"\u05d0\u05e4\u05e9\u05e8 \u05dc\u05d4\u05d5\u05e1\u05d9\u05e3 \u05d7\u05d5\u05de\u05e8, \u05e9\u05db\u05d1\u05d4 \u05d0\u05d7\u05e8\u05d9 \u05e9\u05db\u05d1\u05d4. \u05d6\u05d4 \u05d9\u05d9\u05e6\u05d5\u05e8 \u05ea\u05d5\u05e1\u05e4\u05ea\u05d9."],[48.0,"\u05d5\u05d0\u05e4\u05e9\u05e8 \u05dc\u05d4\u05e1\u05d9\u05e8 \u05d7\u05d5\u05de\u05e8 \u05de\u05d2\u05d5\u05e9 \u05d2\u05d3\u05d5\u05dc, \u05e2\u05d3 \u05e9\u05e0\u05e9\u05d0\u05e8\u05ea \u05d4\u05e6\u05d5\u05e8\u05d4 \u05e9\u05e8\u05e6\u05d9\u05e0\u05d5. \u05d6\u05d4 \u05e2\u05d9\u05d1\u05d5\u05d3."],[54.0,"\u05d4\u05e1\u05d3\u05e8\u05d4 \u05de\u05db\u05e1\u05d4 \u05d0\u05ea \u05e9\u05dc\u05d5\u05e9 \u05d4\u05d3\u05e8\u05db\u05d9\u05dd."],[57.0,"\u05e0\u05ea\u05d7\u05d9\u05dc \u05d1\u05d0\u05d9\u05da \u05e0\u05d5\u05e6\u05e8 \u05d7\u05d5\u05de\u05e8 \u05d4\u05d2\u05dc\u05dd: \u05d1\u05d9\u05e6\u05d9\u05e7\u05d4, \u05d1\u05d7\u05d9\u05e9\u05d5\u05dc \u05d5\u05d1\u05e9\u05d9\u05d7\u05d5\u05dc."],[62.0,"\u05de\u05e9\u05dd \u05e0\u05e2\u05d1\u05d5\u05e8 \u05dc\u05e2\u05d9\u05d1\u05d5\u05d3 \u05d4\u05e9\u05d1\u05d1\u05d9, \u05dc\u05e2\u05d9\u05d1\u05d5\u05d3 \u05e4\u05d7, \u05d5\u05dc\u05ea\u05d4\u05dc\u05d9\u05db\u05d9\u05dd \u05d4\u05dc\u05d0 \u05e7\u05d5\u05e0\u05d1\u05e0\u05e6\u05d9\u05d5\u05e0\u05dc\u05d9\u05d9\u05dd."],[68.0,"\u05d5\u05d1\u05e1\u05d5\u05e3, \u05e0\u05d2\u05d9\u05e2 \u05dc\u05d9\u05d9\u05e6\u05d5\u05e8 \u05d4\u05ea\u05d5\u05e1\u05e4\u05ea\u05d9."],[71.0,"\u05d2\u05dd \u05d1\u05ea\u05d5\u05da \u05d4\u05e1\u05e8\u05ea \u05d4\u05d7\u05d5\u05de\u05e8\u05d9\u05e9 \u05db\u05de\u05d4 \u05de\u05e9\u05e4\u05d7\u05d5\u05ea."],[74.0,"\u05d1\u05e2\u05d9\u05d1\u05d5\u05d3 \u05e9\u05d1\u05d1\u05d9, \u05db\u05dc\u05d9 \u05e2\u05dd \u05dc\u05d4\u05d1 \u05d7\u05d3 \u05d5\u05d2\u05d0\u05d5\u05de\u05d8\u05e8\u05d9\u05d4 \u05de\u05d5\u05d2\u05d3\u05e8\u05ea \u05d2\u05d5\u05d6\u05e8 \u05de\u05d4\u05d7\u05d5\u05de\u05e8 \u05e9\u05d1\u05d1."],[81.0,"\u05d1\u05e2\u05d9\u05d1\u05d5\u05d3 \u05e9\u05d5\u05d7\u05e7, \u05d0\u05dc\u05e4\u05d9 \u05d2\u05e8\u05d2\u05e8\u05d9\u05dd \u05e7\u05e9\u05d9\u05dd \u05d5\u05e7\u05d8\u05e0\u05d9\u05dd \u05d2\u05d5\u05e8\u05d3\u05d9\u05dd \u05db\u05dc \u05d0\u05d7\u05d3 \u05e9\u05d1\u05d1\u05d6\u05e2\u05d9\u05e8."],[87.0,"\u05d7\u05d5\u05ea\u05da: \u05d1\u05e0\u05d9\u05e6\u05d5\u05e5 \u05d7\u05e9\u05de\u05dc\u05d9, \u05d1\u05e7\u05e8\u05df \u05d0\u05d5\u05e8, \u05d1\u05d6\u05e8\u05dd \u05de\u05d9\u05dd \u05d0\u05d5 \u05d1\u05e7\u05e9\u05d5\u05ea \u05e4\u05dc\u05d6\u05de\u05d4."],[97.0,"\u05d1\u05db\u05dc \u05e2\u05d9\u05d1\u05d5\u05d3 \u05e9\u05d1\u05d1\u05d9 \u05d9\u05e9 \u05e9\u05ea\u05d9 \u05ea\u05e0\u05d5\u05e2\u05d5\u05ea."],[100.0,"\u05d4\u05ea\u05e0\u05d5\u05e2\u05d4 \u05d4\u05e8\u05d0\u05e9\u05d9\u05ea \u05d9\u05d5\u05e6\u05e8\u05ea \u05d0\u05ea \u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05d4\u05d7\u05d9\u05ea\u05d5\u05df."],[103.0,"\u05ea\u05e0\u05d5\u05e2\u05ea \u05d4\u05d4\u05d6\u05e0\u05d4 \u05de\u05e7\u05d3\u05de\u05ea \u05d0\u05ea \u05d4\u05db\u05dc\u05d9 \u05dc\u05d7\u05d5\u05de\u05e8 \u05d7\u05d3\u05e2\u05d5."],[107.0,"\u05d1\u05de\u05d7\u05e8\u05d8\u05d4 \u05d4\u05d7\u05dc\u05e7 \u05de\u05e1\u05ea\u05d5\u05d1\u05d1, \u05d5\u05d4\u05db\u05dc\u05d9 \u05e0\u05e2 \u05dc\u05d0\u05d5\u05e8\u05db\u05d5."],[111.0,"\u05d1\u05db\u05e8\u05e1\u05d5\u05de\u05ea \u05d4\u05db\u05dc\u05d9 \u05de\u05e1\u05ea\u05d5\u05d1\u05d1, \u05d5\u05d4\u05d7\u05dc\u05e7 \u05d0\u05d5 \u05d4\u05db\u05dc\u05d9 \u05e0\u05e2\u05d9\u05dd \u05d1\u05e6\u05d9\u05e8\u05d9\u05dd."],[117.0,"\u05e9\u05dc\u05d5\u05e9\u05d4 \u05e4\u05e8\u05de\u05d8\u05e8\u05d9\u05dd \u05d9\u05dc\u05d5\u05d5 \u05d0\u05d5\u05ea\u05e0\u05d5 \u05dc\u05d0\u05d5\u05e8\u05da \u05db\u05dc \u05d4\u05e1\u05d3\u05e8\u05d4."],[121.0,"\u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05d4\u05d7\u05d9\u05ea\u05d5\u05da, \u05e1\u05e5, \u05d4\u05d9\u05d0 \u05d4\u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05e9\u05d1\u05d4 \u05d4\u05dc\u05d4\u05d1 \u05e2\u05d5\u05d1\u05e8 \u05e2\u05dc \u05e4\u05e0\u05d9 \u05d4\u05d7\u05d5\u05de\u05e8, \u05d1\u05de\u05d8\u05e8\u05d9\u05dd \u05dc\u05d3\u05e7\u05d4."],[128.0,"\u05d4\u05d4\u05d6\u05e0\u05d4 \u05d4\u05d9\u05d0 \u05db\u05de\u05d4 \u05d4\u05db\u05dc\u05d9 \u05de\u05ea\u05e7\u05d3\u05dd \u05d1\u05db\u05dc \u05e1\u05d9\u05d1\u05d5\u05d1 \u05d0\u05d5 \u05d1\u05db\u05dc \u05e9\u05df."],[132.0,"\u05e2\u05d5\u05de\u05e7 \u05d4\u05d7\u05d9\u05ea\u05d5\u05da, \u05e74, \u05d4\u05d5\u05d0 \u05db\u05de\u05d4 \u05d7\u05d5\u05de\u05e8 \u05de\u05d5\u05e8\u05d9\u05d3\u05d9\u05dd \u05d1\u05de\u05e2\u05d1\u05e8 \u05d0\u05d7\u05d3."],[137.0,"\u05d4\u05e9\u05d1\u05d1 \u05e2\u05e6\u05de\u05d5 \u05de\u05dc\u05de\u05d3 \u05d4\u05e8\u05d1\u05d4: \u05e6\u05d1\u05e2, \u05e6\u05d5\u05e8\u05d4 \u05d5\u05d0\u05d5\u05e8\u05da \u05d4\u05e9\u05d1\u05d1 \u05de\u05e2\u05d9\u05d3\u05d9\u05dd \u05d0\u05dd \u05d4\u05e4\u05e8\u05de\u05d8\u05e8\u05d9\u05dd \u05e0\u05db\u05d5\u05e0\u05d9\u05dd."],[145.0,"\u05d0\u05d1\u05df \u05d4\u05e9\u05d7\u05d6\u05d4 \u05d1\u05e0\u05d5\u05d9\u05d4 \u05de\u05d2\u05e8\u05d2\u05e8\u05d9\u05dd \u05e7\u05e9\u05d9\u05dd \u05de\u05d0\u05d5\u05d3, \u05e7\u05e9\u05d5\u05e8\u05d9\u05dd \u05d9\u05d7\u05d3 \u05d1\u05d7\u05d5\u05de\u05e8 \u05de\u05e7\u05e9\u05e8."],[150.0,"\u05db\u05dc \u05d2\u05e8\u05d2\u05e8 \u05de\u05d5\u05e8\u05d9\u05d3 \u05de\u05e2\u05d8 \u05de\u05d0\u05d5\u05d3 \u05d7\u05d5\u05de\u05e8. \u05dc\u05db\u05df \u05d4\u05e9\u05d7\u05d6\u05d4 \u05d0\u05d9\u05d8\u05d9\u05ea \u05d9\u05d7\u05e1\u05d9\u05ea, \u05d0\u05d1\u05dc \u05de\u05d3\u05d5\u05d9\u05e7\u05ea \u05de\u05d0\u05d5\u05d3."],[157.0,"\u05d4\u05e9\u05d7\u05d6\u05d4 \u05de\u05ea\u05d0\u05d9\u05de\u05d4 \u05d2\u05dd \u05dc\u05d7\u05d5\u05de\u05e8 \u05de\u05d5\u05e7\u05e9\u05d5\u05d4, \u05e9\u05db\u05dc\u05d9 \u05e8\u05d2\u05d9\u05dc \u05de\u05ea\u05e7\u05e9\u05d4 \u05dc\u05d7\u05ea\u05d5\u05da."],[162.0,"\u05d4\u05d5\u05e0\u05d9\u05e0\u05d2 \u05d5\u05dc\u05d0\u05e4\u05d9\u05e0\u05d2 \u05d4\u05dd \u05d4\u05e9\u05dc\u05d1 \u05d4\u05d1\u05d0, \u05dc\u05d2\u05d9\u05de\u05d5\u05e8 \u05d5\u05dc\u05d3\u05d9\u05d5\u05e7 \u05d2\u05d1\u05d5\u05d4\u05d9\u05dd \u05e2\u05d5\u05d3 \u05d9\u05d5\u05ea\u05e8."],[168.0,"\u05d1\u05ea\u05d4\u05dc\u05d9\u05da \u05d5\u05d0\u05e1\u05dd, \u05e0\u05d9\u05e6\u05d5\u05e6\u05d5\u05ea \u05d7\u05e9\u05de\u05dc\u05d9\u05d9\u05dd \u05de\u05de\u05d9\u05e1\u05d9\u05dd \u05d7\u05dc\u05e7\u05d9\u05e7\u05d9\u05dd \u05d6\u05e2\u05d9\u05e8\u05d9\u05dd \u05de\u05d4\u05d7\u05d5\u05de\u05e8."],[173.0,"\u05d4\u05db\u05dc\u05d9 \u05dc\u05d0 \u05e0\u05d5\u05d2\u05e2 \u05d1\u05d7\u05dc\u05e7, \u05d5\u05dc\u05db\u05df \u05e7\u05e9\u05d9\u05d5\u05ea \u05d4\u05d7\u05d5\u05de\u05e8 \u05db\u05de\u05e2\u05d8 \u05dc\u05d0 \u05de\u05e9\u05e0\u05d4."],[178.0,"\u05d4\u05ea\u05e0\u05d0\u05d9 \u05d4\u05d5\u05d0 \u05e9\u05d4\u05d7\u05d5\u05de\u05e8 \u05de\u05d5\u05dc\u05d9\u05da \u05d7\u05e9\u05de\u05dc."],[181.0,"\u05dc\u05d9\u05d9\u05d6\u05e8 \u05de\u05de\u05d9\u05e1 \u05d0\u05ea \u05d4\u05d7\u05d5\u05de\u05e8 \u05d1\u05e7\u05e8\u05df \u05d0\u05d5\u05e8 \u05de\u05de\u05d5\u05e7\u05d3\u05ea."],[185.0,"\u05e1\u05d9\u05dc\u05d5\u05df \u05de\u05d9\u05dd \u05e2\u05dd \u05d2\u05e8\u05d2\u05e8\u05d9\u05dd \u05e9\u05d5\u05d7\u05e7\u05d9\u05dd \u05d7\u05d5\u05ea\u05da \u05db\u05de\u05e2\u05d8 \u05db\u05dc \u05d7\u05d5\u05de\u05e8, \u05d1\u05dc\u05d9 \u05d0\u05d6\u05d5\u05e8 \u05de\u05d5\u05e9\u05e4\u05e2 \u05d7\u05d5\u05dd."],[190.0,"\u05e4\u05dc\u05d6\u05de\u05d4 \u05d7\u05d5\u05ea\u05db\u05ea \u05de\u05ea\u05db\u05d5\u05ea \u05de\u05d5\u05dc\u05d9\u05db\u05d5\u05ea \u05de\u05d4\u05e8, \u05d0\u05d1\u05dc \u05d1\u05d3\u05d9\u05d5\u05e7 \u05e0\u05de\u05d5\u05da \u05d9\u05d5\u05ea\u05e8."],[196.0,"\u05d1\u05d7\u05d9\u05e8\u05ea \u05ea\u05d4\u05dc\u05d9\u05da \u05de\u05ea\u05d7\u05d9\u05dc\u05d4 \u05d1\u05d7\u05de\u05e9\u05d5 \u05e9\u05d0\u05dc\u05d5\u05ea."],[199.0,"\u05de\u05d4 \u05d4\u05e6\u05d5\u05e8\u05d4? \u05d7\u05dc\u05e7 \u05e1\u05d9\u05d1\u05d5\u05d1\u05d9 \u05de\u05ea\u05d7\u05d9\u05dc \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1\u05de\u05d7\u05e8\u05d8\u05d4, \u05d5\u05d7\u05dc\u05e7 \u05e4\u05e8\u05d9\u05d6\u05de\u05d8\u05d9 \u05d1\u05db\u05e8\u05e1\u05d5\u05de\u05ea."],[207.0,"\u05de\u05d4 \u05d4\u05d7\u05d5\u05de\u05e8, \u05d5\u05de\u05d4 \u05d4\u05e7\u05e9\u05d9\u05d5\u05ea \u05e9\u05dc\u05d5?"],[209.0,"\u05d0\u05d9\u05d6\u05d4 \u05d3\u05d9\u05d5\u05e7 \u05d5\u05d2\u05d9\u05de\u05d5\u05e8 \u05e0\u05d3\u05e8\u05e9\u05d9\u05dd?"],[212.0,"\u05d7\u05e8\u05d9\u05d8\u05d4 \u05d5\u05db\u05e8\u05e1\u05d5\u05dd \u05e0\u05d5\u05ea\u05e0\u05d9\u05dd \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc 7\u05d3\u05d5 \u05e2\u05d3 9\u05d6\u05d5, \u05e2\u05dd \u05d7\u05e1\u05e4\u05d5\u05e1 8 \u05e9\u05dc 0.8 \u05e2\u05d3 3.2 \u05de\u05d9\u05e7\u05e8\u05d5\u05df."],[222.0,"\u05d4\u05e9\u05d7\u05d6\u05d4 \u05de\u05d2\u05d9\u05e2\u05d4 \u05dc\u05e8\u05de\u05d4 \u05e9\u05dc \u2026 \u05e2\u05d3 6 \u05d3\u05d5, \u05d5\u05dc\u05d7\u05e1\u05e4\u05d5\u05e1 Ra \u05e9\u05dc 2 \u05e2\u05d3 0.8 \u05de\u05d9\u05e7\u05e8\u05d5\u05df."],[232.0,"\u05d4\u05d5\u05e0\u05d9\u05e0\u05d2 \u05d5\u05dc\u05d0\u05e4\u05d9\u05e0\u05d2 \u05d9\u05d5\u05e8\u05d3\u05d9\u05dd \u05de\u05ea\u05d7\u05ea \u05dc\u05d6\u05d4."],[235.0,"\u05de\u05d4 \u05d4\u05db\u05de\u05d5\u05ea? \u05d7\u05dc\u05e7 | \u05d1\u05d5\u05d3\u05d3 \u05d5\u05e1\u05d3\u05e8\u05d4 \u05e9\u05dc \u05d0\u05dc\u05e4\u05dc\u05d9\u05dd \u05dc\u05d0 \u05d9\u05d9\u05d5\u05e6\u05e8\u05d5 \u05d1\u05d0\u05d5\u05ea\u05d4 \u05d3\u05d5 | ."],[240.0,"\u05d1\u05e1\u05d3\u05e8\u05d5\u05ea \u05d2\u05d3\u05d5\u05dc\u05d5\u05ea, \u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05de\u05e9\u05ea\u05dc\u05dd \u05dc\u05d7\u05e9\u05dc \u05d0\u05d5 \u05dc\u05d9\u05e6\u05d5\u05e7 \u05e7\u05e8\u05d5\u05d1 \u05dc\u05e6\u05d5\u05e8\u05d4 \u05d4\u05e1\u05d5\u05e4\u05d9\u05ea, \u05d5\u05db\u05da \u05dc\u05d7\u05e1\u05d5\u05da \u05d1\u05e2\u05d9\u05d1\u05d5\u05d3."],[247.0,"\u05d5\u05de\u05d4 \u05d4\u05e2\u05dc\u05d5\u05ea \u05d4\u05db\u05d5\u05dc\u05dc\u05ea, \u05d5\u05dc\u05d0 \u05e8\u05e7 \u05d6\u05de\u05df \u05d4\u05de\u05db\u05d5\u05e0\u05d4."],[251.0,"\u05e0\u05d9\u05e7\u05d7 \u05e4\u05d9\u05df \u05de\u05e4\u05dc\u05d3\u05d4, \u05e9\u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05d9\u05d5\u05ea \u05de\u05d5\u05e7\u05e9\u05d4, \u05e2\u05dd \u05e7\u05d5\u05d8\u05e8 \u05de\u05d3\u05d5\u05d9\u05e7."],[256.0,"\u05d7\u05d5\u05e8\u05d8\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5 \u05db\u05e9\u05d4\u05d7\u05d5\u05de\u05e8 \u05e2\u05d5\u05d3 \u05e8\u05da, \u05d5\u05de\u05e9\u05d0\u05d9\u05e8\u05d9\u05dd \u05ea\u05d5\u05e1\u05e4\u05ea \u05e7\u05d8\u05e0\u05d4 \u05dc\u05e2\u05d9\u05d1\u05d5\u05d3."],[261.0,"\u05d0\u05d7\u05e8 \u05db\u05da \u05d4\u05d5\u05d0 \u05e2\u05d5\u05d1\u05e8 \u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd."],[263.0,"\u05d5\u05d1\u05e1\u05d5\u05e3 \u05de\u05e9\u05d7\u05d9\u05d6\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5 \u05dc\u05de\u05d9\u05d3\u05d4 \u05d4\u05e1\u05d5\u05e4\u05d9\u05ea."],[266.0,"\u05db\u05da \u05e8\u05d5\u05d1 \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05e2\u05d5\u05d1\u05e8\u05d9\u05dd \u05e9\u05e8\u05e9\u05e8\u05ea \u05e9\u05dc \u05ea\u05d4\u05dc\u05d9\u05db\u05d9\u05dd, \u05d5\u05dc\u05d0 \u05ea\u05d4\u05dc\u05d9\u05da \u05d0\u05d7\u05d3."],[272.0,"\u05d1\u05db\u05dc \u05e4\u05e8\u05e7 \u05e0\u05e9\u05d0\u05dc \u05d2\u05dd \u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8 \u05d0\u05ea \u05d4\u05ea\u05d4\u05dc\u05d9\u05da."],[275.0,"\u05d6\u05de\u05df \u05d4\u05e7\u05de\u05d4, \u05d6\u05de\u05df \u05de\u05d7\u05d6\u05d5\u05e8, \u05d1\u05dc\u05d0\u05d9 \u05db\u05dc\u05d9\u05dd, \u05d5\u05e4\u05e2\u05d5\u05dc\u05d5\u05ea \u05e0\u05d5\u05e1\u05e4\u05d5\u05ea \u05db\u05de\u05d5 \u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd \u05d0\u05d5 \u05de\u05e2\u05d1\u05e8 \u05d1\u05d9\u05df \u05de\u05db\u05d5\u05e0\u05d5\u05ea."],[283.0,"\u05d5\u05db\u05dc\u05dc \u05d0\u05d7\u05d3 \u05d7\u05e9\u05d5\u05d1: \u05db\u05db\u05dc \u05e9\u05d4\u05d8\u05d5\u05dc\u05e8\u05e0\u05e1 \u05d4\u05d3\u05d5\u05e7 \u05d9\u05d5\u05ea\u05e8, \u05d4\u05ea\u05d4\u05dc\u05d9\u05da \u05d0\u05e8\u05d5\u05da \u05d5\u05d9\u05e7\u05e8 \u05d9\u05d5\u05ea\u05e8."],[290.0,"\u05d6\u05d5 \u05d4\u05de\u05e4\u05d4 \u05e9\u05dc \u05d4\u05e1\u05d3\u05e8\u05d4: 25 \u05e4\u05e8\u05e7\u05d9\u05dd \u05d1\u05e9\u05e9 \u05e7\u05d1\u05d5\u05e6\u05d5\u05ea."],[295.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0 \u05e0\u05ea\u05d7\u05d9\u05dc \u05de\u05d4\u05d4\u05ea\u05d7\u05dc\u05d4: \u05d9\u05e6\u05d9\u05e7\u05d4."]]};
window.MH_TR["\u05e4\u05e8\u05e701_\u05d9\u05e6\u05d9\u05e7\u05d4"]={"t":"\u05d9\u05e6\u05d9\u05e7\u05d4","l":[[1.0,"\u05d9\u05e6\u05d9\u05e7\u05d4 \u05d4\u05d9\u05d0 \u05d0\u05d7\u05ea \u05d4\u05d3\u05e8\u05db\u05d9\u05dd \u05d4\u05e2\u05ea\u05d9\u05e7\u05d5\u05ea \u05d1\u05d9\u05d5\u05ea\u05e8 \u05dc\u05d9\u05d9\u05e6\u05e8 \u05d7\u05dc\u05e7\u05d9 \u05de\u05ea\u05db\u05ea, \u05d5\u05d4\u05d9\u05d0 \u05e2\u05d3\u05d9\u05d9\u05df \u05de\u05d4\u05e0\u05e4\u05d5\u05e6\u05d5\u05ea \u05d1\u05d9\u05d5\u05ea\u05e8."],[8.0,"\u05d1\u05dc\u05d5\u05e7 \u05de\u05e0\u05d5\u05e2, \u05d1\u05d9\u05ea \u05de\u05e9\u05d0\u05d1\u05d4, \u05d2\u05d5\u05e3 \u05e9\u05dc \u05de\u05d2\u05d5\u05e3 \u05d5\u05dc\u05d4\u05d1 \u05d8\u05d5\u05e8\u05d1\u05d9\u05e0\u05d4 \u05de\u05ea\u05d7\u05d9\u05dc\u05d9\u05dd \u05db\u05d5\u05dc\u05dd \u05db\u05d9\u05e6\u05d9\u05e7\u05d4."],[14.0,"\u05d4\u05e8\u05e2\u05d9\u05d5\u05df \u05e4\u05e9\u05d5\u05d8: \u05de\u05de\u05d9\u05e1\u05d9\u05dd \u05de\u05ea\u05db\u05ea, \u05d9\u05d5\u05e6\u05e7\u05d9\u05dd \u05d0\u05d5\u05ea\u05d4 \u05dc\u05d7\u05dc\u05dc \u05d1\u05e6\u05d5\u05e8\u05ea \u05d4\u05d7\u05dc\u05e7, \u05d5\u05de\u05d7\u05db\u05d9\u05dd \u05e9\u05ea\u05ea\u05de\u05e6\u05e7."],[22.0,"\u05d0\u05d1\u05dc \u05db\u05d3\u05d9 \u05dc\u05e7\u05d1\u05dc \u05d7\u05dc\u05e7 \u05ea\u05e7\u05d9\u05df, \u05e6\u05e8\u05d9\u05da \u05dc\u05e9\u05dc\u05d5\u05d8 \u05d1\u05d4\u05e8\u05d1\u05d4 \u05e4\u05e8\u05d8\u05d9\u05dd."],[26.0,"\u05d1\u05db\u05dc \u05d9\u05e6\u05d9\u05e7\u05d4 \u05d9\u05e9 \u05ea\u05d1\u05e0\u05d9\u05ea, \u05d5\u05d1\u05ea\u05d5\u05db\u05d4 \u05d7\u05dc\u05dc \u05d1\u05e6\u05d5\u05e8\u05ea \u05d4\u05d7\u05dc\u05e7."],[31.0,"\u05d0\u05ea \u05d4\u05d7\u05dc\u05dc \u05d9\u05d5\u05e6\u05e8\u05d9\u05dd \u05d1\u05e2\u05d6\u05e8\u05ea \u05d3\u05d2\u05dd, \u05d4\u05e2\u05ea\u05e7 \u05e9\u05dc \u05d4\u05d7\u05dc\u05e7, \u05de\u05e2\u05e5, \u05de\u05e4\u05dc\u05e1\u05d8\u05d9\u05e7 \u05d0\u05d5 \u05de\u05de\u05ea\u05db\u05ea."],[38.0,"\u05d7\u05dc\u05dc\u05d9\u05dd \u05e4\u05e0\u05d9\u05de\u05d9\u05d9\u05dd, \u05db\u05de\u05d5 \u05d7\u05d5\u05e8 \u05d0\u05d5 \u05ea\u05e2\u05dc\u05d4, \u05d9\u05d5\u05e6\u05e8\u05d9\u05dd \u05d1\u05e2\u05d6\u05e8\u05ea \u05dc\u05d9\u05d1\u05d4 \u05e9\u05de\u05d5\u05e0\u05d7\u05ea \u05d1\u05ea\u05d5\u05da \u05d4\u05ea\u05d1\u05e0\u05d9\u05ea."],[45.0,"\u05d4\u05ea\u05d1\u05e0\u05d9\u05ea \u05d1\u05e0\u05d5\u05d9\u05d4 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05de\u05e9\u05e0\u05d9 \u05d7\u05e6\u05d0\u05d9\u05dd, \u05d5\u05d4\u05de\u05d9\u05e9\u05d5\u05e8 \u05e9\u05d1\u05d9\u05e0\u05d9\u05d4\u05dd \u05e0\u05e7\u05e8\u05d0 \u05e7\u05d5 \u05d4\u05d7\u05dc\u05d5\u05e7\u05d4."],[51.0,"\u05d4\u05de\u05ea\u05db\u05ea \u05e0\u05db\u05e0\u05e1\u05ea \u05d3\u05e8\u05da \u05de\u05e2\u05e8\u05db\u05ea \u05d4\u05d6\u05e0\u05d4: \u05de\u05e9\u05e4\u05da, \u05ea\u05e2\u05dc\u05d5\u05ea, \u05d5\u05e4\u05ea\u05d7\u05d9 \u05db\u05e0\u05d9\u05e1\u05d4 \u05dc\u05d7\u05dc\u05dc."],[57.0,"\u05d5\u05d9\u05e9 \u05d2\u05dd \u05de\u05d6\u05d9\u05df: \u05de\u05d0\u05d2\u05e8 \u05e9\u05dc \u05de\u05ea\u05db\u05ea \u05e0\u05d5\u05d6\u05dc\u05d9\u05ea, \u05e9\u05de\u05de\u05e9\u05d9\u05da \u05dc\u05d4\u05d6\u05d9\u05df \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7 \u05d1\u05d6\u05de\u05df \u05e9\u05d4\u05d5\u05d0 \u05de\u05ea\u05de\u05e6\u05e7."],[64.0,"\u05de\u05ea\u05db\u05ea \u05de\u05ea\u05db\u05d5\u05d5\u05e6\u05ea \u05d1\u05e9\u05dc\u05d5\u05e9\u05d4 \u05e9\u05dc\u05d1\u05d9\u05dd."],[67.0,"\u05db\u05e9\u05d4\u05e0\u05d5\u05d6\u05dc \u05de\u05ea\u05e7\u05e8\u05e8, \u05db\u05e9\u05d4\u05d5\u05d0 \u05d4\u05d5\u05e4\u05da \u05dc\u05de\u05d5\u05e6\u05e7, \u05d5\u05db\u05e9\u05d4\u05de\u05d5\u05e6\u05e7 \u05de\u05de\u05e9\u05d9\u05da \u05dc\u05d4\u05ea\u05e7\u05e8\u05e8 \u05e2\u05d3 \u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05d4\u05d7\u05d3\u05e8."],[74.0,"\u05d4\u05d4\u05ea\u05db\u05d5\u05d5\u05e6\u05d5\u05ea \u05d1\u05d6\u05de\u05df \u05d4\u05d4\u05ea\u05de\u05e6\u05e7\u05d5\u05ea \u05d4\u05d9\u05d0 \u05d4\u05de\u05e1\u05d5\u05db\u05e0\u05ea: \u05d0\u05dd \u05d0\u05d9\u05df \u05de\u05d0\u05d9\u05e4\u05d4 \u05dc\u05d4\u05e9\u05dc\u05d9\u05dd \u05d7\u05d5\u05de\u05e8, \u05e0\u05d5\u05e6\u05e8 \u05d7\u05dc\u05dc \u05d1\u05ea\u05d5\u05da \u05d4\u05d7\u05dc\u05e7."],[82.0,"\u05dc\u05db\u05df \u05d4\u05de\u05d6\u05d9\u05df \u05d7\u05d9\u05d9\u05d1 \u05dc\u05d4\u05ea\u05de\u05e6\u05e7 \u05d0\u05d7\u05e8\u05d5\u05df, \u05db\u05d3\u05d9 \u05e9\u05d4\u05de\u05ea\u05db\u05ea \u05ea\u05d6\u05e8\u05d5\u05dd \u05de\u05de\u05e0\u05d5 \u05d0\u05dc \u05d4\u05d7\u05dc\u05e7 \u05e2\u05d3 \u05d4\u05e1\u05d5\u05e3."],[89.0,"\u05d4\u05d4\u05ea\u05db\u05d5\u05d5\u05e6\u05d5\u05ea \u05d1\u05de\u05e6\u05d1 \u05de\u05d5\u05e6\u05e7 \u05de\u05e2\u05d5\u05e0\u05d4 \u05d0\u05ea \u05d4\u05de\u05d9\u05d3\u05d5\u05ea, \u05d5\u05dc\u05db\u05df \u05d4\u05d3\u05d2\u05dd \u05d2\u05d3\u05d5\u05dc \u05de\u05d4\u05d7\u05dc\u05e7."],[95.0,"\u05d1\u05d1\u05e8\u05d6\u05dc \u05d9\u05e6\u05d9\u05e7\u05d4 \u05d0\u05e4\u05d5\u05e8 \u05d1\u05e2\u05e8\u05da 1%, \u05d1\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05d1\u05e2\u05e8\u05da 1.3%, \u05d5\u05d1\u05e4\u05dc\u05d3\u05d4 \u05d1\u05e2\u05e8\u05da 2%."],[105.0,"\u05d7\u05dc\u05e7 \u05e9\u05de\u05d9\u05d5\u05e2\u05d3 \u05dc\u05d9\u05e6\u05d9\u05e7\u05d4 \u05de\u05ea\u05d5\u05db\u05e0\u05df \u05d0\u05d7\u05e8\u05ea \u05de\u05d7\u05dc\u05e7 \u05e9\u05de\u05e2\u05d5\u05d1\u05d3 \u05de\u05d2\u05d5\u05e9."],[110.0,"\u05d3\u05e4\u05e0\u05d5\u05ea \u05e6\u05e8\u05d9\u05db\u05d5\u05ea \u05d6\u05d5\u05d5\u05d9\u05ea \u05e9\u05dc\u05d9\u05e4\u05d4, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d0\u05d7\u05ea \u05e2\u05d3 \u05e9\u05dc\u05d5\u05e9 \u05de\u05e2\u05dc\u05d5\u05ea, \u05db\u05d3\u05d9 \u05e9\u05d0\u05e4\u05e9\u05e8 \u05d9\u05d4\u05d9\u05d4 \u05dc\u05d4\u05d5\u05e6\u05d9\u05d0 \u05d0\u05ea \u05d4\u05d3\u05d2\u05dd."],[116.0,"\u05e2\u05d5\u05d1\u05d9 \u05d3\u05d5\u05e4\u05df \u05d0\u05d7\u05d9\u05d3 \u05db\u05db\u05dc \u05d4\u05d0\u05e4\u05e9\u05e8: \u05d0\u05d6\u05d5\u05e8 \u05e2\u05d1\u05d4 \u05de\u05ea\u05de\u05e6\u05e7 \u05d0\u05d7\u05e8\u05d5\u05df, \u05d5\u05e9\u05dd \u05e0\u05d5\u05d8\u05d9\u05dd \u05dc\u05d4\u05d9\u05d5\u05d5\u05e6\u05e8 \u05d7\u05dc\u05dc\u05d9\u05dd."],[123.0,"\u05e4\u05d9\u05e0\u05d5\u05ea \u05d7\u05d3\u05d5\u05ea \u05de\u05d5\u05d7\u05dc\u05e4\u05d5\u05ea \u05d1\u05e8\u05d3\u05d9\u05d5\u05e1\u05d9\u05dd, \u05db\u05d9 \u05e4\u05d9\u05e0\u05d4 \u05d7\u05d3\u05d4 \u05de\u05e8\u05db\u05d6\u05ea \u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05d5\u05e2\u05dc\u05d5\u05dc\u05d4 \u05dc\u05d4\u05d9\u05e1\u05d3\u05e7 \u05d1\u05d4\u05ea\u05e7\u05e8\u05e8\u05d5\u05ea."],[130.0,"\u05d5\u05d1\u05db\u05dc \u05de\u05e9\u05d8\u05d7 \u05e9\u05d9\u05e2\u05d5\u05d1\u05d3 \u05d0\u05d7\u05e8 \u05db\u05dc\u05da, \u05de\u05e9\u05d0\u05d9\u05e8\u05d9\u05dd \u05ea\u05d5\u05e1\u05e4\u05ea \u05e2\u05d9\u05d1\u05d5\u05d3: \u05db\u05de\u05d4 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8\u05d9\u05dd \u05e9\u05dc \u05d7\u05d5\u05de\u05e8 \u05de\u05e2\u05dc \u05d4\u05de\u05d9\u05d3\u05d4 \u05d4\u05e1\u05d5\u05e4\u05d9\u05ea."],[138.0,"\u05d4\u05e9\u05d9\u05d8\u05d4 \u05d4\u05e0\u05e4\u05d5\u05e6\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05d4\u05d9\u05d0 \u05d9\u05e6\u05d9\u05e7\u05d4 \u05d1\u05d7\u05d5\u05dc."],[142.0,"\u05d3\u05d5\u05d7\u05e1\u05d9\u05dd \u05d7\u05d5\u05dc \u05e2\u05dd \u05d7\u05d5\u05de\u05e8 \u05de\u05e7\u05e9\u05e8 \u05e1\u05d1\u05d9\u05d1 \u05d4\u05d3\u05d2\u05dd, \u05e9\u05d5\u05dc\u05e4\u05d9\u05dd \u05d0\u05ea \u05d4\u05d3\u05d2\u05dd, \u05d5\u05d9\u05d5\u05e6\u05e7\u05d9\u05dd."],[147.0,"\u05d0\u05d7\u05e8\u05d9 \u05d4\u05d4\u05ea\u05de\u05e6\u05e7\u05d5\u05ea \u05e9\u05d5\u05d1\u05e8\u05d9\u05dd \u05d0\u05ea \u05d4\u05ea\u05d1\u05e0\u05d9\u05ea, \u05d5\u05db\u05dc \u05d9\u05e6\u05d9\u05e7\u05d4 \u05d3\u05d5\u05e8\u05e9\u05ea \u05ea\u05d1\u05e0\u05d9\u05ea \u05d7\u05d3\u05e9\u05d4."],[153.0,"\u05d4\u05d9\u05ea\u05e8\u05d5\u05df: \u05db\u05dc\u05d9\u05dd \u05d6\u05d5\u05dc\u05d9\u05dd, \u05db\u05de\u05e2\u05d8 \u05db\u05dc \u05d2\u05d5\u05d3\u05dc, \u05de\u05e7\u05d9\u05dc\u05d5\u05d2\u05e8\u05de\u05d9\u05dd \u05d1\u05d5\u05d3\u05d3\u05d9\u05dd \u05d5\u05e2\u05d3 \u05e2\u05e9\u05e8\u05d5\u05ea \u05d8\u05d5\u05e0\u05d5\u05ea, \u05d5\u05db\u05de\u05e2\u05d8 \u05db\u05dc \u05de\u05ea\u05db\u05ea."],[161.0,"\u05d4\u05d7\u05d9\u05e1\u05e8\u05d5\u05df: \u05e4\u05e0\u05d9 \u05e9\u05d8\u05d7 \u05de\u05d7\u05d5\u05e1\u05e4\u05e1\u05d9\u05dd, \u05d1\u05e2\u05e8\u05da Ra \u05e9\u05dc 12.5 \u05e2\u05d3 5 \u05de\u05d9\u05e7\u05e8\u05d5\u05df, \u05d5\u05d3\u05d9\u05d5\u05e7 \u05e0\u05de\u05d5\u05da."],[171.0,"\u05dc\u05db\u05df \u05db\u05de\u05e2\u05d8 \u05db\u05dc \u05de\u05e9\u05d8\u05d7 \u05ea\u05e4\u05dc\u05e7\u05d5\u05d3\u05d9 \u05d1\u05d9\u05e6\u05d9\u05e7\u05ea \u05d7\u05d5\u05dc \u05e2\u05d5\u05d1\u05e8 \u05e2\u05d9\u05d1\u05d5\u05d3 \u05e9\u05d1\u05d1\u05d9."],[176.0,"\u05d1\u05d9\u05e6\u05d9\u05e7\u05d4 \u05de\u05d3\u05d5\u05d9\u05e7\u05ea, \u05e9\u05e0\u05e7\u05e8\u05d0\u05ea \u05d2\u05dd \u05d9\u05e6\u05d9\u05e7\u05ea \u05e9\u05e2\u05d5\u05d7\u05d4 \u05d0\u05d1\u05d5\u05d3\u05d4, \u05d4\u05d3\u05d2\u05dd \u05e2\u05e9\u05d5\u05d9 \u05de\u05e9\u05e2\u05d5\u05d4."],[182.0,"\u05de\u05e6\u05e4\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5 \u05d1\u05db\u05de\u05d4 \u05e9\u05db\u05d1\u05d5\u05ea \u05e9\u05dc \u05e7\u05e8\u05de\u05d9\u05e7\u05d4 \u05d5\u05de\u05d7\u05de\u05de\u05d9\u05dd: \u05d4\u05e9\u05e2\u05d5\u05d5\u05d4 \u05e0\u05de\u05e1\u05d4 \u05d5\u05d9\u05d5\u05e6\u05d0\u05ea, \u05d5\u05e0\u05e9\u05d0\u05e8\u05ea \u05e7\u05dc\u05d9\u05e4\u05d4 \u05e7\u05e8\u05de\u05d9\u05ea."],[190.0,"\u05d9\u05d5\u05e6\u05e7\u05d9\u05dd \u05dc\u05ea\u05d5\u05db\u05d4, \u05d5\u05e9\u05d5\u05d1\u05e8\u05d9\u05dd \u05d0\u05d5\u05ea\u05d4 \u05d0\u05d7\u05e8\u05d9 \u05d4\u05d4\u05ea\u05de\u05e6\u05e7\u05d5\u05ea."],[194.0,"\u05d0\u05d9\u05df \u05e7\u05d5 \u05d7\u05dc\u05d5\u05e7\u05d4 \u05d5\u05d0\u05d9\u05df \u05e6\u05d5\u05e8\u05da \u05d1\u05d6\u05d5\u05d5\u05d9\u05ea \u05e9\u05dc\u05d9\u05e4\u05d4, \u05d5\u05dc\u05db\u05df \u05d0\u05e4\u05e9\u05e8 \u05dc\u05e7\u05d1\u05dc \u05e6\u05d5\u05e8\u05d5\u05ea \u05de\u05d5\u05e8\u05db\u05d1\u05d5\u05ea \u05de\u05d0\u05d5\u05d3 \u05d5\u05e4\u05e8\u05d8\u05d9\u05dd \u05d3\u05e7\u05d9\u05dd."],[202.0,"\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05d7\u05dc\u05e7\u05d9\u05dd \u05d1\u05d4\u05e8\u05d1\u05d4, \u05d1\u05e2\u05e8\u05da Ra \u05e9\u05dc 1.6 \u05e2\u05d3 3.2 \u05de\u05d9\u05e7\u05e8\u05d5\u05df, \u05d5\u05d4\u05d3\u05d9\u05d5\u05e7 \u05d2\u05d1\u05d5\u05d4."],[210.0,"\u05db\u05da \u05de\u05d9\u05d9\u05e6\u05e8\u05d9\u05dd \u05dc\u05d4\u05d1\u05d9 \u05d8\u05d5\u05e8\u05d1\u05d9\u05e0\u05d4, \u05e9\u05ea\u05dc\u05d9\u05dd \u05e8\u05e4\u05d5\u05d0\u05d9\u05d9\u05dd, \u05d5\u05d7\u05dc\u05e7\u05d9\u05dd \u05de\u05e4\u05dc\u05d3\u05d5\u05ea, \u05de\u05e1\u05d2\u05e1\u05d5\u05d2\u05d5\u05ea \u05e2\u05dc \u05d5\u05de\u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd."],[218.0,"\u05d4\u05de\u05d7\u05d9\u05e8: \u05ea\u05d4\u05dc\u05d9\u05da \u05d0\u05e8\u05d5\u05da, \u05d4\u05e8\u05d1\u05d4 \u05e2\u05d1\u05d5\u05d3\u05d4, \u05d5\u05e2\u05dc\u05d5\u05ea \u05d2\u05d1\u05d5\u05d4\u05d4 \u05dc\u05db\u05dc \u05d7\u05dc\u05e7."],[224.0,"\u05db\u05e9\u05d4\u05db\u05de\u05d5\u05d9\u05d5\u05ea \u05d2\u05d3\u05d5\u05dc\u05d5\u05ea, \u05de\u05e9\u05ea\u05dc\u05dd \u05dc\u05d4\u05e9\u05e7\u05d9\u05e2 \u05d1\u05ea\u05d1\u05e0\u05d9\u05ea \u05de\u05e4\u05dc\u05d3\u05d4 \u05e9\u05de\u05e9\u05de\u05e9\u05ea \u05d0\u05dc\u05e4\u05d9 \u05d9\u05e6\u05d9\u05e7\u05d5\u05ea."],[230.0,"\u05d1\u05d9\u05e6\u05d9\u05e7\u05d4 \u05d1\u05ea\u05d1\u05e0\u05d9\u05ea \u05e7\u05d1\u05d5\u05e2\u05d4, \u05d4\u05de\u05ea\u05db\u05ea \u05d6\u05d5\u05e8\u05de\u05ea \u05dc\u05ea\u05d1\u05e0\u05d9\u05ea \u05d1\u05db\u05d5\u05d7 \u05d4\u05db\u05d5\u05d1\u05d3."],[235.0,"\u05d1\u05d9\u05e6\u05d9\u05e7\u05ea \u05dc\u05d7\u05e5, \u05d4\u05de\u05ea\u05db\u05ea \u05de\u05d5\u05d6\u05e8\u05e7\u05ea \u05dc\u05ea\u05d1\u05e0\u05d9\u05ea \u05d1\u05dc\u05d7\u05e5 \u05d2\u05d1\u05d5\u05d4 \u05d5\u05d1\u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05d2\u05d1\u05d5\u05d4\u05d4."],[240.0,"\u05db\u05da \u05de\u05ea\u05e7\u05d1\u05dc\u05d9\u05dd \u05d3\u05e4\u05e0\u05d5\u05ea \u05d3\u05e7\u05d5\u05ea, \u05de\u05d9\u05d3\u05d5\u05ea \u05de\u05d3\u05d5\u05d9\u05e7\u05d5\u05ea, \u05d5\u05de\u05d7\u05d6\u05d5\u05e8 \u05e7\u05e6\u05e8 \u05de\u05d0\u05d5\u05d3 \u05dc\u05db\u05dc \u05d7\u05dc\u05e7."],[246.0,"\u05d4\u05e9\u05d9\u05d8\u05d4 \u05de\u05ea\u05d0\u05d9\u05de\u05d4 \u05d1\u05e2\u05d9\u05e7\u05e8 \u05dc\u05de\u05ea\u05db\u05d5\u05ea \u05e2\u05dd \u05e0\u05e7\u05d5\u05d3\u05ea \u05d4\u05ea\u05db\u05d4 \u05e0\u05de\u05d5\u05db\u05d4: \u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd, \u05d0\u05d1\u05e5 \u05d5\u05de\u05d2\u05e0\u05d6\u05d9\u05d5\u05dd."],[253.0,"\u05d0\u05d1\u05dc \u05d4\u05ea\u05d1\u05e0\u05d9\u05ea \u05d9\u05e7\u05e8\u05d4 \u05de\u05d0\u05d5\u05d3, \u05d5\u05de\u05e9\u05ea\u05dc\u05de\u05ea \u05e8\u05e7 \u05d1\u05db\u05de\u05d5\u05d9\u05d5\u05ea \u05d2\u05d3\u05d5\u05dc\u05d5\u05ea."],[257.0,"\u05d5\u05d1\u05d2\u05dc\u05dc \u05d4\u05d4\u05d6\u05e8\u05e7\u05d4 \u05d4\u05de\u05d4\u05d9\u05e8\u05d4 \u05e0\u05db\u05dc\u05d0 \u05d0\u05d5\u05d5\u05d9\u05e8 \u05d1\u05d7\u05d5\u05de\u05e8."],[261.0,"\u05dc\u05db\u05df \u05d7\u05dc\u05e7 \u05de\u05d9\u05e6\u05d9\u05e7\u05ea \u05dc\u05d7\u05e5 \u05e8\u05d2\u05d9\u05dc\u05d4 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05dc\u05d0 \u05de\u05e8\u05ea\u05db\u05d9\u05dd \u05d5\u05dc\u05d0 \u05de\u05d8\u05e4\u05dc\u05d9\u05dd \u05d1\u05d5 \u05d1\u05d7\u05d5\u05dd: \u05d4\u05d2\u05d6 \u05d4\u05db\u05dc\u05d5\u05d0 \u05de\u05ea\u05e4\u05e9\u05d8 \u05d5\u05d9\u05d5\u05e6\u05e8 \u05d1\u05d5\u05e2\u05d5\u05ea."],[271.0,"\u05d1\u05d9\u05e6\u05d9\u05e7\u05d4 \u05d9\u05e9 \u05db\u05de\u05d4 \u05e4\u05d2\u05de\u05d9\u05dd \u05d0\u05d5\u05e4\u05d9\u05d9\u05e0\u05d9\u05d9\u05dd."],[273.0,"\u05e0\u05e7\u05d1\u05d5\u05d1\u05d9\u05d5\u05ea \u05d2\u05d6: \u05d1\u05d5\u05e2\u05d5\u05ea \u05e7\u05d8\u05e0\u05d5\u05ea \u05e9\u05dc \u05d2\u05d6 \u05e9\u05e0\u05dc\u05db\u05d3 \u05d1\u05de\u05ea\u05db\u05ea."],[278.0,"\u05d7\u05dc\u05dc\u05d9 \u05d4\u05ea\u05db\u05d5\u05d5\u05e6\u05d5\u05ea: \u05d7\u05dc\u05dc\u05d9\u05dd \u05d1\u05de\u05e7\u05d5\u05de\u05d5\u05ea \u05e9\u05d4\u05ea\u05de\u05e6\u05e7\u05d5 \u05d0\u05d7\u05e8\u05d5\u05e0\u05d9\u05dd \u05d1\u05dc\u05d9 \u05d4\u05d6\u05e0\u05d4."],[284.0,"\u05de\u05d9\u05dc\u05d5\u05d9 \u05d7\u05e1\u05e8: \u05d4\u05de\u05ea\u05db\u05ea \u05d4\u05ea\u05de\u05e6\u05e7\u05d4 \u05dc\u05e4\u05e0\u05d9 \u05e9\u05de\u05d9\u05dc\u05d0\u05d4 \u05d0\u05ea \u05db\u05dc \u05d4\u05d7\u05dc\u05dc, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1\u05d3\u05e4\u05e0\u05d5\u05ea \u05d3\u05e7\u05d5\u05ea."],[291.0,"\u05e1\u05d3\u05e7\u05d9\u05dd \u05d7\u05de\u05d9\u05dd: \u05e1\u05d3\u05e7\u05d9\u05dd \u05e9\u05e0\u05d5\u05e6\u05e8\u05d9\u05dd \u05db\u05e9\u05d5\u05d4\u05de\u05ea\u05db\u05ea \u05de\u05ea\u05db\u05d5\u05d5\u05e6\u05ea \u05d5\u05d4\u05ea\u05d1\u05e0\u05d9\u05ea \u05de\u05d5\u05e0\u05e2\u05ea \u05de\u05de\u05e0\u05d4."],[297.0,"\u05d7\u05dc\u05e7 \u05de\u05d4\u05e4\u05d2\u05de\u05d9\u05dd \u05de\u05ea\u05d2\u05dc\u05d9\u05dd \u05e8\u05e7 \u05d1\u05e2\u05d9\u05d1\u05d5\u05d3, \u05db\u05e9\u05d4\u05db\u05dc\u05d9 \u05e4\u05d5\u05ea\u05d7 \u05d7\u05dc\u05dc \u05e9\u05d4\u05d9\u05d4 \u05de\u05d5\u05e1\u05ea\u05e8 \u05de\u05ea\u05d7\u05ea \u05dc\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7."],[304.0,"\u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05e7\u05e8\u05d9\u05d8\u05d9\u05d9\u05dd \u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05d9\u05e6\u05d9\u05e7\u05d5\u05ea \u05d1\u05e6\u05d9\u05dc\u05d5\u05dd \u05e8\u05e0\u05d8\u05d2\u05df."],[308.0,"\u05d5\u05de\u05d4 \u05d6\u05d4 \u05d0\u05d5\u05de\u05e8 \u05dc\u05de\u05d9 \u05e9\u05de\u05e2\u05d1\u05d3 \u05d9\u05e6\u05d9\u05e7\u05d5\u05ea?"],[311.0,"\u05d4\u05e9\u05db\u05d1\u05d4 \u05d4\u05d7\u05d9\u05e6\u05d5\u05e0\u05d9\u05ea \u05e7\u05e9\u05d4 \u05d5\u05e9\u05d5\u05d7\u05e7\u05ea: \u05d2\u05e8\u05d2\u05e8\u05d9 \u05d7\u05d5\u05dc \u05d5\u05e7\u05e8\u05d5\u05dd \u05ea\u05d7\u05de\u05d5\u05e6\u05ea \u05e9\u05d5\u05d7\u05e7\u05d9\u05dd \u05d0\u05ea \u05dc\u05d4\u05d1 \u05d4\u05d7\u05d9\u05ea\u05d5\u05da."],[318.0,"\u05dc\u05db\u05df \u05d4\u05de\u05e2\u05d1\u05e8 \u05d4\u05e8\u05d0\u05e9\u05d5\u05df \u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05d9\u05d5\u05ea \u05e2\u05de\u05d5\u05e7 \u05de\u05e1\u05e4\u05d9\u05e7 \u05db\u05d3\u05d9 \u05dc\u05e2\u05d1\u05d5\u05e8 \u05de\u05ea\u05d7\u05ea \u05dc\u05e7\u05e8\u05d5\u05dd."],[323.0,"\u05d5\u05dc\u05db\u05df \u05e7\u05d5\u05d1\u05e2\u05d9\u05dd \u05de\u05e8\u05d0\u05e9 \u05d0\u05d9\u05dc\u05d5 \u05e0\u05e7\u05d5\u05d3\u05d5\u05ea \u05d1\u05d9\u05e6\u05d9\u05e7\u05d4 \u05d9\u05e9\u05de\u05e9\u05d5 \u05dc\u05ea\u05e4\u05d9\u05e1\u05d4 \u05d4\u05d6\u05d5."],[332.0,"\u05d5\u05d0\u05d7\u05e8\u05d9 \u05d4\u05de\u05e2\u05d1\u05e8 \u05d4\u05e8\u05d0\u05e9\u05d5\u05df \u05e2\u05d5\u05d1\u05e8\u05d9\u05dd \u05dc\u05e2\u05d1\u05d5\u05d3 \u05de\u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05de\u05e2\u05d5\u05d1\u05d3\u05d9\u05dd."],[337.0,"\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8\u05d9\u05e6\u05d9\u05e7\u05d4?"],[339.0,"\u05e7\u05d5\u05d3\u05dd \u05db\u05dc \u05d4\u05db\u05dc\u05d9\u05dd: \u05d3\u05d2\u05dd, \u05d0\u05e8\u05d2\u05d6\u05d9 \u05dc\u05d9\u05d1\u05d4, \u05d0\u05d5 \u05ea\u05d1\u05e0\u05d9\u05ea \u05e4\u05dc\u05d3\u05d4. \u05d4\u05e2\u05dc\u05d5\u05ea \u05e9\u05dc\u05d4\u05dd \u05de\u05ea\u05d7\u05dc\u05e7\u05ea \u05e2\u05dc \u05de\u05e1\u05e4\u05e8 \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd."],[347.0,"\u05dc\u05d9\u05d1\u05d5\u05ea: \u05db\u05dc \u05dc\u05d9\u05d1\u05d4 \u05d4\u05d9\u05d0 \u05e2\u05d5\u05d3 \u05e2\u05d1\u05d5\u05d3\u05d4 \u05d5\u05e2\u05d5\u05d3 \u05e1\u05d9\u05db\u05d5\u05df \u05dc\u05e4\u05d2\u05dd."],[352.0,"\u05d0\u05d7\u05d5\u05d6 \u05d4\u05e4\u05e1\u05d9\u05dc\u05d4: \u05d9\u05e6\u05d9\u05e7\u05d4 \u05e4\u05d2\u05d5\u05de\u05d4 \u05e9\u05d4\u05ea\u05d2\u05dc\u05ea\u05d4 \u05e8\u05e7 \u05d0\u05d7\u05e8\u05d9 \u05e2\u05d9\u05d1\u05d5\u05d3 \u05e2\u05dc\u05ea\u05d4 \u05d2\u05dd \u05d0\u05ea \u05d4\u05d9\u05e6\u05d9\u05e7\u05d4 \u05d5\u05d2\u05dd \u05d0\u05ea \u05d4\u05e2\u05d9\u05d1\u05d5\u05d3."],[359.0,"\u05e2\u05d1\u05d5\u05d3\u05ea \u05d2\u05de\u05e8 \u05e0\u05d9\u05ea\u05d5\u05e7 \u05d4\u05de\u05d6\u05d9\u05e0\u05d9\u05dd \u05d5\u05de\u05e2\u05e8\u05db\u05ea \u05d4\u05d4\u05d6\u05e0\u05d4, \u05e0\u05d9\u05e7\u05d5\u05d9, \u05d5\u05d4\u05e9\u05d7\u05d6\u05d4 \u05e9\u05dc \u05e2\u05d5\u05d3\u05e4\u05d9\u05dd."],[366.0,"\u05d1\u05d3\u05d9\u05e7\u05d5\u05ea, \u05db\u05de\u05d5 \u05e8\u05e0\u05d8\u05d2\u05df, \u05d5\u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd \u05db\u05e9\u05e0\u05d3\u05e8\u05e9\u05e9."],[370.0,"\u05d5\u05ea\u05d5\u05e1\u05e4\u05ea \u05d4\u05e2\u05d9\u05d1\u05d5\u05d3: \u05db\u05dc \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8 \u05e9\u05e0\u05e9\u05d0\u05e8 \u05e2\u05dc \u05d4\u05d9\u05e6\u05d9\u05e7\u05d4 \u05d4\u05d5\u05d0 \u05d6\u05de\u05df \u05de\u05db\u05d5\u05e0\u05d4."],[376.0,"\u05d0\u05d6 \u05d0\u05d9\u05da \u05d1\u05d5\u05d7\u05e8\u05d9\u05dd?"],[377.0,"\u05dc\u05db\u05de\u05d4 \u05d7\u05dc\u05e7\u05d9\u05dd \u05d1\u05d5\u05d3\u05d3\u05d9\u05dd, \u05dc\u05e2\u05ea\u05d9\u05dd \u05e7\u05e8\u05d5\u05d1\u05d5\u05ea \u05d6\u05d5\u05dc \u05d9\u05d5\u05ea\u05e8 \u05dc\u05e2\u05d1\u05d3 \u05de\u05d2\u05d5\u05e9, \u05d0\u05d5 \u05dc\u05d9\u05e6\u05d5\u05e7 \u05d1\u05d7\u05d5\u05dc."],[383.0,"\u05dc\u05e1\u05d3\u05e8\u05d4 \u05e7\u05d8\u05e0\u05d4 \u05e2\u05d3 \u05d1\u05d9\u05e0\u05d5\u05e0\u05d9\u05ea \u05e9\u05dc \u05d7\u05dc\u05e7\u05d9\u05dd \u05de\u05d5\u05e8\u05db\u05d1\u05d9\u05dd: \u05d9\u05e6\u05d9\u05e7\u05d4 \u05d1\u05d7\u05d5\u05dc, \u05d0\u05d5 \u05d9\u05e6\u05d9\u05e7\u05d4 \u05de\u05d3\u05d5\u05d9\u05e7\u05ea \u05db\u05e9\u05e0\u05d3\u05e8\u05e9 \u05d3\u05d9\u05d5\u05e7."],[391.0,"\u05dc\u05d0\u05dc\u05e4\u05d9\u05dd \u05d5\u05d9\u05d5\u05ea\u05e8 \u05e9\u05dc \u05d7\u05dc\u05e7\u05d9 \u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd: \u05d9\u05e6\u05d9\u05e7\u05ea \u05dc\u05d7\u05e5."],[396.0,"\u05d5\u05e0\u05e7\u05d5\u05d3\u05d4 \u05d0\u05d7\u05ea \u05dc\u05d6\u05db\u05d5\u05e8: \u05d1\u05d9\u05e6\u05d9\u05e7\u05d4 \u05d0\u05d9\u05df \u05d6\u05e8\u05d9\u05de\u05ea \u05e1\u05d9\u05d1\u05d9\u05dd \u05e9\u05de\u05dc\u05d5\u05d5\u05d4 \u05d0\u05ea \u05e6\u05d5\u05e8\u05ea \u05d4\u05d7\u05dc\u05e7, \u05d5\u05d9\u05db\u05d5\u05dc\u05d9\u05dd \u05dc\u05d4\u05d9\u05d5\u05ea \u05d1\u05d4 \u05d7\u05dc\u05dc\u05d9\u05dd \u05d6\u05e2\u05d9\u05e8\u05d9\u05dd."],[404.0,"\u05dc\u05db\u05df \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d4\u05d9\u05d0 \u05e4\u05d7\u05d5\u05ea \u05d7\u05d6\u05e7\u05d4 \u05d5\u05e4\u05d7\u05d5\u05ea \u05e2\u05de\u05d9\u05d3\u05d4 \u05d1\u05e2\u05d9\u05d9\u05e4\u05d5\u05ea \u05de\u05d7\u05dc\u05e7 \u05de\u05d7\u05d5\u05e9\u05dc \u05de\u05d0\u05d5\u05ea\u05d5 \u05d7\u05d5\u05de\u05e8."],[411.0,"\u05d5\u05de\u05db\u05d0\u05df \u05e0\u05de\u05e9\u05d9\u05da \u05dc\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0: \u05d7\u05d9\u05e9\u05d5\u05dc."]]};
window.MH_TR["\u05e4\u05e8\u05e702_\u05d7\u05d9\u05e9\u05d5\u05dc"]={"t":"\u05d7\u05d9\u05e9\u05d5\u05dc","l":[[1.0,"\u05d7\u05dc\u05e7\u05d9\u05dd \u05e9\u05d7\u05d9\u05d9\u05d1\u05d9\u05dd \u05dc\u05e9\u05d0\u05ea \u05e2\u05d5\u05de\u05e1 \u05d2\u05d1\u05d5\u05d4 \u05d5\u05e2\u05d9\u05d9\u05e4\u05d5\u05ea \u05dc\u05d0\u05d5\u05e8\u05da \u05e9\u05e0\u05d9\u05dd."],[11.0,"\u05e8\u05d5\u05d1\u05dd \u05de\u05ea\u05d7\u05d9\u05dc\u05d9\u05dd \u05db\u05d7\u05d9\u05e9\u05d5\u05d5\u05dc."],[13.0,"\u05d1\u05d7\u05d9\u05e9\u05d5\u05dc \u05dc\u05d0 \u05de\u05de\u05d9\u05e1\u05d9\u05dd \u05d0\u05ea \u05d4\u05de\u05ea\u05db\u05ea: \u05de\u05e2\u05e6\u05d1\u05d9\u05dd \u05d0\u05d5\u05ea\u05d4 \u05d1\u05de\u05e6\u05d1 \u05de\u05d5\u05e6\u05e7, \u05d1\u05db\u05d5\u05d7 \u05e9\u05dc \u05e4\u05d8\u05d9\u05e9 \u05d0\u05d5 \u05e9\u05dc \u05de\u05db\u05d1\u05e9."],[20.0,"\u05d5\u05d4\u05ea\u05d5\u05e6\u05d0\u05d4 \u05d4\u05d9\u05d0 \u05d7\u05dc\u05e7 \u05d7\u05d6\u05e7 \u05d9\u05d5\u05ea\u05e8 \u05de\u05d0\u05d5\u05ea\u05d5 \u05d7\u05dc\u05e7 \u05d1\u05d9\u05e6\u05d9\u05e7\u05d4 \u05d0\u05d5 \u05d1\u05e2\u05d9\u05d1\u05d5\u05d3 \u05de\u05d2\u05d5\u05e9."],[26.0,"\u05de\u05ea\u05db\u05ea \u05de\u05d5\u05e8\u05db\u05d1\u05ea \u05de\u05d2\u05e8\u05d2\u05e8\u05d9\u05dd, \u05d2\u05d1\u05d9\u05e9\u05d9\u05dd \u05d6\u05e2\u05d9\u05e8\u05d9\u05dd."],[30.0,"\u05db\u05e9\u05de\u05e2\u05e6\u05d1\u05d9\u05dd \u05d0\u05d5\u05ea\u05d4 \u05d1\u05db\u05d5\u05d7, \u05d4\u05d2\u05e8\u05d2\u05e8\u05d9\u05dd \u05e0\u05de\u05ea\u05d7\u05d9\u05dd \u05dc\u05d0\u05d5\u05e8\u05da \u05db\u05d9\u05d5\u05d5\u05df \u05d4\u05d6\u05e8\u05d9\u05de\u05d4 \u05e9\u05dc \u05d4\u05d7\u05d5\u05de\u05e8."],[35.0,"\u05db\u05da \u05e0\u05d5\u05e6\u05e8\u05ea \u05d6\u05e8\u05d9\u05de\u05ea \u05e1\u05d9\u05d1\u05d9\u05dd, \u05db\u05de\u05d5 \u05e1\u05d9\u05d1\u05d9\u05dd \u05d1\u05e2\u05e5."],[39.0,"\u05d1\u05d7\u05dc\u05e7 \u05de\u05d7\u05d5\u05e9\u05dc \u05d4\u05e1\u05d9\u05d1\u05d9\u05dd \u05de\u05dc\u05d5\u05d5\u05d9\u05dd \u05d0\u05ea \u05e6\u05d5\u05e8\u05ea \u05d4\u05d7\u05dc\u05e7, \u05d5\u05de\u05e7\u05d9\u05e4\u05d9\u05dd \u05e4\u05d9\u05e0\u05d5\u05ea \u05d5\u05db\u05ea\u05e4\u05d9\u05d9\u05dd."],[45.0,"\u05d1\u05d7\u05dc\u05e7 \u05e9\u05e2\u05d5\u05d1\u05d3 \u05de\u05d2\u05d5\u05e9, \u05d4\u05d7\u05d9\u05ea\u05d5\u05da \u05d7\u05d5\u05e6\u05d4 \u05d0\u05ea \u05d4\u05e1\u05d9\u05d1\u05d9\u05dd \u05d1\u05d3\u05d9\u05d5\u05e7 \u05d1\u05d0\u05d6\u05d5\u05e8\u05d9\u05dd \u05d4\u05d0\u05dc\u05d4."],[50.0,"\u05d1\u05e0\u05d5\u05e1\u05e3, \u05d4\u05dc\u05d7\u05e5 \u05e1\u05d5\u05d2\u05e8 \u05d7\u05dc\u05dc\u05d9\u05dd \u05d6\u05e2\u05d9\u05e8\u05d9\u05dd \u05e9\u05e0\u05e9\u05d0\u05e8\u05d5 \u05de\u05d4\u05d9\u05e6\u05d9\u05e7\u05d4 \u05e9\u05dc \u05d7\u05d5\u05de\u05e8 \u05d4\u05d2\u05dc\u05dd, \u05d5\u05d4\u05de\u05d1\u05e0\u05d4 \u05e0\u05e2\u05e9\u05d4 \u05e2\u05d3\u05d9\u05df \u05d5\u05d0\u05d7\u05d9\u05d3 \u05d9\u05d5\u05ea\u05e8."],[58.0,"\u05d4\u05ea\u05d5\u05e6\u05d0\u05d4: \u05d7\u05d5\u05d6\u05e7, \u05e2\u05de\u05d9\u05d3\u05d5\u05ea \u05d1\u05e2\u05d9\u05d9\u05e4\u05d5\u05ea \u05d5\u05e2\u05de\u05d9\u05d3\u05d5\u05ea \u05d1\u05d4\u05dc\u05dd \u05d2\u05d1\u05d5\u05d4\u05d9\u05dd \u05d9\u05d5\u05ea\u05e8."],[65.0,"\u05e8\u05d5\u05d1 \u05d4\u05d7\u05d9\u05e9\u05d5\u05dc \u05e0\u05e2\u05e9\u05d4 \u05d1\u05d7\u05d5\u05dd."],[67.0,"\u05d4\u05d4\u05ea\u05d2\u05d1\u05e9\u05d5\u05ea \u05de\u05d7\u05d3\u05e9, \u05d5\u05d0\u05d6 \u05d4\u05d5\u05d0 \u05e8\u05da, \u05d5\u05d4\u05d2\u05e8\u05d2\u05e8\u05d9\u05dd \u05e0\u05d1\u05e0\u05d9\u05dd \u05de\u05d7\u05d3\u05e9 \u05ea\u05d5\u05da \u05db\u05d3\u05d9 \u05d4\u05e2\u05d9\u05e6\u05d5\u05d1."],[76.0,"\u05d1\u05e4\u05dc\u05d3\u05d4 \u05d6\u05d4 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1\u05d9\u05df 1100 \u05dc-1250 \u05de\u05e2\u05dc\u05d5\u05ea, \u05d5\u05d1\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05d1\u05e2\u05e8\u05da 400 \u05e2\u05d3 500 \u05de\u05e2\u05dc\u05d5\u05ea."],[85.0,"\u05d4\u05d7\u05d9\u05e1\u05e8\u05d5\u05df: \u05e2\u05dc \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05e0\u05d5\u05e6\u05e8 \u05e1\u05e7\u05d9\u05d9\u05dc, \u05e9\u05db\u05d1\u05ea \u05ea\u05d7\u05de\u05d5\u05e6\u05ea \u05e7\u05e9\u05d4, \u05d5\u05d4\u05de\u05d9\u05d3\u05d5\u05ea \u05e4\u05d7\u05d5\u05ea \u05de\u05d3\u05d5\u05d9\u05e7\u05d5\u05ea."],[93.0,"\u05d1\u05d7\u05d9\u05e9\u05d5\u05dc \u05e7\u05e8 \u05de\u05e2\u05e6\u05d1\u05d9\u05dd \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05d4\u05d7\u05d3\u05e8."],[96.0,"\u05e6\u05e8\u05d9\u05da \u05db\u05d5\u05d7\u05d5\u05ea \u05d2\u05d3\u05d5\u05dc\u05d9\u05dd \u05d1\u05d4\u05e8\u05d1\u05d4, \u05d0\u05d1\u05dc \u05de\u05e7\u05d1\u05dc\u05d9\u05dd \u05de\u05d9\u05d3\u05d5\u05ea \u05de\u05d3\u05d5\u05d9\u05e7\u05d5\u05ea \u05d5\u05e4\u05e0\u05d9 \u05e9\u05d8\u05d7 \u05e0\u05e7\u05d9\u05d9\u05dd, \u05d5\u05d4\u05d7\u05d5\u05de\u05e8 \u05de\u05ea\u05e7\u05e9\u05d4 \u05d1\u05d6\u05de\u05df \u05d4\u05e2\u05d9\u05e6\u05d5\u05d1."],[105.0,"\u05db\u05da \u05de\u05d9\u05d9\u05e6\u05e8\u05d9\u05dd, \u05dc\u05de\u05e9\u05dc, \u05d1\u05e8\u05d2\u05d9\u05dd \u05d5\u05de\u05e1\u05de\u05e8\u05d5\u05ea \u05d1\u05db\u05de\u05d5\u05d9\u05d5\u05ea \u05e2\u05e6\u05d5\u05de\u05d5\u05ea."],[109.0,"\u05d5\u05d9\u05e9 \u05d2\u05dd \u05d7\u05d9\u05e9\u05d5\u05dc \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05d1\u05d9\u05e0\u05d9\u05d9\u05dd, \u05e9\u05de\u05e9\u05dc\u05d1 \u05d7\u05dc\u05e7 \u05de\u05d4\u05d9\u05ea\u05e8\u05d5\u05e0\u05d5\u05ea \u05e9\u05dc \u05e9\u05e0\u05d9\u05d4\u05dd."],[115.0,"\u05d1\u05d7\u05d9\u05e9\u05d5\u05dc \u05e4\u05ea\u05d5\u05d7, \u05d4\u05d7\u05d5\u05de\u05e8 \u05e0\u05de\u05e2\u05da \u05d1\u05d9\u05df \u05ea\u05d1\u05e0\u05d9\u05d5\u05ea \u05e4\u05e9\u05d5\u05d8\u05d5\u05ea, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05e9\u05d8\u05d5\u05d7\u05d5\u05ea."],[120.0,"\u05d4\u05d7\u05d5\u05de\u05e8 \u05dc\u05d0 \u05e1\u05d2\u05d5\u05e8 \u05de\u05db\u05dc \u05d4\u05e6\u05d3\u05d3\u05d9\u05dd, \u05d5\u05d4\u05de\u05e4\u05e2\u05d9\u05dc \u05de\u05e1\u05d5\u05d1\u05d1 \u05d5\u05de\u05d6\u05d9\u05d6 \u05d0\u05d5\u05ea\u05d5 \u05d1\u05d9\u05df \u05de\u05db\u05d4 \u05dc\u05de\u05db\u05d4."],[126.0,"\u05db\u05da \u05de\u05d0\u05e8\u05d9\u05db\u05d9\u05dd, \u05de\u05e7\u05e6\u05e8\u05d9\u05dd \u05d5\u05de\u05e2\u05d1\u05d9\u05dd \u05d0\u05ea \u05d4\u05d7\u05d5\u05de\u05e8, \u05d5\u05de\u05d9\u05d9\u05e6\u05e8\u05d9\u05dd \u05d2\u05dc\u05d9\u05dd \u05d2\u05d3\u05d5\u05dc\u05d9\u05dd, \u05d8\u05d1\u05e2\u05d5\u05ea \u05d5\u05d3\u05d9\u05e1\u05e7\u05d9\u05d5\u05ea."],[134.0,"\u05d4\u05db\u05dc\u05d9\u05dd \u05d6\u05d5\u05dc\u05d9\u05dd, \u05d5\u05d0\u05e4\u05e9\u05e8 \u05dc\u05d7\u05e9\u05dc \u05d7\u05dc\u05e7\u05d9\u05dd \u05e9\u05e9\u05d5\u05e7\u05dc\u05d9\u05dd \u05e2\u05e9\u05e8\u05d5\u05ea \u05d8\u05d5\u05e0\u05d5\u05ea \u05d5\u05d9\u05d5\u05ea\u05e8."],[139.0,"\u05d0\u05d1\u05dc \u05d4\u05d3\u05d9\u05d5\u05e7 \u05e0\u05de\u05d5\u05da, \u05d5\u05de\u05e9\u05d0\u05d9\u05e8\u05d9\u05dd \u05ea\u05d5\u05e1\u05e4\u05ea \u05e2\u05d9\u05d1\u05d5\u05d3 \u05d2\u05d3\u05d5\u05dc\u05d4."],[143.0,"\u05d1\u05d7\u05d9\u05e9\u05d5\u05dc \u05d1\u05ea\u05d1\u05e0\u05d9\u05ea \u05e1\u05d2\u05d5\u05e8\u05d4, \u05dc\u05db\u05dc \u05d7\u05dc\u05e7 \u05d9\u05e9 \u05d6\u05d5\u05d2 \u05ea\u05d1\u05e0\u05d9\u05d5\u05ea \u05de\u05e4\u05dc\u05d3\u05d4, \u05d5\u05d1\u05d4\u05df \u05d7\u05dc\u05dc \u05d1\u05e6\u05d5\u05e8\u05ea \u05d4\u05d7\u05dc\u05e7."],[150.0,"\u05de\u05e0\u05d9\u05d7\u05d9\u05dd \u05d2\u05d5\u05e9 \u05d7\u05dd \u05d1\u05d9\u05df \u05d4\u05ea\u05d1\u05e0\u05d9\u05d5\u05ea, \u05d5\u05d4\u05df \u05e0\u05e1\u05d2\u05e8\u05d5\u05ea \u05e2\u05dc\u05d9\u05d5 \u05d5\u05de\u05db\u05e8\u05d9\u05d7\u05d5\u05ea \u05d0\u05ea \u05d4\u05d7\u05d5\u05de\u05e8 \u05dc\u05de\u05dc\u05d0 \u05d0\u05ea \u05d4\u05d7\u05dc\u05dc."],[156.0,"\u05db\u05d3\u05d9 \u05e9\u05d4\u05d7\u05dc\u05dc \u05d9\u05ea\u05de\u05dc\u05d0 \u05e2\u05d3 \u05d4\u05e1\u05d5\u05e3, \u05dc\u05d5\u05e7\u05d7\u05d9\u05dd \u05e7\u05e6\u05ea \u05d9\u05d5\u05ea\u05e8 \u05d7\u05d5\u05de\u05e8 \u05de\u05de\u05d4 \u05e9\u05e6\u05e8\u05d9\u05da."],[161.0,"\u05d4\u05e2\u05d5\u05d3\u05e3 \u05e0\u05e4\u05dc\u05d8 \u05d1\u05d9\u05df \u05d4\u05ea\u05d1\u05e0\u05d9\u05d5\u05ea, \u05d5\u05d9\u05d5\u05e6\u05e8 \u05e9\u05e4\u05d4 \u05d3\u05e7\u05d4 \u05de\u05e1\u05d1\u05d9\u05d1 \u05dc\u05d7\u05dc\u05e7, \u05e9\u05e0\u05e7\u05e8\u05d0\u05ea \u05d4\u05d1\u05d6\u05e7."],[168.0,"\u05d4\u05d4\u05d1\u05d6\u05e7 \u05de\u05ea\u05e7\u05e8\u05e8 \u05de\u05d4\u05e8, \u05e0\u05e2\u05e9\u05d4 \u05e7\u05e9\u05d4, \u05d5\u05d1\u05d5\u05dc\u05dd \u05d0\u05ea \u05d4\u05de\u05e9\u05da \u05d4\u05d6\u05e8\u05d9\u05de\u05d4 \u05d4\u05d7\u05d5\u05e6\u05d4."],[173.0,"\u05db\u05da \u05d4\u05d5\u05d0 \u05d3\u05d5\u05d7\u05e3 \u05d0\u05ea \u05d4\u05d7\u05d5\u05de\u05e8 \u05dc\u05de\u05dc\u05d0 \u05d0\u05ea \u05d4\u05e4\u05d9\u05e0\u05d5\u05ea."],[176.0,"\u05d1\u05e1\u05d5\u05e3 \u05d7\u05d5\u05ea\u05db\u05d9\u05dd \u05d0\u05ea \u05d4\u05d4\u05d1\u05d6\u05e7 \u05d1\u05de\u05db\u05d1\u05e9 \u05e0\u05e4\u05e8\u05d3."],[180.0,"\u05d7\u05dc\u05e7 \u05de\u05d5\u05e8\u05db\u05d1 \u05dc\u05d0 \u05e0\u05d5\u05e6\u05e8 \u05d1\u05de\u05db\u05d4 \u05d0\u05d7\u05ea: \u05d4\u05d5\u05d0 \u05e2\u05d5\u05d1\u05e8 \u05db\u05de\u05d4 \u05ea\u05d7\u05e0\u05d5\u05ea, \u05de\u05e2\u05d9\u05e6\u05d5\u05d1 \u05d2\u05e1 \u05d5\u05e2\u05d3 \u05d4\u05e6\u05d5\u05e8\u05d4 \u05d4\u05e1\u05d5\u05e4\u05d9\u05ea."],[187.0,"\u05d4\u05ea\u05d1\u05e0\u05d9\u05d5\u05ea \u05d9\u05e7\u05e8\u05d5\u05ea, \u05d5\u05dc\u05db\u05df \u05d4\u05e9\u05d9\u05d8\u05d4 \u05de\u05e9\u05d5\u05ea\u05dc\u05de\u05ea \u05d1\u05e1\u05d3\u05e8\u05d5\u05ea."],[192.0,"\u05d0\u05ea \u05d4\u05db\u05d5\u05d7 \u05e0\u05d5\u05ea\u05e0\u05d9\u05dd \u05e4\u05d8\u05d9\u05e9 \u05d0\u05d5 \u05de\u05db\u05d1\u05e9."],[195.0,"\u05e4\u05d8\u05d9\u05e9 \u05de\u05db\u05d4 \u05de\u05d4\u05e8, \u05d4\u05e8\u05d1\u05d4 \u05de\u05db\u05d5\u05ea \u05e7\u05e6\u05e8\u05d5\u05ea, \u05d5\u05d4\u05d7\u05d5\u05de\u05e8 \u05d6\u05d5\u05e8\u05dd \u05d1\u05e2\u05d9\u05e7\u05e8 \u05dc\u05d9\u05d3 \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7."],[201.0,"\u05de\u05db\u05d1\u05e9 \u05dc\u05d5\u05d7\u05e5 \u05dc\u05d0\u05d8 \u05d5\u05d1\u05d0\u05d5\u05e4\u05dc\u05df \u05e8\u05e6\u05d9\u05e3, \u05d5\u05d4\u05e2\u05d9\u05e6\u05d5\u05d1 \u05d7\u05d5\u05d3\u05e8 \u05e2\u05de\u05d5\u05e7 \u05d9\u05d5\u05ea\u05e8 \u05dc\u05ea\u05d5\u05da \u05d4\u05d7\u05dc\u05e7."],[207.0,"\u05d2\u05dd \u05d7\u05dc\u05e7 \u05dc\u05d7\u05d9\u05e9\u05d5\u05dc \u05de\u05ea\u05d5\u05db\u05e0\u05df \u05d0\u05d7\u05e8\u05ea."],[210.0,"\u05e6\u05e8\u05d9\u05da \u05e7\u05d5 \u05d7\u05dc\u05d5\u05e7\u05d4 \u05d1\u05d9\u05df \u05d4\u05ea\u05d1\u05e0\u05d9\u05d5\u05ea, \u05d5\u05d6\u05d5\u05d5\u05d9\u05d5\u05ea \u05e9\u05dc\u05d9\u05e4\u05d4 \u05db\u05d3\u05d9 \u05dc\u05e9\u05d7\u05e8\u05e8 \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc 5 \u05e2\u05d3 7 \u05de\u05e2\u05dc\u05d5\u05ea \u05d1\u05d3\u05e4\u05e0\u05d5\u05ea \u05d4\u05d7\u05d9\u05e6\u05d5\u05e0\u05d9\u05d5\u05ea."],[219.0,"\u05e8\u05d3\u05d9\u05d5\u05e1\u05d9\u05dd \u05e0\u05d3\u05d9\u05d1\u05d9\u05dd \u05d1\u05e4\u05d9\u05e0\u05d5\u05ea, \u05db\u05d3\u05d9 \u05e9\u05d4\u05d7\u05d5\u05de\u05e8 \u05d9\u05d6\u05e8\u05d5\u05dd \u05d1\u05dc\u05d9 \u05dc\u05d4\u05d9\u05ea\u05e7\u05e2 \u05d5\u05dc\u05d9\u05e6\u05d5\u05e8 \u05e7\u05e4\u05dc."],[225.0,"\u05d5\u05dc\u05d0 \u05e6\u05dc\u05e2\u05d5\u05ea \u05d2\u05d1\u05d5\u05d4\u05d5\u05ea \u05d5\u05d3\u05e7\u05d5\u05ea \u05de\u05d3\u05d9, \u05e9\u05e7\u05e9\u05d4 \u05dc\u05de\u05dc\u05d0."],[228.0,"\u05d5\u05ea\u05d5\u05e1\u05e4\u05ea \u05e2\u05d9\u05d1\u05d5\u05d3 \u05e2\u05dc \u05db\u05dc \u05de\u05e9\u05d8\u05d7 \u05de\u05d3\u05d5\u05d9\u05e7, \u05e9\u05d2\u05dd \u05de\u05db\u05e1\u05d4 \u05d0\u05ea \u05e9\u05db\u05d1\u05ea \u05d4\u05e1\u05e7\u05d9\u05d9\u05dc."],[234.0,"\u05d2\u05dd \u05dc\u05d7\u05d9\u05e9\u05d5\u05dc \u05d9\u05e9 \u05e4\u05d2\u05de\u05d9\u05dd \u05d0\u05d5\u05e4\u05d9\u05d9\u05e0\u05d9\u05d9\u05dd."],[236.0,"\u05e7\u05e4\u05dc: \u05d4\u05d7\u05d5\u05de\u05e8 \u05de\u05ea\u05e7\u05e4\u05dc \u05e2\u05dc \u05e2\u05e6\u05de\u05d5 \u05d5\u05d9\u05d5\u05e6\u05e8 \u05e1\u05d3\u05e7 \u05e1\u05de\u05d5\u05d9, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05dc\u05d9\u05d3 \u05e4\u05d9\u05e0\u05d4 \u05d7\u05d3\u05d4."],[243.0,"\u05de\u05d9\u05dc\u05d5\u05d9 \u05d7\u05e1\u05e8: \u05dc\u05d0 \u05d4\u05d9\u05d4 \u05de\u05e1\u05e4\u05d9\u05e7 \u05d7\u05d5\u05de\u05e8 \u05d0\u05d5 \u05d7\u05d5\u05dd, \u05d5\u05d4\u05e4\u05d9\u05e0\u05d5\u05ea \u05dc\u05d0 \u05d4\u05ea\u05de\u05dc\u05d0\u05d5."],[248.0,"\u05d0\u05d9 \u05d4\u05ea\u05d0\u05de\u05d4: \u05d4\u05ea\u05d1\u05e0\u05d9\u05ea \u05d4\u05e2\u05dc\u05d9\u05d5\u05e0\u05d4 \u05d5\u05d4\u05ea\u05d7\u05ea\u05d5\u05e0\u05d4 \u05d6\u05d6\u05d5 \u05d6\u05d5 \u05d1\u05d9\u05d7\u05e1 \u05dc\u05d6\u05d5, \u05d5\u05e9\u05e0\u05d9 \u05d7\u05e6\u05d0\u05d9 \u05d4\u05d7\u05dc\u05e7 \u05dc\u05d0 \u05de\u05d9\u05d5\u05e9\u05e8\u05d9\u05dd."],[256.0,"\u05d5\u05e1\u05d3\u05e7\u05d9\u05dd, \u05db\u05e9\u05de\u05d7\u05e9\u05dc\u05d9\u05dd \u05d7\u05d5\u05de\u05e8 \u05e7\u05e8 \u05de\u05d3\u05d9."],[260.0,"\u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05e7\u05e8\u05d9\u05d8\u05d9\u05d9\u05dd \u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05d7\u05d9\u05e9\u05d5\u05dc\u05d9\u05dd \u05d1\u05d0\u05d5\u05dc\u05d8\u05e8\u05e1\u05d0\u05d5\u05e0\u05d3, \u05db\u05d3\u05d9 \u05dc\u05de\u05e6\u05d5\u05d0 \u05e4\u05d2\u05de\u05d9\u05dd \u05e1\u05e0\u05d9\u05de\u05d9\u05d9\u05dd."],[265.0,"\u05d5\u05de\u05d4 \u05d6\u05d4 \u05d0\u05d5\u05de\u05e8 \u05dc\u05de\u05d9 \u05e9\u05de\u05e2\u05d1\u05d3 \u05d7\u05d9\u05e9\u05d5\u05dc\u05d9\u05dd?"],[268.0,"\u05db\u05de\u05d5 | \u05d1\u05d9\u05e6\u05d9\u05e7\u05d4, | \u05d4\u05e1\u05e7\u05d9\u05d9\u05dc | \u05e7\u05e9\u05d4 | \u05d5\u05e9\u05d5\u05d7\u05e7, \u05d5\u05dc\u05db\u05df \u05d4\u05de\u05e2\u05d1\u05e8 \u05d4\u05e8\u05d0\u05e9\u05d5 \u05e6\u05e8\u05d9\u05da \u05dc\u05e2\u05d1\u05d5\u05e8 \u05de\u05ea\u05d7\u05ea\u05d9\u05d5."],[275.0,"\u05d3\u05e4\u05e0\u05d5\u05ea \u05e2\u05dd \u05d6\u05d5\u05d5\u05d9\u05ea \u05e9\u05dc\u05d9\u05e4\u05d4 \u05d0\u05d9\u05e0\u05df \u05de\u05e7\u05d1\u05d9\u05dc\u05d5\u05ea, \u05d5\u05dc\u05db\u05df \u05e7\u05e9\u05d4 \u05dc\u05ea\u05e4\u05d5\u05e1 \u05d0\u05d5\u05ea\u05df \u05d1\u05de\u05dc\u05d7\u05e6\u05d9\u05d9\u05dd \u05e8\u05d2\u05d9\u05dc\u05d9\u05dd."],[281.0,"\u05d0\u05d9 \u05d4\u05ea\u05d0\u05de\u05d4 \u05d1\u05d9\u05df \u05d7\u05e6\u05d0\u05d9 \u05d4\u05d7\u05dc\u05e7 \u05de\u05e9\u05e4\u05d9\u05e2\u05d4 \u05e2\u05dc \u05d4\u05de\u05d9\u05e7\u05d5\u05dd \u05e9\u05dc \u05d4\u05ea\u05e4\u05d9\u05e1\u05d4 \u05d4\u05e8\u05d0\u05e9\u05d5\u05e0\u05d4, \u05d5\u05dc\u05db\u05df \u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05d0\u05d5\u05ea\u05d4 \u05dc\u05e4\u05e0\u05d9 \u05e9\u05de\u05ea\u05d7\u05d9\u05dc\u05d9\u05dd."],[288.0,"\u05d5\u05d1\u05d7\u05dc\u05e7 \u05de\u05d7\u05d5\u05e9\u05dc \u05d9\u05e9 \u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05e4\u05e0\u05d9\u05de\u05d9\u05d9\u05dd: \u05db\u05e9\u05de\u05d5\u05e8\u05d9\u05d3\u05d9\u05dd \u05d4\u05e8\u05d1\u05d4 \u05d7\u05d5\u05de\u05e8 \u05d1\u05e6\u05d3 \u05d0\u05d7\u05d3, \u05d4\u05d7\u05dc\u05e7 \u05e2\u05dc\u05d5\u05dc \u05dc\u05d4\u05ea\u05e2\u05d5\u05d5\u05ea."],[296.0,"\u05dc\u05db\u05df \u05de\u05d5\u05e8\u05d9\u05d3\u05d9\u05dd \u05d7\u05d5\u05de\u05e8 \u05d1\u05d4\u05d3\u05e8\u05d2\u05d4 \u05d5\u05d1\u05d0\u05d5\u05e4\u05df \u05e1\u05d9\u05de\u05d8\u05e8\u05d9, \u05d5\u05de\u05e9\u05d0\u05d9\u05e8\u05d9\u05dd \u05de\u05e2\u05d1\u05e8 \u05d2\u05d9\u05de\u05d5\u05e8 \u05dc\u05e1\u05d5\u05e3."],[302.0,"\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8 \u05d7\u05d9\u05e9\u05d5\u05dc?"],[304.0,"\u05d4\u05ea\u05d1\u05e0\u05d9\u05d5\u05ea: \u05e4\u05dc\u05d3\u05ea \u05db\u05dc\u05d9\u05dd, \u05e2\u05d9\u05d1\u05d5\u05d3 \u05de\u05d3\u05d5\u05d9\u05e7, \u05d5\u05d4\u05df \u05e0\u05e9\u05d7\u05e7\u05d5\u05ea \u05d5\u05d3\u05d5\u05e8\u05e9\u05d5\u05d5\u05ea \u05ea\u05d9\u05e7\u05d5\u05df \u05d5\u05d4\u05d7\u05dc\u05e4\u05d4."],[311.0,"\u05d7\u05d9\u05de\u05d5\u05dd: \u05d0\u05e0\u05e8\u05d2\u05d9\u05d4, \u05ea\u05e0\u05d5\u05e8\u05d9\u05dd \u05d4\u05de\u05df."],[314.0,"\u05d4\u05d7\u05d5\u05de\u05e8 \u05e9\u05d4\u05d5\u05dc\u05da \u05dc\u05d4\u05d1\u05d6\u05e7: \u05d4\u05d5\u05d0 \u05e0\u05e7\u05e0\u05d4, \u05d7\u05d5\u05de\u05dd \u05d5\u05e0\u05d7\u05ea\u05da, \u05d5\u05dc\u05d0 \u05e0\u05db\u05e0\u05e1 \u05dc\u05d7\u05dc\u05e7."],[320.0,"\u05d7\u05d9\u05ea\u05d5\u05da \u05d4\u05d4\u05d1\u05d6\u05e7, \u05e0\u05d9\u05e7\u05d5\u05d9 \u05d4\u05e1\u05e7\u05d9\u05d9\u05dc \u05d5\u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd."],[324.0,"\u05d1\u05d3\u05d9\u05e7\u05d5\u05ea \u05db\u05de\u05d5 \u05d0\u05d5\u05dc\u05d8\u05e8\u05e1\u05d0\u05d5\u05e0\u05d3."],[326.0,"\u05d5\u05ea\u05d5\u05e1\u05e4\u05ea \u05d4\u05e2\u05d9\u05d1\u05d5\u05d3, \u05e9\u05d5\u05d1: \u05db\u05dc \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8 \u05d4\u05d5\u05d0 \u05d6\u05de\u05df \u05de\u05db\u05d5\u05e0\u05d4."],[332.0,"\u05d0\u05d6\u05de\u05ea\u05d9\u05dc\u05d7\u05e9\u05dc?"],[334.0,"\u05db\u05e9\u05d4\u05d7\u05dc\u05e7 \u05e0\u05d5\u05e9\u05d0 \u05e2\u05d5\u05de\u05e1 \u05d2\u05d1\u05d5\u05d4, \u05e2\u05d9\u05d9\u05e4\u05d5\u05ea \u05d0\u05d5 \u05d4\u05dc\u05dd, \u05d5\u05db\u05e9\u05d4\u05db\u05e9\u05dc \u05e9\u05dc\u05d5 \u05de\u05e1\u05d5\u05db\u05df."],[340.0,"\u05d1\u05e1\u05d3\u05e8\u05d5\u05ea, \u05d7\u05d9\u05e9\u05d5\u05dc \u05e7\u05e8\u05d5\u05d1 \u05dc\u05e6\u05d5\u05e8\u05d4 \u05d4\u05e1\u05d5\u05e4\u05d9\u05ea \u05d7\u05d5\u05e1\u05da \u05d7\u05d5\u05de\u05e8 \u05d5\u05d6\u05de\u05df \u05e2\u05d9\u05d1\u05d5\u05d3 \u05dc\u05e2\u05d5\u05de\u05ea \u05e2\u05d9\u05d1\u05d5\u05d3 \u05de\u05d2\u05d5\u05e9."],[346.0,"\u05d0\u05d1\u05dc \u05e6\u05d5\u05e8\u05d5\u05ea \u05e4\u05e0\u05d9\u05de\u05d9\u05d5\u05ea \u05de\u05d5\u05e8\u05db\u05d1\u05d5\u05ea, \u05d7\u05dc\u05dc\u05d9\u05dd \u05d5\u05e7\u05d9\u05e8\u05d5\u05ea \u05d3\u05e7\u05d9\u05dd \u05e7\u05e9\u05d9\u05dd \u05dc\u05d7\u05d9\u05e9\u05d5\u05dc, \u05d5\u05e9\u05dd \u05d4\u05d9\u05e6\u05d9\u05e7\u05d4 \u05de\u05e0\u05e6\u05d7\u05ea."],[354.0,"\u05d5\u05d1\u05d7\u05dc\u05e7 \u05d1\u05d5\u05d3\u05d3, \u05dc\u05e8\u05d5\u05d1 \u05e4\u05e9\u05d5\u05d8 \u05d9\u05d5\u05ea\u05e8 \u05dc\u05e2\u05d1\u05d3 \u05de\u05d2\u05d5\u05e9, \u05d0\u05d5 \u05de\u05d7\u05d9\u05e9\u05d5\u05dc \u05e4\u05ea\u05d5\u05d7."],[359.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0 \u05e0\u05db\u05d9\u05e8 \u05e2\u05d5\u05d3 \u05d3\u05e8\u05da \u05dc\u05e2\u05e6\u05d1 \u05de\u05ea\u05db\u05ea \u05d1\u05db\u05d5\u05d7: \u05e9\u05d9\u05d7\u05d5\u05dc."]]};
window.MH_TR["\u05e4\u05e8\u05e703_\u05e9\u05d9\u05d7\u05d5\u05dc"]={"t":"\u05e9\u05d9\u05d7\u05d5\u05dc","l":[[1.0,"\u05de\u05e1\u05d9\u05dc\u05d5\u05ea, \u05e6\u05d9\u05e0\u05d5\u05e8\u05d5\u05ea, \u05de\u05e1\u05d2\u05e8\u05d5\u05ea \u05e9\u05dc \u05d7\u05dc\u05d5\u05e0\u05d5\u05ea, \u05d5\u05d2\u05d5\u05e4\u05d9 \u05e7\u05d9\u05e8\u05d5\u05e8 \u05e2\u05dd \u05e2\u05e9\u05e8\u05d5\u05ea \u05e6\u05dc\u05e2\u05d5\u05ea."],[7.0,"\u05dc\u05db\u05d5\u05dc\u05dd \u05d9\u05e9 \u05d3\u05d1\u05e8 \u05d0\u05d7\u05d3 \u05de\u05e9\u05d5\u05ea\u05e3: \u05d7\u05ea\u05da \u05e7\u05d1\u05d5\u05e2 \u05dc\u05db\u05dc \u05d4\u05d0\u05d5\u05e8\u05da."],[12.0,"\u05d0\u05ea \u05e8\u05d5\u05d1\u05dd \u05de\u05d9\u05d9\u05e6\u05e8\u05d9\u05dd \u05d1\u05e9\u05d9\u05d7\u05d5\u05dc."],[14.0,"\u05d4\u05e8\u05e2\u05d9\u05d5\u05df \u05d3\u05d5\u05de\u05d4 \u05dc\u05dc\u05d7\u05d9\u05e6\u05d4 \u05e2\u05dc \u05e9\u05e4\u05d5\u05e4\u05e8\u05ea \u05de\u05e9\u05d5\u05d7\u05ea \u05e9\u05d9\u05e0\u05d9\u05d9\u05dd: \u05d4\u05d7\u05d5\u05de\u05e8 \u05d9\u05d5\u05e6\u05d0 \u05d3\u05e8\u05da \u05e4\u05ea\u05d7, \u05d5\u05de\u05e7\u05d1\u05dc \u05d0\u05ea \u05e6\u05d5\u05e8\u05ea \u05d4\u05e4\u05ea\u05d7."],[22.0,"\u05de\u05d7\u05de\u05de\u05d9\u05dd \u05d2\u05d5\u05e9 \u05d2\u05dc\u05d9\u05dc\u05d9 \u05e9\u05dc \u05de\u05ea\u05db\u05ea, \u05d5\u05de\u05db\u05e0\u05d9\u05e1\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5 \u05dc\u05ea\u05d5\u05da \u05de\u05db\u05dc."],[26.0,"\u05d1\u05d5\u05db\u05e0\u05d4 \u05d3\u05d5\u05d7\u05e4\u05ea \u05d0\u05ea \u05d4\u05d2\u05d5\u05e9 \u05d1\u05db\u05d5\u05d7 \u05e2\u05e6\u05d5\u05dd \u05d0\u05dc \u05ea\u05d1\u05e0\u05d9\u05ea, \u05e9\u05d9\u05e9 \u05d1\u05d4 \u05e4\u05ea\u05d7 \u05d1\u05e6\u05d5\u05e8\u05ea \u05d4\u05d7\u05ea\u05df."],[32.0,"\u05d4\u05de\u05ea\u05db\u05ea \u05d6\u05d5\u05e8\u05de\u05ea \u05d3\u05e8\u05da \u05d4\u05e4\u05ea\u05d7, \u05d5\u05d9\u05d5\u05e6\u05d0\u05ea \u05de\u05d4\u05e6\u05d3 \u05d4\u05e9\u05e0\u05d9 \u05d1\u05e6\u05d5\u05e8\u05ea \u05e4\u05e8\u05d5\u05e4\u05d9\u05dc \u05d0\u05e8\u05d5\u05da."],[38.0,"\u05d4\u05d9\u05d7\u05e1 \u05d1\u05d9\u05df \u05e9\u05d8\u05d7 \u05d4\u05d7\u05ea\u05da \u05e9\u05dc \u05d4\u05d2\u05d5\u05e9 \u05dc\u05e9\u05d8\u05d7 \u05d4\u05d7\u05ea\u05da \u05e9\u05dc \u05d4\u05e4\u05e8\u05d5\u05e4\u05d9\u05dc \u05e0\u05e7\u05e8\u05d0 \u05d9\u05d7\u05e1 \u05d4\u05e9\u05d9\u05d7\u05d5\u05dc."],[44.0,"\u05d1\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05d4\u05d9\u05d7\u05e1 \u05d4\u05d6\u05d4 \u05de\u05d2\u05d9\u05e2 \u05dc\u05e2\u05ea\u05d9\u05dd \u05e7\u05e8\u05d5\u05d1\u05d5\u05ea \u05dc\u05e2\u05e9\u05e8\u05d5\u05ea, \u05d5\u05de\u05d2\u05d5\u05e9 \u05d0\u05d7\u05d3 \u05d9\u05d5\u05e6\u05d0 \u05e4\u05e8\u05d5\u05e4\u05d9\u05dc \u05d1\u05d0\u05d5\u05e8\u05da \u05e9\u05dc \u05e2\u05e9\u05e8\u05d5\u05ea \u05de\u05d8\u05e8\u05d9\u05dd."],[52.0,"\u05d1\u05d3\u05e8\u05da \u05d6\u05d5 \u05de\u05e7\u05d1\u05dc\u05d9\u05dd \u05e6\u05d5\u05e8\u05d5\u05ea \u05e9\u05e7\u05e9\u05d4 \u05de\u05d0\u05d5\u05d3 \u05dc\u05e7\u05d1\u05dc \u05d1\u05db\u05dc \u05d3\u05e8\u05da \u05d0\u05d7\u05e8\u05ea, \u05d5\u05d1\u05d0\u05d5\u05e8\u05da \u05db\u05de\u05e2\u05d8 \u05d1\u05dc\u05ea\u05d9 \u05de\u05d5\u05d2\u05d1\u05dc."],[59.0,"\u05d9\u05e9 \u05e9\u05ea\u05d9 \u05d3\u05e8\u05db\u05d9\u05dd \u05e2\u05d9\u05e7\u05e8\u05d9\u05d5\u05ea \u05dc\u05e9\u05d7\u05dc."],[62.0,"\u05d1\u05e9\u05d9\u05d7\u05d5\u05dc \u05d9\u05e9\u05d9\u05e8, \u05d4\u05d1\u05d5\u05db\u05e0\u05d4 \u05d3\u05d5\u05d7\u05e4\u05ea \u05d0\u05ea \u05d4\u05d2\u05d5\u05e9, \u05d5\u05d4\u05d5\u05d0 \u05de\u05d7\u05dc\u05d9\u05e7 \u05dc\u05d0\u05d5\u05e8\u05da \u05d3\u05d5\u05e4\u05df \u05d4\u05de\u05db\u05dc."],[67.0,"\u05d4\u05d7\u05d9\u05db\u05d5\u05da \u05e2\u05dd \u05d4\u05d3\u05d5\u05e4\u05df \u05d3\u05d5\u05e8\u05e9 \u05db\u05d5\u05d7 \u05de\u05e1\u05e3, \u05d5\u05d4\u05db\u05d5\u05d7 \u05d4\u05d2\u05d1\u05d5\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05d4\u05d5\u05d0 \u05d1\u05d4\u05ea\u05d7\u05dc\u05d4, \u05db\u05e9\u05d4\u05d2\u05d5\u05e9 \u05d4\u05d0\u05e8\u05d5\u05da \u05d1\u05d9\u05d5\u05ea\u05e8."],[74.0,"\u05d1\u05e9\u05d9\u05d7\u05d5\u05dc \u05e2\u05e7\u05d9\u05e3, \u05d4\u05d2\u05d5\u05e9 \u05dc\u05d0 \u05d6\u05d6 \u05d1\u05d9\u05d7\u05e1 \u05dc\u05de\u05db\u05dc, \u05d5\u05d4\u05ea\u05d1\u05e0\u05d9\u05ea \u05e0\u05d3\u05d7\u05e4\u05ea \u05dc\u05ea\u05d5\u05db\u05d5."],[80.0,"\u05d0\u05d9\u05df \u05d7\u05d9\u05db\u05d5\u05da \u05e2\u05dd \u05d4\u05d3\u05d5\u05e4\u05df, \u05d5\u05dc\u05db\u05df \u05e6\u05e8\u05d9\u05da \u05e4\u05d7\u05d5\u05ea \u05db\u05d5\u05d7, \u05d0\u05d1\u05dc \u05d4\u05de\u05ea\u05e7\u05df \u05de\u05d5\u05e8\u05db\u05d1 \u05d9\u05d5\u05ea\u05e8."],[87.0,"\u05e8\u05d5\u05d1 \u05d4\u05e9\u05d9\u05d7\u05d5\u05dc \u05e0\u05e2\u05e9\u05d4 \u05d1\u05d7\u05d5\u05dd."],[89.0,"\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05de\u05e9\u05d7\u05dc\u05d9\u05dd \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1\u05e2\u05e8\u05da 400 \u05e2\u05d3 500 \u05de\u05e2\u05dc\u05d5\u05ea, \u05d5\u05d4\u05d5\u05d0 \u05d4\u05d7\u05d5\u05de\u05e8 \u05d4\u05e0\u05e4\u05d5\u05e5 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05dc\u05e9\u05d9\u05d7\u05d5\u05dc."],[96.0,"\u05d0\u05d1\u05dc \u05d0\u05dc\u05d4 \u05d3\u05d5\u05e8\u05e9\u05d5\u05d9\u05dd \u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d5\u05ea \u05d5\u05db\u05d5\u05d7\u05d5\u05ea \u05d2\u05d1\u05d5\u05d4\u05d9\u05dd \u05d1\u05d4\u05e8\u05d1\u05d4, \u05d5\u05e1\u05d9\u05db\u05d4 \u05de\u05d9\u05d5\u05d7\u05d3\u05ea."],[107.0,"\u05d1\u05e9\u05d9\u05d7\u05d5\u05dc \u05e7\u05e8, \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05d4\u05d7\u05d3\u05e8, \u05de\u05d5\u05d7\u05e6\u05d9\u05dd \u05d2\u05d5\u05e9 \u05e7\u05d8\u05df \u05d1\u05de\u05db\u05d4 \u05de\u05d4\u05d9\u05e8\u05d4."],[112.0,"\u05db\u05da \u05de\u05d9\u05d9\u05e6\u05e8\u05d9\u05dd, \u05dc\u05de\u05e9\u05dc, \u05e4\u05d7\u05d9\u05d5\u05ea \u05ea\u05e8\u05e1\u05d9\u05e1, \u05e9\u05e4\u05d5\u05e4\u05e8\u05d5\u05ea \u05d5\u05d1\u05ea\u05d9 \u05e1\u05d5\u05dc\u05dc\u05d5\u05ea."],[118.0,"\u05d0\u05d9\u05da \u05de\u05e9\u05d7\u05dc\u05d9\u05dd \u05e6\u05d9\u05e0\u05d5\u05e8, \u05d0\u05d5 \u05e4\u05e8\u05d5\u05e4\u05d9\u05dc \u05e2\u05dd \u05d7\u05dc\u05dc\u05d9\u05dd \u05e1\u05d2\u05d5\u05e8\u05d9\u05dd?"],[122.0,"\u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05ea\u05d1\u05e0\u05d9\u05ea \u05de\u05d9\u05d5\u05d7\u05d3\u05ea, \u05e9\u05d9\u05e9 \u05d1\u05d4 \u05dc\u05d9\u05d1\u05d4 \u05e9\u05de\u05d7\u05d6\u05d9\u05e7\u05d9\u05dd \u05d0\u05d5\u05ea\u05d4 \u05d2\u05e9\u05e8\u05d9\u05dd \u05d3\u05e7\u05d9\u05dd."],[127.0,"\u05d4\u05de\u05ea\u05db\u05ea \u05de\u05ea\u05e4\u05e6\u05dc\u05ea \u05e1\u05d1\u05d9\u05d1 \u05d4\u05d2\u05e9\u05e8\u05d9\u05dd, \u05d5\u05de\u05ea\u05d0\u05d7\u05d3\u05ea \u05e9\u05d5\u05d1 \u05d1\u05ea\u05d0 \u05e9\u05de\u05e1\u05d1\u05d9\u05d1 \u05dc\u05dc\u05d9\u05d1\u05d4, \u05dc\u05e4\u05e0\u05d9 \u05e9\u05d4\u05d9\u05d0 \u05d9\u05d5\u05e6\u05d0\u05ea."],[134.0,"\u05d1\u05de\u05e7\u05d5\u05de\u05d5\u05ea \u05e9\u05d1\u05d4\u05dd \u05d4\u05d6\u05e8\u05de\u05d9\u05dd \u05de\u05ea\u05d0\u05d7\u05d3\u05d9\u05dd \u05e0\u05d5\u05e6\u05e8\u05d9\u05dd \u05e7\u05d5\u05d5\u05d9 \u05e8\u05d9\u05ea\u05d5\u05da \u05dc\u05d0\u05d5\u05e8\u05da \u05d4\u05e4\u05e8\u05d5\u05e4\u05d9\u05dc."],[139.0,"\u05d1\u05e9\u05d9\u05d7\u05d5\u05dc \u05d7\u05dd \u05d4\u05d6\u05e8\u05de\u05d9\u05dd \u05de\u05ea\u05e8\u05ea\u05db\u05d9\u05dd \u05d4\u05d9\u05d8\u05d1, \u05d0\u05d1\u05dc \u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05e7\u05e8\u05d9\u05d8\u05d9\u05d9\u05dd \u05dc\u05d5\u05e7\u05d7\u05d9\u05dd \u05d0\u05ea \u05d4\u05e7\u05d5\u05d5\u05d9\u05dd \u05d4\u05d0\u05dc\u05d4 \u05d1\u05d7\u05e9\u05d1\u05d5\u05df."],[146.0,"\u05db\u05e9\u05d0\u05e1\u05d5\u05e8 \u05e9\u05d9\u05d4\u05d9\u05d4 \u05ea\u05e4\u05e8, \u05de\u05e9\u05d7\u05dc\u05d9\u05dd \u05d2\u05d5\u05e9 \u05d7\u05dc\u05d5\u05dc \u05e1\u05d1\u05d9\u05d1 \u05de\u05d5\u05d8 \u05de\u05e8\u05db\u05d6\u05d9, \u05d5\u05de\u05e7\u05d1\u05dc\u05d9\u05dd \u05e6\u05d9\u05e0\u05d5\u05e8 \u05d1\u05dc\u05d9 \u05e7\u05d5\u05d5\u05d9 \u05e8\u05d9\u05ea\u05d5\u05da."],[154.0,"\u05d4\u05e4\u05e8\u05d5\u05e4\u05d9\u05dc \u05d9\u05d5\u05e6\u05d0 \u05d7\u05dd, \u05d5\u05de\u05e7\u05e8\u05e8\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5 \u05d1\u05d0\u05d5\u05d5\u05d9\u05e8 \u05d0\u05d5 \u05d1\u05de\u05d9\u05dd."],[158.0,"\u05d0\u05d7\u05e8 \u05db\u05da \u05de\u05d5\u05ea\u05d7\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5 \u05de\u05e2\u05d8, \u05db\u05d3\u05d9 \u05dc\u05d9\u05d9\u05e9\u05e8 \u05d0\u05d5\u05ea\u05d5 \u05d5\u05dc\u05d4\u05d5\u05e8\u05d9\u05d3 \u05de\u05d0\u05de\u05e6\u05d9\u05dd."],[162.0,"\u05d7\u05d5\u05ea\u05db\u05d9\u05dd \u05dc\u05d0\u05d5\u05e8\u05da, \u05d5\u05d1\u05e1\u05d2\u05e1\u05d5\u05d2\u05d5\u05ea \u05e8\u05d1\u05d5\u05ea \u05e9\u05dc \u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05de\u05d1\u05e6\u05e2\u05d9\u05dd \u05d4\u05e7\u05e9\u05d9\u05d4 \u05d1\u05d4\u05d6\u05d3\u05e7\u05e0\u05d5\u05ea, \u05e9\u05de\u05e2\u05dc\u05d4 \u05d0\u05ea \u05d4\u05d7\u05d5\u05d6\u05e7."],[170.0,"\u05d0\u05ea \u05d4\u05e7\u05e6\u05d4 \u05e9\u05dc \u05d4\u05d2\u05d5\u05e9, \u05e9\u05e0\u05e9\u05d0\u05e8 \u05d1\u05de\u05db\u05dc, \u05dc\u05d0 \u05de\u05e9\u05d7\u05dc\u05d9\u05dd \u05e2\u05d3 \u05d4\u05e1\u05d5\u05e3: \u05d7\u05d5\u05ea\u05db\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5 \u05d5\u05e9\u05d5\u05dc\u05d7\u05d9\u05dd \u05dc\u05de\u05d9\u05d7\u05d6\u05d5\u05e8."],[177.0,"\u05d2\u05dd \u05e4\u05e8\u05d5\u05e4\u05d9\u05dc \u05dc\u05e9\u05d9\u05d7\u05d5\u05dc \u05de\u05ea\u05db\u05e0\u05e0\u05d9\u05dd \u05dc\u05e4\u05d9 \u05db\u05dc\u05dc\u05d9\u05dd."],[180.0,"\u05e2\u05d5\u05d1\u05d9 \u05d3\u05d5\u05e4\u05df \u05d0\u05d7\u05d9\u05d3 \u05db\u05db\u05dc \u05d4\u05d0\u05e4\u05e9\u05e8: \u05d7\u05dc\u05e7 \u05e2\u05d1\u05d4 \u05d6\u05d5\u05e8\u05dd \u05de\u05d4\u05e8 \u05d9\u05d5\u05ea\u05e8 \u05de\u05d7\u05dc\u05e7 \u05d3\u05e7, \u05d5\u05d4\u05e4\u05e8\u05d5\u05e4\u05d9\u05dc \u05de\u05ea\u05e2\u05e7\u05dd."],[188.0,"\u05e4\u05d9\u05e0\u05d5\u05ea \u05de\u05e2\u05d5\u05d2\u05dc\u05d5\u05ea, \u05db\u05d3\u05d9 \u05e9\u05d4\u05d7\u05d5\u05de\u05e8 \u05d9\u05d6\u05e8\u05d5\u05dd \u05d1\u05e7\u05dc\u05d5\u05ea \u05d5\u05d4\u05ea\u05d1\u05e0\u05d9\u05ea \u05dc\u05d0 \u05ea\u05d9\u05e1\u05d3\u05e7."],[192.0,"\u05d5\u05dc\u05d0 \u05ea\u05e2\u05dc\u05d5\u05ea \u05e2\u05de\u05d5\u05e7\u05d5\u05ea \u05d5\u05e6\u05e8\u05d5\u05ea: \u05d4\u05d7\u05dc\u05e7 \u05e9\u05dc \u05d4\u05ea\u05d1\u05e0\u05d9\u05ea \u05e9\u05d9\u05d5\u05e6\u05e8 \u05d0\u05d5\u05ea\u05df \u05d3\u05e7 \u05d5\u05d0\u05e8\u05d5\u05da, \u05d5\u05e2\u05dc\u05d5\u05dc \u05dc\u05d4\u05d9\u05e9\u05d1\u05e8."],[200.0,"\u05e4\u05e8\u05d5\u05e4\u05d9\u05dc \u05e1\u05d9\u05de\u05d8\u05e8\u05d9 \u05d5\u05e7\u05d8\u05df \u05d9\u05d5\u05ea\u05e8 \u05e0\u05d5\u05d7 \u05d9\u05d5\u05ea\u05e8 \u05dc\u05e9\u05d9\u05d7\u05d5\u05dc, \u05d5\u05de\u05e7\u05d1\u05dc \u05d8\u05d5\u05dc\u05e8\u05e0\u05e1 \u05d4\u05d3\u05d5\u05e7 \u05d9\u05d5\u05ea\u05e8."],[206.0,"\u05d2\u05dd \u05d1\u05e9\u05d9\u05d7\u05d5\u05dc \u05d9\u05e9 \u05e4\u05d2\u05de\u05d9\u05dd \u05d0\u05d5\u05e4\u05d9\u05d9\u05e0\u05d9\u05d9\u05dd."],[208.0,"\u05e7\u05d5\u05d5\u05d9 \u05ea\u05d1\u05e0\u05d9\u05ea: \u05e4\u05e1\u05d9\u05dd \u05d3\u05e7\u05d9\u05dd \u05dc\u05d0\u05d5\u05e8\u05da \u05d4\u05e4\u05e8\u05d5\u05e4\u05d9\u05dc, \u05de\u05e9\u05d7\u05d9\u05e7\u05d4 \u05d0\u05d5 \u05de\u05dc\u05db\u05dc\u05d5\u05da \u05e2\u05dc \u05d4\u05ea\u05d1\u05e0\u05d9\u05ea."],[215.0,"\u05e1\u05d3\u05e7\u05d9\u05dd \u05e2\u05dc \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7, \u05db\u05e9\u05de\u05e9\u05d7\u05dc\u05d9\u05dd \u05de\u05d4\u05e8 \u05de\u05d3\u05d9 \u05d0\u05d5 \u05d7\u05dd \u05de\u05d3\u05d9."],[219.0,"\u05d1\u05d5\u05e2\u05d5\u05ea, \u05de\u05d0\u05d5\u05d5\u05d9\u05e8 \u05d0\u05d5 \u05de\u05d2\u05d6 \u05e9\u05e0\u05dc\u05db\u05d3 \u05d1\u05d9\u05df \u05d4\u05d2\u05d5\u05e9 \u05dc\u05de\u05db\u05dc."],[224.0,"\u05d5\u05e4\u05d9\u05ea\u05d5\u05dc \u05d5\u05e2\u05d9\u05e7\u05d5\u05dd, \u05db\u05e9\u05d4\u05d6\u05e8\u05d9\u05de\u05d4 \u05dc\u05d0 \u05de\u05d0\u05d5\u05d6\u05e0\u05ea."],[228.0,"\u05d5\u05de\u05d4 \u05d6\u05d4 \u05d0\u05d5\u05de\u05e8 \u05dc\u05de\u05d9 \u05e9\u05de\u05e2\u05d1\u05d3 \u05e4\u05e8\u05d5\u05e4\u05d9\u05dc\u05d9\u05dd?"],[230.0,"\u05e4\u05e8\u05d5\u05e4\u05d9\u05dc \u05d0\u05d9\u05e0\u05d5 \u05d9\u05e9\u05e8\u05d5\u05e9\u05d8\u05d5\u05d7 \u05dc\u05d2\u05de\u05e8\u05d9: \u05d9\u05e9 \u05dc\u05d5 \u05e2\u05d9\u05e7\u05d5\u05dd \u05d5\u05e4\u05d9\u05ea\u05d5\u05dc, \u05d1\u05ea\u05d5\u05da \u05d4\u05d8\u05d5\u05dc\u05e8\u05e0\u05e1 \u05e9\u05dc \u05d4\u05ea\u05e7\u05df."],[237.0,"\u05dc\u05db\u05df \u05dc\u05d5\u05e7\u05d7\u05d9\u05dd \u05d9\u05d9\u05d7\u05d5\u05e1 \u05de\u05de\u05e9\u05d8\u05d7 \u05de\u05e2\u05d5\u05d1\u05d3, \u05d5\u05dc\u05d0 \u05e1\u05d5\u05de\u05db\u05d9\u05dd \u05e2\u05dc \u05d4\u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05d4\u05d2\u05d5\u05dc\u05de\u05d9\u05d9\u05dd \u05dc\u05de\u05d9\u05d3\u05d5\u05ea \u05de\u05d3\u05d5\u05d9\u05e7\u05d5\u05ea."],[243.0,"\u05d3\u05e4\u05e0\u05d5\u05ea \u05d3\u05e7\u05d5\u05ea \u05e8\u05d5\u05d8\u05d8\u05d5\u05ea \u05d5\u05de\u05ea\u05db\u05d5\u05e4\u05e4\u05d5\u05ea \u05ea\u05d7\u05ea \u05db\u05d5\u05d7\u05d5\u05ea \u05d4\u05d7\u05d9\u05ea\u05d5\u05da \u05d5\u05d4\u05ea\u05e4\u05d9\u05e1\u05d4, \u05d5\u05dc\u05db\u05df \u05ea\u05d5\u05de\u05db\u05d9\u05dd \u05d1\u05d4\u05df \u05d5\u05dc\u05d0 \u05de\u05d4\u05d3\u05e7\u05d9\u05dd \u05d7\u05d6\u05e7 \u05de\u05d3\u05d9."],[252.0,"\u05d5\u05db\u05d9\u05d5\u05d5\u05df \u05e9\u05d4\u05d7\u05ea\u05da \u05db\u05d1\u05e8 \u05e7\u05e8\u05d5\u05d1 \u05dc\u05e1\u05d5\u05e4\u05d9, \u05dc\u05e8\u05d5\u05d1 \u05e0\u05e9\u05d0\u05e8\u05d5\u05ea \u05e8\u05e7 \u05e4\u05e2\u05d5\u05dc\u05d5\u05ea \u05e7\u05e6\u05e8\u05d5\u05ea: \u05d7\u05d9\u05ea\u05d5\u05da \u05dc\u05d0\u05d5\u05e8\u05da, \u05e7\u05d9\u05d3\u05d5\u05d7 \u05d5\u05db\u05e8\u05e1\u05d5\u05dd \u05de\u05e7\u05d5\u05de\u05d9."],[261.0,"\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8 \u05e9\u05d9\u05d7\u05d5\u05dc?"],[263.0,"\u05d7\u05d9\u05e9\u05d5\u05dc \u05d0\u05d5 \u05e9\u05dc \u05d9\u05e6\u05d9\u05e7\u05ea \u05dc\u05d7\u05e5, \u05d5\u05dc\u05db\u05df \u05d2\u05dd \u05e4\u05e8\u05d5\u05e4\u05d9\u05dc \u05de\u05d9\u05d5\u05d7\u05d3 \u05de\u05e9\u05ea\u05dc\u05dd \u05d1\u05db\u05de\u05d5\u05d9\u05d5\u05ea \u05d1\u05d9\u05e0\u05d5\u05e0\u05d9\u05d5\u05ea."],[273.0,"\u05d0\u05d1\u05dc \u05d9\u05e9 \u05db\u05de\u05d5\u05ea \u05de\u05d9\u05e0\u05d9\u05de\u05dc\u05d9\u05ea: \u05de\u05e9\u05d7\u05dc\u05d9\u05dd \u05d2\u05d5\u05e9\u05d9\u05dd \u05e9\u05dc\u05de\u05d9\u05dd, \u05d5\u05de\u05e7\u05d1\u05dc\u05d9\u05dd \u05e2\u05e9\u05e8\u05d5\u05ea \u05de\u05d8\u05e8\u05d9\u05dd \u05d1\u05db\u05dc \u05e4\u05e2\u05dd."],[279.0,"\u05e4\u05d7\u05ea: \u05e9\u05d0\u05e8\u05d9\u05ea \u05d4\u05d2\u05d5\u05e9, \u05d5\u05d4\u05e7\u05e6\u05d5\u05d5\u05ea \u05e9\u05e0\u05d7\u05ea\u05db\u05d9\u05dd \u05d0\u05d7\u05e8\u05d9 \u05d4\u05de\u05ea\u05d9\u05d7\u05d4."],[284.0,"\u05e4\u05e8\u05d5\u05e4\u05d9\u05dc \u05de\u05d5\u05e8\u05db\u05d1, \u05e2\u05dd \u05d7\u05dc\u05dc\u05d9\u05dd \u05d5\u05d3\u05e4\u05e0\u05d5\u05ea \u05d3\u05e7\u05d5\u05ea, \u05de\u05e9\u05d7\u05dc\u05d9\u05dd \u05dc\u05d0\u05d8 \u05d9\u05d5\u05ea\u05e8, \u05d5\u05d4\u05ea\u05d1\u05e0\u05d9\u05ea \u05e9\u05dc\u05d5 \u05e0\u05e9\u05d7\u05e7\u05ea \u05de\u05d4\u05e8 \u05d9\u05d5\u05ea\u05e8."],[291.0,"\u05d5\u05e4\u05e2\u05d5\u05dc\u05d5\u05ea \u05e0\u05d5\u05e1\u05e4\u05d5\u05ea: \u05d4\u05e7\u05e9\u05d9\u05d4 \u05d1\u05d4\u05d6\u05d3\u05e7\u05e0\u05d5\u05ea, \u05d0\u05d9\u05dc\u05d2\u05d5\u05df \u05d0\u05d5 \u05e6\u05d1\u05d9\u05e2\u05d4, \u05d5\u05e2\u05d9\u05d1\u05d5\u05d3."],[298.0,"\u05d0\u05d6\u05de\u05ea\u05d9\u05dc\u05e9\u05d7\u05dc?"],[299.0,"\u05db\u05e9\u05d4\u05d7\u05dc\u05e7 \u05d0\u05e8\u05d5\u05da, \u05d5\u05d9\u05e9 \u05dc\u05d5 \u05d7\u05ea\u05da \u05e7\u05d1\u05d5\u05e2."],[303.0,"\u05db\u05e9\u05d0\u05e4\u05e9\u05e8 \u05dc\u05e7\u05e0\u05d5\u05ea \u05e4\u05e8\u05d5\u05e4\u05d9\u05dc \u05e7\u05e8\u05d5\u05d1 \u05dc\u05e6\u05d5\u05e8\u05d4 \u05d4\u05e1\u05d5\u05e4\u05d9\u05ea, \u05d5\u05dc\u05d7\u05e1\u05d5\u05da \u05d4\u05e8\u05d1\u05d4 \u05e2\u05d9\u05d1\u05d5\u05d3 \u05de\u05d2\u05d5\u05e9."],[308.0,"\u05d5\u05db\u05e9\u05d4\u05d7\u05d5\u05de\u05e8 \u05de\u05ea\u05d0\u05d9\u05dd, \u05d1\u05e2\u05d9\u05e7\u05e8 \u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd."],[311.0,"\u05d1\u05d6\u05d4 \u05e1\u05d9\u05d9\u05de\u05e0\u05d5 \u05d0\u05ea \u05d4\u05d3\u05e8\u05db\u05d9\u05dd \u05dc\u05d9\u05d9\u05e6\u05e8 \u05d0\u05ea \u05d7\u05d5\u05de\u05e8 \u05d4\u05d2\u05dc\u05dd \u05d5\u05d0\u05ea \u05d4\u05e6\u05d5\u05e8\u05d4 \u05d4\u05e8\u05d0\u05e9\u05d5\u05e0\u05d9\u05ea."],[316.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0 \u05e0\u05ea\u05d7\u05d9\u05dc \u05d1\u05e2\u05d9\u05d1\u05d5\u05d3 \u05d4\u05e9\u05d1\u05d1\u05d9, \u05e2\u05dd \u05d4\u05ea\u05d4\u05dc\u05d9\u05da \u05d4\u05e0\u05e1\u05d5\u05e5 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05d7\u05e8\u05d9\u05d8\u05d4."]]};
window.MH_TR["\u05e4\u05e8\u05e704_\u05d7\u05e8\u05d9\u05d8\u05d4"]={"t":"\u05d7\u05e8\u05d9\u05d8\u05d4","l":[[1.0,"\u05d2\u05dc\u05d9\u05dd, \u05e4\u05d9\u05e0\u05d9\u05dd, \u05ea\u05d5\u05ea\u05d1\u05d9\u05dd \u05d5\u05d1\u05e8\u05d2\u05d9\u05dd: \u05db\u05de\u05e2\u05d8 \u05db\u05dc \u05d7\u05dc\u05e7 \u05e2\u05d2\u05d5\u05dc \u05e2\u05d5\u05d1\u05e8 \u05d1\u05de\u05d7\u05e8\u05d8\u05d4."],[7.0,"\u05d7\u05e8\u05d9\u05d8\u05d4 \u05d4\u05d9\u05d0 \u05ea\u05d4\u05dc\u05d9\u05da \u05d4\u05e2\u05d9\u05d1\u05d5\u05d3 \u05d4\u05e9\u05d1\u05d1\u05d9 \u05d4\u05e0\u05e4\u05d5\u05e5 \u05d1\u05d9\u05d5\u05ea\u05e8."],[11.0,"\u05d4\u05e2\u05d9\u05e7\u05e8\u05d5\u05df: \u05d4\u05d7\u05dc\u05e7 \u05de\u05e1\u05ea\u05d5\u05d1\u05d1, \u05d5\u05d4\u05db\u05dc\u05d9 \u05e0\u05e2 \u05dc\u05d0\u05d5\u05e8\u05da \u05d4\u05d7\u05dc\u05e7 \u05d0\u05d5 \u05dc\u05db\u05d9\u05d5\u05d5\u05df \u05d4\u05de\u05e8\u05db\u05d6 \u05e9\u05dc\u05d5, \u05d5\u05de\u05e1\u05d9\u05e8 \u05e9\u05db\u05d1\u05d4 \u05e9\u05dc \u05d7\u05d5\u05de\u05e8."],[20.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d6\u05d4 \u05e0\u05db\u05d9\u05e8 \u05d0\u05ea \u05d4\u05de\u05db\u05d5\u05e0\u05d4, \u05d0\u05ea \u05d4\u05e4\u05e2\u05d5\u05dc\u05d5\u05ea, \u05d0\u05ea \u05d4\u05db\u05dc\u05d9\u05dd, \u05d5\u05d0\u05ea \u05de\u05d4 \u05e9\u05e7\u05d5\u05d1\u05e2 \u05d3\u05d9\u05d5\u05e7 \u05d5\u05e2\u05dc\u05d5\u05ea."],[27.0,"\u05d1\u05e6\u05d3 \u05d4\u05e9\u05de\u05d0\u05dc\u05d9 \u05e0\u05de\u05e6\u05d0 \u05e8\u05d0\u05e9 \u05d4\u05de\u05db\u05d5\u05e0\u05d4, \u05d5\u05d1\u05d5 \u05d4\u05e6\u05d9\u05e8 \u05d4\u05e8\u05d0\u05e9\u05d9 \u05e9\u05de\u05e1\u05d5\u05d1\u05d1 \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7."],[33.0,"\u05e2\u05dc \u05d4\u05e6\u05d9\u05e8 \u05de\u05d5\u05e8\u05db\u05d1 \u05e4\u05d5\u05d8\u05e8, \u05e2\u05dd \u05e9\u05dc\u05d5\u05e9 \u05dc\u05e1\u05ea\u05d5\u05ea \u05e9\u05ea\u05d5\u05e4\u05e1\u05d5\u05ea \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7."],[38.0,"\u05de\u05d7\u05d6\u05d9\u05e7 \u05d4\u05e1\u05d9\u05de\u05d4 \u05de\u05d7\u05d5\u05d1\u05e8 \u05dc\u05e6\u05e8\u05d9\u05d7, \u05e9\u05e0\u05e2 \u05d1\u05e9\u05e0\u05d9 \u05e6\u05d9\u05e8\u05d9\u05dd: \u05dc\u05d0\u05d5\u05e8\u05da \u05d4\u05d7\u05dc\u05e7, \u05d5\u05d1\u05e0\u05d9\u05e6\u05d1 \u05dc\u05d5."],[44.0,"\u05d1\u05de\u05db\u05d5\u05e0\u05d5\u05ea \u05de\u05e7\u05d5\u05d1\u05dc \u05dc\u05e7\u05e8\u05d5\u05d0 \u05dc\u05e6\u05d9\u05e8 \u05d4\u05d0\u05d5\u05e8\u05da 7, \u05d5\u05dc\u05e6\u05d9\u05e8 \u05d4\u05e7\u05d5\u05d8\u05e8 \u05d0."],[49.0,"\u05d1\u05e6\u05d3 \u05d4\u05e9\u05e0\u05d9 \u05d9\u05e9 \u05d2\u05d5\u05e3 \u05d6\u05e0\u05d1, \u05e2\u05dd \u05de\u05e8\u05db\u05d6 \u05e9\u05ea\u05d5\u05de\u05da \u05d1\u05e7\u05e6\u05d4 \u05e9\u05dc \u05d7\u05dc\u05e7 \u05d0\u05e8\u05d5\u05da."],[56.0,"\u05d1\u05e4\u05e8\u05e7 0 \u05d4\u05db\u05e8\u05e0\u05d5 \u05e9\u05dc\u05d5\u05e9\u05d4 \u05e4\u05e8\u05de\u05d8\u05e8\u05d9\u05dd: \u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05d7\u05d9\u05ea\u05d5\u05da, \u05d4\u05d6\u05e0\u05d4 \u05d5\u05e2\u05d5\u05de\u05e7 \u05d7\u05d9\u05ea\u05d5\u05da."],[62.0,"\u05d1\u05d7\u05e8\u05d9\u05d8\u05d4, \u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05d4\u05d7\u05d9\u05ea\u05d5\u05da \u05ea\u05dc\u05d5\u05d9\u05d4 \u05d1\u05e1\u05d9\u05d1\u05d5\u05d1\u05d9 \u05d4\u05e6\u05d9\u05e8 \u05d5\u05d1\u05e7\u05d5\u05d8\u05e8 \u05d4\u05d7\u05dc\u05e7."],[67.0,"\u05d1\u05d0\u05d5\u05ea\u05dd \u05e1\u05d9\u05d1\u05d5\u05d1\u05d9\u05dd, \u05e7\u05d5\u05d8\u05e8 \u05d2\u05d3\u05d5\u05dc \u05e2\u05d5\u05d1\u05e8 \u05de\u05e8\u05d7\u05e7 \u05d2\u05d3\u05d5\u05dc \u05d9\u05d5\u05ea\u05e8 \u05d1\u05db\u05dc \u05e1\u05d9\u05d1\u05d5\u05d1, \u05d5\u05dc\u05db\u05df \u05d4\u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05e9\u05dc\u05d5 \u05d2\u05d1\u05d5\u05d4\u05d4 \u05d9\u05d5\u05ea\u05e8."],[75.0,"\u05dc\u05de\u05e9\u05dc, \u05db\u05d3\u05d9 \u05dc\u05d7\u05e8\u05d5\u05d8 \u05e7\u05d5\u05d8\u05e8 50 \u05de\"\u05de \u05d1\u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05d7\u05d9\u05ea\u05d5\u05da \u05e9\u05dc 0 \u05de\u05d8\u05e8 \u05dc\u05d3\u05e7\u05d4, \u05e6\u05e8\u05d9\u05da \u05d1\u05e2\u05e8\u05da 1,270 \u05e1\u05d9\u05d1\u05d5\u05d1\u05d9\u05dd \u05dc\u05d3\u05e7\u05d4."],[84.0,"\u05db\u05e9\u05d7\u05d5\u05e8\u05d8\u05d9\u05dd \u05e4\u05e0\u05d9\u05dd \u05dc\u05db\u05d9\u05d5\u05d5\u05df \u05d4\u05de\u05e8\u05db\u05d6, \u05d4\u05e7\u05d5\u05d8\u05e8 \u05e7\u05d8\u05df, \u05d5\u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05d4\u05d7\u05d9\u05ea\u05d5\u05da \u05d9\u05d5\u05e8\u05d3\u05ea."],[90.0,"\u05d4\u05de\u05db\u05d5\u05e0\u05d4 \u05de\u05e2\u05dc\u05d4 \u05d0\u05ea \u05d4\u05e1\u05d9\u05d1\u05d5\u05d1\u05d9\u05dd \u05db\u05e9\u05d4\u05e7\u05d5\u05d8\u05e8 \u05e7\u05d8\u05df, \u05e2\u05d3 \u05d2\u05d1\u05d5\u05dc \u05e9\u05e7\u05d5\u05d1\u05e2\u05d9\u05dd \u05de\u05e8\u05d0\u05e9."],[99.0,"\u05d4\u05d4\u05d6\u05e0\u05d4 \u05d1\u05d7\u05e8\u05d9\u05d8\u05d4 \u05e0\u05de\u05d3\u05d3\u05ea \u05d1\u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8\u05d9\u05dd \u05dc\u05e1\u05d9\u05d1\u05d5\u05d1, \u05d5\u05e2\u05d5\u05de\u05e7 \u05d4\u05d7\u05d9\u05ea\u05d5\u05da \u05d4\u05d5\u05d0 \u05db\u05de\u05d4 \u05de\u05d5\u05e8\u05d9\u05d3\u05d9\u05dd \u05de\u05d4\u05e8\u05d3\u05d9\u05d5\u05e1 \u05d1\u05de\u05e2\u05d1\u05e8 \u05d0\u05d7\u05d3."],[107.0,"\u05db\u05e9\u05de\u05d5\u05e8\u05d9\u05d3\u05d9\u05dd \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8 \u05d0\u05d7\u05d3 \u05d1\u05e8\u05d3\u05d9\u05d5\u05e1, \u05d4\u05e7\u05d5\u05d8\u05e8 \u05e7\u05d8\u05df \u05d1\u05e9\u05e0\u05d9 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8\u05d9\u05dd."],[113.0,"\u05d1\u05de\u05d7\u05e8\u05d8\u05d4 \u05d0\u05e4\u05e9\u05e8 \u05dc\u05d1\u05e6\u05e2 \u05d4\u05e8\u05d1\u05d4 \u05e4\u05e2\u05d5\u05dc\u05d5\u05ea."],[116.0,"\u05d7\u05e8\u05d9\u05d8\u05d4 \u05d0\u05d5\u05e8\u05db\u05d9\u05ea \u05de\u05e7\u05d8\u05d9\u05e0\u05d4 \u05d0\u05ea \u05d4\u05e7\u05d5\u05d8\u05e8 \u05dc\u05d0\u05d5\u05e8\u05da \u05d4\u05d7\u05dc\u05e7."],[120.0,"\u05d7\u05e8\u05d9\u05d8\u05ea \u05e4\u05e0\u05d9\u05dd \u05de\u05d9\u05d9\u05e9\u05e8\u05ea \u05d0\u05ea \u05e7\u05e6\u05d4 \u05d4\u05d7\u05dc\u05e7."],[123.0,"\u05e0\u05d9\u05e7\u05d5\u05e8 \u05d9\u05d5\u05e6\u05e8 \u05d7\u05e8\u05d9\u05e5, \u05d5\u05e0\u05d9\u05ea\u05d5\u05e7 \u05d7\u05d5\u05ea\u05da \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7 \u05de\u05d4\u05de\u05d5\u05d8."],[127.0,"\u05e7\u05d9\u05d3\u05d5\u05d7 \u05d5\u05d7\u05e8\u05d9\u05d8\u05d4 \u05e4\u05e0\u05d9\u05de\u05d9\u05ea \u05d9\u05d5\u05e6\u05e8\u05d9\u05dd \u05e7\u05d3\u05d7\u05d9\u05dd \u05de\u05d3\u05d5\u05d9\u05e7\u05d9\u05dd \u05d1\u05de\u05e8\u05db\u05d6 \u05d4\u05d7\u05dc\u05e7."],[132.0,"\u05d5\u05d4\u05d1\u05e8\u05d2\u05d4 \u05d9\u05d5\u05e6\u05e8\u05ea \u05ea\u05d1\u05e8\u05d9\u05d2, \u05db\u05e9\u05d4\u05d4\u05d6\u05e0\u05d4 \u05d1\u05db\u05dc \u05e1\u05d9\u05d1\u05d5\u05d1 \u05e9\u05d5\u05d5\u05d4 \u05d1\u05d3\u05d9\u05d5\u05e7 \u05dc\u05e4\u05e1\u05d9\u05e2\u05d4."],[138.0,"\u05d5\u05d0\u05e4\u05e9\u05e8 \u05d2\u05dd \u05dc\u05d7\u05e8\u05d5\u05d8 \u05de\u05d7\u05e8\u05d5\u05d8\u05d9\u05dd, \u05e8\u05d3\u05d9\u05d5\u05e1\u05d9\u05dd \u05d5\u05e4\u05e8\u05d5\u05e4\u05d9\u05dc\u05d9\u05dd, \u05db\u05e9\u05e9\u05e0\u05d9 \u05d4\u05e6\u05d9\u05e8\u05d9\u05dd \u2026."],[144.0,"\u05e8\u05d5\u05d1 \u05d4\u05db\u05dc\u05d9\u05dd \u05d4\u05d9\u05d5\u05dd \u05d4\u05dd \u05de\u05d7\u05d6\u05d9\u05e7 \u05e2\u05dd \u05e1\u05d9\u05de\u05d4 \u05de\u05ea\u05d7\u05dc\u05e4\u05ea, \u05de\u05e7\u05e8\u05d1\u05d9\u05d3 \u05d0\u05d5 \u05de\u05d7\u05d5\u05de\u05e8\u05e7\u05e9\u05d4 \u05d0\u05d7\u05e8."],[150.0,"\u05dc\u05dc\u05d4\u05d1 \u05d9\u05e9 \u05d6\u05d5\u05d5\u05d9\u05ea \u05e7\u05d5\u05d3\u05e7\u05d5\u05d3: \u05dc\u05d4\u05d1 \u05e2\u05dd \u05d6\u05d5\u05d5\u05d9\u05ea \u05d2\u05d3\u05d5\u05dc\u05d4 \u05d7\u05d6\u05e7 \u05d9\u05d5\u05ea\u05e8, \u05d5\u05dc\u05d4\u05d1 \u05e2\u05dd \u05d6\u05d5\u05d5\u05d9\u05ea \u05d7\u05d3\u05d4 \u05de\u05d2\u05d9\u05e2 \u05dc\u05de\u05e7\u05d5\u05de\u05d5\u05ea \u05e6\u05e8\u05d9\u05dd."],[159.0,"\u05dc\u05de\u05e9\u05dc, \u05dc\u05d4\u05d1 \u05de\u05e2\u05d5\u05d9\u05df \u05e9\u05dc 80 \u05de\u05e2\u05dc\u05d5\u05ea \u05de\u05ea\u05d0\u05d9\u05dd \u05dc\u05d7\u05e8\u05d9\u05d8\u05d4 \u05d2\u05e1\u05d4, \u05d5\u05dc\u05d4\u05d1 \u05e9\u05dc 35 \u05de\u05e2\u05dc\u05d5\u05ea \u05de\u05ea\u05d0\u05d9\u05dd \u05dc\u05d7\u05e8\u05d9\u05d8\u05ea \u05e4\u05e8\u05d5\u05e4\u05d9\u05dc."],[168.0,"\u05d1\u05e7\u05d5\u05d3\u05e7\u05d5\u05d3 \u05d9\u05e9 \u05e8\u05d3\u05d9\u05d5\u05e1: \u05e8\u05d3\u05d9\u05d5\u05e1 \u05d2\u05d3\u05d5\u05dc \u05d5\u05d4\u05d6\u05e0\u05d4 \u05e7\u05d8\u05e0\u05d4 \u05e0\u05d5\u05ea\u05e0\u05d9\u05dd \u05e1\u05e0\u05d9 \u05e9\u05d8\u05d7 \u05d7\u05dc\u05e7\u05d9\u05dd \u05d9\u05d5\u05ea\u05e8."],[174.0,"\u05d0\u05d1\u05dc \u05e8\u05d3\u05d9\u05d5\u05e1 \u05d2\u05d3\u05d5\u05dc \u05de\u05d3\u05d9 \u05de\u05d2\u05d3\u05d9\u05dc \u05d0\u05ea \u05d4\u05db\u05d5\u05d7\u05d5\u05ea \u05d4\u05e8\u05d3\u05d9\u05d0\u05dc\u05d9\u05d9\u05dd, \u05d5\u05e2\u05dc\u05d5\u05dc \u05dc\u05d2\u05e8\u05d5\u05dd \u05dc\u05e8\u05e2\u05d9\u05d3\u05d5\u05ea."],[180.0,"\u05d5\u05e2\u05dc \u05d4\u05dc\u05d4\u05d1 \u05d9\u05e9 \u05e9\u05d5\u05d1\u05e8 \u05e9\u05d1\u05d1\u05d9\u05dd: \u05e6\u05d5\u05e8\u05d4 \u05e9\u05de\u05db\u05d5\u05e4\u05e4\u05ea \u05d0\u05ea \u05d4\u05e9\u05d5\u05d1\u05d1 \u05d5\u05e9\u05d5\u05d1\u05e8\u05ea \u05d0\u05d5\u05ea\u05d5 \u05dc\u05d7\u05ea\u05d9\u05db\u05d5\u05ea \u05e7\u05e6\u05e8\u05d5\u05ea."],[187.0,"\u05d3\u05d9\u05d5\u05e7 \u05d4\u05d7\u05e8\u05d9\u05d8\u05d4 \u05de\u05ea\u05d7\u05d9\u05dc \u05d1\u05ea\u05e4\u05d9\u05e1\u05d4."],[190.0,"\u05e4\u05d5\u05d8\u05e8 \u05e2\u05dd \u05e9\u05dc\u05d5\u05e9 \u05dc\u05e1\u05ea\u05d5\u05ea \u05de\u05de\u05e8\u05db\u05d6 \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7 \u05dc\u05d1\u05d3, \u05d0\u05d1\u05dc \u05dc\u05d0 \u05d1\u05d3\u05d9\u05d5\u05e7 \u05de\u05d5\u05e9\u05dc\u05dd."],[195.0,"\u05db\u05e9\u05e6\u05e8\u05d9\u05da \u05d3\u05d9\u05d5\u05e7 \u05d2\u05d1\u05d5\u05d4, \u05d7\u05d5\u05e8\u05d8\u05d9\u05dd \u05dc\u05e1\u05ea\u05d5\u05ea \u05e8\u05db\u05d5\u05ea \u05d1\u05d3\u05d9\u05d5\u05e7 \u05dc\u05e7\u05d5\u05d8\u05e8 \u05e9\u05dc \u05d4\u05d7\u05dc\u05e7, \u05e2\u05dc \u05d4\u05de\u05db\u05d5\u05e0\u05d4 \u05e2\u05e6\u05de\u05d4."],[202.0,"\u05dc\u05d7\u05dc\u05e7\u05d9\u05dd \u05e7\u05d8\u05e0\u05d9\u05dd \u05d5\u05dc\u05de\u05d5\u05d8\u05d5\u05ea \u05de\u05e9\u05de\u05e9 \u05e7\u05d5\u05dc\u05d8, \u05e9\u05ea\u05d5\u05e4\u05e1 \u05de\u05e1\u05d1\u05d9\u05d1 \u05d5\u05de\u05d3\u05d5\u05d9\u05e7 \u05de\u05d0\u05d5\u05d3."],[208.0,"\u05d7\u05dc\u05e7 \u05d0\u05e8\u05d5\u05da \u05d5\u05d3\u05e7 \u05de\u05ea\u05db\u05d5\u05e4\u05e3 \u05ea\u05d7\u05ea \u05db\u05d5\u05d7 \u05d4\u05d7\u05d9\u05ea\u05d5\u05da."],[211.0,"\u05db\u05dc\u05dc \u05d0\u05e6\u05d1\u05e2: \u05db\u05e9\u05d4\u05d0\u05d5\u05e8\u05da \u05d4\u05d1\u05d5\u05dc\u05d8 \u05de\u05d4\u05e4\u05d5\u05d8\u05e8 \u05e2\u05d5\u05dc\u05d4 \u05e2\u05dc \u05e1\u05d9 3 \u05de\u05d4\u05e7\u05d5\u05d8\u05e8, \u05ea\u05d5\u05de\u05db\u05d9\u05dd \u05d1\u05e7\u05e6\u05d4 \u05d1\u05de\u05e8\u05db\u05d6."],[219.0,"\u05d5\u05d1\u05d7\u05dc\u05e7 \u05d0\u05e8\u05d5\u05da \u05de\u05d0\u05d5\u05d3 \u05de\u05d5\u05e1\u05d9\u05e4\u05d9\u05dd \u05de\u05e9\u05e2\u05e0\u05ea, \u05e9\u05ea\u05d5\u05de\u05db\u05ea \u05d1\u05d5 \u05d1\u05d0\u05de\u05e6\u05e2."],[224.0,"\u05d4\u05e9\u05d1\u05d1 \u05de\u05e1\u05e4\u05e8 \u05de\u05d4 \u05e7\u05d5\u05e8\u05d4 \u05d1\u05d7\u05d9\u05ea\u05d5\u05df."],[226.0,"\u05e9\u05d1\u05d1\u05d9\u05dd \u05d0\u05e8\u05d5\u05db\u05d9\u05dd \u05d5\u05de\u05e1\u05ea\u05dc\u05e1\u05dc\u05d9\u05dd \u05de\u05e1\u05ea\u05d1\u05db\u05d9\u05dd \u05e1\u05d1\u05d9\u05d1 \u05d4\u05d7\u05dc\u05e7 \u05d5\u05d4\u05db\u05dc\u05d9, \u05e9\u05d5\u05e8\u05d8\u05d9\u05dd \u05d0\u05ea \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7, \u05d5\u05de\u05e1\u05d5\u05db\u05e0\u05d9\u05dd \u05dc\u05de\u05e4\u05e2\u05d9\u05dc."],[234.0,"\u05e9\u05d1\u05d1\u05d9\u05dd \u05e7\u05e6\u05e8\u05d9\u05dd, \u05d1\u05e6\u05d5\u05e8\u05ea \u05e1\u05e4\u05d9\u05e8\u05dc\u05d4 \u05d0\u05d5 \u05d1\u05e6\u05d5\u05e8\u05ea 6, \u05d4\u05dd \u05e1\u05d9\u05de\u05df \u05dc\u05e4\u05e8\u05de\u05d8\u05e8\u05d9\u05dd \u05e0\u05db\u05d5\u05e0\u05d9\u05dd."],[240.0,"\u05db\u05e9\u05d4\u05e9\u05d1\u05d1\u05d9\u05dd \u05d0\u05e8\u05d5\u05db\u05d9\u05dd, \u05de\u05d2\u05d3\u05d9\u05dc\u05d9\u05dd \u05d0\u05ea \u05d4\u05d4\u05d6\u05e0\u05d4 \u05d0\u05d5 \u05d0\u05ea \u05e2\u05d5\u05de\u05e7 \u05d4\u05d7\u05d9\u05ea\u05d5\u05da, \u05d0\u05d5 \u05d1\u05d5\u05d7\u05e8\u05d9\u05dd \u05dc\u05d4\u05d1 \u05e2\u05dd \u05e9\u05d5\u05d1\u05e8 \u05e9\u05d1\u05d1\u05d9\u05dd \u05d0\u05d7\u05e8."],[248.0,"\u05d1\u05de\u05d7\u05e8\u05d8\u05ea CNC, \u05ea\u05d5\u05db\u05e0\u05d9\u05ea \u05e9\u05d5\u05dc\u05d8\u05ea \u05d1\u05e6\u05d9\u05e8\u05d9\u05dd, \u05d5\u05d4\u05e6\u05e8\u05d9\u05d7 \u05de\u05d7\u05dc\u05d9\u05e3 \u05db\u05dc\u05d9\u05dd \u05dc\u05d1\u05d3."],[254.0,"\u05d1\u05de\u05e8\u05db\u05d6 \u05d7\u05e8\u05d9\u05d8\u05d4 \u05d9\u05e9 \u05d2\u05dd \u05db\u05dc\u05d9\u05dd \u05de\u05d5\u05e0\u05e2\u05d9\u05dd: \u05de\u05e7\u05d3\u05d7\u05d5\u05ea \u05d5\u05db\u05e8\u05e1\u05de\u05d9\u05dd \u05e9\u05de\u05e1\u05ea\u05d5\u05d1\u05d1\u05d9\u05dd \u05d1\u05e6\u05e8\u05d9\u05d7 \u05e2\u05e6\u05de\u05d5."],[261.0,"\u05db\u05da \u05d0\u05e4\u05e9\u05e8 \u05dc\u05e7\u05d3\u05d5\u05d7 \u05d5\u05dc\u05db\u05e8\u05e1\u05dd \u05d1\u05d7\u05dc\u05e7 \u05d1\u05dc\u05d9 \u05dc\u05d4\u05d5\u05e8\u05d9\u05d3 \u05d0\u05d5\u05ea\u05d5 \u05de\u05d4\u05de\u05db\u05d5\u05e0\u05d4."],[265.0,"\u05e2\u05dd \u05e6\u05d9\u05e8 \u05e0\u05d2\u05d3\u05d9, \u05d4\u05d7\u05dc\u05e7 \u05e2\u05d5\u05d1\u05e8 \u05de\u05e6\u05d9\u05e8 \u05dc\u05e6\u05d9\u05e8, \u05d5\u05de\u05e2\u05d1\u05d3\u05d9\u05dd \u05d2\u05dd \u05d0\u05ea \u05d4\u05e6\u05d3 \u05d4\u05e9\u05e0\u05d9 \u05e9\u05dc\u05d5 \u05d1\u05dc\u05d9 \u05ea\u05e4\u05d9\u05e1\u05d4 \u05e0\u05d5\u05e1\u05e4\u05ea."],[273.0,"\u05d1\u05de\u05d7\u05e8\u05d8\u05d4 \u05e9\u05d5\u05d5\u05d9\u05d9\u05e6\u05e8\u05d9\u05ea, \u05d4\u05de\u05d5\u05d8 \u05e0\u05e2 \u05d3\u05e8\u05da \u05ea\u05d5\u05ea\u05d1 \u05de\u05d5\u05d1\u05d9\u05dc, \u05d5\u05d4\u05d7\u05d9\u05ea\u05d5\u05da \u05ea\u05de\u05d9\u05d3 \u05e7\u05e8\u05d5\u05d1 \u05dc\u05ea\u05de\u05d9\u05db\u05d4."],[279.0,"\u05db\u05da \u05de\u05d9\u05d9\u05e6\u05e8\u05d9\u05dd \u05d7\u05dc\u05e7\u05d9\u05dd \u05e7\u05d8\u05e0\u05d9\u05dd, \u05d0\u05e8\u05d5\u05db\u05d9\u05dd \u05d5\u05de\u05d3\u05d5\u05d9\u05e7\u05d9\u05dd."],[283.0,"\u05d7\u05e8\u05d9\u05d8\u05d4 \u05e8\u05d2\u05d9\u05dc\u05d4 \u05e0\u05d5\u05ea\u05e0\u05ea \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d3\u05d9\u05d5\u05e7 \u05e9\u05dc 7\u05d3\u05d5 \u05e2\u05d3 9\u05d3\u05d5, \u05d5\u05d7\u05e1\u05e4\u05d5\u05e1 Ra \u05e9\u05dc 0.8 \u05e2\u05d3 3.2 \u05de\u05d9\u05e7\u05e8\u05d5\u05df."],[294.0,"\u05d1\u05d2\u05d9\u05de\u05d5\u05e8 \u05e2\u05d3\u05d9\u05df, \u05e2\u05dd \u05dc\u05d4\u05d1 \u05d5\u05e4\u05e8\u05de\u05d8\u05e8\u05d9\u05dd \u05de\u05ea\u05d0\u05d9\u05de\u05d9\u05dd, \u05d0\u05e4\u05e9\u05e8 \u05dc\u05d4\u05d2\u05d9\u05e2 \u05dc\u05d3\u05d9\u05d5\u05e7 \u05d5\u05dc\u05d7\u05e1\u05e4\u05d5\u05e1 \u05d8\u05d5\u05d1\u05d9\u05dd \u05d9\u05d5\u05ea\u05e8."],[300.0,"\u05d9\u05ea\u05e8\u05d5\u05df \u05d2\u05d3\u05d5\u05dc \u05e9\u05dc \u05d7\u05e8\u05d9\u05d8\u05d4: \u05db\u05dc \u05de\u05d4 \u05e9\u05e0\u05d7\u05e8\u05d8 \u05d1\u05d0\u05d5\u05ea\u05d4 \u05ea\u05e4\u05d9\u05e1\u05d4 \u05e1\u05d5\u05d1\u05d1 \u05e1\u05d1\u05d9\u05d1 \u05d0\u05d5\u05ea\u05d5 \u05e6\u05d9\u05e8."],[307.0,"\u05dc\u05db\u05df \u05e7\u05d8\u05e8\u05d9\u05dd \u05e9\u05d7\u05d9\u05d9\u05d1\u05d9\u05dd \u05dc\u05d4\u05d9\u05d5\u05ea \u05e2\u05dc \u05d0\u05d5\u05ea\u05d5 \u05e6\u05d9\u05e8, \u05db\u05de\u05d5 \u05de\u05d5\u05e9\u05d1\u05d9 \u05de\u05e1\u05d1\u05d9\u05dd, \u05d7\u05d5\u05e8\u05d8\u05d9\u05dd \u05d1\u05ea\u05e4\u05d9\u05e1\u05d4 \u05d0\u05d7\u05ea."],[314.0,"\u05d2\u05dd \u05d1\u05d7\u05e8\u05d9\u05d8\u05d4 \u05d9\u05e9 \u05d1\u05e2\u05d9\u05d5\u05ea \u05d0\u05d5\u05e4\u05d9\u05d9\u05e0\u05d9\u05d5\u05ea."],[316.0,"\u05e8\u05e2\u05d9\u05d3\u05d5\u05ea \u05de\u05e9\u05d0\u05d9\u05e8\u05d5\u05ea \u05e1\u05d9\u05de\u05e0\u05d9\u05dd \u05d2\u05dc\u05d9\u05d9\u05dd \u05e2\u05dc \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7, \u05d1\u05e2\u05d9\u05e7\u05e8 \u05d1\u05d7\u05dc\u05e7 \u05d3\u05e7 \u05d0\u05d5 \u05d1\u05de\u05d7\u05d6\u05d9\u05e7 \u05e9\u05d1\u05d5\u05dc\u05d8 \u05de\u05d3\u05d9."],[323.0,"\u05d4\u05e6\u05d8\u05d1\u05e8\u05d5\u05ea \u05d7\u05d5\u05de\u05e8 \u05e2\u05dc \u05d4\u05e7\u05d5\u05d3\u05e7\u05d5\u05d3: \u05d7\u05d5\u05de\u05e8 \u05e8\u05da \u05e0\u05d3\u05d1\u05e7 \u05dc\u05dc\u05d4\u05d1, \u05d5\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05e0\u05e2\u05e9\u05d9\u05dd \u05d2\u05e1\u05d9\u05dd."],[330.0,"\u05d4\u05e4\u05ea\u05e8\u05d5\u05df \u05d4\u05e0\u05e4\u05d5\u05e5: \u05dc\u05d4\u05e2\u05dc\u05d5\u05ea \u05d0\u05ea \u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05d4\u05d7\u05d9\u05ea\u05d5\u05da."],[334.0,"\u05d7\u05dc\u05e7 \u05d0\u05e8\u05d5\u05da \u05e9\u05de\u05ea\u05db\u05d5\u05e4\u05e3 \u05d9\u05d5\u05e6\u05d0 \u05e7\u05d5\u05e0\u05d9 \u05d0\u05d5 \u05d1\u05e6\u05d5\u05e8\u05ea \u05d7\u05d1\u05d9\u05ea, \u05db\u05d9 \u05d1\u05de\u05e7\u05d5\u05dd \u05e9\u05d4\u05d5\u05d0 \u05de\u05ea\u05db\u05d5\u05e4\u05e3 \u05d4\u05e1\u05d9\u05de\u05d4 \u05d7\u05d5\u05ea\u05db\u05ea \u05e4\u05d7\u05d5\u05ea."],[342.0,"\u05d5\u05d1\u05dc\u05d0\u05d9 \u05e9\u05dc \u05d4\u05dc\u05d4\u05d1 \u05de\u05e9\u05e0\u05d4 \u05d0\u05ea \u05d4\u05de\u05d9\u05d3\u05d4 \u05dc\u05d0\u05d8, \u05dc\u05d0\u05d5\u05e8\u05da \u05d4\u05e1\u05d3\u05e8\u05d4, \u05d5\u05dc\u05db\u05df \u05de\u05d5\u05d3\u05d3\u05d9\u05dd \u05d5\u05de\u05ea\u05e7\u05e0\u05d9\u05dd \u05d1\u05ea\u05d5\u05db\u05e0\u05d9\u05ea."],[349.0,"\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8 \u05d7\u05e8\u05d9\u05d8\u05d4?"],[351.0,"\u05d6\u05de\u05df \u05d4\u05db\u05e0\u05d4: \u05dc\u05e1\u05ea\u05d5\u05ea, \u05db\u05dc\u05d9\u05dd, \u05ea\u05d5\u05db\u05e0\u05d9\u05ea, \u05d5\u05d7\u05dc\u05e7 \u05e8\u05d0\u05e9\u05d5\u05df \u05dc\u05d1\u05d3\u05d9\u05e7\u05d4."],[357.0,"\u05d6\u05de\u05df \u05de\u05d7\u05d6\u05d5\u05e8: \u05db\u05de\u05d4 \u05d7\u05d5\u05de\u05e8 \u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05d5\u05e8\u05d9\u05d3, \u05d5\u05d1\u05d0\u05d9\u05d6\u05d5 \u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05d4\u05d7\u05d5\u05de\u05e8 \u05de\u05e8\u05e9\u05d4 \u05dc\u05d7\u05ea\u05d5\u05da."],[363.0,"\u05e0\u05d9\u05e8\u05d5\u05e1\u05d8\u05d4, \u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd \u05d5\u05e1\u05d2\u05e1\u05d5\u05d2\u05d5\u05ea \u05e2\u05dc \u05e0\u05d7\u05e8\u05d8\u05d9\u05dd \u05dc\u05d0\u05d8 \u05d1\u05d4\u05e8\u05d1\u05d4 \u05de\u05e4\u05dc\u05d3\u05d4 \u05e8\u05d2\u05d9\u05dc\u05d4."],[368.0,"\u05d8\u05d5\u05dc\u05e8\u05e0\u05e1 \u05d4\u05d3\u05d5\u05e7: \u05e2\u05d5\u05d3 \u05de\u05e2\u05d1\u05e8\u05d9 \u05d2\u05d9\u05de\u05d5\u05e8, \u05e2\u05d5\u05d3 \u05de\u05d3\u05d9\u05d3\u05d5\u05ea, \u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d4\u05e9\u05d7\u05d6\u05d4 \u05d0\u05d7\u05e8 \u05db\u05df."],[375.0,"\u05d1\u05de\u05e8\u05db\u05d6 \u05d7\u05e8\u05d9\u05d8\u05d4 \u05d4\u05df \u05e0\u05e2\u05e9\u05d5\u05ea \u05d1\u05d0\u05d5\u05ea\u05d4 \u05ea\u05e4\u05d9\u05e1\u05d4, \u05d5\u05d1\u05de\u05d7\u05e8\u05d8\u05d4 \u05e8\u05d2\u05d9\u05dc\u05d4 \u05d4\u05df \u05d3\u05d5\u05e8\u05e9\u05d5\u05ea \u05de\u05db\u05d5\u05e0\u05d4 \u05e0\u05d5\u05e1\u05e4\u05ea."],[386.0,"\u05d7\u05e8\u05d9\u05d8\u05d4 \u05de\u05ea\u05d0\u05d9\u05de\u05d4 \u05dc\u05db\u05dc \u05d7\u05dc\u05e7 \u05e1\u05d9\u05d1\u05d5\u05d1\u05d9, \u05de\u05e4\u05d9\u05df \u05e7\u05d8\u05df \u05d5\u05e2\u05d3 \u05d2\u05dc \u05d1\u05d0\u05d5\u05e8\u05da \u05e9\u05dc \u05de\u05d8\u05e8\u05d9\u05dd."],[392.0,"\u05d5\u05db\u05e9\u05dc\u05d7\u05dc\u05e7 \u05d9\u05e9 \u05de\u05e9\u05d8\u05d7\u05d9\u05dd, \u05db\u05d9\u05e1\u05d9\u05dd \u05d5\u05e6\u05d5\u05e8\u05d5\u05ea \u05e9\u05d0\u05d9\u05e0\u05df \u05e1\u05d9\u05d1\u05d5\u05d1\u05d9\u05d5\u05ea, \u05e2\u05d5\u05d1\u05e8\u05d9\u05dd \u05dc\u05de\u05db\u05d5\u05e0\u05d4 \u05d4\u05d1\u05d0\u05d4."],[398.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0: \u05db\u05e8\u05e1\u05d5\u05dd."]]};
window.MH_TR["\u05e4\u05e8\u05e705_\u05db\u05e8\u05e1\u05d5\u05dd"]={"t":"\u05db\u05e8\u05e1\u05d5\u05dd","l":[[1.0,"\u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05e9\u05d8\u05d5\u05d7\u05d9\u05dd, \u05db\u05d9\u05e1\u05d9\u05dd, \u05d7\u05e8\u05d9\u05e6\u05d9\u05dd \u05d5\u05e6\u05d5\u05e8\u05d5\u05ea \u05d7\u05d5\u05e4\u05e9\u05d9\u05d5\u05ea: \u05d0\u05ea \u05e8\u05d5\u05d1 \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05e9\u05d0\u05d9\u05e0\u05dd \u05e2\u05d2\u05d5\u05dc\u05d9\u05dd \u05de\u05e2\u05d1\u05d3\u05d9\u05dd \u05d1\u05db\u05e8\u05e1\u05d5\u05dd."],[9.0,"\u05d1\u05db\u05e8\u05e1\u05d5\u05dd, \u05d4\u05d4\u05e4\u05da \u05de\u05d7\u05e8\u05d9\u05d8\u05d4: \u05d4\u05db\u05dc\u05d9 \u05de\u05e1\u05ea\u05d5\u05d1\u05d1, \u05d5\u05d4\u05d7\u05dc\u05e7 \u05d0\u05d5 \u05d4\u05db\u05dc\u05d9 \u05e0\u05e2\u05d9\u05dd \u05d1\u05e6\u05d9\u05e8\u05d9\u05dd."],[17.0,"\u05dc\u05db\u05dc\u05d9 \u05d4\u05db\u05e8\u05e1\u05d5\u05dd \u05d9\u05e9 \u05db\u05de\u05d4 \u05e9\u05d9\u05e0\u05d9\u05d9\u05dd, \u05d5\u05db\u05dc \u05e9\u05df \u05d7\u05d5\u05ea\u05db\u05ea \u05e9\u05d1\u05d1 \u05e7\u05d8\u05df \u05d1\u05db\u05dc \u05e1\u05d9\u05d1\u05d5\u05d1."],[23.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d6\u05d4 \u05e0\u05db\u05d9\u05e8 \u05d0\u05ea \u05d4\u05de\u05db\u05d5\u05e0\u05d5\u05ea, \u05d0\u05ea \u05d4\u05db\u05dc\u05d9\u05dd, \u05d0\u05ea \u05d4\u05e4\u05e8\u05de\u05d8\u05e8\u05d9\u05dd, \u05d5\u05d0\u05ea \u05de\u05d4 \u05e9\u05de\u05d9\u05d9\u05e7\u05e8 \u05d7\u05dc\u05e7 \u05de\u05db\u05d5\u05e8\u05e1\u05dd."],[30.0,"\u05d1\u05db\u05e8\u05e1\u05d5\u05de\u05ea \u05d0\u05e0\u05dc\u05d9\u05ea, \u05d4\u05e6\u05d9\u05e8 \u05d4\u05e8\u05d0\u05e9\u05d9 \u05e2\u05d5\u05de\u05d3, \u05d5\u05d4\u05db\u05dc\u05d9 \u05d7\u05d5\u05ea\u05da \u05de\u05dc\u05de\u05e2\u05dc\u05d4."],[35.0,"\u05d4\u05e9\u05d5\u05dc\u05d7\u05df \u05e0\u05e2 \u05d1\u05e9\u05e0\u05d9 \u05e6\u05d9\u05e8\u05d9\u05dd, \u05d0 \u05d5-\u05e5, \u05d5\u05d4\u05e6\u05d9\u05e8 \u05d4\u05e8\u05d0\u05e9\u05d9\u05e0\u05e2 \u05dc\u05de\u05e2\u05dc\u05d4 \u05d5\u05dc\u05de\u05d8\u05d4, \u05d1\u05e6\u05d9\u05e8 7."],[43.0,"\u05d1\u05de\u05e8\u05db\u05d6 \u05e2\u05d9\u05d1\u05d5\u05d3 \u05d9\u05e9 \u05d2\u05dd \u05de\u05d7\u05dc\u05d9\u05e3 \u05db\u05dc\u05d9\u05dd, \u05e9\u05de\u05d7\u05dc\u05d9\u05e3 \u05db\u05dc\u05d9 \u05ea\u05d5\u05da \u05e9\u05e0\u05d9\u05d5\u05ea, \u05d5\u05d4\u05db\u05d5\u05dc \u05e0\u05e9\u05dc\u05d8 \u05d1\u05ea\u05d5\u05db\u05e0\u05d9\u05ea."],[49.0,"\u05d9\u05e9 \u05d2\u05dd \u05db\u05e8\u05e1\u05d5\u05de\u05d5\u05ea \u05d0\u05d5\u05e4\u05e7\u05d9\u05d5\u05ea, \u05e9\u05d1\u05d4\u05df \u05d4\u05e6\u05d9\u05e8 \u05e9\u05d5\u05db\u05d1, \u05d5\u05d4\u05df \u05e0\u05d5\u05d7\u05d5\u05ea \u05dc\u05d7\u05dc\u05e7\u05d9\u05dd \u05d2\u05d3\u05d5\u05dc\u05d9\u05dd \u05d5\u05dc\u05e4\u05d9\u05e0\u05d5\u05d9 \u05e9\u05d1\u05d1\u05d9\u05dd."],[56.0,"\u05de\u05e1\u05e4\u05e8 \u05d4\u05e6\u05d9\u05e8\u05d9\u05dd \u05e7\u05d5\u05d1\u05e2 \u05de\u05d0\u05d9\u05dc\u05d5 \u05e6\u05d3\u05d3\u05d9\u05dd \u05d0\u05e4\u05e9\u05e8 \u05dc\u05d4\u05d2\u05d9\u05e2 \u05dc\u05d7\u05dc\u05e7, \u05d5\u05e2\u05dc \u05d6\u05d4 \u05e0\u05e8\u05d7\u05d9\u05d1 \u05d1\u05e4\u05e8\u05e7 21."],[63.0,"\u05d4\u05db\u05dc\u05d9 \u05d4\u05e0\u05e4\u05d5\u05e5 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05d4\u05d5\u05d0 \u05db\u05e8\u05e1\u05dd \u05d0\u05e6\u05d1\u05e2: \u05d4\u05d5\u05d0 \u05d7\u05d5\u05ea\u05da \u05d2\u05dd \u05d1\u05e6\u05d3 \u05d5\u05d2\u05dd \u05d1\u05e7\u05e6\u05d4."],[69.0,"\u05dc\u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05d2\u05d3\u05d5\u05dc\u05d9\u05dd \u05de\u05e9\u05de\u05e9 \u05e8\u05d0\u05e9 \u05db\u05e8\u05e1\u05d5\u05dd \u05e4\u05e0\u05d9\u05dd, \u05e2\u05dd \u05dc\u05d4\u05d1\u05d9 \u05d7\u05d9\u05ea\u05d5\u05da \u05de\u05ea\u05d7\u05dc\u05e4\u05d9\u05dd."],[74.0,"\u05dc\u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05de\u05e2\u05d5\u05e7\u05dc\u05d9\u05dd \u05d5\u05dc\u05ea\u05d1\u05e0\u05d9\u05d5\u05ea \u05de\u05e9\u05de\u05e9 \u05db\u05e8\u05e1\u05dd \u05db\u05d3\u05d5\u05e8\u05d9, \u05e2\u05dd \u05e7\u05e6\u05d4 \u05e2\u05d2\u05d5\u05dc."],[80.0,"\u05db\u05dc\u05d9 \u05db\u05e8\u05e1\u05d5\u05dd \u05e2\u05e9\u05d5\u05d9\u05d9\u05dd \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05de\u05e7\u05e8\u05d1\u05d9\u05d3 \u05de\u05dc\u05d0 \u05d0\u05d5 \u05de\u05e4\u05dc\u05d3\u05d4 \u05de\u05d4\u05d9\u05e8\u05d4, \u05d0\u05d5 \u05e9\u05d9\u05e9 \u05dc\u05d4\u05dd \u05dc\u05d4\u05d1\u05d9 \u05d7\u05d9\u05ea\u05d5\u05da \u05de\u05ea\u05d7\u05dc\u05e4\u05d9\u05dd."],[87.0,"\u05d5\u05db\u05dc\u05d9 \u05e2\u05dd \u05de\u05e2\u05d8 \u05e9\u05d9\u05e0\u05d9\u05d9\u05dd \u05de\u05e9\u05d0\u05d9\u05e8 \u05de\u05e7\u05d5\u05dd \u05dc\u05e9\u05d1\u05d1\u05d9\u05dd, \u05d5\u05de\u05ea\u05d0\u05d9\u05dd \u05dc\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05d5\u05dc\u05d4\u05d5\u05e8\u05d3\u05d4 \u05d2\u05e1\u05d4."],[97.0,"\u05d2\u05dd \u05db\u05d0\u05df \u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05d4\u05d7\u05d9\u05ea\u05d5\u05da \u05e0\u05e7\u05d1\u05e2\u05ea \u05dc\u05e4\u05d9 \u05d4\u05e7\u05d5\u05d8\u05e8 \u05d5\u05d4\u05e1\u05d9\u05d1\u05d5\u05d1\u05d9\u05dd, \u05d0\u05d1\u05dc \u05d4\u05e7\u05d5\u05d8\u05e8 \u05d4\u05d5\u05d0 \u05e9\u05dc \u05d4\u05db\u05dc\u05d9, \u05d5\u05dc\u05d0 \u05e9\u05dc \u05d4\u05d7\u05dc\u05e7."],[105.0,"\u05dc\u05de\u05e9\u05dc, \u05db\u05dc\u05d9 \u05d1\u05e7\u05d5\u05d8\u05e8 10 \u05de\"\u05de, \u05d1\u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05d7\u05d9\u05ea\u05d5\u05da \u05e9\u05dc 150 \u05de\u05d8\u05e8 \u05dc\u05d3\u05e7\u05d4, \u05e6\u05e8\u05d9\u05da \u05d1\u05e2\u05e8\u05da 4,800 \u05e1\u05d9\u05d1\u05d5\u05d1\u05d9\u05dd \u05dc\u05d3\u05e7\u05d4."],[115.0,"\u05d1\u05db\u05e8\u05e1\u05d5\u05dd, \u05d4\u05d4\u05d6\u05e0\u05d4 \u05e0\u05de\u05d3\u05d3\u05ea \u05dc\u05db\u05dc \u05e9\u05df: \u05db\u05de\u05d4 \u05d4\u05db\u05dc\u05d9 \u05de\u05ea\u05e7\u05d3\u05dd \u05d1\u05d6\u05de\u05df \u05e9\u05e9\u05df \u05d0\u05d7\u05ea \u05e2\u05d5\u05d1\u05e8\u05ea \u05d1\u05d7\u05d5\u05de\u05e8."],[122.0,"\u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05d4\u05e9\u05d5\u05dc\u05d7\u05df \u05d4\u05d9\u05d0 \u05d4\u05d4\u05d6\u05e0\u05d4 \u05dc\u05e9\u05df, \u05db\u05e4\u05d5\u05dc \u05de\u05e1\u05e4\u05e8 \u05d4\u05e9\u05d9\u05e0\u05d9\u05d9\u05dd, \u05db\u05e4\u05d5\u05dc \u05d4\u05e1\u05d9\u05d1\u05d5\u05d1\u05d9\u05dd."],[128.0,"\u05d1\u05d3\u05d5\u05d2\u05de\u05d4 \u05e9\u05dc\u05e0\u05d5, \u05e2\u05dd 4 \u05e9\u05d9\u05e0\u05d9\u05d9\u05dd \u05d5-0.05 \u05de\"\u05de \u05dc\u05e9\u05df, \u05de\u05e7\u05d1\u05dc\u05d9\u05dd \u05d1\u05e2\u05e8\u05da 960 \u05de\"\u05de \u05dc\u05d3\u05e7\u05d4."],[136.0,"\u05d5\u05d9\u05e9 \u05e9\u05e0\u05d9 \u05de\u05de\u05d3\u05d9 \u05d7\u05d9\u05ea\u05d5\u05da: \u05e2\u05d5\u05de\u05e7 \u05e6\u05d9\u05e8\u05d9, \u05dc\u05d0\u05d5\u05e8\u05da \u05d4\u05db\u05dc\u05d9, \u05d5\u05e8\u05d5\u05d7\u05d1 \u05d7\u05d9\u05ea\u05d5\u05da, \u05db\u05de\u05d4 \u05de\u05e7\u05d5\u05d8\u05e8 \u05d4\u05db\u05dc\u05d9 \u05e0\u05db\u05e0\u05e1 \u05dc\u05d7\u05d5\u05de\u05e8."],[145.0,"\u05d9\u05e9 \u05e9\u05ea\u05d9 \u05d3\u05e8\u05db\u05d9\u05dd \u05e9\u05d1\u05d4\u05df \u05d4\u05db\u05dc\u05d9 \u05e4\u05d5\u05d2\u05e9 \u05d0\u05ea \u05d4\u05d7\u05d5\u05de\u05e8."],[149.0,"\u05d1\u05db\u05e8\u05e1\u05d5\u05dd \u05e0\u05d2\u05d3 \u05d4\u05db\u05d9\u05d5\u05d5\u05df, \u05d4\u05e9\u05df \u05e0\u05db\u05e0\u05e1\u05ea \u05d3\u05e7\u05d4 \u05d5\u05d9\u05d5\u05e6\u05d0\u05ea \u05e2\u05d1\u05d4."],[153.0,"\u05d1\u05d4\u05ea\u05d7\u05dc\u05d4 \u05d4\u05d9\u05d0 \u05de\u05d7\u05dc\u05d9\u05e7\u05d4 \u05d5\u05de\u05e9\u05e4\u05e9\u05e4\u05ea, \u05d5\u05d6\u05d4 \u05de\u05d7\u05de\u05dd \u05d5\u05e9\u05d5\u05d7\u05e7 \u05d0\u05d5\u05ea\u05d4."],[158.0,"\u05d1\u05db\u05e8\u05e1\u05d5\u05dd \u05e2\u05dd \u05d4\u05db\u05d9\u05d5\u05d5\u05df, \u05d4\u05e9\u05df \u05e0\u05db\u05e0\u05e1\u05ea \u05e2\u05d1\u05d4 \u05d5\u05d9\u05d5\u05e6\u05d0\u05ea \u05d3\u05e7\u05d4."],[162.0,"\u05d4\u05d1\u05dc\u05d0\u05d9\u05e7\u05d8\u05df \u05d9\u05d5\u05ea\u05e8\u05d5\u05e4\u05e0\u05d9 791 \u05d4\u05e9\u05d8\u05d7 \u05d8\u05d5\u05d1\u05d9\u05dd \u05d9\u05d5\u05ea\u05e8, \u05d5\u05dc\u05db\u05df \u05d1\u05de\u05db\u05d5\u05e0\u05d5\u05ea CNC \u05d6\u05d5 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d4\u05d1\u05d7\u05d9\u05e8\u05d4."],[170.0,"\u05d1\u05de\u05db\u05d5\u05e0\u05d5\u05ea \u05d9\u05e9\u05e0\u05d5\u05ea, \u05e2\u05dd \u05de\u05e9\u05d7\u05e7 \u05d1\u05d1\u05d5\u05e8\u05d2, \u05db\u05e8\u05e1\u05d5\u05dd \u05e2\u05dd \u05d4\u05db\u05d9\u05d5\u05d5\u05df \u05e2\u05dc\u05d5\u05dc \u05dc\u05de\u05e9\u05d5\u05da \u05d0\u05ea \u05d4\u05e9\u05d5\u05dc\u05d7\u05df."],[176.0,"\u05d1\u05db\u05e8\u05e1\u05d5\u05dd \u05d0\u05e4\u05e9\u05e8 \u05dc\u05d1\u05e6\u05e2 \u05d4\u05e8\u05d1\u05d4 \u05e4\u05e2\u05d5\u05dc\u05d5\u05ea."],[179.0,"\u05db\u05e8\u05e1\u05d5\u05dd \u05e4\u05e0\u05d9\u05dd \u05de\u05d9\u05d9\u05e9\u05e8 \u05de\u05e9\u05d8\u05d7 \u05d2\u05d3\u05d5\u05dc."],[182.0,"\u05db\u05e8\u05e1\u05d5\u05dd \u05db\u05ea\u05e3 \u05d9\u05d5\u05e6\u05e8 \u05d3\u05d5\u05e4\u05df \u05d5\u05e8\u05e6\u05e4\u05d4 \u05d1\u05d6\u05d5\u05d5\u05d9\u05ea \u05d9\u05e9\u05e8\u05d4."],[186.0,"\u05d1\u05d7\u05e8\u05d9\u05e5 \u05d5\u05d1\u05db\u05d9\u05e1, \u05d4\u05db\u05dc\u05d9 \u05e0\u05db\u05e0\u05e1 \u05dc\u05ea\u05d5\u05da \u05d4\u05d7\u05d5\u05de\u05e8 \u05d5\u05de\u05e4\u05e0\u05d4 \u05e6\u05d5\u05e8\u05d4 \u05e1\u05d2\u05d5\u05e8\u05d4."],[191.0,"\u05db\u05e8\u05e1\u05d5\u05dd \u05e7\u05d5\u05e0\u05d8\u05d5\u05e8 \u05e2\u05d5\u05e7\u05d1 \u05d0\u05d7\u05e8\u05d9 \u05e7\u05d5 \u05d4\u05de\u05ea\u05d0\u05e8 \u05e9\u05dc \u05d4\u05d7\u05dc\u05e7."],[196.0,"\u05d5\u05d1\u05de\u05e8\u05db\u05d6 \u05e2\u05d9\u05d1\u05d5\u05d3 \u05d2\u05dd \u05e7\u05d5\u05d3\u05d7\u05d9\u05dd, \u05de\u05d1\u05e8\u05d9\u05d2\u05d9\u05dd, \u05d5\u05de\u05e2\u05d1\u05d3\u05d9\u05dd \u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05de\u05e2\u05d5\u05e7\u05dc\u05d9\u05dd."],[201.0,"\u05d0\u05ea \u05e8\u05d5\u05d1 \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05ea\u05d5\u05e4\u05e1\u05d9\u05dd \u05d1\u05de\u05dc\u05d7\u05e6\u05d9\u05d9\u05dd, \u05d0\u05d5 \u05d1\u05de\u05ea\u05e7\u05df \u05de\u05d9\u05d5\u05d7\u05d3 \u05dc\u05d7\u05dc\u05e7."],[207.0,"\u05d4\u05ea\u05e4\u05d9\u05e1\u05d4 \u05e7\u05d5\u05d1\u05e2\u05ea \u05de\u05d0\u05d9\u05e4\u05dc\u05d4 \u05e0\u05de\u05d3\u05d3\u05d5\u05ea \u05d4\u05de\u05d9\u05d3\u05d5\u05ea, \u05d5\u05db\u05dc \u05ea\u05e4\u05d9\u05e1\u05d4 \u05e0\u05d5\u05e1\u05e4\u05ea \u05d9\u05db\u05d5\u05dc\u05d4 \u05dc\u05d4\u05d5\u05e1\u05d9\u05e3 \u05e9\u05d2\u05d9\u05d0\u05d4."],[212.0,"\u05dc\u05db\u05df \u05de\u05ea\u05db\u05e0\u05e0\u05d9\u05dd \u05d0\u05ea \u05d4\u05e2\u05d9\u05d1\u05d5\u05d3 \u05db\u05da \u05e9\u05db\u05de\u05d4 \u05e9\u05d9\u05d5\u05ea\u05e8 \u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05d7\u05e9\u05d5\u05d1\u05d9\u05dd \u05d9\u05e2\u05d5\u05d1\u05d3\u05d5 \u05d1\u05d0\u05d5\u05ea\u05d4 \u05ea\u05e4\u05d9\u05e1\u05d4."],[218.0,"\u05d5\u05db\u05dc \u05ea\u05e4\u05d9\u05e1\u05d4 \u05e9\u05d7\u05d5\u05e1\u05db\u05d9\u05dd, \u05d7\u05d5\u05e1\u05db\u05ea \u05d2\u05dd \u05d6\u05de\u05df \u05d4\u05db\u05e0\u05d4."],[223.0,"\u05d2\u05dd \u05d1\u05db\u05e8\u05e1\u05d5\u05dd \u05d9\u05e9 \u05d1\u05e2\u05d9\u05d5\u05ea \u05d0\u05d5\u05e4\u05d9\u05d9\u05e0\u05d9\u05d5\u05ea."],[225.0,"\u05db\u05dc\u05d9 \u05d0\u05e8\u05d5\u05da \u05d5\u05d3\u05e7 \u05de\u05ea\u05db\u05d5\u05e4\u05e3: \u05d4\u05d3\u05d5\u05e4\u05df \u05d9\u05d5\u05e6\u05d0\u05ea \u05dc\u05d0 \u05d9\u05e9\u05e8\u05d4, \u05d5\u05d4\u05db\u05dc\u05d9 \u05e2\u05dc\u05d5\u05dc \u05dc\u05d4\u05d9\u05e9\u05d1\u05e8."],[232.0,"\u05db\u05dc\u05dc \u05d0\u05e6\u05d1\u05e2: \u05db\u05e9\u05d4\u05db\u05dc\u05d9 \u05d1\u05d5\u05dc\u05d8 \u05d9\u05d5\u05ea\u05e8 \u05de\u05e4\u05d9 3 \u05e2\u05d3 4 \u05de\u05d4\u05e7\u05d5\u05d8\u05e8 \u05e9\u05dc\u05d5, \u05de\u05e7\u05d8\u05d9\u05e0\u05d9\u05dd \u05d0\u05ea \u05e2\u05d5\u05de\u05e7 \u05d4\u05d7\u05d9\u05ea\u05d5\u05da \u05d5\u05d0\u05ea \u05d4\u05d4\u05d6\u05e0\u05d4."],[240.0,"\u05e8\u05e2\u05d9\u05d3\u05d5\u05ea \u05de\u05e9\u05d0\u05d9\u05e8\u05d5\u05ea \u05e1\u05d9\u05de\u05e0\u05d9\u05dd \u05e2\u05dc \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7, \u05d1\u05e2\u05d9\u05e7\u05e8 \u05d1\u05d3\u05e4\u05e0\u05d5\u05ea \u05d3\u05e7\u05d5\u05ea."],[245.0,"\u05d1\u05db\u05d9\u05e1\u05d9\u05dd \u05e2\u05de\u05d5\u05e7\u05d9\u05dd, \u05e9\u05d1\u05d1\u05d9\u05dd \u05e9\u05dc\u05d0 \u05de\u05ea\u05e4\u05e0\u05d9\u05dd \u05e0\u05d7\u05ea\u05db\u05d9\u05dd \u05e9\u05d5\u05d1, \u05d5\u05e2\u05dc\u05d5\u05dc\u05d9\u05dd \u05dc\u05e9\u05d1\u05d5\u05e8 \u05d0\u05ea \u05d4\u05db\u05dc\u05d9."],[251.0,"\u05d5\u05d1\u05db\u05dc \u05e7\u05e6\u05d4 \u05e9\u05dc \u05d7\u05d9\u05ea\u05d5\u05da \u05e0\u05d5\u05e6\u05e8 \u05d2\u05e8\u05d3, \u05e9\u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05e1\u05d9\u05e8."],[256.0,"\u05d4\u05db\u05dc\u05d9 \u05e2\u05d2\u05d5\u05dc, \u05d5\u05dc\u05db\u05df \u05e4\u05d9\u05e0\u05d4 \u05e4\u05e0\u05d9\u05de\u05d9\u05ea \u05d1\u05db\u05d9\u05e1 \u05ea\u05de\u05d9\u05d3 \u05ea\u05d4\u05d9\u05d4 \u05e2\u05dd \u05e8\u05d3\u05d9\u05d5\u05e1."],[261.0,"\u05d0\u05dd \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d9\u05e9 \u05e4\u05d9\u05e0\u05d4 \u05e4\u05e0\u05d9\u05de\u05d9\u05ea \u05d7\u05d3\u05d4, \u05e6\u05e8\u05d9\u05da \u05ea\u05d4\u05dc\u05d9\u05da \u05d0\u05d7\u05e8, \u05db\u05de\u05d5 \u05d5\u05d0\u05e1\u05dd."],[267.0,"\u05db\u05d3\u05d0\u05d9 \u05dc\u05ea\u05ea \u05e8\u05d3\u05d9\u05d5\u05e1 \u05d2\u05d3\u05d5\u05dc \u05de\u05e2\u05d8 \u05de\u05d4\u05e8\u05d3\u05d9\u05d5\u05e1 \u05e9\u05dc \u05d4\u05db\u05dc\u05d9, \u05db\u05d3\u05d9 \u05e9\u05d4\u05db\u05dc\u05d9 \u05d9\u05e2\u05d1\u05d5\u05e8 \u05d1\u05e4\u05d9\u05e0\u05d4 \u05d1\u05dc\u05d9 \u05dc\u05d4\u05d9\u05e2\u05e6\u05e8."],[273.0,"\u05db\u05d9\u05e1 \u05e2\u05de\u05d5\u05e7 \u05d5\u05e6\u05e8 \u05d3\u05d5\u05e8\u05e9 \u05db\u05dc\u05d9 \u05d0\u05e8\u05d5\u05da \u05d5\u05d3\u05e7, \u05d5\u05d6\u05d4 \u05d0\u05d9\u05d8\u05d9 \u05d5\u05de\u05e1\u05d5\u05db\u05df \u05dc\u05db\u05dc\u05d9."],[279.0,"\u05d5\u05db\u05dc \u05e6\u05d3 \u05e0\u05d5\u05e1\u05e3 \u05e9\u05e6\u05e8\u05d9\u05da \u05dc\u05e2\u05d1\u05d3 \u05d4\u05d5\u05d0 \u05e2\u05d5\u05d3 \u05ea\u05e4\u05d9\u05e1\u05d4, \u05d5\u05e2\u05d5\u05d3 \u05d6\u05de\u05df."],[284.0,"\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8 \u05db\u05e8\u05e1\u05d5\u05dd?"],[286.0,"\u05de\u05e1\u05e4\u05e8 \u05d4\u05ea\u05e4\u05d9\u05e1\u05d5\u05ea: \u05db\u05dc \u05ea\u05e4\u05d9\u05e1\u05d4 \u05d4\u05d9\u05d0 \u05d6\u05de\u05df \u05d4\u05db\u05e0\u05d4, \u05de\u05dc\u05d7\u05e6\u05d9\u05d9\u05dd \u05d0\u05d5 \u05de\u05ea\u05e7\u05df, \u05d5\u05d1\u05d3\u05d9\u05e7\u05d4."],[292.0,"\u05ea\u05db\u05e0\u05d5\u05ea: \u05d7\u05dc\u05e7 \u05de\u05d5\u05e8\u05db\u05d1 \u05d3\u05d5\u05e8\u05e9 \u05d6\u05de\u05df \u05ea\u05db\u05e0\u05d5\u05ea \u05d5\u05d1\u05d3\u05d9\u05e7\u05d4 \u05e9\u05dc \u05d4\u05de\u05e1\u05dc\u05d5\u05dc."],[298.0,"\u05d6\u05de\u05df \u05de\u05d7\u05d6\u05d5\u05e8: \u05db\u05de\u05d4 \u05d7\u05d5\u05de\u05e8 \u05de\u05d5\u05e8\u05d9\u05d3\u05d9\u05dd, \u05d5\u05de\u05de\u05d4 \u05d4\u05d7\u05dc\u05e7 \u05e2\u05e9\u05d5\u05d5\u05d9."],[302.0,"\u05db\u05dc\u05d9\u05dd \u05e7\u05d8\u05e0\u05d9\u05dd \u05d1\u05db\u05d9\u05e1\u05d9\u05dd \u05e2\u05de\u05d5\u05e7\u05d9\u05dd, \u05d5\u05d3\u05e4\u05e0\u05d5\u05ea \u05d3\u05e7\u05d5\u05ea, \u05de\u05d7\u05d9\u05d9\u05d1\u05d9\u05dd \u05dc\u05e2\u05d1\u05d5\u05d3 \u05dc\u05d0\u05d8."],[308.0,"\u05d5\u05d8\u05d5\u05dc\u05e8\u05e0\u05e1\u05d9\u05dd \u05d4\u05d3\u05d5\u05e7\u05d9\u05dd, \u05d4\u05e1\u05e8\u05ea \u05d2\u05e8\u05d3, \u05d5\u05d1\u05d3\u05d9\u05e7\u05d5\u05ea \u05de\u05d3\u05d9\u05d3\u05d4."],[313.0,"\u05d7\u05e8\u05d9\u05d8\u05d4 \u05d5\u05db\u05e8\u05e1\u05d5\u05dd \u05d4\u05dd \u05e9\u05e0\u05d9 \u05d4\u05ea\u05d4\u05dc\u05d9\u05db\u05d9\u05dd \u05d4\u05de\u05e8\u05db\u05d6\u05d9\u05d9\u05dd \u05d1\u05e2\u05d9\u05d1\u05d5\u05d3 \u05e9\u05d1\u05d1\u05d9."],[317.0,"\u05d7\u05e8\u05d9\u05d8\u05d4 \u05dc\u05d7\u05dc\u05e7\u05d9\u05dd \u05e1\u05d9\u05d1\u05d5\u05d1\u05d9\u05d9\u05dd, \u05d5\u05db\u05e8\u05e1\u05d5\u05dd \u05dc\u05db\u05dc \u05d4\u05e9\u05d0\u05e8: \u05de\u05e9\u05d8\u05d7\u05d9\u05dd, \u05db\u05d9\u05e1\u05d9\u05dd, \u05d7\u05e8\u05d9\u05e6\u05d9\u05dd \u05d5\u05e6\u05d5\u05e8\u05d5\u05ea."],[325.0,"\u05d5\u05d1\u05d7\u05dc\u05e7 \u05d0\u05d7\u05d3 \u05d9\u05e9 \u05dc\u05e2\u05ea\u05d9\u05dd \u05e7\u05e8\u05d5\u05d1\u05d5\u05ea \u05d2\u05dd \u05d5\u05d2\u05dd."],[328.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0: \u05e7\u05d9\u05d3\u05d5\u05d7."]]};
window.MH_TR["\u05e4\u05e8\u05e706_\u05e7\u05d9\u05d3\u05d5\u05d7"]={"t":"\u05e7\u05d9\u05d3\u05d5\u05d7","l":[[1.0,"\u05db\u05de\u05e2\u05d8 \u05d1\u05db\u05dc \u05d7\u05dc\u05e7 \u05d9\u05e9 \u05e7\u05d3\u05d7\u05d9\u05dd: \u05dc\u05d1\u05e8\u05d2\u05d9\u05dd, \u05dc\u05e4\u05d9\u05e0\u05d9\u05dd, \u05dc\u05de\u05e2\u05d1\u05e8 \u05e0\u05d5\u05d6\u05dc\u05d9\u05dd, \u05d0\u05d5 \u05dc\u05d4\u05e8\u05db\u05d1\u05d4 \u05e9\u05dc \u05d7\u05dc\u05e7\u05d9\u05dd \u05d0\u05d7\u05e8\u05d9\u05dd."],[9.0,"\u05e7\u05d9\u05d3\u05d5\u05d7 \u05d4\u05d5\u05d0 \u05d4\u05e4\u05e2\u05d5\u05dc\u05d4 \u05d4\u05e9\u05db\u05d9\u05d7\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05d1\u05e2\u05d9\u05d1\u05d5\u05d3 \u05d4\u05e9\u05d1\u05d1\u05d9, \u05d5\u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d2\u05dd \u05d4\u05e8\u05d0\u05e9\u05d5\u05e0\u05d4 \u05d1\u05db\u05dc \u05e7\u05d3\u05d7."],[15.0,"\u05d0\u05d1\u05dc \u05de\u05e7\u05d3\u05d7 \u05dc\u05d1\u05d3 \u05e0\u05d5\u05ea\u05df \u05d3\u05d9\u05d5\u05e7 \u05de\u05d5\u05d2\u05d1\u05dc, \u05d5\u05dc\u05db\u05df \u05d9\u05e9 \u05e1\u05d1\u05d9\u05d1\u05d5 \u05de\u05e9\u05e4\u05d7\u05d4 \u05e9\u05dc\u05de\u05d4 \u05e9\u05dc \u05db\u05dc\u05d9\u05dd."],[22.0,"\u05d4\u05de\u05e7\u05d3\u05d7 \u05d4\u05e0\u05e4\u05d5\u05e5 \u05d4\u05d5\u05d0 \u05de\u05e7\u05d3\u05d7 \u05dc\u05d5\u05dc\u05d9\u05e0\u05d9, \u05e2\u05dd \u05e9\u05ea\u05d9 \u05e9\u05e4\u05d5\u05ea \u05d7\u05d9\u05ea\u05d5\u05da \u05d1\u05e7\u05e6\u05d4."],[27.0,"\u05d4\u05ea\u05e2\u05dc\u05d5\u05ea \u05d4\u05dc\u05d5\u05dc\u05d9\u05e0\u05d9\u05d5\u05ea \u05de\u05d5\u05e6\u05d9\u05d0\u05d5\u05ea \u05d0\u05ea \u05d4\u05e9\u05d1\u05d1\u05d9\u05dd \u05de\u05ea\u05d5\u05da \u05d4\u05e7\u05d3\u05d7, \u05d5\u05de\u05db\u05e0\u05d9\u05e1\u05d5\u05ea \u05e0\u05d5\u05d6\u05dc \u05e7\u05d9\u05e8\u05d5\u05e8."],[32.0,"\u05dc\u05e7\u05e6\u05d4 \u05d9\u05e9 \u05d6\u05d5\u05d5\u05d9\u05ea: \u05d1\u05de\u05e7\u05d3\u05d7 \u05de\u05e4\u05dc\u05d3\u05d4 \u05de\u05d4\u05d9\u05e8\u05d4 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc 118 \u05de\u05e2\u05dc\u05d5\u05ea, \u05d5\u05d1\u05de\u05e7\u05d3\u05d7 \u05e7\u05e8\u05d1\u05d9\u05d3 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc 130 \u05e2\u05d3 140."],[43.0,"\u05d1\u05de\u05e8\u05db\u05d6 \u05e9\u05dc \u05d4\u05e7\u05e6\u05d4 \u05d9\u05e9 \u05e7\u05d8\u05e2 \u05e9\u05dc\u05d0 \u05d7\u05d5\u05ea\u05da \u05d8\u05d5\u05d1, \u05d5\u05dc\u05db\u05df \u05de\u05e7\u05d3\u05d7 \u05d0\u05e8\u05d5\u05da \u05e0\u05d5\u05d8\u05d4 \u05dc\u05e0\u05d3\u05d5\u05d3 \u05db\u05e9\u05d4\u05d5\u05d0 \u05de\u05ea\u05d7\u05d9\u05dc \u05dc\u05e7\u05d3\u05d5\u05d7."],[51.0,"\u05db\u05d3\u05d9 \u05e9\u05d4\u05e7\u05d3\u05d7 \u05d9\u05ea\u05d7\u05d9\u05dc \u05d1\u05d3\u05d9\u05d5\u05e7 \u05d1\u05de\u05e7\u05d5\u05dd, \u05e7\u05d5\u05d3\u05d7\u05d9\u05dd \u05e7\u05d5\u05d3\u05dd \u05e7\u05d9\u05d3\u05d5\u05d7 \u05de\u05e8\u05db\u05d5\u05d6, \u05d1\u05de\u05e7\u05d3\u05d7 \u05e7\u05e6\u05e8 \u05d5\u05e7\u05e9\u05d9\u05d7."],[58.0,"\u05d2\u05dd \u05d1\u05e7\u05d9\u05d3\u05d5\u05d7 \u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05d4\u05d7\u05d9\u05ea\u05d5\u05da \u05e0\u05e7\u05d1\u05e2\u05ea \u05dc\u05e4\u05d9 \u05e7\u05d5\u05d8\u05e8 \u05d4\u05de\u05e7\u05d3\u05d7 \u05d5\u05d4\u05e1\u05d9\u05d1\u05d5\u05d1\u05d9\u05dd, \u05d5\u05d4\u05d4\u05d6\u05e0\u05d4 \u05d4\u05d9\u05d0 \u05d1\u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8\u05d9\u05dd \u05dc\u05e1\u05d9\u05d1\u05d5\u05d1."],[66.0,"\u05d1\u05de\u05e8\u05db\u05d6 \u05e9\u05dc \u05d4\u05de\u05e7\u05d3\u05d7 \u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05d4\u05d7\u05d9\u05ea\u05d5\u05da \u05db\u05de\u05e2\u05d8 \u05d0\u05e4\u05e1, \u05d5\u05e9\u05dd \u05d4\u05d7\u05d5\u05de\u05e8 \u05e0\u05d3\u05d7\u05e7 \u05d9\u05d5\u05ea\u05e8 \u05de\u05e9\u05d4\u05d5\u05d0 \u05e0\u05d7\u05ea\u05df."],[73.0,"\u05dc\u05db\u05df \u05d4\u05db\u05d5\u05d7 \u05d4\u05e6\u05d9\u05e8\u05d9 \u05d1\u05e7\u05d9\u05d3\u05d5\u05d7 \u05d2\u05d1\u05d5\u05d4."],[76.0,"\u05db\u05db\u05dc \u05e9\u05d4\u05e7\u05d3\u05d7 \u05e2\u05de\u05d5\u05e7 \u05d9\u05d5\u05ea\u05e8, \u05e7\u05e9\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05dc\u05d4\u05d5\u05e6\u05d9\u05d0 \u05d0\u05ea \u05d4\u05e9\u05d1\u05d1\u05d9\u05dd."],[80.0,"\u05d1\u05e7\u05d3\u05d7 \u05e2\u05de\u05d5\u05e7, \u05d1\u05e2\u05e8\u05da \u05de\u05e2\u05d1\u05e8 \u05dc\u05dc\u05d9 3 \u05e2\u05d3 5 \u05de\u05d4\u05e7\u05d5\u05d8\u05e8, \u05e7\u05d5\u05d3\u05d7\u05d9\u05dd \u05d1\u05e0\u05e1\u05d9\u05d2\u05d5\u05ea: \u05e0\u05db\u05e0\u05e1\u05d9\u05dd, \u05d9\u05d5\u05e6\u05d0\u05d9\u05dd \u05dc\u05e4\u05e0\u05d5\u05ea \u05e9\u05d1\u05d1\u05d9\u05dd, \u05d5\u05d7\u05d5\u05d6\u05e8\u05d9\u05dd."],[90.0,"\u05de\u05e7\u05d3\u05d7\u05d9 \u05e7\u05e8\u05d1\u05d9\u05d3 \u05e2\u05dd \u05e7\u05d9\u05e8\u05d5\u05e8 \u05d3\u05e8\u05da \u05d4\u05db\u05dc\u05d9 \u05de\u05d2\u05d9\u05e2\u05d9\u05dd \u05dc\u05e2\u05d5\u05de\u05e7 \u05d2\u05d3\u05d5\u05dc \u05d1\u05d4\u05e8\u05d1\u05d4, \u05d5\u05dc\u05e7\u05d3\u05d7\u05d9\u05dd \u05e2\u05de\u05d5\u05e7\u05d9\u05dd \u05de\u05d0\u05d5\u05d3 \u05d9\u05e9 \u05de\u05e7\u05d3\u05d7\u05d9 \u05d0\u05e7\u05d3\u05d7."],[99.0,"\u05de\u05e7\u05d3\u05d7 \u05d9\u05d5\u05e6\u05e8 \u05e7\u05d3\u05d7 \u05de\u05d4\u05e8, \u05d0\u05d1\u05dc \u05dc\u05d0 \u05de\u05d3\u05d5\u05d9\u05e7 \u05d1\u05de\u05d9\u05d5\u05d7\u05d3."],[103.0,"\u05d4\u05e7\u05d3\u05d7 \u05d9\u05d5\u05e6\u05d0 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05de\u05e2\u05d8 \u05d2\u05d3\u05d5\u05dc \u05de\u05d4\u05e7\u05d5\u05d8\u05e8 \u05d4\u05e0\u05d5\u05de\u05d9\u05e0\u05dc\u05d9, \u05d5\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05e9\u05dc\u05d5 \u05de\u05d7\u05d5\u05e1\u05e4\u05e1\u05d9\u05dd \u05d9\u05d7\u05e1\u05d9\u05ea."],[110.0,"\u05d2\u05dd \u05d4\u05de\u05d9\u05e7\u05d5\u05dd \u05d5\u05d4\u05d9\u05e9\u05e8\u05d5\u05ea \u05e9\u05dc \u05d4\u05e7\u05d3\u05d7 \u05ea\u05dc\u05d5\u05d9\u05d9\u05dd \u05d1\u05d4\u05ea\u05d7\u05dc\u05d4 \u05d8\u05d5\u05d1\u05d4 \u05d5\u05d1\u05de\u05e7\u05d3\u05d7 \u05e7\u05e9\u05d9\u05d7."],[115.0,"\u05dc\u05e7\u05d3\u05d7 \u05dc\u05d1\u05d5\u05e8\u05d2 \u05d0\u05d5 \u05dc\u05de\u05e2\u05d1\u05e8 \u05d6\u05d4 \u05de\u05e1\u05e4\u05d9\u05e7. \u05dc\u05e7\u05d3\u05d7 \u05de\u05d3\u05d5\u05d9\u05e7, \u05db\u05de\u05d5 \u05de\u05d5\u05e9\u05d1 \u05dc\u05e4\u05d9\u05df \u05d0\u05d5 \u05dc\u05de\u05e1\u05d1, \u05de\u05de\u05e9\u05d9\u05db\u05d9\u05dd \u05d1\u05db\u05dc\u05d9 \u05e0\u05d5\u05e1\u05e3."],[124.0,"\u05d5\u05d6\u05d5 \u05d4\u05de\u05e9\u05e4\u05d7\u05d4 \u05e9\u05dc \u05d4\u05e7\u05d9\u05d3\u05d5\u05d7."],[127.0,"\u05e8\u05d9\u05de\u05e8 \u05de\u05e8\u05d7\u05d9\u05d1 \u05e7\u05d3\u05d7 \u05d1\u05e9\u05db\u05d1\u05d4 \u05d3\u05e7\u05d4, \u05d5\u05e0\u05d5\u05ea\u05df \u05e7\u05d5\u05d8\u05e8 \u05de\u05d3\u05d5\u05d9\u05e7, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1\u05d8\u05d5\u05dc\u05e8\u05e0\u05e1 7\u05d4, \u05d5\u05e4\u05e0\u05d9 \u05e9\u05d8\u05d7 \u05d7\u05dc\u05e7\u05d9\u05dd."],[135.0,"\u05d0\u05d1\u05dc \u05e8\u05d9\u05de\u05e8 \u05e2\u05d5\u05e7\u05d1 \u05d0\u05d7\u05e8\u05d9 \u05d4\u05e7\u05d3\u05d7 \u05d4\u05e7\u05d9\u05d9\u05dd, \u05d5\u05dc\u05d0 \u05de\u05ea\u05e7\u05df \u05d0\u05ea \u05d4\u05de\u05d9\u05e7\u05d5\u05dd \u05e9\u05dc\u05d5."],[140.0,"\u05db\u05e9\u05e6\u05e8\u05d9\u05da \u05d2\u05dd \u05de\u05d9\u05e7\u05d5\u05dd \u05de\u05d3\u05d5\u05d9\u05e7, \u05de\u05d1\u05e6\u05e2\u05d9\u05dd \u05d7\u05e8\u05d9\u05d8\u05d4 \u05e4\u05e0\u05d9\u05de\u05d9\u05ea \u05d1\u05e8\u05d0\u05e9 \u05d1\u05d5\u05e8\u05d9\u05e0\u05d2, \u05e9\u05de\u05ea\u05e7\u05df \u05d2\u05dd \u05d0\u05ea \u05d4\u05de\u05d9\u05e7\u05d5\u05dd \u05d5\u05d0\u05ea \u05d4\u05d9\u05e9\u05e8\u05d5\u05ea."],[147.0,"\u05e9\u05d9\u05e7\u05d5\u05e2 \u05d9\u05d5\u05e6\u05e8 \u05de\u05d5\u05e9\u05d1 \u05e9\u05d8\u05d5\u05d7 \u05dc\u05e8\u05d0\u05e9 \u05e9\u05dc \u05d1\u05d5\u05e8\u05d2, \u05db\u05d3\u05d9 \u2026 \u05dc\u05d0 \u05d9\u05d1\u05dc\u05d5\u05d8."],[152.0,"\u05d5\u05e9\u05d9\u05e7\u05d5\u05e2 \u05e7\u05d5\u05e0\u05d9 \u05d9\u05d5\u05e6\u05e8 \u05de\u05d5\u05e9\u05d1 \u05dc\u05d1\u05d5\u05e8\u05d2 \u05e2\u05dd \u05e8\u05d0\u05e9 \u05e7\u05d5\u05e0\u05d9, \u05d5\u05de\u05e9\u05de\u05e9 \u05d2\u05dd \u05dc\u05d4\u05d5\u05e8\u05d3\u05ea \u05d2\u05e8\u05d3 \u05de\u05e9\u05e4\u05ea \u05d4\u05e7\u05d3\u05d7."],[159.0,"\u05d5\u05d0\u05ea \u05d4\u05d4\u05d1\u05e8\u05d2\u05d4 \u05d1\u05e7\u05d3\u05d7 \u05e0\u05db\u05d9\u05e8 \u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0."],[163.0,"\u05e7\u05d3\u05d7 \u05e2\u05d5\u05d1\u05e8 \u05d9\u05d5\u05e6\u05d0 \u05de\u05e6\u05d3 \u05dc\u05e6\u05d3, \u05d5\u05e7\u05d3\u05d7 \u05e2\u05d9\u05d5\u05d5\u05e8 \u05e0\u05e2\u05e6\u05e8 \u05d1\u05ea\u05d5\u05da \u05d4\u05d7\u05d5\u05de\u05e8."],[169.0,"\u05d1\u05ea\u05d7\u05ea\u05d9\u05ea \u05e9\u05dc \u05e7\u05d3\u05d7 \u05e2\u05d9\u05d5\u05d5\u05e8 \u05e0\u05e9\u05d0\u05e8 \u05e7\u05d5\u05e0\u05d5\u05e1, \u05d1\u05d6\u05d5\u05d5\u05d9\u05ea \u05e9\u05dc \u05e7\u05e6\u05d4 \u05d4\u05de\u05e7\u05d3\u05d7."],[174.0,"\u05d0\u05dd \u05e6\u05e8\u05d9\u05da \u05ea\u05d7\u05ea\u05d9\u05ea \u05e9\u05d8\u05d5\u05d7\u05d4, \u05e6\u05e8\u05d9\u05da \u05db\u05dc\u05d9 \u05de\u05d9\u05d5\u05d7\u05d3, \u05d5\u05d6\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8."],[179.0,"\u05d5\u05d1\u05e7\u05d3\u05d7 \u05e2\u05d9\u05d5\u05d5\u05e8, \u05d4\u05e9\u05d1\u05d1\u05d9\u05dd \u05e6\u05e8\u05d9\u05db\u05d9\u05dd \u05dc\u05e6\u05d0\u05ea \u05d3\u05e8\u05da \u05d0\u05d5\u05ea\u05d5 \u05e4\u05ea\u05d7 \u05e9\u05d5\u05d1\u05d5 \u05d4\u05de\u05e7\u05d3\u05d7 \u05e0\u05db\u05e0\u05e1."],[185.0,"\u05d2\u05dd \u05d1\u05e7\u05d9\u05d3\u05d5\u05d7 \u05d9\u05e9 \u05d1\u05e2\u05d9\u05d5\u05ea \u05d0\u05d5\u05e4\u05d9\u05d9\u05e0\u05d9\u05d5\u05ea."],[188.0,"\u05e0\u05d3\u05d9\u05d3\u05d4 \u05d1\u05ea\u05d7\u05d9\u05dc\u05ea \u05d4\u05e7\u05d9\u05d3\u05d5\u05d7, \u05d1\u05e2\u05d9\u05e7\u05e8 \u05db\u05e9\u05d4\u05de\u05e7\u05d3\u05d7 \u05e0\u05db\u05e0\u05e1 \u05dc\u05de\u05e9\u05d8\u05d7 \u05de\u05e9\u05d5\u05e4\u05e2 \u05d0\u05d5 \u05de\u05e2\u05d5\u05e7\u05dc."],[194.0,"\u05e9\u05d1\u05d1\u05d9\u05dd \u05e9\u05e0\u05ea\u05e7\u05e2\u05d9\u05dd \u05d1\u05ea\u05e2\u05dc\u05d5\u05ea \u05e9\u05e9\u05d5\u05d1\u05e8\u05d9\u05dd \u05de\u05e7\u05d3\u05d7\u05d9\u05dd, \u05d1\u05e2\u05d9\u05e7\u05e8 \u05e7\u05d8\u05e0\u05d9\u05dd."],[199.0,"\u05d2\u05e8\u05d3 \u05d1\u05d9\u05e6\u05d9\u05d0\u05d4 \u05e9\u05dc \u05e7\u05d3\u05d7 \u05e2\u05d5\u05d1\u05e8, \u05e9\u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05e1\u05d9\u05e8."],[203.0,"\u05d5\u05de\u05e7\u05d3\u05d7 \u05e9\u05d7\u05d5\u05e7 \u05d7\u05d5\u05ea\u05da \u05e4\u05d7\u05d5\u05ea \u05d8\u05d5\u05d1, \u05de\u05ea\u05d7\u05de\u05dd, \u05d5\u05e0\u05d5\u05ea\u05df \u05e7\u05d3\u05d7 \u05d2\u05d3\u05d5\u05dc \u05de\u05d3\u05d9 \u05d0\u05d5 \u05dc\u05d0 \u05e2\u05d2\u05d5\u05dc."],[211.0,"\u05d2\u05dd \u05e7\u05d3\u05d7\u05d9\u05dd \u05db\u05d3\u05d0\u05d9 \u05dc\u05ea\u05db\u05e0\u05df \u05e0\u05db\u05d5\u05df."],[213.0,"\u05dc\u05d4\u05e9\u05d5\u05ea\u05de\u05e9 \u05d1\u05e7\u05d8\u05e8\u05d9\u05dd \u05e1\u05d8\u05e0\u05d3\u05e8\u05d8\u05d9\u05d9\u05dd, \u05e9\u05d9\u05e9 \u05dc\u05d4\u05dd \u05de\u05e7\u05d3\u05d7 \u05de\u05d5\u05db\u05df \u05de\u05d4\u05de\u05d3\u05e3."],[218.0,"\u05dc\u05d4\u05e9\u05d0\u05d9\u05e8 \u05dc\u05de\u05e7\u05d3\u05d7 \u05de\u05e9\u05d8\u05d7 \u05e0\u05d9\u05e6\u05d1 \u05dc\u05d5, \u05d1\u05db\u05e0\u05d9\u05e1\u05d4 \u05d5\u05d1\u05d9\u05e6\u05d9\u05d0\u05d4."],[222.0,"\u05dc\u05d4\u05d9\u05de\u05e0\u05e2, \u05db\u05e9\u05d0\u05e4\u05e9\u05e8, \u05de\u05e7\u05d3\u05d7\u05d9\u05dd \u05e2\u05de\u05d5\u05e7\u05d9\u05dd \u05de\u05d0\u05d5\u05d3 \u05d1\u05e7\u05d5\u05d8\u05e8 \u05e7\u05d8\u05df."],[227.0,"\u05d5\u05dc\u05ea\u05ea \u05d8\u05d5\u05dc\u05e8\u05e0\u05e1 \u05d4\u05d3\u05d5\u05e7 \u05e8\u05e7 \u05dc\u05e7\u05d3\u05d7\u05d9\u05dd \u05e9\u05d1\u05d0\u05de\u05ea \u05e6\u05e8\u05d9\u05db\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5, \u05db\u05d9 \u05db\u05dc \u05e7\u05d3\u05d7 \u05de\u05d3\u05d5\u05d9\u05e7 \u05de\u05d5\u05e1\u05d9\u05e3 \u05e4\u05e2\u05d5\u05dc\u05d4."],[234.0,"\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8 \u05e7\u05d9\u05d3\u05d5\u05d7?"],[236.0,"\u05de\u05e1\u05e4\u05e8 \u05d4\u05e7\u05d3\u05d7\u05d9\u05dd \u05d5\u05d4\u05e7\u05d8\u05e8\u05d9\u05dd \u05d4\u05e9\u05d5\u05e0\u05d9\u05dd: \u05db\u05dc \u05e7\u05d5\u05d8\u05e8 \u05d4\u05d5\u05d0 \u05e2\u05d5\u05d3 \u05db\u05dc\u05d9 \u05d5\u05e2\u05d5\u05d3 \u05d4\u05d7\u05dc\u05e1\u05d4."],[242.0,"\u05e7\u05d3\u05d7\u05d9\u05dd \u05e2\u05de\u05d5\u05e7\u05d9\u05dd, \u05e9\u05d3\u05d5\u05e8\u05e9\u05d9\u05dd \u05e0\u05e1\u05d9\u05d2\u05d5\u05ea \u05d0\u05d5 \u05db\u05dc\u05d9\u05dd \u05de\u05d9\u05d5\u05d7\u05d3\u05d9\u05dd."],[246.0,"\u05e7\u05d3\u05d7\u05d9\u05dd \u05de\u05d3\u05d5\u05d9\u05e7\u05d9\u05dd, \u05e9\u05d3\u05d5\u05e8\u05e9\u05d9\u05dd \u05e8\u05d9\u05de\u05e8 \u05d0\u05d5 \u05d7\u05e8\u05d9\u05d8\u05d4 \u05e4\u05e0\u05d9\u05de\u05d9\u05ea \u05d0\u05d7\u05e8\u05d9 \u05d4\u05e7\u05d9\u05d3\u05d5\u05d7."],[251.0,"\u05d7\u05d5\u05de\u05e8\u05d9\u05dd \u05e7\u05e9\u05d9\u05dd, \u05d5\u05de\u05e7\u05d3\u05d7\u05d9\u05dd \u05e7\u05d8\u05e0\u05d9\u05dd \u05e9\u05e0\u05e9\u05d1\u05e8\u05d9\u05dd."],[254.0,"\u05d5\u05d4\u05e1\u05e8\u05ea \u05d2\u05e8\u05d3, \u05d1\u05e2\u05d9\u05e7\u05e8 \u05d1\u05e7\u05d3\u05d7\u05d9\u05dd \u05e9\u05e0\u05e4\u05d2\u05e9\u05d9\u05dd \u05d1\u05ea\u05d5\u05da \u05d4\u05d7\u05dc\u05e7."],[260.0,"\u05e7\u05d9\u05d3\u05d5\u05d7 \u05d9\u05d5\u05e6\u05e8 \u05d0\u05ea \u05d4\u05e7\u05d3\u05d7, \u05d5\u05d4\u05de\u05e9\u05e4\u05d7\u05d4 \u05e9\u05dc\u05d5 \u05e0\u05d5\u05ea\u05e0\u05ea \u05dc\u05d5 \u05d3\u05d9\u05d5\u05e7 \u05d5\u05e6\u05d5\u05e8\u05d4."],[265.0,"\u05de\u05e7\u05d3\u05d7 \u05dc\u05de\u05d4\u05d9\u05e8\u05d5\u05ea, \u05e8\u05d9\u05de\u05e8 \u05dc\u05e7\u05d5\u05d8\u05e8 \u05de\u05d3\u05d5\u05d9\u05e7, \u05d7\u05e8\u05d9\u05d8\u05d4 \u05e4\u05e0\u05d9\u05de\u05d9\u05ea \u05dc\u05de\u05d9\u05e7\u05d5\u05dd \u05de\u05d3\u05d5\u05d9\u05e7, \u05d5\u05e9\u05d9\u05e7\u05d5\u05e2 \u05dc\u05e8\u05d0\u05e9 \u05d4\u05d1\u05d5\u05e8\u05d2."],[273.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0: \u05d4\u05d1\u05e8\u05d2\u05d4."]]};
window.MH_TR["\u05e4\u05e8\u05e707_\u05d4\u05d1\u05e8\u05d2\u05d4"]={"t":"\u05d4\u05d1\u05e8\u05d2\u05d4","l":[[1.0,"\u05db\u05de\u05e2\u05d8 \u05db\u05dc \u05de\u05d5\u05e6\u05e8 \u05de\u05db\u05e0\u05d9 \u05de\u05d5\u05d7\u05d6\u05e7 \u05d9\u05d7\u05d3 \u05d1\u05d1\u05e8\u05d2\u05d9\u05dd."],[5.0,"\u05d4\u05d1\u05e8\u05d2\u05d4 \u05d4\u05d9\u05d0 \u05d9\u05e6\u05d9\u05e8\u05d4 \u05e9\u05dc \u05ea\u05d1\u05e8\u05d9\u05d2: \u05d7\u05e8\u05d9\u05e5 \u05dc\u05d5\u05dc\u05d9\u05d9\u05e0\u05d9, \u05e4\u05e0\u05d9\u05de\u05d9 \u05d1\u05e7\u05d3\u05d7 \u05d0\u05d5 \u05d7\u05d9\u05e6\u05d5\u05e0\u05d9 \u05e2\u05dc \u05d2\u05dc."],[11.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d6\u05d4 \u05e0\u05db\u05d9\u05e8 \u05d0\u05ea \u05d4\u05ea\u05d1\u05e8\u05d9\u05d2 \u05e2\u05e6\u05de\u05d5, \u05d0\u05ea \u05d4\u05d3\u05e8\u05db\u05d9\u05dd \u05dc\u05d9\u05d9\u05e6\u05e8 \u05d0\u05d5\u05ea\u05d5, \u05d5\u05d0\u05ea \u05de\u05d4 \u05e9\u05d7\u05e9\u05d5\u05d1 \u05dc\u05d3\u05e2\u05ea \u05db\u05e9\u05de\u05ea\u05db\u05e0\u05e0\u05d9\u05dd \u05d7\u05dc\u05e7 \u05de\u05d5\u05d1\u05e8\u05d2."],[20.0,"\u05ea\u05d1\u05e8\u05d9\u05d2 \u05d4\u05d5\u05d0 \u05d7\u05e8\u05d9\u05e5 \u05e9\u05de\u05e1\u05ea\u05dc\u05e1\u05dc \u05e1\u05d1\u05d9\u05d1 \u05e6\u05d9\u05e8, \u05db\u05de\u05d5 \u05dc\u05d5\u05dc\u05d9\u05d9\u05df."],[24.0,"\u05d4\u05e4\u05e1\u05d9\u05e2\u05d4 \u05d4\u05d9\u05d0 \u05d4\u05de\u05e8\u05d7\u05e7 \u05d1\u05d9\u05df \u05e9\u05ea\u05d9 \u05e9\u05d9\u05e0\u05d9\u05d9\u05dd \u05e1\u05de\u05d5\u05db\u05d5\u05ea, \u05d5\u05d1\u05ea\u05d1\u05e8\u05d9\u05d2 \u05e8\u05d2\u05d9\u05dc \u05d4\u05d9\u05d0 \u05d2\u05dd \u05d4\u05de\u05e8\u05d7\u05e7 \u05e9\u05d4\u05d1\u05d5\u05e8\u05d2 \u05de\u05ea\u05e7\u05d3\u05dd \u05d1\u05e1\u05d9\u05d1\u05d5\u05d1 \u05d0\u05d7\u05d3."],[32.0,"\u05d4\u05ea\u05d1\u05e8\u05d9\u05d2 \u05d4\u05e0\u05e4\u05d5\u05e5 \u05d4\u05d5\u05d0 \u05d4\u05de\u05d8\u05e8\u05d9, \u05e2\u05dd \u05d6\u05d5\u05d5\u05d9\u05ea \u05e9\u05dc 60 \u05de\u05e2\u05dc\u05d5\u05ea \u05d1\u05d9\u05df \u05e6\u05d9\u05d3\u05d9 \u05d4\u05e9\u05df."],[37.0,"\u05dc\u05de\u05e9\u05dc, 10\u05d5\u05d0 \u05d4\u05d5\u05d0 \u05ea\u05d1\u05e8\u05d9\u05d2 \u05d1\u05e7\u05d5\u05d8\u05e8 10 \u05de\"\u05de, \u05e2\u05dd \u05e4\u05e1\u05d9\u05e2\u05d4 \u05d2\u05e1\u05d4 \u05e9\u05dc 1.5 \u05de\"\u05de."],[44.0,"\u05d9\u05e9 \u05d2\u05dd \u05ea\u05d1\u05e8\u05d9\u05d2 \u05e2\u05d3\u05d9\u05df, \u05e2\u05dd \u05e4\u05e1\u05d9\u05e2\u05d4 \u05e7\u05d8\u05e0\u05d4 \u05d9\u05d5\u05ea\u05e8, \u05dc\u05de\u05e9\u05dc 10\u05d5\u05d0 \u05e2\u05dd \u05e4\u05e1\u05d9\u05e2\u05d4 \u05e9\u05dc 1.25 \u05de\"\u05de."],[51.0,"\u05e9\u05d0\u05d5\u05d8\u05de\u05d9\u05dd, \u05d5\u05ea\u05d1\u05e8\u05d9\u05d2 \u05d8\u05e8\u05e4\u05d6\u05d9 \u05dc\u05ea\u05e0\u05d5\u05e2\u05d4, \u05db\u05de\u05d5 \u05d1\u05d1\u05d5\u05e8\u05d2 \u05d4\u05d4\u05d6\u05e0\u05d4 \u05e9\u05dc \u05de\u05db\u05d5\u05e0\u05d4."],[61.0,"\u05db\u05d3\u05d9 \u05e9\u05d1\u05d5\u05e8\u05d2 \u05d5\u05d0\u05d5\u05dd \u05d9\u05ea\u05d0\u05d9\u05de\u05d5 \u05d6\u05d4 \u05dc\u05d6\u05d4, \u05d9\u05e9 \u05dc\u05d4\u05dd \u05d3\u05e8\u05d2\u05d5\u05ea \u05d8\u05d5\u05dc\u05e8\u05e0\u05e1. \u05d4\u05e0\u05e4\u05d5\u05e6\u05d5\u05ea: \u05d76 \u05dc\u05d0\u05d5\u05dd, \u05d5-60 \u05dc\u05d1\u05d5\u05e8\u05d2."],[71.0,"\u05ea\u05d1\u05e8\u05d9\u05d2 \u05e4\u05e0\u05d9\u05de\u05d9 \u05d1\u05e7\u05d3\u05d7 \u05de\u05d1\u05e6\u05e2\u05d9\u05dd \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1\u05de\u05d1\u05e8\u05d6."],[75.0,"\u05e7\u05d5\u05d3\u05d7\u05d9\u05dd \u05e7\u05d5\u05d3\u05dd \u05e7\u05d3\u05d7 \u05d1\u05e7\u05d5\u05d8\u05e8 \u05de\u05ea\u05d0\u05d9\u05dd, \u05d5\u05d4\u05de\u05d1\u05e8\u05d6 \u05d7\u05d5\u05ea\u05da \u05d0\u05ea \u05d4\u05e9\u05d9\u05e0\u05d9\u05d9\u05dd \u05d1\u05d3\u05e4\u05e0\u05d5\u05ea \u05d4\u05e7\u05d3\u05d7."],[81.0,"\u05d1\u05ea\u05d1\u05e8\u05d9\u05d2 \u05de\u05d8\u05e8\u05d9 \u05d2\u05e1, \u05e7\u05d5\u05d8\u05e8 \u05d4\u05e7\u05d3\u05d7 \u05d4\u05d5\u05d0 \u05d1\u05e2\u05e8\u05da \u05d4\u05e7\u05d5\u05d8\u05e8 \u05e4\u05d7\u05d5\u05ea \u05d4\u05e4\u05e1\u05d9\u05e2\u05d4: \u05d1\u05e9\u05d1\u05d9\u05dc 10\u05d5\u05d0 \u05e7\u05d5\u05d3\u05d7\u05d9\u05dd 8.5 \u05de\"\u05de."],[90.0,"\u05de\u05d1\u05e8\u05d6 \u05e2\u05dd \u05ea\u05e2\u05dc\u05d5\u05ea \u05dc\u05d5\u05dc\u05d9\u05e0\u05d9\u05d5\u05ea \u05de\u05d5\u05e9\u05da \u05d0\u05ea \u05d4\u05e9\u05d1\u05d1\u05d9\u05dd \u05dc\u05de\u05e2\u05dc\u05d4, \u05d5\u05de\u05ea\u05d0\u05d9\u05dd \u05dc\u05e7\u05d3\u05d7\u05d9\u05dd \u05e2\u05d9\u05d5\u05d5\u05e8\u05d9\u05dd."],[96.0,"\u05de\u05d1\u05e8\u05d6 \u05e2\u05dd \u05e7\u05e6\u05d4 \u05e1\u05e4\u05d9\u05e8\u05dc\u05d4 \u05d3\u05d5\u05d7\u05e3 \u05d0\u05ea \u05d4\u05e9\u05d5\u05d1\u05d1\u05d9\u05dd \u05e7\u05d3\u05d9\u05de\u05d4, \u05d5\u05de\u05ea\u05d0\u05d9\u05dd \u05dc\u05e7\u05d3\u05d7\u05d9\u05dd \u05e2\u05d5\u05d1\u05e8\u05d9\u05dd."],[101.0,"\u05d9\u05e9 \u05d2\u05dd \u05de\u05d1\u05e8\u05d6 \u05de\u05e2\u05e6\u05d1, \u05e9\u05dc\u05d0 \u05d7\u05d5\u05ea\u05da \u05d0\u05dc\u05d0 \u05d3\u05d5\u05d7\u05e7 \u05d0\u05ea \u05d4\u05d7\u05d5\u05de\u05e8 \u05dc\u05e6\u05d5\u05e8\u05ea \u05d4\u05e9\u05df."],[107.0,"\u05d0\u05d9\u05df \u05e9\u05d1\u05d1\u05d9\u05dd \u05d5\u05d4\u05ea\u05d1\u05e8\u05d9\u05d2 \u05d7\u05d6\u05e7 \u05d9\u05d5\u05ea\u05e8, \u05d0\u05d1\u05dc \u05e6\u05e8\u05d9\u05da \u05e7\u05d3\u05d7 \u05d2\u05d3\u05d5\u05dc \u05de\u05e2\u05d8 \u05d9\u05d5\u05ea\u05e8, \u05d5\u05d7\u05d5\u05de\u05e8 \u05e8\u05e7\u05d9\u05e2."],[113.0,"\u05d4\u05e1\u05db\u05e0\u05d4 \u05d4\u05d2\u05d3\u05d5\u05dc\u05d4: \u05de\u05d1\u05e8\u05d6 \u05e9\u05e0\u05e9\u05d1\u05e8 \u05d1\u05ea\u05d5\u05da \u05d4\u05e7\u05d3\u05d7. \u05e7\u05e9\u05d4 \u05dc\u05d4\u05d5\u05e6\u05d9\u05d0 \u05d0\u05d5\u05ea\u05d5, \u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05e8\u05e7 EDM-2, \u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d4\u05d7\u05dc\u05e7 \u05e0\u05e4\u05e1\u05dc."],[123.0,"\u05d3\u05e8\u05da \u05d0\u05d7\u05e8\u05ea \u05d4\u05d9\u05d0 \u05db\u05e8\u05e1\u05d5\u05dd \u05d4\u05d1\u05e8\u05d2\u05d4."],[126.0,"\u05db\u05dc\u05d9 \u05e7\u05d8\u05df \u05de\u05e7\u05d5\u05d8\u05e8 \u05d4\u05e7\u05d3\u05d7 \u05e0\u05db\u05e0\u05e1 \u05d5\u05e0\u05e2 \u05d1\u05ea\u05e0\u05d5\u05e2\u05d4 \u05de\u05e2\u05d2\u05dc\u05d9\u05ea \u05d5\u05dc\u05d5\u05dc\u05d9\u05d9\u05e0\u05d9\u05ea, \u05d5\u05d1\u05db\u05dc \u05e1\u05d9\u05d1\u05d5\u05d1 \u05de\u05ea\u05e7\u05d3\u05dd \u05e4\u05e1\u05d9\u05e2\u05d4 \u05d0\u05d7\u05ea."],[135.0,"\u05db\u05dc\u05d9 \u05d0\u05d7\u05d3 \u05de\u05ea\u05d0\u05d9\u05dd \u05dc\u05d4\u05e8\u05d1\u05d4 \u05e7\u05d8\u05e8\u05d9\u05dd \u05e2\u05dd \u05d0\u05d5\u05ea\u05d4 \u05e4\u05e1\u05d9\u05e2\u05d4, \u05d5\u05d4\u05e9\u05d1\u05d1\u05d9\u05dd \u05e7\u05d8\u05e0\u05d9\u05dd."],[139.0,"\u05d5\u05d0\u05dd \u05d4\u05db\u05dc\u05d9 \u05e0\u05e9\u05d1\u05e8, \u05d4\u05d5\u05d0 \u05e7\u05d8\u05df \u05de\u05d4\u05e7\u05d3\u05d7 \u05d5\u05e7\u05dc \u05dc\u05d4\u05d5\u05e6\u05d9\u05d0 \u05d0\u05d5\u05ea\u05d5."],[144.0,"\u05dc\u05db\u05df \u05d6\u05d5 \u05d1\u05d7\u05d9\u05e8\u05d4 \u05d8\u05d5\u05d1\u05d4 \u05dc\u05d7\u05dc\u05e7\u05d9\u05dd \u05d9\u05e7\u05e8\u05d9\u05dd, \u05dc\u05d7\u05d5\u05de\u05e8\u05d9\u05dd \u05e7\u05e9\u05d9\u05dd \u05d5\u05dc\u05e7\u05d8\u05e8\u05d9\u05dd \u05d2\u05d3\u05d5\u05dc\u05d9\u05dd."],[150.0,"\u05ea\u05d1\u05e8\u05d9\u05d2 \u05d7\u05d9\u05e6\u05d5\u05e0\u05d9 \u05d0\u05e4\u05e9\u05e8 \u05dc\u05d7\u05e8\u05d5\u05d8 \u05d0\u05d5 \u05dc\u05d2\u05dc\u05d2\u05dc."],[153.0,"\u05d1\u05de\u05d7\u05e8\u05d8\u05d4, \u05dc\u05d4\u05d1 \u05d7\u05d9\u05ea\u05d5\u05da \u05d1\u05e6\u05d5\u05e8\u05ea \u05d4\u05e9\u05d5\u05df \u05e2\u05d5\u05d1\u05e8 \u05d1\u05db\u05de\u05d4 \u05de\u05e2\u05d1\u05e8\u05d9\u05dd, \u05d5\u05d1\u05db\u05dc \u05de\u05e2\u05d1\u05e8 \u05de\u05e2\u05de\u05d9\u05e7 \u05e2\u05d5\u05d3 \u05e7\u05e6\u05ea."],[161.0,"\u05d4\u05de\u05db\u05d5\u05e0\u05d4 \u05de\u05e1\u05e0\u05db\u05e8\u05e0\u05ea \u05d0\u05ea \u05d4\u05d4\u05d6\u05e0\u05d4 \u05e2\u05dd \u05d4\u05e1\u05d9\u05d1\u05d5\u05d1, \u05db\u05da \u05e9\u05db\u05dc \u05de\u05e2\u05d1\u05e8 \u05e0\u05d5\u05e4\u05dc \u05d1\u05d3\u05d9\u05d5\u05e7 \u05e2\u05dc \u05d4\u05d7\u05e8\u05d9\u05e5."],[168.0,"\u05d1\u05d2\u05dc\u05d2\u05d5\u05dc \u05d4\u05d1\u05e8\u05d2\u05d4 \u05dc\u05d0 \u05de\u05d5\u05e8\u05d9\u05d3\u05d9\u05dd \u05d7\u05d5\u05de\u05e8: \u05d2\u05dc\u05d9\u05dc\u05d9\u05dd \u05e7\u05e9\u05d9\u05dd \u05e2\u05dd \u05e6\u05d5\u05e8\u05ea \u05d4\u05ea\u05d1\u05e8\u05d9\u05d2 \u05dc\u05d5\u05d7\u05e6\u05d9\u05dd \u05e2\u05dc \u05d4\u05de\u05d5\u05d8, \u05d5\u05d4\u05d7\u05d5\u05de\u05e8 \u05d6\u05d5\u05e8\u05dd \u05dc\u05e6\u05d5\u05e8\u05ea \u05d4\u05e9\u05d9\u05e0\u05d9\u05d9\u05dd."],[176.0,"\u05d4\u05ea\u05d1\u05e8\u05d9\u05d2 \u05d7\u05d6\u05e7 \u05d9\u05d5\u05ea\u05e8, \u05db\u05d9 \u05d4\u05e1\u05d9\u05d1\u05d9\u05dd \u05dc\u05d0 \u05e0\u05d7\u05ea\u05db\u05d9\u05dd, \u05d5\u05d4\u05ea\u05d4\u05dc\u05d9\u05da \u05de\u05d4\u05d9\u05e8 \u05de\u05d0\u05d5\u05d3."],[182.0,"\u05db\u05da \u05de\u05d9\u05d9\u05e6\u05e8\u05d9\u05dd \u05d0\u05ea \u05e8\u05d5\u05d1 \u05d4\u05d1\u05e8\u05d2\u05d9\u05dd \u05d4\u05e1\u05d8\u05e0\u05d3\u05e8\u05d8\u05d9\u05d9\u05dd."],[185.0,"\u05d2\u05dd \u05d4\u05d1\u05e8\u05d2\u05d5\u05ea \u05db\u05d3\u05d0\u05d9 \u05dc\u05ea\u05db\u05e0\u05df \u05e0\u05db\u05d5\u05df."],[188.0,"\u05d0\u05d7\u05d9\u05d6\u05d4 \u05e9\u05dc \u05d1\u05e2\u05e8\u05da \u05e4\u05e2\u05dd \u05d5\u05d7\u05e6\u05d9 \u05d4\u05e7\u05d5\u05d8\u05e8 \u05de\u05e1\u05e4\u05d9\u05e7, \u05d5\u05d1\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05d1\u05e2\u05e8\u05da \u05e4\u05e2\u05de\u05d9\u05d9\u05dd \u05d4\u05e7\u05d5\u05d8\u05e8."],[198.0,"\u05de\u05e2\u05d1\u05e8 \u05dc\u05d6\u05d4, \u05d4\u05e9\u05d9\u05e0\u05d9\u05d9\u05dd \u05d4\u05e0\u05d5\u05e1\u05e4\u05d5\u05ea \u05db\u05de\u05e2\u05d8 \u05dc\u05d0 \u05e0\u05d5\u05e9\u05d0\u05d5\u05ea \u05e2\u05d5\u05de\u05e1, \u05d5\u05e8\u05e7 \u05de\u05d5\u05e1\u05d9\u05e4\u05d5\u05ea \u05d6\u05de\u05df \u05d5\u05e1\u05d9\u05db\u05d5\u05df."],[204.0,"\u05d1\u05e7\u05d3\u05d7 \u05e2\u05d9\u05d5\u05d5\u05e8 \u05e7\u05d5\u05d3\u05d7\u05d9\u05dd \u05e2\u05de\u05d5\u05e7 \u05d9\u05d5\u05ea\u05e8 \u05de\u05d4\u05ea\u05d1\u05e8\u05d9\u05d2, \u05db\u05d3\u05d9 \u05dc\u05d4\u05e9\u05d0\u05d9\u05e8 \u05de\u05e7\u05d5\u05dd \u05dc\u05e7\u05e6\u05d4 \u05d4\u05de\u05d1\u05e8\u05d6 \u05d5\u05dc\u05e9\u05d1\u05d1\u05d9\u05dd."],[211.0,"\u05d1\u05ea\u05d1\u05e8\u05d9\u05d2 \u05d7\u05d9\u05e6\u05d5\u05e0\u05d9 \u05e9\u05de\u05d2\u05d9\u05e2 \u05e2\u05d3 \u05db\u05ea\u05e3, \u05de\u05ea\u05db\u05e0\u05e0\u05d9\u05dd \u05d7\u05e8\u05d9\u05e5 \u05d9\u05e6\u05d9\u05d0\u05d4, \u05db\u05d3\u05d9 \u05e9\u05d4\u05db\u05dc\u05d9 \u05d9\u05d5\u05db\u05dc \u05dc\u05e6\u05d0\u05ea."],[217.0,"\u05d5\u05d1\u05ea\u05d7\u05d9\u05dc\u05ea \u05db\u05dc \u05ea\u05d1\u05e8\u05d9\u05d2 \u05e2\u05d5\u05e9\u05d9\u05dd \u05e9\u05d9\u05e4\u05d5\u05e2 \u05e7\u05d8\u05df, \u05db\u05d3\u05d9 \u05e9\u05d4\u05d1\u05d5\u05e8\u05d2 \u05d9\u05d9\u05db\u05e0\u05e1 \u05d1\u05e7\u05dc\u05d5\u05ea \u05d5\u05d4\u05e9\u05df \u05d4\u05e8\u05d0\u05e9\u05d5\u05e0\u05d4 \u05dc\u05d0 \u05ea\u05ea\u05e2\u05e7\u05dd."],[224.0,"\u05d1\u05d7\u05d5\u05de\u05e8\u05d9\u05dd \u05e8\u05db\u05d9\u05dd, \u05d0\u05d5 \u05db\u05e9\u05d4\u05d1\u05d5\u05e8\u05d2 \u05e0\u05e4\u05ea\u05d7 \u05d5\u05e0\u05e1\u05d2\u05e8 \u05d4\u05e8\u05d1\u05d4 \u05e4\u05e2\u05de\u05d9\u05dd, \u05de\u05ea\u05e7\u05d9\u05e0\u05d9\u05dd \u05e7\u05e4\u05d9\u05e5 \u05d4\u05d1\u05e8\u05d2\u05d4, \u05e9\u05de\u05d7\u05d6\u05e7 \u05d0\u05ea \u05d4\u05ea\u05d1\u05e8\u05d9\u05d2."],[233.0,"\u05ea\u05d1\u05e8\u05d9\u05d2 \u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05d1\u05de\u05d3\u05d9\u05dd \u05e9\u05dc \u05e2\u05d5\u05d1\u05e8 \u05d5\u05dc\u05d0 \u05e2\u05d5\u05d1\u05e8."],[236.0,"\u05dc\u05d4\u05d9\u05db\u05e0\u05e1 \u05e2\u05d3 \u05d4\u05e1\u05d5\u05e3, \u05d5\u05d4\u05e6\u05d3 \u05d4\u05dc\u05d0 \u05e2\u05d5\u05d1\u05e8 \u05dc\u05d0 \u05d0\u05de\u05d5\u05e8 \u05dc\u05d4\u05d9\u05db\u05e0\u05e1 \u05d9\u05d5\u05ea\u05e8 \u05de\u05db\u05de\u05d4 \u05e1\u05d9\u05d1\u05d5\u05d1\u05d9\u05dd."],[246.0,"\u05dc\u05ea\u05d1\u05e8\u05d9\u05d2 \u05d7\u05d9\u05e6\u05d5\u05e0\u05d9 \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05d8\u05d1\u05e2\u05ea, \u05d1\u05d0\u05d5\u05ea\u05d5 \u05e2\u05d9\u05e7\u05e8\u05d5\u05df."],[251.0,"\u05d2\u05dd \u05d1\u05d4\u05d1\u05e8\u05d2\u05d4 \u05d9\u05e9 \u05d1\u05e2\u05d9\u05d5\u05ea \u05d0\u05d5\u05e4\u05d9\u05d9\u05e0\u05d9\u05d5\u05ea."],[254.0,"\u05de\u05d1\u05e8\u05d6 \u05e9\u05d1\u05d5\u05e8, \u05d1\u05e2\u05d9\u05e7\u05e8 \u05d1\u05e7\u05d3\u05d7\u05d9\u05dd \u05e2\u05d9\u05d5\u05d5\u05e8\u05d9\u05dd \u05e7\u05d8\u05e0\u05d9\u05dd, \u05d5\u05d1\u05d7\u05d5\u05de\u05e8\u05d9\u05dd \u05e7\u05e9\u05d9\u05dd \u05d0\u05d5 \u05d3\u05d1\u05d9\u05e7\u05d9\u05dd."],[260.0,"\u05ea\u05d1\u05e8\u05d9\u05d2 \u05d2\u05d3\u05d5\u05dc \u05de\u05d3\u05d9 \u05d0\u05d5 \u05e7\u05d8\u05df \u05de\u05d3\u05d9, \u05e9\u05e0\u05e4\u05e1\u05dc \u05d1\u05d1\u05d3\u05d9\u05e7\u05d4, \u05d1\u05d2\u05dc\u05dc \u05de\u05d1\u05e8\u05d6 \u05e9\u05d7\u05d5\u05e7 \u05d0\u05d5 \u05e7\u05d3\u05d7 \u05d1\u05e7\u05d5\u05d8\u05e8 \u05dc\u05d0 \u05e0\u05db\u05d5\u05df."],[267.0,"\u05e9\u05d9\u05e0\u05d9\u05d9\u05dd \u05e7\u05e8\u05d5\u05e2\u05d5\u05ea, \u05db\u05e9\u05d4\u05e9\u05d1\u05d1\u05d9\u05dd \u05dc\u05d0 \u05de\u05ea\u05e4\u05e0\u05d9\u05dd \u05d0\u05d5 \u05e9\u05d0\u05d9\u05df \u05de\u05e1\u05e4\u05d9\u05e7 \u05e1\u05d9\u05db\u05d4."],[272.0,"\u05d5\u05d2\u05e8\u05d3 \u05d1\u05ea\u05d7\u05d9\u05dc\u05ea \u05d4\u05ea\u05d1\u05e8\u05d9\u05d2, \u05e9\u05de\u05e4\u05e8\u05d9\u05e2 \u05dc\u05d1\u05d5\u05e8\u05d2 \u05dc\u05d4\u05d9\u05db\u05e0\u05e1."],[277.0,"\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8 \u05d4\u05d1\u05e8\u05d2\u05d4?"],[279.0,"\u05de\u05e1\u05e4\u05e8 \u05d4\u05ea\u05d1\u05e8\u05d9\u05d2\u05d9\u05dd \u05d5\u05d4\u05d2\u05d3\u05dc\u05d9\u05dd \u05d4\u05e9\u05d5\u05d5\u05e0\u05d9\u05dd: \u05db\u05dc \u05d2\u05d5\u05d3\u05dc \u05d4\u05d5\u05d0 \u05e2\u05d5\u05d3 \u05de\u05e7\u05d3\u05d7 \u05d5\u05e2\u05d5\u05d3 \u05de\u05d1\u05e8\u05d6."],[285.0,"\u05ea\u05d1\u05e8\u05d9\u05d2\u05d9\u05dd \u05e7\u05d8\u05e0\u05d9\u05dd \u05d1\u05e7\u05d3\u05d7\u05d9\u05dd \u05e2\u05d9\u05d5\u05d5\u05e8\u05d9\u05dd \u05e2\u05de\u05d5\u05e7\u05d9\u05dd, \u05e9\u05d3\u05d5\u05e8\u05e9\u05d9\u05dd \u05e2\u05d1\u05d5\u05d3\u05d4 \u05d6\u05d4\u05d9\u05e8\u05d4."],[290.0,"\u05d7\u05d5\u05de\u05e8\u05d9\u05dd \u05e7\u05e9\u05d9\u05dd, \u05db\u05de\u05d5 \u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd \u05d5\u05e0\u05d9\u05e8\u05d5\u05e1\u05d8\u05d4, \u05d5\u05d4\u05e1\u05d9\u05db\u05d5\u05df \u05e9\u05dc \u05de\u05d1\u05e8\u05d6 \u05e9\u05d1\u05d5\u05e8 \u05d1\u05d7\u05dc\u05e7 \u05d9\u05e7\u05e8."],[296.0,"\u05d3\u05e8\u05d2\u05d5\u05ea \u05d8\u05d5\u05dc\u05e8\u05e0\u05e1 \u05d4\u05d3\u05d5\u05e7\u05d5\u05ea, \u05ea\u05d1\u05e8\u05d9\u05d2\u05d9\u05dd \u05de\u05d9\u05d5\u05d7\u05d3\u05d9\u05dd, \u05d5\u05e7\u05e4\u05d9\u05e6\u05d9 \u05d4\u05d1\u05e8\u05d2\u05d4."],[301.0,"\u05d5\u05d1\u05d3\u05d9\u05e7\u05d4 \u05d1\u05de\u05d3\u05d9\u05dd \u05e9\u05dc \u05db\u05dc \u05ea\u05d1\u05e8\u05d9\u05d2."],[304.0,"\u05dc\u05ea\u05d1\u05e8\u05d9\u05d2 \u05e4\u05e0\u05d9\u05de\u05d9: \u05de\u05d1\u05e8\u05d6, \u05d5\u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05d9\u05e7\u05e8\u05d9\u05dd \u05d0\u05d5 \u05e7\u05e9\u05d9\u05dd \u05db\u05e8\u05e1\u05d5\u05dd \u05d4\u05d1\u05e8\u05d2\u05d4."],[311.0,"\u05dc\u05ea\u05d1\u05e8\u05d9\u05d2 \u05d7\u05d9\u05e6\u05d5\u05e0\u05d9: \u05d7\u05e8\u05d9\u05d8\u05d4, \u05d5\u05d1\u05db\u05de\u05d5\u05d9\u05d5\u05ea \u05d2\u05d3\u05d5\u05dc\u05d5\u05ea \u05d2\u05dc\u05d2\u05d5\u05dc."],[315.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0: \u05d4\u05e9\u05d7\u05d6\u05d4."]]};
window.MH_TR["\u05e4\u05e8\u05e708_\u05d4\u05e9\u05d7\u05d6\u05d4"]={"t":"\u05d4\u05e9\u05d7\u05d6\u05d4","l":[[1.0,"\u05db\u05e9\u05d4\u05d8\u05d5\u05dc\u05e8\u05e0\u05e1 \u05d4\u05d3\u05d5\u05e7 \u05de\u05d0\u05d5\u05d3, \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05e6\u05e8\u05d9\u05db\u05d9\u05dd \u05dc\u05d4\u05d9\u05d5\u05ea \u05d7\u05dc\u05e7\u05d9\u05dd, \u05d0\u05d5 \u05e9\u05d4\u05d7\u05d5\u05de\u05e8 \u05de\u05d5\u05e7\u05e9\u05d4, \u05de\u05e9\u05d7\u05d9\u05d6\u05d9\u05dd."],[8.0,"\u05d1\u05d4\u05e9\u05d7\u05d6\u05d4, \u05d0\u05dc\u05e4\u05d9 \u05d2\u05e8\u05d2\u05e8\u05d9\u05dd \u05e7\u05e9\u05d5\u05d9\u05dd \u05d5\u05e7\u05d8\u05e0\u05d9\u05dd \u05d2\u05d5\u05e8\u05d3\u05d9\u05dd \u05db\u05dc \u05d0\u05d7\u05d3 \u05e9\u05d1\u05d1\u05d6\u05e2\u05d9\u05e8."],[14.0,"\u05dc\u05db\u05df \u05d4\u05e9\u05d7\u05d6\u05d4 \u05d0\u05d9\u05d8\u05d9\u05ea \u05d9\u05d7\u05e1\u05d9\u05ea, \u05d0\u05d1\u05dc \u05de\u05d3\u05d5\u05d9\u05e7\u05ea \u05de\u05d0\u05d5\u05d3."],[19.0,"\u05d0\u05d1\u05df \u05d4\u05e9\u05d7\u05d6\u05d4 \u05d1\u05e0\u05d5\u05d9\u05d4 \u05de\u05e9\u05dc\u05d5\u05e9\u05d4 \u05d3\u05d1\u05e8\u05d9\u05dd: \u05d2\u05e8\u05d2\u05e8\u05d9\u05dd, \u05d7\u05d5\u05de\u05e8 \u05e7\u05e9\u05e8 (bond) \u05d5\u05e0\u05e7\u05d1\u05d5\u05d1\u05d9\u05d5\u05ea."],[25.0,"\u05d4\u05d2\u05e8\u05d2\u05e8\u05d9\u05dd \u05d4\u05dd \u05d4\u05dc\u05d4\u05d1\u05d9\u05dd: \u05ea\u05d7\u05de\u05d5\u05e6\u05ea \u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05dc\u05e8\u05d5\u05d1 \u05d4\u05e4\u05dc\u05d3\u05d5\u05ea, \u05e1\u05d9\u05dc\u05d9\u05e7\u05d5\u05df \u05e7\u05e8\u05d1\u05d9\u05d3 \u05dc\u05d1\u05e8\u05d6\u05dc \u05d9\u05e6\u05d9\u05e7\u05d4 \u05d5\u05dc\u05de\u05ea\u05db\u05d5\u05ea \u05dc\u05d0 \u05d1\u05e8\u05d6\u05dc\u05d9\u05d5\u05ea."],[34.0,"\u05dc\u05e4\u05dc\u05d3\u05d5\u05ea \u05de\u05d5\u05e7\u05e9\u05d5\u05d5\u05ea \u05de\u05d0\u05d5\u05d3 \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1-\u05d068, \u05d5\u05dc\u05e7\u05e8\u05d1\u05d9\u05d3 \u05d5\u05dc\u05e7\u05e8\u05de\u05d9\u05e7\u05d4 \u05d1\u05d9\u05d4\u05dc\u05d5\u05dd."],[40.0,"\u05d4\u05e7\u05e9\u05e8 \u05de\u05d7\u05d6\u05d9\u05e7 \u05d0\u05ea \u05d4\u05d2\u05e8\u05d2\u05e8\u05d9\u05dd, \u05d5\u05d4\u05e0\u05e7\u05d1\u05d5\u05d1\u05d9\u05d5\u05ea \u05de\u05e9\u05d0\u05d9\u05e8\u05d5\u05ea \u05de\u05e7\u05d5\u05dd \u05dc\u05e9\u05d1\u05d1\u05d9\u05dd \u05d5\u05dc\u05e0\u05d5\u05d6\u05dc \u05d4\u05e7\u05d9\u05e8\u05d5\u05e8."],[46.0,"\u05d2\u05e8\u05d2\u05e8\u05d9\u05dd \u05d2\u05e1\u05d9\u05dd \u05de\u05d5\u05e8\u05d9\u05d3\u05d9\u05dd \u05d4\u05e8\u05d1\u05d4 \u05d7\u05d5\u05de\u05e8, \u05d5\u05d2\u05e8\u05d2\u05e8\u05d9\u05dd \u05e2\u05d3\u05d9\u05e0\u05d9\u05dd \u05e0\u05d5\u05ea\u05e0\u05d9\u05dd \u05e4\u05e0\u05d9 \u05e9\u05d8\u05d7 \u05d7\u05dc\u05e7\u05d9\u05dd \u05d9\u05d5\u05ea\u05e8."],[52.0,"\u05d5\u05d9\u05e9 \u05db\u05dc\u05dc \u05e9\u05e0\u05e8\u05d0\u05d4 \u05d4\u05e4\u05d5\u05da: \u05dc\u05d7\u05d5\u05de\u05e8 \u05e7\u05e9\u05d4 \u05d1\u05d5\u05d7\u05e8\u05d9\u05dd \u05d0\u05d1\u05df \u05e8\u05db\u05d4."],[58.0,"\u05d1\u05e7\u05e9\u05e8\u05e8\u05da, \u05d2\u05e8\u05d2\u05e8 \u05e9\u05d4\u05ea\u05e7\u05d4\u05d4 \u05e0\u05e9\u05d1\u05e8 \u05d4\u05d7\u05d5\u05e6\u05d4, \u05d5\u05d2\u05e8\u05d2\u05e8 \u05d7\u05d3 \u05d7\u05d3\u05e9 \u05e0\u05d7\u05e9\u05e3. \u05db\u05da \u05d4\u05d0\u05d1\u05df \u05de\u05d7\u05d3\u05d3\u05ea \u05d0\u05ea \u05e2\u05e6\u05de\u05d4."],[67.0,"\u05d4\u05e9\u05d7\u05d6\u05d4 \u05e9\u05d8\u05d5\u05d7\u05d4 \u05de\u05d9\u05d9\u05e9\u05e8\u05ea \u05de\u05e9\u05d8\u05d7\u05d9\u05dd: \u05d4\u05d7\u05dc\u05e7 \u05de\u05d5\u05d7\u05d6\u05e7 \u05e2\u05dc \u05e9\u05d5\u05dc\u05d7\u05df \u05de\u05d2\u05e0\u05d8\u05d9, \u05d5\u05e0\u05e2 \u05d4\u05dc\u05d5\u05da \u05d5\u05d7\u05d6\u05d5\u05e8 \u05de\u05ea\u05d7\u05ea \u05dc\u05d0\u05d1\u05df."],[75.0,"\u05d1\u05d4\u05e9\u05d7\u05d6\u05d4 \u05e2\u05d2\u05d5\u05dc\u05d4 \u05d7\u05d9\u05e6\u05d5\u05e0\u05d9\u05ea \u05d4\u05d7\u05dc\u05e7 \u05de\u05e1\u05ea\u05d5\u05d1\u05d1 \u05d1\u05d9\u05df \u05de\u05e8\u05db\u05d6\u05d9\u05dd, \u05d5\u05d4\u05d0\u05d1\u05df \u05de\u05e9\u05d7\u05e1\u05d7\u05d4 \u05d0\u05ea \u05d4\u05e7\u05d5\u05d8\u05e8."],[82.0,"\u05d1\u05d4\u05e9\u05d7\u05d6\u05d4 \u05e4\u05e0\u05d9\u05de\u05d9\u05ea, \u05d0\u05d1\u05df \u05e7\u05d8\u05e0\u05d4 \u05e0\u05db\u05e0\u05e1\u05ea \u05dc\u05ea\u05d5\u05da \u05e7\u05d3\u05d7 \u05d5\u05de\u05e9\u05d7\u05d9\u05d6\u05d4 \u05d0\u05d5\u05ea\u05d5 \u05de\u05d1\u05e4\u05e0\u05d9\u05dd."],[87.0,"\u05d5\u05d1\u05d4\u05e9\u05d7\u05d6\u05ea \u05e1\u05e0\u05d8\u05e8\u05dc\u05e1 (centerless) \u05d4\u05d7\u05dc\u05e7 \u05e0\u05ea\u05de\u05da \u05d1\u05d9\u05df \u05e9\u05ea\u05d9 \u05d0\u05d1\u05e0\u05d9\u05dd \u05d5\u05e2\u05dc \u05e1\u05e8\u05d2\u05dc, \u05d1\u05dc\u05d9 \u05de\u05e8\u05db\u05d6\u05d9\u05dd \u05d5\u05d1\u05dc\u05d9 \u05ea\u05e4\u05d9\u05e1\u05d4."],[95.0,"\u05db\u05da \u05de\u05e9\u05d7\u05d9\u05d6\u05d9\u05dd \u05e4\u05d9\u05e0\u05d9\u05dd \u05d1\u05db\u05de\u05d5\u05d9\u05d5\u05ea \u05d2\u05d3\u05d5\u05dc\u05d5\u05ea \u05d1\u05de\u05d4\u05d9\u05e8\u05d5\u05ea."],[99.0,"\u05d4\u05d0\u05d1\u05df \u05de\u05e1\u05ea\u05d5\u05d1\u05d1\u05ea \u05de\u05d4\u05e8 \u05de\u05d0\u05d5\u05d3, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1\u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05d4\u05d9\u05e7\u05e4\u05d9\u05ea \u05e9\u05dc 30 \u05e2\u05d3 35 \u05de\u05d8\u05e8 \u05dc\u05e9\u05e0\u05d9\u05d9\u05d4."],[106.0,"\u05d0\u05d1\u05dc \u05d1\u05db\u05dc \u05de\u05e2\u05d1\u05e8 \u05de\u05d5\u05e8\u05d9\u05d3\u05d9\u05dd \u05de\u05e2\u05d8 \u05de\u05d0\u05d5\u05d3, \u05dc\u05e8\u05d5\u05d1 \u05db\u05de\u05d4 \u05de\u05d0\u05d9\u05d5\u05ea \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8."],[111.0,"\u05d1\u05e1\u05d5\u05e3 \u05e2\u05d5\u05e9\u05d9\u05dd \u05e1\u05e4\u05d0\u05e8\u05e7 \u05d0\u05d0\u05d5\u05d8 \u05e1\u05d8\u05e1-%\u05d6508): \u05db\u05de\u05d4 \u05de\u05e2\u05d1\u05e8\u05d9\u05dd \u05d1\u05dc\u05d9 \u05d4\u05d6\u05e0\u05d4, \u05e2\u05d3 \u05e9\u05d4\u05e0\u05d9\u05e6\u05d5\u05e6\u05d5\u05ea \u05db\u05de\u05e2\u05d8 \u05e0\u05e2\u05dc\u05de\u05d9\u05dd."],[118.0,"\u05e0\u05d5\u05d6\u05dc \u05d4\u05e7\u05d9\u05e8\u05d5\u05e8 \u05d7\u05d9\u05d5\u05e0\u05d9: \u05db\u05de\u05e2\u05d8 \u05db\u05dc \u05d4\u05d0\u05e0\u05e8\u05d2\u05d9\u05d4 \u05d1\u05d4\u05e9\u05d7\u05d6\u05d4 \u05d4\u05d5\u05e4\u05db\u05ea \u05dc\u05d7\u05d5\u05dd."],[123.0,"\u05d4\u05e9\u05d7\u05d6\u05d4 \u05de\u05d2\u05d9\u05e2\u05d4 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05dc\u05d3\u05d9\u05d5\u05e7 \u05e9\u05dc \u05e4\u05d6\u05d5 \u05e2\u05d3 6\u05d3\u05d5, \u05d5\u05dc\u05d7\u05e1\u05e4\u05d5\u05e1 Ra \u05e9\u05dc 0.2 \u05e2\u05d3 0.8 \u05de\u05d9\u05e7\u05e8\u05d5\u05df."],[134.0,"\u05d4\u05d9\u05d0 \u05e0\u05d5\u05ea\u05e0\u05ea \u05d2\u05dd \u05e6\u05d5\u05e8\u05d4 \u05d2\u05d0\u05d5\u05de\u05d8\u05e8\u05d9\u05ea \u05d8\u05d5\u05d1\u05d4: \u05e2\u05d2\u05d9\u05dc\u05d5\u05ea, \u05de\u05d9\u05e9\u05d5\u05e8\u05d9\u05d5\u05ea \u05d5\u05d9\u05e9\u05e8\u05d5\u05ea."],[139.0,"\u05d5\u05d4\u05d9\u05d0 \u05de\u05ea\u05d0\u05d9\u05de\u05d4 \u05dc\u05d7\u05d5\u05de\u05e8\u05d9\u05dd \u05de\u05d5\u05e7\u05e9\u05d5\u05d9\u05dd, \u05d0\u05d7\u05e8\u05d9 \u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd, \u05db\u05e9\u05db\u05dc\u05d9 \u05d7\u05d9\u05ea\u05d5\u05da \u05e8\u05d2\u05d9\u05dc \u05db\u05d1\u05e8 \u05de\u05ea\u05e7\u05e9\u05d4."],[146.0,"\u05e2\u05dd \u05d4\u05d6\u05de\u05df \u05d4\u05d0\u05d1\u05df \u05de\u05ea\u05e7\u05d4\u05d4 \u05d5\u05e0\u05e1\u05ea\u05de\u05ea, \u05d5\u05d4\u05e6\u05d5\u05e8\u05d4 \u05e9\u05dc\u05d4 \u05de\u05e9\u05ea\u05e0\u05d4."],[151.0,"\u05dc\u05db\u05df \u05e2\u05d5\u05e9\u05d9\u05dd \u05dc\u05d4 \u05d3\u05e8\u05e1\u05d9\u05e0\u05d2 (\u2026): \u05db\u05dc\u05d9 \u05d9\u05d4\u05dc\u05d5\u05dd \u05de\u05e1\u05d9\u05e8 \u05e9\u05db\u05d1\u05d4 \u05d3\u05e7\u05d4 \u05d5\u05d7\u05d5\u05e9\u05e3 \u05d2\u05e8\u05d2\u05e8\u05d9\u05dd \u05d7\u05d3\u05d9\u05dd."],[157.0,"\u05d4\u05d0\u05d1\u05df \u05d2\u05dd \u05de\u05d0\u05d5\u05d6\u05e0\u05ea, \u05db\u05d9 \u05d7\u05d5\u05e1\u05e8 \u05d0\u05d9\u05d6\u05d5\u05df \u05d9\u05d5\u05e6\u05e8 \u05e8\u05e2\u05d9\u05d3\u05d5\u05ea \u05d5\u05e1\u05d9\u05de\u05e0\u05d9\u05dd \u05e2\u05dc \u05d4\u05d7\u05dc\u05e7."],[162.0,"\u05d5\u05d1\u05d8\u05d9\u05d7\u05d5\u05ea: \u05e2\u05dc \u05db\u05dc \u05d0\u05d1\u05df \u05e8\u05e9\u05d5\u05de\u05d4 \u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05de\u05e7\u05e1\u05d9\u05de\u05dc\u05d9\u05ea, \u05d5\u05d0\u05e1\u05d5\u05e8 \u05dc\u05e2\u05d1\u05d5\u05e8 \u05d0\u05d5\u05ea\u05d4. \u05d0\u05d1\u05df \u05e9\u05e0\u05e9\u05d1\u05e8\u05ea \u05d1\u05e1\u05d9\u05d1\u05d5\u05d1 \u05de\u05e1\u05d5\u05db\u05e0\u05ea \u05de\u05d0\u05d5\u05d3."],[172.0,"\u05d2\u05dd \u05d1\u05d4\u05e9\u05d7\u05d6\u05d4 \u05d9\u05e9 \u05d1\u05e2\u05d9\u05d5\u05ea \u05d0\u05d5\u05e4\u05d9\u05d9\u05e0\u05d9\u05d5\u05ea."],[175.0,"\u05d4\u05e7\u05e9\u05d9\u05d5\u05ea \u05e9\u05dc \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7, \u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d9\u05d5\u05e6\u05e8 \u05e1\u05d3\u05e7\u05d9\u05dd \u05d6\u05e2\u05d9\u05e8\u05d9\u05dd. \u05dc\u05d0 \u05ea\u05de\u05d9\u05d3 \u05e8\u05d5\u05d0\u05d9\u05dd \u05d0\u05d5\u05ea\u05d4 \u05d1\u05e2\u05d9\u05df."],[184.0,"\u05e1\u05d9\u05de\u05e0\u05d9 \u05e8\u05e2\u05d9\u05d3\u05d5\u05ea, \u05de\u05d0\u05d1\u05df \u05dc\u05d0 \u05de\u05d0\u05d5\u05d6\u05e0\u05ea \u05d0\u05d5 \u05de\u05d7\u05dc\u05e7 \u05e9\u05dc\u05d0 \u05e0\u05ea\u05de\u05da \u05d8\u05d5\u05d1."],[189.0,"\u05d0\u05d1\u05df \u05e1\u05ea\u05d5\u05de\u05d4, \u05d1\u05e2\u05d9\u05e7\u05e8 \u05d1\u05d7\u05d5\u05de\u05e8\u05d9\u05dd \u05e8\u05db\u05d9\u05dd, \u05e9\u05de\u05e9\u05e4\u05e9\u05e4\u05ea \u05d1\u05de\u05e7\u05d5\u05dd \u05dc\u05d7\u05ea\u05d5\u05da."],[194.0,"\u05d5\u05d7\u05dc\u05e7 \u05e7\u05d5\u05e0\u05d9 \u05d0\u05d5 \u05dc\u05d0 \u05e2\u05d2\u05d5\u05dc, \u05db\u05e9\u05d4\u05de\u05db\u05d5\u05e0\u05d4 \u05d0\u05d5 \u05d4\u05ea\u05de\u05d9\u05db\u05d4 \u05dc\u05d0 \u05de\u05db\u05d5\u05d5\u05e0\u05d5\u05ea."],[200.0,"\u05de\u05e9\u05d7\u05d7\u05d9\u05dd \u05e8\u05e7 \u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05e9\u05d1\u05d0\u05de\u05ea \u05e6\u05e8\u05d9\u05db\u05d9\u05dd \u05d0\u05ea \u05d6\u05d4."],[204.0,"\u05de\u05e9\u05d0\u05d9\u05e8\u05d9\u05dd \u05dc\u05d4\u05e9\u05d7\u05d6\u05d4 \u05ea\u05d5\u05e1\u05e4\u05ea \u05e7\u05d8\u05e0\u05d4, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05db\u05de\u05d4 \u05e2\u05e9\u05d9\u05e8\u05d9\u05d5\u05ea \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8, \u05db\u05d9 \u05db\u05dc \u05de\u05e2\u05d1\u05e8 \u05de\u05d5\u05e8\u05d9\u05d3 \u05de\u05e2\u05d8."],[211.0,"\u05d1\u05e4\u05d9\u05e0\u05d4 \u05e9\u05dc \u05db\u05ea\u05e3, \u05dc\u05d0\u05d1\u05df \u05d9\u05e9 \u05e8\u05d3\u05d9\u05d5\u05e1, \u05d5\u05dc\u05db\u05df \u05de\u05ea\u05db\u05e0\u05e0\u05d9\u05dd \u05d7\u05e8\u05d9\u05e5 \u05d9\u05e6\u05d9\u05d0\u05d4 \u05d0\u05d5 \u05e8\u05d3\u05d9\u05d5\u05e1 \u05de\u05ea\u05d0\u05d9\u05dd."],[218.0,"\u05d5\u05d0\u05ea \u05d4\u05d7\u05dc\u05e7 \u05de\u05e7\u05e9\u05d9\u05dd \u05dc\u05e4\u05e0\u05d9 \u05d4\u05d4\u05e9\u05d7\u05d6\u05d4, \u05db\u05d9 \u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd \u05d0\u05d7\u05e8\u05d9 \u05d4\u05e9\u05d7\u05d6\u05d4 \u05e2\u05dc\u05d5\u05dc \u05dc\u05e2\u05d5\u05d5\u05ea \u05d0\u05d5\u05ea\u05d5."],[225.0,"\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8 \u05d4\u05e9\u05d7\u05d6\u05d4?"],[226.0,"\u05d4\u05d5\u05e8\u05d3\u05ea \u05d7\u05d5\u05de\u05e8 \u05d0\u05d9\u05d8\u05d9\u05ea: \u05db\u05dc \u05e2\u05e9\u05d9\u05e8\u05d9\u05ea \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8 \u05de\u05d9\u05d5\u05ea\u05e8\u05ea \u05d4\u05d9\u05d0 \u05e2\u05d5\u05d3 \u05de\u05e2\u05d1\u05e8\u05d9\u05dd."],[232.0,"\u05d6\u05de\u05df \u05d4\u05db\u05e0\u05d4, \u05d3\u05e8\u05e1\u05d9\u05e0\u05d2 \u05d5\u05d0\u05d7\u05d5\u05df."],[235.0,"\u05de\u05db\u05d5\u05e0\u05d5\u05ea \u05d9\u05d9\u05e2\u05d5\u05d3\u05d9\u05d5\u05ea, \u05d5\u05e2\u05d5\u05d1\u05d3 \u05de\u05d9\u05d5\u05de\u05df."],[238.0,"\u05d1\u05d3\u05d9\u05e7\u05d5\u05ea \u05de\u05d3\u05d5\u05d9\u05e7\u05d5\u05ea, \u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d1\u05d3\u05d9\u05e7\u05d4 \u05dc\u05e9\u05e8\u05d9\u05e4\u05ea \u05d4\u05e9\u05d7\u05d6\u05d4."],[242.0,"\u05d5\u05e1\u05d9\u05db\u05d5\u05df \u05dc\u05e4\u05e1\u05d9\u05dc\u05d4, \u05db\u05d9 \u05d4\u05d4\u05e9\u05d7\u05d6\u05d4 \u05d1\u05d0\u05d4 \u05d1\u05e1\u05d5\u05e3, \u05d0\u05d7\u05e8\u05d9 \u05e9\u05d4\u05d7\u05dc\u05e7 \u05db\u05d1\u05e8 \u05e2\u05d1\u05e8 \u05d0\u05ea \u05db\u05dc \u05d4\u05ea\u05d4\u05dc\u05d9\u05db\u05d9\u05dd."],[249.0,"\u05d4\u05e9\u05d7\u05d6\u05d4 \u05d4\u05d9\u05d0 \u05d4\u05e9\u05dc\u05d1 \u05e9\u05d1\u05d5 \u05d7\u05dc\u05e7 \u05de\u05e7\u05d1\u05dc \u05d0\u05ea \u05d4\u05d3\u05d9\u05d5\u05e7 \u05d5\u05d4\u05d2\u05d9\u05de\u05d5\u05e8 \u05d4\u05e1\u05d5\u05e4\u05d9\u05d9\u05dd."],[254.0,"\u05d4\u05d9\u05d0 \u05d0\u05d9\u05d8\u05d9\u05ea \u05d5\u05d9\u05e7\u05e8\u05d4 \u05d9\u05d7\u05e1\u05d9\u05ea, \u05d5\u05dc\u05db\u05df \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05d4 \u05e8\u05e7 \u05d0\u05d9\u05e4\u05d4 \u05e9\u05e6\u05e8\u05d9\u05da."],[259.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0: \u05d1\u05e8\u05d5\u05e6'\u05d9\u05e0\u05d2."]]};
window.MH_TR["\u05e4\u05e8\u05e709_\u05d1\u05e8\u05d5\u05e6\u05d9\u05e0\u05d2_\u05d7\u05d9\u05d8\u05d5\u05d8"]={"t":"\u05d1\u05e8\u05d5\u05e6'\u05d9\u05e0\u05d2 (\u05d7\u05d9\u05d8\u05d5\u05d8)","l":[[1.0,"\u05d7\u05e8\u05d9\u05e5 \u05e9\u05d2\u05dd \u05d1\u05e7\u05d3\u05d7 \u05e9\u05dc \u05d2\u05dc\u05d2\u05dc \u05e9\u05d9\u05e0\u05d9\u05d9\u05dd, \u05e1\u05e4\u05dc\u05d9\u05d9\u05e0\u05d9\u05dd (splines) \u05d1\u05ea\u05d5\u05da \u05ea\u05d5\u05ea\u05d1, \u05d0\u05d5 \u05e7\u05d3\u05d7 \u05de\u05e9\u05d5\u05e9\u05d4."],[7.0,"\u05d0\u05ea \u05d4\u05e6\u05d5\u05e8\u05d5\u05ea \u05d4\u05d0\u05dc\u05d4 \u05e7\u05e9\u05d4 \u05de\u05d0\u05d5\u05d3 \u05dc\u05d9\u05d9\u05e6\u05e8 \u05d1\u05d7\u05e8\u05d9\u05d8\u05d4 \u05d0\u05d5 \u05d1\u05db\u05e8\u05e1\u05d5\u05dd."],[12.0,"\u05d1\u05d1\u05e8\u05d5\u05e6'\u05d9\u05e0\u05d2, \u05e9\u05d1\u05e2\u05d1\u05e8\u05d9\u05ea \u05e0\u05e7\u05e8\u05d0 \u05d7\u05d9\u05d8\u05d5\u05d8, \u05de\u05d9\u05d9\u05e6\u05e8\u05d9\u05dd \u05d0\u05d5\u05ea\u05df \u05d1\u05de\u05e2\u05d1\u05e8 \u05d0\u05d7\u05d3."],[18.0,"\u05d4\u05db\u05dc\u05d9 \u05e0\u05e7\u05e8\u05d0 \u05d1\u05e8\u05d5\u05e5' (broach): \u05de\u05d5\u05d8 \u05d0\u05e8\u05d5\u05da \u05e2\u05dd \u05d4\u05e8\u05d1\u05d4 \u05e9\u05d9\u05e0\u05d9\u05d9\u05dd \u05d1\u05e9\u05d5\u05e8\u05d4."],[22.0,"\u05db\u05dc \u05e9\u05df \u05d2\u05d1\u05d5\u05d4\u05d4 \u05de\u05e2\u05d8 \u05de\u05d4\u05e9\u05df \u05e9\u05dc\u05e4\u05e0\u05d9\u05d4, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1\u05db\u05de\u05d4 \u05de\u05d0\u05d9\u05d5\u05ea \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8."],[28.0,"\u05de\u05d5\u05e8\u05d9\u05d3\u05d4 \u05e2\u05d5\u05d3 \u05e9\u05db\u05d1\u05d4 \u05d3\u05e7\u05d4, \u05d5\u05d4\u05e9\u05df \u05d4\u05d0\u05d7\u05e8\u05ea\u05e0\u05d4 \u05de\u05e9\u05d0\u05d9\u05e8\u05d4 \u05d0\u05ea \u05d4\u05e6\u05d5\u05e8\u05d4 \u05d4\u05e1\u05d5\u05e4\u05d9\u05ea."],[37.0,"\u05d1\u05d4\u05ea\u05d7\u05dc\u05d4 \u05d9\u05e9 \u05e9\u05d9\u05e0\u05d9 \u05d2\u05e8\u05d5\u05e1\u05d4, \u05d1\u05d0\u05de\u05e6\u05e2 \u05e9\u05d9\u05e0\u05d9 \u05d1\u05d9\u05e0\u05d9\u05d9\u05dd, \u05d5\u05d1\u05e1\u05d5\u05e3 \u05e9\u05d9\u05e0\u05d9 \u05d2\u05d9\u05de\u05d5\u05e8 \u05d1\u05d0\u05d5\u05ea\u05d5 \u05d2\u05d5\u05d3\u05dc, \u05e9\u05de\u05db\u05d9\u05d9\u05dc\u05d5\u05ea \u05d0\u05ea \u05d4\u05de\u05d9\u05d3\u05d4."],[45.0,"\u05d1\u05e7\u05e6\u05d4 \u05d4\u05db\u05dc\u05d9 \u05d9\u05e9 \u05e4\u05d9\u05d9\u05dc\u05d5\u05d8 (pilot) \u05e9\u05e0\u05db\u05e0\u05e1 \u05dc\u05e7\u05d3\u05d7 \u05d4\u05de\u05e7\u05d3\u05d9\u05dd \u05d5\u05de\u05d9\u05d9\u05e9\u05e8 \u05d0\u05ea \u05d4\u05db\u05dc\u05d9."],[50.0,"\u05d1\u05d9\u05df \u05d4\u05e9\u05d9\u05e0\u05d9\u05d9\u05dd \u05d9\u05e9 \u05db\u05d9\u05e1 \u05e9\u05d1\u05d1\u05d9\u05dd, \u05d5\u05d4\u05e9\u05d1\u05d1 \u05e0\u05e9\u05d0\u05e8 \u05d1\u05d5 \u05e2\u05d3 \u05e9\u05d4\u05e9\u05df \u05d9\u05d5\u05e6\u05d0\u05ea \u05de\u05d4\u05d7\u05dc\u05e7."],[56.0,"\u05dc\u05db\u05df \u05d0\u05d5\u05e8\u05da \u05d4\u05d7\u05d9\u05ea\u05d5\u05da \u05de\u05d5\u05d2\u05d1\u05dc: \u05d1\u05d7\u05dc\u05e7 \u05d0\u05e8\u05d5\u05da \u05de\u05d3\u05d9, \u05d4\u05db\u05d9\u05e1 \u05de\u05ea\u05de\u05dc\u05d0."],[62.0,"\u05d0\u05d5\u05ea\u05d5 \u05dc\u05e6\u05d5\u05e8\u05d4 \u05d4\u05e8\u05e6\u05d5\u05d9\u05d4: \u05d7\u05e8\u05d9\u05e5 \u05e9\u05d2\u05dd, \u05e1\u05e4\u05dc\u05d9\u05d9\u05e0\u05d9\u05dd, \u05e8\u05d9\u05d1\u05d5\u05e2 \u05d0\u05d5 \u05de\u05e9\u05d5\u05e9\u05d4."],[72.0,"\u05d1\u05d1\u05e8\u05d5\u05e6'\u05d9\u05e0\u05d2 \u05d7\u05d9\u05e6\u05d5\u05e0\u05d9, \u05d4\u05db\u05dc\u05d9 \u05e2\u05d5\u05d1\u05e8 \u05e2\u05dc \u05e4\u05e0\u05d9 \u05d4\u05d7\u05dc\u05e7, \u05d5\u05d9\u05d5\u05e6\u05e8 \u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05d5\u05e4\u05e8\u05d5\u05e4\u05d9\u05dc\u05d9\u05dd."],[78.0,"\u05db\u05da \u05de\u05d9\u05d9\u05e6\u05e8\u05d9\u05dd, \u05dc\u05de\u05e9\u05dc, \u05d0\u05ea \u05d4\u05d7\u05e8\u05d9\u05e6\u05d9\u05dd \u05d1\u05d3\u05d9\u05e1\u05e7\u05d5\u05ea \u05e9\u05dc \u05d8\u05d5\u05e8\u05d1\u05d9\u05e0\u05d4, \u05e9\u05d0\u05dc\u05d9\u05d4\u05dd \u05e0\u05db\u05e0\u05e1\u05d9\u05dd \u05e9\u05d5\u05e8\u05e9\u05d9 \u05d4\u05dc\u05d4\u05d1\u05d9\u05dd."],[84.0,"\u05d1\u05d1\u05ea\u05d9 \u05de\u05dc\u05d0\u05db\u05d4, \u05d7\u05e8\u05d9\u05e5 \u05e9\u05d2\u05dd \u05e2\u05d5\u05e9\u05d9\u05dd \u05dc\u05e2\u05ea\u05d9\u05dd \u05e7\u05e8\u05d5\u05d1\u05d5\u05ea \u05e2\u05dd \u05e2\u05e8\u05db\u05ea \u05d1\u05e8\u05d5\u05e5' \u05d9\u05d3\u05e0\u05d9\u05ea \u05d5\u05de\u05db\u05d1\u05e9 \u05e4\u05e9\u05d5\u05d8."],[91.0,"\u05d5\u05d9\u05e9 \u05d2\u05dd \u05d1\u05e8\u05d5\u05e6'\u05d9\u05e0\u05d2 \u05e1\u05d9\u05d1\u05d5\u05d1\u05d9 (rotary) \u05e9\u05de\u05ea\u05d1\u05e6\u05e2 \u05e2\u05dc \u05de\u05d7\u05e8\u05d8\u05d4 \u05d0\u05d5 \u05e2\u05dc \u05db\u05e8\u05e1\u05d5\u05de\u05ea, \u05d5\u05de\u05ea\u05d0\u05d9\u05dd \u05dc\u05de\u05e2\u05d5\u05d5\u05e9\u05d9\u05dd \u05d1\u05e7\u05d3\u05d7\u05d9\u05dd \u05e2\u05d9\u05d5\u05d5\u05e8\u05d9\u05dd."],[99.0,"\u05de\u05e2\u05d1\u05e8 \u05d0\u05d7\u05d3, \u05d5\u05dc\u05db\u05df \u05d6\u05de\u05df \u05d4\u05de\u05d7\u05d6\u05d5\u05e8 \u05e7\u05e6\u05e8 \u05de\u05d0\u05d5\u05d3, \u05dc\u05e8\u05d5\u05d1 \u05e9\u05e0\u05d9\u05d5\u05ea."],[104.0,"\u05d4\u05d3\u05d9\u05d5\u05e7 \u05d8\u05d5\u05d1, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc 7\u05d3\u05d5 \u05e2\u05d3 8\u05d6\u05d5, \u05d5\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05d8\u05d5\u05d1\u05d9\u05dd."],[111.0,"\u05d5\u05db\u05dc \u05d7\u05dc\u05e7 \u05d9\u05d5\u05e6\u05d0 \u05db\u05de\u05d5 \u05d4\u05e7\u05d5\u05d3\u05dd, \u05db\u05d9 \u05d4\u05e6\u05d5\u05e8\u05d4 \u05e0\u05de\u05e6\u05d0\u05ea \u05d1\u05db\u05dc\u05d9."],[116.0,"\u05d4\u05db\u05dc\u05d9 \u05d9\u05e7\u05e8, \u05d5\u05de\u05ea\u05d0\u05d9\u05dd \u05e8\u05e7 \u05dc\u05e6\u05d5\u05e8\u05d4 \u05d0\u05d7\u05ea \u05d5\u05dc\u05d2\u05d5\u05d3\u05dc \u05d0\u05d7\u05d3."],[120.0,"\u05dc\u05db\u05df \u05d1\u05e8\u05d5\u05e6'\u05d9\u05e0\u05d2 \u05de\u05e9\u05ea\u05dc\u05dd \u05d1\u05e2\u05d9\u05e7\u05e8 \u05d1\u05db\u05de\u05d5\u05d9\u05d5\u05ea, \u05d7\u05d5\u05e5 \u05de\u05d1\u05e8\u05d5\u05e6'\u05d9\u05dd \u05e1\u05d8\u05e0\u05d3\u05e8\u05d8\u05d9\u05d9\u05dd \u05dc\u05d7\u05e8\u05d9\u05e6\u05d9 \u05e9\u05d2\u05dd."],[126.0,"\u05d1\u05d1\u05e8\u05d5\u05e6'\u05d9\u05e0\u05d2 \u05e4\u05e0\u05d9\u05de\u05d9 \u05e8\u05d2\u05d9\u05dc \u05d4\u05e7\u05d3\u05d7 \u05d7\u05d9\u05d9\u05d1 \u05dc\u05d4\u05d9\u05d5\u05ea \u05e2\u05d5\u05d1\u05e8."],[130.0,"\u05d5\u05db\u05d5\u05d7\u05d5\u05ea \u05d4\u05d7\u05d9\u05ea\u05d5\u05da \u05d2\u05d3\u05d5\u05dc\u05d9\u05dd, \u05d5\u05dc\u05db\u05df \u05d4\u05d7\u05dc\u05e7 \u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05d9\u05d5\u05ea \u05d7\u05d6\u05e7, \u05d5\u05d4\u05d3\u05e4\u05e0\u05d5\u05ea \u05e9\u05dc\u05d5 \u05dc\u05d0 \u05d3\u05e7\u05d5\u05ea \u05de\u05d3\u05d9."],[138.0,"\u05d2\u05dd \u05dc\u05d1\u05e8\u05d5\u05e6'\u05d9\u05e0\u05d2 \u05d9\u05e9 \u05db\u05dc\u05dc\u05d9 \u05ea\u05db\u05e0\u05d5\u05df."],[140.0,"\u05e2\u05d3\u05d9\u05e3 \u05e7\u05d3\u05d7 \u05e2\u05d5\u05d1\u05e8, \u05d5\u05d0\u05d5\u05e8\u05da \u05d7\u05d9\u05ea\u05d5\u05da \u05e1\u05d1\u05d9\u05e8 \u05d1\u05d9\u05d7\u05e1 \u05dc\u05db\u05dc\u05d9."],[145.0,"\u05d4\u05e7\u05d3\u05d7 \u05d4\u05de\u05e7\u05d3\u05d9\u05dd \u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05d9\u05d5\u05ea \u05d1\u05e7\u05d5\u05d8\u05e8 \u05d5\u05d1\u05d8\u05d5\u05dc\u05e8\u05e0\u05e1 \u05d4\u05e0\u05db\u05d5\u05e0\u05d9\u05dd, \u05db\u05d9 \u05d4\u05db\u05dc\u05d9 \u05de\u05ea\u05d7\u05d9\u05dc \u05de\u05de\u05e0\u05d5."],[151.0,"\u05d5\u05d0\u05dd \u05d4\u05d7\u05e8\u05d9\u05e5 \u05d7\u05d9\u05d9\u05d1 \u05dc\u05d4\u05d9\u05e2\u05e6\u05e8 \u05d1\u05ea\u05d5\u05da \u05d4\u05d7\u05dc\u05e7, \u05e6\u05e8\u05d9\u05da \u05d7\u05e8\u05d9\u05e5 \u05d9\u05e6\u05d9\u05d0\u05d4, \u05d0\u05d5 \u05ea\u05d4\u05dc\u05d9\u05da \u05d0\u05d7\u05e8."],[157.0,"\u05d2\u05dd \u05d1\u05d1\u05e8\u05d5\u05e6'\u05d9\u05e0\u05d2 \u05d9\u05e9 \u05d1\u05e2\u05d9\u05d5\u05ea \u05d0\u05d5\u05e4\u05d9\u05d9\u05e0\u05d9\u05d5\u05ea."],[160.0,"\u05db\u05dc\u05d9 \u05e9\u05d1\u05d5\u05e8, \u05d1\u05e2\u05d9\u05e7\u05e8 \u05db\u05e2\u05d5\u05d4\u05db\u05d9\u05e1\u05d9\u05dd \u05de\u05ea\u05de\u05dc\u05d0\u05d9\u05dd \u05d0\u05d5 \u05db\u05e9\u05d4\u05d7\u05d5\u05de\u05e8 \u05e7\u05e9\u05d4 \u05de\u05d3\u05d9."],[165.0,"\u05d7\u05e8\u05d9\u05e5 \u05e9\u05d2\u05dd \u05e9\u05d6\u05d6 \u05de\u05d4\u05de\u05e7\u05d5\u05dd \u05d0\u05d5 \u05dc\u05d0 \u05de\u05e7\u05d1\u05d9\u05dc \u05dc\u05e6\u05d9\u05e8, \u05db\u05e9\u05d4\u05d7\u05dc\u05e7 \u05dc\u05d0 \u05de\u05d9\u05d5\u05e9\u05e8 \u05d8\u05d5\u05d1."],[171.0,"\u05e1\u05d9\u05de\u05e0\u05d9 \u05e8\u05e2\u05d9\u05d3\u05d5\u05ea \u05e2\u05dc \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7."],[174.0,"\u05d5\u05d2\u05e8\u05d3 \u05d1\u05d9\u05e6\u05d9\u05d0\u05d4 \u05e9\u05dc \u05d4\u05db\u05dc\u05d9."],[176.0,"\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8 \u05d1\u05e8\u05d5\u05e6'\u05d9\u05e0\u05d2?"],[178.0,"\u05d4\u05db\u05dc\u05d9: \u05d0\u05e8\u05d5\u05da, \u05e2\u05dd \u05d4\u05e8\u05d1\u05d4 \u05e9\u05d9\u05e0\u05d9\u05d9\u05dd, \u05d5\u05de\u05d9\u05d5\u05e6\u05e8 \u05d1\u05de\u05d9\u05d5\u05d7\u05d3 \u05dc\u05e6\u05d5\u05e8\u05d4."],[183.0,"\u05d4\u05e9\u05d7\u05d6\u05d4 \u05de\u05d7\u05d3\u05e9 \u05e9\u05dc \u05d4\u05db\u05dc\u05d9, \u05d5\u05d0\u05d7\u05d6\u05e7\u05d4 \u05e9\u05dc\u05d5."],[186.0,"\u05de\u05db\u05d5\u05e0\u05d4 \u05d9\u05d9\u05e2\u05d5\u05d3\u05d9\u05ea \u05dc\u05db\u05d5\u05d7\u05d5\u05ea \u05d2\u05d3\u05d5\u05dc\u05d9\u05dd."],[189.0,"\u05d5\u05d1\u05db\u05de\u05d5\u05d9\u05d5\u05ea \u05e7\u05d8\u05e0\u05d5\u05ea, \u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d6\u05d5\u05dc \u05d9\u05d5\u05ea\u05e8 \u05dc\u05d1\u05d7\u05d5\u05e8 \u05d1\u05d7\u05d5\u05d8 EDM \u05d0\u05d5 \u05d1\u05de\u05db\u05d5\u05e0\u05ea \u05d7\u05e8\u05d9\u05e6\u05d4 (\u2026)."],[195.0,"\u05d1\u05e8\u05d5\u05e6'\u05d9\u05e0\u05d2 \u05de\u05d9\u05d9\u05e6\u05e8 \u05d1\u05de\u05e2\u05d1\u05e8 \u05d0\u05d7\u05d3 \u05e6\u05d5\u05e8\u05d5\u05ea \u05e4\u05e0\u05d9\u05de\u05d9\u05d5\u05ea \u05d5\u05d7\u05d9\u05e6\u05d5\u05e0\u05d9\u05d5\u05ea \u05de\u05d3\u05d5\u05d9\u05e7\u05d5\u05ea."],[200.0,"\u05d4\u05db\u05dc\u05d9 \u05d9\u05e7\u05e8, \u05d0\u05d1\u05dc \u05d1\u05db\u05de\u05d5\u05d9\u05d5\u05ea \u05d2\u05d3\u05d5\u05dc\u05d5\u05ea \u05d4\u05de\u05d7\u05d9\u05e8 \u05dc\u05d7\u05dc\u05e7 \u05e0\u05de\u05d5\u05da \u05de\u05d0\u05d5\u05d3."],[205.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0: \u05d2\u05dc\u05d2\u05dc\u05d9 \u05e9\u05d9\u05e0\u05d9\u05d9\u05dd."]]};
window.MH_TR["\u05e4\u05e8\u05e710_\u05d2\u05dc\u05d2\u05dc\u05d9_\u05e9\u05d9\u05e0\u05d9\u05d9\u05dd"]={"t":"\u05d2\u05dc\u05d2\u05dc\u05d9 \u05e9\u05d9\u05e0\u05d9\u05d9\u05dd","l":[[1.0,"\u05d2\u05dc\u05d2\u05dc\u05d9 \u05e9\u05d9\u05e0\u05d9\u05d9\u05dd \u05de\u05e2\u05d1\u05d9\u05e8\u05d9\u05dd \u05ea\u05e0\u05d5\u05e2\u05d4 \u05d5\u05de\u05d5\u05de\u05e0\u05d8 \u05d1\u05d9\u05df \u05e6\u05d9\u05e8\u05d9\u05dd, \u05d1\u05ea\u05d9\u05d1\u05d5\u05ea \u05d4\u05d9\u05dc\u05d5\u05db\u05d9\u05dd, \u05d1\u05de\u05e0\u05d5\u05e2\u05d9\u05dd \u05d5\u05d1\u05de\u05db\u05d5\u05e0\u05d5\u05ea."],[8.0,"\u05db\u05d3\u05d9 \u05e9\u05d9\u05e2\u05d1\u05d3\u05d5 \u05d1\u05e9\u05e7\u05d8 \u05d5\u05dc\u05d0\u05d5\u05e8\u05da \u05d6\u05de\u05df, \u05e6\u05d5\u05e8\u05ea \u05d4\u05e9\u05df \u05e6\u05e8\u05d9\u05db\u05d4 \u05dc\u05d4\u05d9\u05d5\u05ea \u05de\u05d3\u05d5\u05d9\u05e7\u05ea \u05de\u05d0\u05d5\u05d3."],[14.0,"\u05dc\u05db\u05df \u05d2\u05dc\u05d2\u05dc\u05d9 \u05e9\u05d9\u05e0\u05d9\u05d9\u05dd \u05de\u05d9\u05d9\u05e6\u05e8\u05d9\u05dd \u05d1\u05de\u05db\u05d5\u05e0\u05d5\u05ea \u05d5\u05d1\u05db\u05dc\u05d9\u05dd \u05de\u05d9\u05d5\u05d7\u05d3\u05d9\u05dd."],[19.0,"\u05db\u05e9\u05e9\u05ea\u05d9 \u05e9\u05d9\u05e0\u05d9\u05d9\u05dd \u05de\u05ea\u05d2\u05dc\u05d2\u05dc\u05d5\u05ea \u05d6\u05d5 \u05e2\u05dc \u05d6\u05d5, \u05d9\u05d7\u05e1 \u05d4\u05e1\u05d9\u05d1\u05d5\u05d1\u05d9\u05dd \u05e0\u05e9\u05d0\u05e8 \u05e7\u05d1\u05d5\u05e2."],[27.0,"\u05d4\u05d2\u05d5\u05d3\u05dc \u05e9\u05dc \u05d4\u05e9\u05df \u05e0\u05e7\u05d1\u05e2 \u05dc\u05e4\u05d9 \u05d4\u05de\u05d5\u05d3\u05d5\u05dc."],[30.0,"\u05e7\u05d5\u05d8\u05e8 \u05d4\u05d7\u05dc\u05d5\u05e7\u05d4 \u05d4\u05d5\u05d0 \u05d4\u05de\u05d5\u05d3\u05d5\u05dc \u05db\u05e4\u05d5\u05dc \u05de\u05e1\u05e4\u05e8 \u05d4\u05e9\u05d9\u05e0\u05d9\u05d9\u05dd: \u05d2\u05dc\u05d2\u05dc \u05d1\u05de\u05d5\u05d3\u05d5\u05dc 2 \u05e2\u05dd 30 \u05e9\u05d9\u05e0\u05d9\u05d9\u05dd, \u05e7\u05d5\u05d8\u05e8 \u05d4\u05d7\u05dc\u05d5\u05e7\u05d4 \u05e9\u05dc\u05d5 60 \u05de\"\u05de."],[39.0,"\u05d6\u05d5\u05d5\u05d9\u05ea \u05d4\u05dc\u05d7\u05e5 \u05d4\u05e1\u05d8\u05e0\u05d3\u05e8\u05d8\u05d9\u05ea \u05d4\u05d9\u05d0 20 \u05de\u05e2\u05dc\u05d5\u05ea."],[43.0,"\u05e9\u05e2\u05d5\u05d1\u05d3\u05d5\u05ea \u05e9\u05e7\u05d8 \u05d9\u05d5\u05ea\u05e8, \u05d2\u05dc\u05d2\u05dc\u05d9\u05dd \u05e7\u05d5\u05e0\u05d9\u05d9\u05dd \u05dc\u05e6\u05d9\u05e8\u05d9\u05dd \u05d1\u05d6\u05d5\u05d5\u05d9\u05ea, \u05d5\u05d2\u05dc\u05d2\u05dc \u05d5\u05ea\u05d5\u05dc\u05e2\u05ea \u05dc\u05d4\u05e7\u05d8\u05e0\u05d4 \u05d2\u05d3\u05d5\u05dc\u05d4 \u05e9\u05dc \u05d4\u05de\u05d4\u05d9\u05e8\u05d5\u05ea."],[54.0,"\u05d4\u05e9\u05d9\u05d8\u05d4 \u05d4\u05e0\u05e4\u05d5\u05e6\u05d4 \u05d4\u05d9\u05d0 \u05d4\u05d5\u05d1\u05d9\u05e0\u05d2 (hobbing)."],[57.0,"\u05d7\u05d5\u05ea\u05db\u05d5\u05ea, \u05d5\u05d4\u05d5\u05d0 \u05de\u05e1\u05ea\u05d5\u05d1\u05d1 \u05d1\u05e1\u05e0\u05db\u05e8\u05d5\u05df \u05e2\u05dd \u05d4\u05d2\u05dc\u05d2\u05dc, \u05db\u05da \u05e9\u05d4\u05e9\u05d9\u05e0\u05d9\u05d9\u05dd \u05e0\u05d5\u05e6\u05e8\u05d5\u05ea \u05d1\u05ea\u05d4\u05dc\u05d9\u05da \u05e9\u05dc \u05d2\u05dc\u05d2\u05d5\u05dc."],[67.0,"\u05d4\u05d5\u05d1\u05d9\u05e0\u05d2 \u05de\u05d4\u05d9\u05e8 \u05d5\u05de\u05d3\u05d5\u05d9\u05e7, \u05d5\u05de\u05ea\u05d0\u05d9\u05dd \u05dc\u05e8\u05d5\u05d1 \u05d4\u05d2\u05dc\u05d2\u05dc\u05d9\u05dd \u05d4\u05d7\u05d9\u05e6\u05d5\u05e0\u05d9\u05d9\u05dd, \u05e2\u05dd \u05e9\u05d9\u05e0\u05d9\u05d9\u05dd \u05d9\u05e9\u05e8\u05d5\u05ea \u05d0\u05d5 \u05de\u05e9\u05d5\u05e4\u05e2\u05d5\u05ea."],[73.0,"\u05d1\u05d2\u05d9\u05e8 \u05e9\u05d9\u05d9\u05e4\u05d9\u05e0\u05d2 (gear shaping), \u05db\u05dc\u05d9 \u05d1\u05e6\u05d5\u05e8\u05ea \u05d2\u05dc\u05d2\u05dc \u05e0\u05e2 \u05dc\u05de\u05e2\u05dc\u05d4 \u05d5\u05dc\u05de\u05d8\u05d4 \u05d5\u05de\u05e1\u05ea\u05d5\u05d1\u05d1 \u05d9\u05d7\u05d3 \u05e2\u05dd \u05d4\u05d7\u05dc\u05e7."],[80.0,"\u05db\u05da \u05d0\u05e4\u05e9\u05e8 \u05dc\u05d9\u05d9\u05e6\u05e8 \u05d2\u05dd \u05d2\u05dc\u05d2\u05dc\u05d9\u05dd \u05e4\u05e0\u05d9\u05de\u05d9\u05d9\u05dd, \u05d5\u05d2\u05dd \u05e9\u05d9\u05e0\u05d9\u05d9\u05dd \u05e7\u05e8\u05d5\u05d1 \u05dc\u05db\u05ea\u05e3, \u05e9\u05dd \u05dc\u05d4\u05d5\u05d1 \u05d0\u05d9\u05df \u05de\u05e7\u05d5\u05dd \u05dc\u05e6\u05d0\u05ea."],[87.0,"\u05d1\u05db\u05de\u05d5\u05d9\u05d5\u05ea \u05e7\u05d8\u05e0\u05d5\u05ea \u05d0\u05e4\u05e9\u05e8 \u05dc\u05db\u05e8\u05e1\u05dd \u05db\u05dc \u05e8\u05d5\u05d5\u05d7 \u05d1\u05d9\u05df \u05e9\u05d9\u05e0\u05d9\u05d9\u05dd \u05d1\u05e0\u05e4\u05e8\u05d3, \u05e2\u05dd \u05db\u05e8\u05e1\u05dd \u05d1\u05e6\u05d5\u05e8\u05ea \u05d4\u05e8\u05d5\u05d5\u05d7, \u05d0\u05d1\u05dc \u05d4\u05d3\u05d9\u05d5\u05e7 \u05e0\u05de\u05d5\u05da \u05d9\u05d5\u05ea\u05e8."],[95.0,"\u05d5\u05e1\u05e4\u05dc\u05d9\u05d9\u05e0\u05d9\u05dd \u05e4\u05e0\u05d9\u05de\u05d9\u05d9\u05dd \u05de\u05d9\u05d9\u05e6\u05e8\u05d9\u05dd \u05dc\u05e2\u05ea\u05d9\u05dd \u05e7\u05e8\u05d5\u05d1\u05d5\u05ea \u05d1\u05d1\u05e8\u05d5\u05e6'\u05d9\u05e0\u05d2, \u05db\u05de\u05d5 \u05e9\u05e8\u05d0\u05d9\u05e0\u05d5 \u05d1\u05e4\u05e8\u05e7 \u05d4\u05e7\u05d5\u05d3\u05dd."],[101.0,"\u05e8\u05d5\u05d1 \u05d2\u05dc\u05d2\u05dc\u05d9 \u05d4\u05e9\u05d9\u05e0\u05d9\u05d9\u05dd \u05de\u05d5\u05e7\u05e9\u05d9\u05dd, \u05db\u05d3\u05d9 \u05e9\u05d9\u05e2\u05de\u05d3\u05d5 \u05d1\u05e9\u05d7\u05d9\u05e7\u05d4 \u05d5\u05d1\u05e2\u05d5\u05de\u05e1."],[106.0,"\u05d4\u05e0\u05e4\u05d5\u05e5\u05da \u05d4\u05d5\u05d0 \u05e6\u05de\u05e0\u05d8\u05e6\u05d9\u05d4: \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 | \u05de\u05e7\u05d1\u05dc\u05d9\u05dd \u05e4\u05d7\u05de \u05d5\u05de\u05d5\u05e7\u05e9\u05d9\u05dd, \u05d5\u05d4\u05dc\u05d9\u05d1\u05d4 \u05e0\u05e9\u05d0\u05e8\u05ea \u05e7\u05e9\u05d9\u05d7\u05d4."],[113.0,"\u05d8\u05d9\u05e4\u05d5\u05dc \u05d4\u05d7\u05d5\u05dd \u05de\u05e2\u05d5\u05d5\u05ea \u05de\u05e2\u05d8 \u05d0\u05ea \u05d4\u05d2\u05dc\u05d2\u05dc, \u05d5\u05dc\u05db\u05df \u05d1\u05d2\u05dc\u05d2\u05dc\u05d9\u05dd \u05de\u05d3\u05d5\u05d9\u05e7\u05d9\u05dd \u05de\u05e9\u05d7\u05d9\u05d6\u05d9\u05dd \u05d0\u05ea \u05d4\u05e9\u05d9\u05e0\u05d9\u05d9\u05dd \u05d0\u05d7\u05e8\u05d9 \u05d4\u05d4\u05e7\u05e9\u05d9\u05d4."],[121.0,"\u05d1\u05d2\u05dc\u05d2\u05dc\u05d9 \u05e9\u05d9\u05e0\u05d9\u05d9\u05dd \u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05d0\u05ea \u05d4\u05e4\u05e8\u05d5\u05e4\u05d9\u05dc, \u05d0\u05ea \u05d4\u05e4\u05e1\u05d9\u05e2\u05d4 \u05d5\u05d0\u05ea \u05d4\u05e8\u05d0\u05e0\u05d0\u05d0\u05d5\u05d8 (\u05d6\u05d8\u05e1\u05d7\u05d8\u05d6), \u05d1\u05de\u05db\u05d5\u05e0\u05ea \u05de\u05d3\u05d9\u05d3\u05d4 \u05d9\u05d9\u05e2\u05d5\u05d3\u05d9\u05ea."],[127.0,"\u05d1\u05e1\u05d3\u05e0\u05d4 \u05de\u05d5\u05d3\u05d3\u05d9\u05dd \u05dc\u05e2\u05ea\u05d9\u05dd \u05e7\u05e8\u05d5\u05d1\u05d5\u05ea \u05de\u05d9\u05d3\u05d4 \u05e2\u05dc \u05e4\u05e0\u05d9 \u05db\u05de\u05d4 \u05e9\u05d9\u05e0\u05d9\u05d9\u05dd, \u05d0\u05d5 \u05de\u05e2\u05dc \u05e4\u05d9\u05e0\u05d9\u05dd."],[133.0,"\u05d3\u05e8\u05d2\u05ea \u05d4\u05d3\u05d9\u05d5\u05e7 \u05e0\u05e7\u05d1\u05e2\u05ea \u05dc\u05e4\u05d9 \u05ea\u05e7\u05df, \u05d5\u05db\u05db\u05dc \u05e9\u05d4\u05d9\u05d0 \u05d4\u05d3\u05d5\u05e7\u05d4 \u05d9\u05d5\u05ea\u05e8, \u05d4\u05d2\u05dc\u05d2\u05dc\u05d9\u05e7\u05e8 \u05d9\u05d5\u05ea\u05e8."],[140.0,"\u05d2\u05dd \u05d1\u05d2\u05dc\u05d2\u05dc\u05d9 \u05e9\u05d9\u05e0\u05d9\u05d9\u05dd \u05d9\u05e9 \u05d1\u05e2\u05d9\u05d5\u05ea \u05d0\u05d5\u05e4\u05d9\u05d9\u05e0\u05d9\u05d5\u05ea."],[143.0,"\u05e8\u05e2\u05e9 \u05d5\u05e8\u05e2\u05d9\u05d3\u05d5\u05ea, \u05db\u05e9\u05e4\u05e8\u05d5\u05e4\u05d9\u05dc \u05d4\u05e9\u05df \u05d0\u05d5 \u05d4\u05e4\u05e1\u05d9\u05e2\u05d4 \u05dc\u05d0 \u05de\u05d3\u05d5\u05d9\u05e7\u05d9\u05dd."],[147.0,"\u05e4\u05d9\u05d8\u05d9\u05e0\u05d2 (pitting): \u05d7\u05d5\u05e8\u05d9\u05dd \u05e7\u05d8\u05e0\u05d9\u05dd \u05e2\u05dc \u05e4\u05e0\u05d9 \u05d4\u05e9\u05df, \u05de\u05e2\u05d9\u05d9\u05e4\u05d5\u05ea \u05de\u05d2\u05e2."],[152.0,"\u05e9\u05d7\u05d9\u05e7\u05d4, \u05db\u05e9\u05d4\u05d4\u05e7\u05e9\u05d9\u05d4 \u05d0\u05d5 \u05d4\u05e1\u05d9\u05db\u05d4 \u05dc\u05d0 \u05de\u05e1\u05e4\u05d9\u05e7\u05d5\u05ea."],[156.0,"\u05d5\u05e2\u05d9\u05d5\u05d5\u05ea \u05de\u05d8\u05d9\u05e4\u05d5\u05dc \u05d4\u05d7\u05d5\u05dd, \u05e9\u05de\u05e9\u05e0\u05d4 \u05d0\u05ea \u05d4\u05d2\u05d0\u05d5\u05de\u05d8\u05e8\u05d9\u05d4."],[160.0,"\u05db\u05d3\u05d0\u05d9 \u05dc\u05d1\u05d7\u05d5\u05e8 \u05de\u05d5\u05d3\u05d5\u05dc \u05e1\u05d8\u05e0\u05d3\u05e8\u05d8\u05d9, \u05e9\u05d9\u05e9 \u05dc\u05d5 \u05db\u05dc\u05d9\u05dd \u05de\u05d5\u05db\u05e0\u05d9\u05dd."],[164.0,"\u05de\u05ea\u05d7\u05ea \u05dc\u05d1\u05e2\u05e8\u05da 17 \u05e9\u05d9\u05e0\u05d9\u05d9\u05dd \u05d4\u05db\u05dc\u05d9 \u05d7\u05d5\u05ea\u05da \u05d0\u05ea \u05d1\u05e1\u05d9\u05e1 \u05d4\u05e9\u05df \u05d5\u05de\u05d7\u05dc\u05d9\u05e9 \u05d0\u05d5\u05ea\u05d4."],[173.0,"\u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05e9\u05d0\u05d9\u05e8 \u05de\u05e7\u05d5\u05dd \u05dc\u05d9\u05e6\u05d9\u05d0\u05ea \u05d4\u05db\u05dc\u05d9 \u05dc\u05d9\u05d3 \u05db\u05ea\u05e3, \u05d0\u05d5 \u05dc\u05d1\u05d7\u05d5\u05e8 \u05d1\u05d2\u05d9\u05e8 \u05e9\u05d9\u05d9\u05e4\u05d9\u05e0\u05d2."],[179.0,"\u05d5\u05dc\u05d0 \u05dc\u05d3\u05e8\u05d5\u05e9 \u05d3\u05e8\u05d2\u05ea \u05d3\u05d9\u05d5\u05e7 \u05d2\u05d1\u05d5\u05d4\u05d4 \u05de\u05de\u05d4 \u05e9\u05d1\u05d0\u05de\u05ea \u05e6\u05e8\u05d9\u05da."],[183.0,"\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8 \u05d2\u05dc\u05d2\u05dc\u05d9 \u05e9\u05d9\u05e0\u05d9\u05d9\u05dd?"],[185.0,"\u05de\u05db\u05d5\u05e0\u05d5\u05ea \u05d9\u05d9\u05e2\u05d5\u05d3\u05d9\u05d5\u05ea, \u05d5\u05db\u05dc\u05d9\u05dd \u05e9\u05de\u05ea\u05d0\u05d9\u05de\u05d9\u05dd \u05dc\u05de\u05d5\u05d3\u05d5\u05dc \u05de\u05e1\u05d5\u05d9\u05dd."],[189.0,"\u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd \u05d5\u05d4\u05e9\u05d7\u05d6\u05ea \u05e9\u05d9\u05e0\u05d9\u05d9\u05dd \u05d0\u05d7\u05e8\u05d9\u05d5."],[192.0,"\u05d1\u05d3\u05d9\u05e7\u05d4 \u05d1\u05de\u05db\u05d5\u05e0\u05ea \u05de\u05d3\u05d9\u05d3\u05d4 \u05d9\u05d9\u05e2\u05d5\u05d3\u05d9\u05ea."],[195.0,"\u05d5\u05d3\u05e8\u05d2\u05ea \u05d3\u05d9\u05d5\u05e7 \u05d2\u05d1\u05d5\u05d4\u05d4. \u05d1\u05db\u05de\u05d5\u05d9\u05d5\u05ea \u05e7\u05d8\u05e0\u05d5\u05ea, \u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05e2\u05d3\u05d9\u05e3 \u05dc\u05e7\u05e0\u05d5\u05ea \u05d2\u05dc\u05d2\u05dc \u05e1\u05d8\u05e0\u05d3\u05e8\u05d8\u05d9 \u05d5\u05dc\u05e2\u05d1\u05d3 \u05d0\u05d5\u05ea\u05d5."],[202.0,"\u05d2\u05dc\u05d2\u05dc\u05d9 \u05e9\u05d9\u05e0\u05d9\u05d9\u05dd \u05d3\u05d5\u05e8\u05e9\u05d9\u05dd \u05db\u05dc\u05d9\u05dd \u05d5\u05de\u05db\u05d5\u05e0\u05d5\u05ea \u05de\u05d9\u05d5\u05d7\u05d3\u05d9\u05dd, \u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd \u05d5\u05d1\u05d3\u05d9\u05e7\u05d4 \u05de\u05d3\u05d5\u05d9\u05e7\u05ea."],[208.0,"\u05d1\u05d6\u05d4 \u05e1\u05d9\u05d9\u05de\u05e0\u05d5 \u05d0\u05ea \u05e7\u05d1\u05d5\u05e6\u05ea \u05d4\u05e2\u05d9\u05d1\u05d5\u05d3 \u05d4\u05e9\u05d1\u05d1\u05d9."],[211.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0 \u05e0\u05ea\u05d7\u05d9\u05dc \u05d1\u05e2\u05d9\u05d1\u05d5\u05d3 \u05e4\u05d7: \u05d6\u05d9\u05d5\u05d5\u05d3."]]};
window.MH_TR["\u05e4\u05e8\u05e711_\u05d6\u05d9\u05d5\u05d5\u05d3"]={"t":"\u05d6\u05d9\u05d5\u05d5\u05d3","l":[[1.0,"\u05d0\u05e8\u05d5\u05e0\u05d5\u05ea \u05d7\u05e9\u05de\u05dc, \u05de\u05d0\u05e8\u05d6\u05d9\u05dd \u05dc\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05e0\u05d9\u05e7\u05d4, \u05ea\u05d5\u05e9\u05d1\u05d5\u05ea, \u05de\u05d2\u05e9\u05d9\u05dd \u05d5\u05e9\u05dc\u05d3\u05d5\u05ea: \u05db\u05d5\u05dc\u05dd \u05de\u05ea\u05d7\u05d9\u05dc\u05d9\u05dd \u05db\u05dc\u05d5\u05d7 \u05e4\u05d7 \u05e9\u05d5\u05d8\u05d5\u05d7."],[9.0,"\u05d6\u05d9\u05d5\u05d5\u05d3 \u05d4\u05d5\u05d0 \u05db\u05dc \u05de\u05e9\u05e4\u05d7\u05ea \u05d4\u05ea\u05d4\u05dc\u05d9\u05db\u05d9\u05dd \u05e9\u05d4\u05d5\u05e4\u05db\u05d9\u05dd \u05e4\u05d7 \u05e9\u05d8\u05d5\u05d7 \u05dc\u05d7\u05dc\u05e7 \u05d0\u05d5 \u05dc\u05de\u05db\u05dc\u05d5\u05dc: \u05d7\u05d9\u05ea\u05d5\u05da, \u05e0\u05d9\u05e7\u05d5\u05d1, \u05db\u05d9\u05e4\u05d5\u05e3, \u05d7\u05d9\u05d1\u05d5\u05e8 \u05d5\u05d2\u05d9\u05de\u05d5\u05e8."],[20.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d6\u05d4 \u05e0\u05e8\u05d0\u05d4 \u05d0\u05ea \u05d4\u05ea\u05de\u05d5\u05e0\u05d4 \u05d4\u05de\u05dc\u05d0\u05d4, \u05d5\u05d1\u05e4\u05e8\u05e7\u05d9\u05dd \u05d4\u05d1\u05d0\u05d9\u05dd \u05e0\u05e8\u05d7\u05d9\u05d1 \u05e2\u05dc \u05d7\u05dc\u05e7 \u05de\u05d4\u05ea\u05d4\u05dc\u05d9\u05db\u05d9\u05dd."],[27.0,"\u05e4\u05d7 \u05d4\u05d5\u05d0 \u05d7\u05d5\u05de\u05e8 \u05d3\u05e7 \u05d1\u05d9\u05d7\u05e1 \u05dc\u05d2\u05d5\u05d3\u05dc \u05e9\u05dc\u05d5, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1\u05e2\u05d5\u05d1\u05d9 \u05e9\u05dc \u05e2\u05d3 \u05db-6 \u05de\"\u05de."],[33.0,"\u05de\u05e2\u05dc \u05d6\u05d4 \u05de\u05d3\u05d1\u05e8\u05d9\u05dd \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05e2\u05dc \u05e4\u05dc\u05d8\u05d5\u05ea."],[36.0,"\u05d1\u05d6\u05d9\u05d5\u05d5\u05d3 \u05db\u05de\u05e2\u05d8 \u05dc\u05d0 \u05de\u05d5\u05e8\u05d9\u05d3\u05d9\u05dd \u05d7\u05d5\u05de\u05e8: \u05d7\u05d5\u05ea\u05db\u05d9\u05dd \u05d0\u05ea \u05d4\u05e6\u05d5\u05e8\u05d4 \u05d4\u05e9\u05d8\u05d5\u05d7\u05d4, \u05d5\u05de\u05db\u05d5\u05e4\u05e4\u05d9\u05dd \u05d0\u05d5\u05ea\u05d4."],[42.0,"\u05dc\u05db\u05df \u05d6\u05d4 \u05de\u05d4\u05d9\u05e8 \u05d5\u05d6\u05d5\u05dc, \u05d5\u05d4\u05e2\u05d5\u05d1\u05d9 \u05e9\u05dc \u05d4\u05d7\u05dc\u05e7 \u05d0\u05d7\u05d9\u05d3 \u05d1\u05db\u05dc \u05de\u05e7\u05d5\u05dd."],[47.0,"\u05d4\u05d7\u05d5\u05de\u05e8\u05d9\u05dd \u05d4\u05e0\u05e4\u05d5\u05e6\u05d9\u05dd: \u05e4\u05dc\u05d3\u05d4 \u05e8\u05d2\u05d9\u05dc\u05d4 \u05d5\u05de\u05d2\u05d5\u05dc\u05d5\u05d5\u05e0\u05ea, \u05e0\u05d9\u05e8\u05d5\u05e1\u05d8\u05d4 \u05d5\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd."],[53.0,"\u05dc\u05d4\u05d9\u05e1\u05d3\u05e7 \u05d1\u05dc\u05d9\u05e4\u05d5\u05e3 \u05d1\u05e8\u05d3\u05d9\u05d5\u05e1 \u05e7\u05d8\u05df, \u05d5\u05dc\u05db\u05df \u05d1\u05d5\u05d7\u05e8\u05d9\u05dd \u05e1\u05d2\u05e1\u05d5\u05d2\u05ea \u05e9\u05de\u05ea\u05db\u05d5\u05e4\u05e4\u05ea \u05d4\u05d9\u05d8\u05d1, \u05d0\u05d5 \u05e8\u05d3\u05d9\u05d5\u05e1 \u05d2\u05d3\u05d5\u05dc \u05d9\u05d5\u05ea\u05e8."],[65.0,"\u05db\u05da \u05e0\u05e8\u05d0\u05d9\u05ea \u05d6\u05e8\u05d9\u05de\u05ea \u05d4\u05e2\u05d1\u05d5\u05d3\u05d4 \u05d4\u05d8\u05d9\u05e4\u05d5\u05e1\u05d9\u05ea."],[67.0,"\u05de\u05ea\u05db\u05e0\u05e0\u05d9\u05dd \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7, \u05d5\u05de\u05d7\u05e9\u05d1\u05d9\u05dd \u05d0\u05ea \u05d4\u05e4\u05e8\u05d9\u05e1\u05d4: \u05d4\u05e6\u05d5\u05e8\u05d4 \u05d4\u05e9\u05d8\u05d5\u05d7\u05d4, \u05dc\u05e4\u05e0\u05d9 \u05d4\u05db\u05d9\u05e4\u05d5\u05e3."],[73.0,"\u05d7\u05d5\u05ea\u05db\u05d9\u05dd \u05d5\u05de\u05e0\u05e7\u05d1\u05d9\u05dd \u05d0\u05ea \u05d4\u05e4\u05e8\u05d9\u05e1\u05d4 \u05de\u05ea\u05d5\u05da \u05dc\u05d5\u05d7."],[77.0,"\u05de\u05db\u05d5\u05e4\u05e4\u05d9\u05dd, \u05de\u05d7\u05d1\u05e8\u05d9\u05dd, \u05d5\u05d1\u05e1\u05d5\u05e3 \u05de\u05d1\u05e6\u05e2\u05d9\u05dd \u05d2\u05d9\u05de\u05d5\u05e8, \u05db\u05de\u05d5 \u05e6\u05d1\u05d9\u05e2\u05d4 \u05d0\u05d5 \u05e6\u05d9\u05e4\u05d5\u05d9."],[83.0,"\u05db\u05e9\u05de\u05db\u05d5\u05e4\u05e4\u05d9\u05dd \u05e4\u05d7, \u05d4\u05e6\u05d3 \u05d4\u05e4\u05e0\u05d9\u05de\u05d9 \u05e9\u05dc \u05d4\u05db\u05d9\u05e4\u05d5\u05e3 \u05e0\u05d3\u05d7\u05e1, \u05d5\u05d4\u05e6\u05d3 \u05d4\u05d7\u05d9\u05e6\u05d5\u05e0\u05d9 \u05e0\u05de\u05ea\u05d7."],[89.0,"\u05d1\u05d0\u05de\u05e6\u05e2 \u05d9\u05e9 \u05e9\u05db\u05d1\u05d4 \u05e9\u05d0\u05d5\u05e8\u05db\u05d4 \u05dc\u05d0 \u05de\u05e9\u05ea\u05e0\u05d4: \u05d4\u05e6\u05d9\u05e8 \u05d4\u05e0\u05d9\u05d9\u05d8\u05e8\u05dc\u05d9."],[94.0,"\u05d1\u05db\u05d9\u05e4\u05d5\u05e3, \u05d4\u05e6\u05d9\u05e8 \u05d4\u05d6\u05d4 \u05d6\u05d6 \u05dc\u05db\u05d9\u05d5\u05d5\u05df \u05d4\u05e6\u05d3 \u05d4\u05e4\u05e0\u05d9\u05de\u05d9."],[98.0,"\u05d0\u05ea \u05d4\u05de\u05d9\u05e7\u05d5\u05dd \u05e9\u05dc\u05d5 \u05de\u05ea\u05d0\u05e8 \u05de\u05e7\u05d3\u05dd \u05d0, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1\u05d9\u05df 0.3 \u05dc-0.5."],[104.0,"\u05dc\u05db\u05df \u05d0\u05d5\u05e8\u05da \u05d4\u05e4\u05e8\u05d9\u05e1\u05d4 \u05e7\u05e6\u05e8 \u05de\u05e1\u05db\u05d5\u05dd \u05d4\u05de\u05d9\u05d3\u05d5\u05ea \u05d4\u05d7\u05d9\u05e6\u05d5\u05e0\u05d9\u05d5\u05ea \u05e9\u05dc \u05d4\u05d7\u05dc\u05e7."],[109.0,"\u05d0\u05ea \u05d4\u05d7\u05d9\u05e9\u05d5\u05d1 \u05e2\u05d5\u05e9\u05d4 \u05ea\u05d5\u05db\u05e0\u05ea \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8, \u05d0\u05d1\u05dc \u05d4\u05de\u05e7\u05d3\u05dd \u05ea\u05dc\u05d5\u05d9 \u05d1\u05d7\u05d5\u05de\u05e8, \u05d1\u05e2\u05d5\u05d1\u05d9 \u05d5\u05d1\u05db\u05dc\u05d9, \u05d5\u05dc\u05db\u05df \u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05d7\u05dc\u05e7 \u05e8\u05d0\u05e9\u05d5\u05df."],[118.0,"\u05d0\u05ea \u05d4\u05e4\u05e8\u05d9\u05e1\u05d4 \u05d7\u05d5\u05ea\u05db\u05d9\u05dd \u05d1\u05db\u05de\u05d4 \u05d3\u05e8\u05db\u05d9\u05dd."],[120.0,"\u05d2\u05d9\u05dc\u05d9\u05d5\u05d8\u05d9\u05e0\u05d4 \u05d7\u05d5\u05ea\u05db\u05ea \u05e7\u05d5\u05d5\u05d9\u05dd \u05d9\u05e9\u05e8\u05d9\u05dd, \u05de\u05d4\u05e8 \u05d5\u05d1\u05d6\u05d5\u05dc."],[124.0,"\u05de\u05db\u05d5\u05e0\u05ea \u05e0\u05d9\u05e7\u05d5\u05d1 \u05e2\u05dd \u05e6\u05e8\u05d9\u05d7 \u05de\u05d7\u05d6\u05d9\u05e7\u05d4 \u05e2\u05e9\u05e8\u05d5\u05ea \u05db\u05dc\u05d9\u05dd, \u05d5\u05de\u05e0\u05e7\u05d1\u05ea \u05e7\u05d3\u05d7\u05d9\u05dd \u05d5\u05e6\u05d5\u05e8\u05d5\u05ea \u05d1\u05de\u05d4\u05d9\u05e8\u05d5\u05ea."],[130.0,"\u05d4\u05d9\u05d0 \u05d9\u05db\u05d5\u05dc\u05d4 \u05d2\u05dd \u05dc\u05e2\u05e6\u05d1 \u05e6\u05d5\u05e8\u05d5\u05ea \u05e7\u05d8\u05e0\u05d5\u05ea, \u05db\u05de\u05d5 \u05ea\u05e8\u05d9\u05e1\u05d9 \u05d0\u05d5\u05d5\u05e8\u05d5\u05e8."],[134.0,"\u05dc\u05d9\u05d9\u05d6\u05e8 \u05d7\u05d5\u05ea\u05da \u05db\u05dc \u05e6\u05d5\u05e8\u05d4, \u05d1\u05dc\u05d9 \u05db\u05dc\u05d9 \u05de\u05d9\u05d5\u05d7\u05d3 \u05d5\u05d1\u05d3\u05d9\u05d5\u05e7 \u05d8\u05d5\u05d1, \u05d5\u05dc\u05db\u05df \u05d4\u05d5\u05d0 \u05de\u05ea\u05d0\u05d9\u05dd \u05dc\u05d0\u05d1\u05d8\u05d9\u05e4\u05d5\u05e1\u05d9\u05dd \u05d5\u05dc\u05d4\u05e8\u05d1\u05d4 \u05e1\u05d5\u05d2\u05d9 \u05d7\u05dc\u05e7\u05d9\u05dd."],[143.0,"\u05dc\u05d9\u05d9\u05d6\u05e8, \u05e1\u05d9\u05dc\u05d5\u05df \u05de\u05d9\u05dd \u05d5\u05e4\u05dc\u05d6\u05de\u05d4 \u05d9\u05e7\u05d1\u05dc\u05d5 \u05e4\u05e8\u05e7\u05d9\u05dd \u05de\u05e9\u05dc\u05d4\u05dd, \u05d5\u05e2\u05dc \u05d4\u05e0\u05d9\u05e7\u05d5\u05d1 \u05e0\u05e8\u05d7\u05d9\u05d1 \u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0."],[150.0,"\u05d0\u05ea \u05e8\u05d5\u05d1 \u05d4\u05db\u05d9\u05e4\u05d5\u05e4\u05d9\u05dd \u05e2\u05d5\u05e9\u05d9\u05dd \u05d1\u05de\u05db\u05d1\u05e9 \u05db\u05d9\u05e4\u05d5\u05e3."],[153.0,"\u05e1\u05db\u05d9\u05df \u05dc\u05d5\u05d7\u05e6\u05ea \u05d0\u05ea \u05d4\u05e4\u05d7 \u05dc\u05ea\u05d5\u05da \u05de\u05d8\u05e8\u05d9\u05e6\u05d4 \u05d1\u05e6\u05d5\u05e8\u05ea \u05e5, \u05d5\u05d4\u05e2\u05d5\u05de\u05e7 \u05e9\u05dc\u05d4 \u05e7\u05d5\u05d1\u05e2 \u05d0\u05ea \u05d4\u05d6\u05d5\u05d5\u05d9\u05ea."],[159.0,"\u05d0\u05d7\u05e8\u05d9 \u05d4\u05db\u05d9\u05e4\u05d5\u05e3, \u05d4\u05e4\u05d7 \u05e7\u05d5\u05e4\u05e5 \u05de\u05e2\u05d8 \u05d7\u05d6\u05e8\u05d4."],[162.0,"\u05dc\u05db\u05df \u05de\u05db\u05d5\u05e4\u05e4\u05d9\u05dd \u05e7\u05e6\u05ea \u05d9\u05d5\u05ea\u05e8 \u05de\u05d4\u05d6\u05d5\u05d5\u05d9\u05ea \u05d4\u05e0\u05d3\u05e8\u05e2\u05d5\u05ea."],[166.0,"\u05dc\u05db\u05dc \u05d7\u05d5\u05de\u05e8 \u05d5\u05e2\u05d5\u05d1\u05d9 \u05d9\u05e9 \u05e8\u05d3\u05d9\u05d5\u05e1 \u05db\u05d9\u05e4\u05d5\u05e3 \u05de\u05d9\u05e0\u05d9\u05de\u05dc\u05d9, \u05d5\u05de\u05ea\u05d7\u05ea\u05d9\u05d5 \u05d4\u05e6\u05d3 \u05d4\u05d7\u05d9\u05e6\u05d5\u05e0\u05d9 \u05e0\u05e1\u05d3\u05e7."],[172.0,"\u05db\u05d3\u05d0\u05d9 \u05e9\u05e7\u05d5 \u05d4\u05db\u05d9\u05e4\u05d5\u05e3 \u05d9\u05d4\u05d9\u05d4 \u05e0\u05d9\u05e6\u05d1 \u05dc\u05db\u05d9\u05d5\u05d5\u05df \u05d4\u05d2\u05dc\u05d2\u05d5\u05dc \u05e9\u05dc \u05d4\u05e4\u05d7, \u05db\u05d9 \u05db\u05da \u05d4\u05e1\u05d9\u05db\u05d5\u05df \u05dc\u05e1\u05d3\u05e7\u05d9\u05dd \u05e7\u05d8\u05df \u05d9\u05d5\u05ea\u05e8."],[179.0,"\u05e2\u05dc \u05db\u05d9\u05e4\u05d5\u05e3 \u05e0\u05e8\u05d7\u05d9\u05d1 \u05d1\u05e4\u05e8\u05e7 13."],[182.0,"\u05db\u05e9\u05e6\u05e8\u05d9\u05da \u05d2\u05dc\u05d9\u05dc\u05d9\u05dd \u05d5\u05e7\u05d5\u05e0\u05d5\u05e1\u05d9\u05dd, \u05de\u05e2\u05e8\u05d2\u05dc\u05d9\u05dd \u05d0\u05ea \u05d4\u05e4\u05d7 \u05d1\u05d9\u05df \u05d2\u05dc\u05d9\u05dc\u05d9\u05dd, \u05d5\u05e2\u05dc \u05d6\u05d4 \u05d1\u05e4\u05e8\u05e7 14."],[189.0,"\u05d5\u05d1\u05db\u05de\u05d5\u05d9\u05d5\u05ea \u05d2\u05d3\u05d5\u05dc\u05d5\u05ea, \u05db\u05d5\u05d1\u05e9\u05d9\u05dd \u05d5\u05de\u05d8\u05d1\u05d9\u05e2\u05d9\u05dd \u05e6\u05d5\u05e8\u05d5\u05ea \u05e9\u05dc\u05de\u05d5\u05ea \u05d1\u05ea\u05d1\u05e0\u05d9\u05ea, \u05d1\u05de\u05db\u05d4 \u05d0\u05d7\u05ea \u05d0\u05d5 \u05d1\u05db\u05de\u05d4 \u05ea\u05d7\u05e0\u05d5\u05ea."],[196.0,"\u05e2\u05dc \u05d6\u05d4 \u05e0\u05e8\u05d7\u05d9\u05d1 \u05d1\u05e4\u05e8\u05e7 15."],[199.0,"\u05d7\u05dc\u05e7\u05d9\u05dd \u05de\u05e4\u05d7 \u05de\u05d7\u05d1\u05e8\u05d9\u05dd \u05d1\u05dc\u05de\u05d4 \u05d3\u05e8\u05db\u05d9\u05dd."],[202.0,"\u05e8\u05d9\u05ea\u05d5\u05da \u05e0\u05e7\u05d5\u05d3\u05ea\u05d9 \u05de\u05d7\u05d1\u05e8 \u05e9\u05e0\u05d9 \u05e4\u05d7\u05d9\u05dd \u05d1\u05e0\u05e7\u05d5\u05d3\u05d5\u05ea, \u05d1\u05d6\u05e8\u05dd \u05d7\u05e9\u05d5\u05de\u05dc\u05d9, \u05de\u05d4\u05e8 \u05d5\u05d1\u05dc\u05d9 \u05d7\u05d5\u05de\u05e8 \u05e0\u05d5\u05e1\u05e3."],[209.0,"\u05d5\u05d0\u05d8\u05d5\u05dd, \u05d0\u05d1\u05dc \u05de\u05d7\u05de\u05dd \u05d5\u05de\u05e2\u05d5\u05d5\u05ea \u05d0\u05ea \u05d4\u05e4\u05d7, \u05d5\u05d3\u05d5\u05e8\u05e9 \u05dc\u05e2\u05ea\u05d9\u05dd \u05d4\u05e9\u05d7\u05d6\u05d4."],[218.0,"\u05de\u05e1\u05de\u05e8\u05d5\u05ea, \u05db\u05d5\u05dc\u05dc \u05de\u05e1\u05de\u05e8\u05d5\u05ea \u05e2\u05d9\u05d5\u05d5\u05e8\u05d5\u05ea \u05e9\u05de\u05ea\u05e7\u05d9\u05e0\u05d9\u05dd \u05de\u05e6\u05d3 \u05d0\u05d7\u05d3, \u05de\u05d7\u05d1\u05e8\u05d5\u05ea \u05d1\u05dc\u05d9 \u05d7\u05d5\u05dd."],[224.0,"\u05d5\u05d0\u05d5\u05de\u05d9 \u05dc\u05d7\u05d9\u05e6\u05d4, \u05d5\u05d1\u05e8\u05d2\u05d9\u05dd \u05d5\u05e2\u05de\u05d5\u05d3\u05d5\u05e0\u05d9\u05dd \u05de\u05e1\u05d5\u05d2 \u05d3\u05d5\u05de\u05d4, \u05e0\u05dc\u05d7\u05e6\u05d9\u05dd \u05dc\u05ea\u05d5\u05da \u05e7\u05d3\u05d7 \u05d1\u05e4\u05d7, \u05d5\u05e0\u05d5\u05ea\u05e0\u05d9\u05dd \u05d4\u05d1\u05e8\u05d2\u05d4 \u05d7\u05d6\u05e7\u05d4 \u05d2\u05dd \u05d1\u05e4\u05d7 \u05d3\u05e7."],[233.0,"\u05d2\u05dd \u05dc\u05d6\u05d9\u05d5\u05d5\u05d3 \u05d9\u05e9 \u05db\u05dc\u05dc\u05d9 \u05ea\u05db\u05e0\u05d5\u05df."],[235.0,"\u05e7\u05d3\u05d7 \u05e7\u05e8\u05d5\u05d1 \u05de\u05d3\u05d9 \u05dc\u05e7\u05d5 \u05db\u05d9\u05e4\u05d5\u05e3 \u05de\u05ea\u05e2\u05d5\u05d5\u05ea."],[238.0,"\u05db\u05dc\u05dc \u05d0\u05e6\u05d1\u05e2: \u05d4\u05de\u05e8\u05d7\u05e7 \u05de\u05e9\u05e4\u05ea \u05d4\u05e7\u05d3\u05d7 \u05dc\u05db\u05d9\u05e4\u05d5\u05e3, \u05dc\u05e4\u05d7\u05d5\u05ea \u05e4\u05e2\u05de\u05d9\u05d9\u05dd \u05d5\u05d7\u05e6\u05d9 \u05e2\u05d5\u05d1\u05d9 \u05d4\u05e4\u05d7, \u05d5\u05e2\u05d5\u05d3 \u05e8\u05d3\u05d9\u05d5\u05e1 \u05d4\u05db\u05d9\u05e4\u05d5\u05e3."],[246.0,"\u05db\u05e9\u05e0\u05d9\u05e4\u05d5\u05e3 \u05de\u05d2\u05d9\u05e2 \u05e2\u05d3 \u05e9\u05e4\u05ea \u05d4\u05e4\u05d7, \u05d7\u05d5\u05ea\u05db\u05d9\u05dd \u05d7\u05e8\u05d9\u05e5 \u05e9\u05d7\u05e8\u05d5\u05e8 \u05e7\u05d8\u05df, \u05db\u05d3\u05d9 \u05e9\u05d4\u05e4\u05d7 \u05dc\u05d0 \u05d9\u05d9\u05e7\u05e8\u05e2 \u05d1\u05e4\u05d9\u05e0\u05d4."],[253.0,"\u05d0\u05d5\u05d2\u05df \u05e7\u05e6\u05e8 \u05de\u05d3\u05d9 \u05dc\u05d0 \u05e0\u05ea\u05e4\u05e1 \u05d4\u05d9\u05d8\u05d1 \u05d1\u05de\u05d8\u05e8\u05d9\u05e6\u05d4, \u05d5\u05dc\u05d0 \u05de\u05ea\u05db\u05d5\u05e4\u05e3 \u05e0\u05db\u05d5\u05df."],[258.0,"\u05d5\u05db\u05d3\u05d0\u05d9 \u05dc\u05d4\u05e9\u05ea\u05de\u05e9 \u05d1\u05d0\u05d5\u05ea\u05d5 \u05e8\u05d3\u05d9\u05d5\u05e1 \u05d1\u05db\u05dc \u05d4\u05db\u05d9\u05e4\u05d5\u05e4\u05d9\u05dd, \u05db\u05d3\u05d9 \u05dc\u05e2\u05d1\u05d5\u05d3 \u05e2\u05dd \u05db\u05dc\u05d9 \u05d0\u05d7\u05d3."],[263.0,"\u05db\u05d9\u05e4\u05d5\u05e3 \u05de\u05d5\u05e1\u05d9\u05e3 \u05e1\u05d8\u05d9\u05d9\u05d4, \u05d5\u05de\u05d9\u05d3\u05d4 \u05e9\u05e2\u05d5\u05d1\u05e8\u05ea \u05d3\u05e8\u05da \u05db\u05de\u05d4 \u05db\u05d9\u05e4\u05d5\u05e4\u05d9\u05dd \u05e4\u05d7\u05d5\u05ea \u05de\u05d3\u05d5\u05d9\u05e7\u05ea."],[273.0,"\u05d1\u05e1\u05d5\u05e3 \u05de\u05e1\u05d9\u05e8\u05d9\u05dd \u05d2\u05e8\u05d3 \u05de\u05d4\u05e7\u05e6\u05d5\u05d5\u05ea, \u05d5\u05de\u05d1\u05e6\u05e2\u05d9\u05dd \u05d2\u05d9\u05de\u05d5\u05e8 \u05dc\u05e4\u05d9 \u05d4\u05d7\u05d5\u05de\u05e8 \u05d5\u05d4\u05e9\u05d9\u05de\u05d5\u05e9."],[278.0,"\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05de\u05d0\u05dc\u05d2\u05e0\u05d9\u05dd, \u05d5\u05d1\u05e0\u05d9\u05e8\u05d5\u05e1\u05d8\u05d4 \u05de\u05d1\u05e6\u05e2\u05d9\u05dd \u05e4\u05e1\u05d9\u05d1\u05e6\u05d9\u05d4 \u05d0\u05d5 \u05dc\u05d9\u05d8\u05d5\u05e9\u05e9."],[288.0,"\u05e9\u05d9\u05de\u05d5 \u05dc\u05d1: \u05e6\u05d1\u05e2 \u05d5\u05e6\u05d9\u05e4\u05d5\u05d9 \u05de\u05d5\u05e1\u05d9\u05e4\u05d9\u05dd \u05e2\u05d5\u05d1\u05d9, \u05d5\u05d6\u05d4 \u05d7\u05e9\u05d5\u05d5\u05d1 \u05d1\u05e7\u05d3\u05d7\u05d9\u05dd \u05d5\u05d1\u05d4\u05e8\u05db\u05d1\u05d4."],[294.0,"\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8\u05d6\u05d9\u05d5\u05d5\u05d3?"],[296.0,"\u05d4\u05db\u05d9\u05e4\u05d5\u05e4\u05d9\u05dd: \u05db\u05dc \u05db\u05d9\u05e4\u05d5\u05e3 \u05d4\u05d5\u05d0 \u05e4\u05e2\u05d5\u05dc\u05d4, \u05d5\u05db\u05dc \u05d4\u05d7\u05dc\u05e4\u05ea \u05db\u05dc\u05d9 \u05d1\u05de\u05db\u05d1\u05e9 \u05d4\u05d9\u05d0 \u05d6\u05de\u05df \u05d4\u05db\u05e0\u05d4."],[302.0,"\u05e8\u05d9\u05ea\u05d5\u05da \u05d5\u05d4\u05e9\u05d7\u05d6\u05d4: \u05d4\u05e8\u05d1\u05d4 \u05e2\u05d1\u05d5\u05d3\u05ea \u05d9\u05d3\u05d9\u05d9\u05dd, \u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d2\u05dd \u05d9\u05d9\u05e9\u05d5\u05e8 \u05d0\u05d7\u05e8\u05d9 \u05e2\u05d9\u05d5\u05d5\u05ea."],[308.0,"\u05db\u05dc\u05d9\u05dd: \u05dc\u05db\u05d1\u05d9\u05e9\u05d4 \u05e6\u05e8\u05d9\u05da \u05ea\u05d1\u05e0\u05d9\u05ea \u05d9\u05e7\u05e8\u05d4, \u05d5\u05dc\u05dc\u05d9\u05d9\u05d6\u05e8 \u05dc\u05d0 \u05e6\u05e8\u05d9\u05da \u05db\u05dc\u05d9 \u05d1\u05db\u05dc\u05dc."],[314.0,"\u05e0\u05d9\u05e6\u05d5\u05dc \u05d4\u05d7\u05d5\u05de\u05e8: \u05db\u05de\u05d4 \u05d7\u05dc\u05e7\u05d9\u05dd \u05e0\u05db\u05e0\u05e1\u05d9\u05dd \u05d1\u05dc\u05d5\u05d7 \u05d0\u05d7\u05d3, \u05d5\u05db\u05de\u05d4 \u05d4\u05d5\u05dc\u05da \u05dc\u05e4\u05d7\u05ea."],[320.0,"\u05d5\u05d2\u05d9\u05de\u05d5\u05e8, \u05d4\u05e8\u05db\u05d1\u05d4 \u05e9\u05dc \u05e8\u05db\u05d9\u05d1\u05d9 \u05dc\u05d7\u05d9\u05e6\u05d4, \u05d5\u05d8\u05d5\u05dc\u05e8\u05e0\u05e1\u05d9\u05dd \u05d4\u05d3\u05d5\u05e7\u05d9\u05dd."],[325.0,"\u05d0\u05d6 \u05d0\u05d9\u05da \u05d1\u05d5\u05d7\u05e8\u05d9\u05dd?"],[327.0,"\u05dc\u05d0\u05d1\u05d8\u05d9\u05e4\u05d5\u05e1 \u05d5\u05dc\u05e1\u05d3\u05e8\u05d5\u05ea \u05e7\u05d8\u05e0\u05d5\u05ea: \u05dc\u05d9\u05d9\u05d6\u05e8 \u05d5\u05de\u05db\u05d1\u05e9 \u05db\u05d9\u05e4\u05d5\u05e3, \u05d1\u05dc\u05d9 \u05db\u05dc\u05d9\u05dd \u05de\u05d9\u05d5\u05d7\u05d3\u05d9\u05dd."],[332.0,"\u05dc\u05e1\u05d3\u05e8\u05d5\u05ea \u05d1\u05d9\u05e0\u05d5\u05e0\u05d9\u05d5\u05ea: \u05de\u05db\u05d5\u05e0\u05ea \u05e0\u05d9\u05e7\u05d5\u05d1 \u05e2\u05dd \u05e6\u05e8\u05d9\u05d7, \u05d5\u05db\u05d9\u05e4\u05d5\u05e3."],[337.0,"\u05dc\u05db\u05de\u05d5\u05d9\u05d5\u05ea \u05d2\u05d3\u05d5\u05dc\u05d5\u05ea: \u05db\u05d1\u05d9\u05e9\u05d4 \u05d1\u05ea\u05d1\u05e0\u05d9\u05ea, \u05e9\u05de\u05d9\u05d9\u05e6\u05e8\u05ea \u05d7\u05dc\u05e7 \u05d1\u05db\u05dc \u05de\u05db\u05d4."],[342.0,"\u05d5\u05db\u05e9\u05d4\u05d7\u05dc\u05e7 \u05e2\u05d1\u05d4, \u05de\u05e1\u05d9\u05d1\u05d9 \u05d0\u05d5 \u05de\u05d3\u05d5\u05d9\u05e7 \u05de\u05d0\u05d5\u05d3, \u05e2\u05d3\u05d9\u05e3 \u05e2\u05d9\u05d1\u05d5\u05d3 \u05e9\u05d1\u05d1\u05d9."],[348.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0: \u05e0\u05d9\u05e7\u05d5\u05d1."]]};
window.MH_TR["\u05e4\u05e8\u05e712_\u05e0\u05d9\u05e7\u05d5\u05d1"]={"t":"\u05e0\u05d9\u05e7\u05d5\u05d1","l":[[1.0,"\u05d1\u05dc\u05d5\u05d7 \u05e4\u05d7 \u05e9\u05dc \u05d0\u05e8\u05d5\u05df \u05d7\u05e9\u05de\u05dc \u05d9\u05e9 \u05e2\u05e9\u05e8\u05d5\u05ea \u05e7\u05d3\u05d7\u05d9\u05dd, \u05d7\u05dc\u05d5\u05e0\u05d5\u05ea \u05d5\u05ea\u05e8\u05d9\u05e1\u05d9\u05dd."],[6.0,"\u05d0\u05ea \u05e8\u05d5\u05d1\u05dd \u05de\u05d9\u05d9\u05e6\u05e8\u05d9\u05dd \u05d1\u05e0\u05d9\u05e7\u05d5\u05d1: \u05db\u05dc\u05d9 \u05e9\u05e0\u05db\u05e0\u05e1 \u05dc\u05ea\u05d5\u05da \u05d4\u05e4\u05d7 \u05d5\u05d9\u05d5\u05e6\u05d0 \u05d1\u05e9\u05d1\u05e8\u05d9\u05e8 \u05e9\u05e0\u05d9\u05d9\u05d4."],[12.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d6\u05d4 \u05e0\u05db\u05d9\u05e8 \u05d0\u05d9\u05da \u05d6\u05d4 \u05e2\u05d5\u05d1\u05d3, \u05de\u05d4 \u05d4\u05d5\u05d0 \u05e0\u05d5\u05ea\u05df, \u05d5\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8 \u05d0\u05d5\u05ea\u05d5."],[18.0,"\u05d1\u05e0\u05d9\u05e7\u05d5\u05d1 \u05d9\u05e9 \u05e9\u05e0\u05d9 \u05d7\u05dc\u05e7\u05d9\u05dd: \u05e1\u05db\u05d9\u05df \u05e0\u05d9\u05e7\u05d5\u05d1 \u05de\u05dc\u05de\u05e2\u05dc\u05d4, \u05d5\u05de\u05d8\u05e8\u05d9\u05e6\u05d4 \u05de\u05dc\u05de\u05d8\u05d4."],[24.0,"\u05d1\u05d9\u05df \u05d4\u05e1\u05db\u05d9\u05df \u05dc\u05de\u05d8\u05e8\u05d9\u05e6\u05d4 \u05d9\u05e9 \u05de\u05e8\u05d5\u05d5\u05d7 \u05e7\u05d8\u05df, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc 5 \u05e2\u05d3 10 \u05d0\u05d7\u05d5\u05d6 \u05de\u05e2\u05d5\u05d1\u05d9 \u05d4\u05e4\u05d7 \u05d1\u05db\u05dc \u05e6\u05d3."],[31.0,"\u05d4\u05e1\u05db\u05d9\u05df \u05d9\u05d5\u05e8\u05d3\u05ea, \u05dc\u05d5\u05d7\u05e6\u05ea \u05d0\u05ea \u05d4\u05e4\u05d7, \u05d5\u05d2\u05d5\u05d6\u05e8\u05ea \u05d0\u05d5\u05ea\u05d5."],[35.0,"\u05d1\u05d7\u05dc\u05e7 \u05d4\u05e2\u05dc\u05d9\u05d5\u05df \u05e9\u05dc \u05d4\u05d3\u05d5\u05e4\u05df \u05e0\u05d5\u05e6\u05e8 \u05e4\u05e1 \u05d7\u05dc\u05e7, \u05d5\u05de\u05ea\u05d7\u05ea\u05d9\u05d5 \u05d0\u05d6\u05d5\u05e8 \u05e9\u05d1\u05d9\u05e8\u05d4 \u05de\u05d7\u05d5\u05e1\u05e4\u05e1."],[41.0,"\u05d5\u05d1\u05e6\u05d3 \u05d4\u05d9\u05e6\u05d9\u05d0\u05d4, \u05de\u05ea\u05d7\u05ea \u05dc\u05e4\u05d7, \u05e0\u05d5\u05e6\u05e8 \u05d2\u05e8\u05d3."],[45.0,"\u05de\u05e8\u05d5\u05d5\u05d7 \u05e7\u05d8\u05df \u05de\u05d3\u05d9 \u05e9\u05d5\u05d7\u05e7 \u05d0\u05ea \u05d4\u05db\u05dc\u05d9, \u05d5\u05de\u05e8\u05d5\u05d5\u05d7 \u05d2\u05d3\u05d5\u05dc \u05de\u05d3\u05d9 \u05de\u05d2\u05d3\u05d9\u05dc \u05d0\u05ea \u05d4\u05d2\u05e8\u05d3."],[51.0,"\u05db\u05e9\u05d4\u05d7\u05ea\u05d9\u05db\u05d4 \u05e9\u05e0\u05e4\u05dc\u05d4 \u05d4\u05d9\u05d0 \u05e4\u05e1\u05d5\u05dc\u05ea, \u05d5\u05e7\u05d3\u05d7 \u05d4\u05d5\u05d0 \u05de\u05d4 \u05e9\u05e0\u05e9\u05d0\u05e8, \u05d6\u05d4 0\u05d7\u05d5\u05e1\u05d6\u05e4\u05d5\u05e7."],[57.0,"\u05db\u05e9\u05d4\u05d7\u05ea\u05d9\u05db\u05d4 \u05e9\u05e0\u05e4\u05dc\u05d4 \u05d4\u05d9\u05d0 \u05d4\u05d7\u05dc\u05e7 \u05e2\u05e6\u05de\u05d5, \u05d6\u05d4 blanking"],[62.0,"\u05d4\u05e2\u05d9\u05e7\u05e8\u05d5\u05df \u05d6\u05d4\u05d4, \u05d4\u05d4\u05d1\u05d3\u05dc \u05d4\u05d5\u05d0 \u05de\u05d4 \u05e9\u05d5\u05de\u05e8\u05d9\u05dd."],[66.0,"\u05de\u05db\u05d5\u05e0\u05ea \u05e0\u05d9\u05e7\u05d5\u05d1 \u05e2\u05dd \u05e6\u05e8\u05d9\u05d7 \u05de\u05d7\u05d6\u05d9\u05e7\u05d4 \u05e2\u05e9\u05e8\u05d5\u05ea \u05db\u05dc\u05d9\u05dd \u05d1\u05e6\u05d5\u05e8\u05d5\u05ea \u05d5\u05d1\u05d2\u05d3\u05dc\u05d9\u05dd \u05e9\u05d5\u05e0\u05d9\u05dd."],[71.0,"\u05d4\u05dc\u05d5\u05d7 \u05d6\u05d6 \u05de\u05ea\u05d7\u05ea \u05dc\u05e6\u05e8\u05d9\u05d7, \u05d5\u05d4\u05de\u05db\u05d5\u05e0\u05d4 \u05d1\u05d5\u05d7\u05e8\u05ea \u05db\u05dc\u05d9 \u05d5\u05de\u05e0\u05e7\u05d1\u05ea \u05d0\u05dc\u05e4\u05d9 \u05de\u05db\u05d5\u05ea \u05d1\u05e9\u05e2\u05d4."],[77.0,"\u05e6\u05d5\u05e8\u05d4 \u05d2\u05d3\u05d5\u05dc\u05d4 \u05e9\u05d0\u05d9\u05df \u05dc\u05d4 \u05db\u05dc\u05d9, \u05de\u05e0\u05e7\u05d1\u05d9\u05dd \u05d1\u05de\u05db\u05d5\u05ea \u05e7\u05d8\u05e0\u05d5\u05ea \u05d5\u05e6\u05e4\u05d5\u05e4\u05d5\u05ea \u05dc\u05d0\u05d5\u05e8\u05da \u05d4\u05e7\u05d5: \u05d6\u05d4 \u05e1\u05d7\u05d5\u05d5\u05e4\u05e4\u05d5\u05d7."],[84.0,"\u05db\u05dc\u05d9\u05dd \u05de\u05d9\u05d5\u05d7\u05d3\u05d9\u05dd \u05d9\u05db\u05d5\u05dc\u05d9\u05dd \u05d2\u05dd \u05dc\u05e2\u05e6\u05d1: \u05ea\u05e8\u05d9\u05e1\u05d9 \u05d0\u05d5\u05d5\u05e8\u05d5\u05e8, \u05e6\u05dc\u05e2\u05d5\u05ea \u05d7\u05d9\u05d6\u05d5\u05e7, \u05e6\u05d5\u05d5\u05d0\u05e8\u05d5\u05e0\u05d9\u05dd \u05dc\u05d4\u05d1\u05e8\u05d2\u05d4 \u05d5\u05e9\u05e7\u05e2\u05d9\u05dd."],[92.0,"\u05d1\u05d7\u05dc\u05e7 \u05de\u05d4\u05de\u05db\u05d5\u05e0\u05d5\u05ea \u05d4\u05db\u05dc\u05d9\u05dd \u05de\u05e1\u05ea\u05d5\u05d1\u05d1\u05d9\u05dd, \u05db\u05da \u05e9\u05d0\u05d5\u05ea\u05d5 \u05db\u05dc\u05d9 \u05de\u05e0\u05e7\u05d1 \u05d1\u05db\u05de\u05d4 \u05d6\u05d5\u05d5\u05d9\u05d5\u05ea."],[98.0,"\u05d4\u05db\u05d5\u05d7 \u05e9\u05e6\u05e8\u05d9\u05da \u05ea\u05dc\u05d5\u05d9 \u05d1\u05d4\u05d9\u05e7\u05e3 \u05d4\u05e7\u05d3\u05d7, \u05d1\u05e2\u05d5\u05d1\u05d9 \u05d4\u05e4\u05d7 \u05d5\u05d1\u05d7\u05d5\u05d6\u05e7 \u05d4\u05d7\u05d5\u05de\u05e8."],[103.0,"\u05dc\u05d3\u05d5\u05d2\u05de\u05d4, \u05e7\u05d3\u05d7 \u05d1\u05e7\u05d5\u05d8\u05e8 20 \u05de\"\u05de \u05d1\u05e4\u05dc\u05d3\u05d4 \u05d1\u05e2\u05d5\u05d1\u05d9 2 \u05de\"\u05de \u05d3\u05d5\u05e8\u05e9\u05e2\u05d5 \u05d1\u05e2\u05e8\u05da 4.5 \u05d8\u05d5\u05df."],[111.0,"\u05dc\u05db\u05df \u05d1\u05e4\u05d7 \u05e2\u05d1\u05d4 \u05d0\u05d5 \u05d1\u05e0\u05d9\u05e8\u05d5\u05e1\u05d8\u05d4, \u05d4\u05db\u05d5\u05d7 \u05d2\u05d3\u05dc \u05de\u05d4\u05e8."],[116.0,"\u05e0\u05d9\u05e7\u05d5\u05d1 \u05de\u05d4\u05d9\u05e8 \u05de\u05d0\u05d5\u05d3 \u05d1\u05e7\u05d3\u05d7\u05d9\u05dd \u05d5\u05e6\u05d5\u05e8\u05d5\u05ea \u05e9\u05d7\u05d5\u05d6\u05e8\u05d9\u05dd \u05e2\u05dc \u05e2\u05e6\u05de\u05dd."],[120.0,"\u05d4\u05d3\u05d9\u05d5\u05e7 \u05d8\u05d5\u05d1, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1\u05e1\u05d1\u05d9\u05d1\u05d5\u05ea \u05e2\u05e9\u05d9\u05e8\u05d9\u05ea \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8."],[124.0,"\u05d5\u05d1\u05d0\u05d5\u05ea\u05d4 \u05de\u05db\u05d5\u05e0\u05d4 \u05d0\u05e4\u05e9\u05e8 \u05d2\u05dd \u05dc\u05e2\u05e6\u05d1, \u05d3\u05d1\u05e8 \u05e9\u05dc\u05d9\u05d9\u05d6\u05e8 \u05dc\u05d0 \u05d9\u05d5\u05d3\u05e2 \u05dc\u05e2\u05e9\u05d5\u05ea."],[130.0,"\u05d2\u05dd \u05dc\u05e0\u05d9\u05e7\u05d5\u05d1 \u05d9\u05e9 \u05db\u05dc\u05dc\u05d9 \u05ea\u05db\u05e0\u05d5\u05df."],[132.0,"\u05e7\u05d5\u05d8\u05e8 \u05d4\u05e7\u05d3\u05d7 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05dc\u05d0 \u05e7\u05d8\u05df \u05de\u05e2\u05d5\u05d1\u05d9 \u05d4\u05e4\u05d7, \u05d5\u05d1\u05e0\u05d9\u05e8\u05d5\u05e1\u05d8\u05d4 \u05e6\u05e8\u05d9\u05da \u05e7\u05d5\u05d8\u05e8 \u05d2\u05d3\u05d5\u05dc \u05d9\u05d5\u05ea\u05e8."],[138.0,"\u05e7\u05d3\u05d7 \u05e7\u05e8\u05d5\u05d1 \u05de\u05d3\u05d9 \u05dc\u05e9\u05e4\u05d4 \u05d0\u05d5 \u05dc\u05e7\u05d3\u05d7 \u05d0\u05d7\u05e8 \u05e2\u05dc\u05d5\u05dc \u05dc\u05e2\u05d5\u05d5\u05ea \u05d0\u05ea \u05d4\u05e4\u05d7 \u05d0\u05d5 \u05dc\u05e7\u05e8\u05d5\u05e2 \u05d0\u05d5\u05ea\u05d5."],[145.0,"\u05db\u05d3\u05d0\u05d9 \u05dc\u05d4\u05e9\u05ea\u05de\u05e9 \u05d1\u05d2\u05d3\u05dc\u05d9\u05dd \u05d5\u05d1\u05e6\u05d5\u05e8\u05d5\u05ea \u05e1\u05d8\u05e0\u05d3\u05e8\u05d8\u05d9\u05d9\u05dd, \u05e9\u05d9\u05e9 \u05dc\u05d4\u05dd \u05db\u05dc\u05d9\u05dd \u05de\u05d5\u05db\u05e0\u05d9\u05dd."],[150.0,"\u05d5\u05db\u05d3\u05d0\u05d9 \u05dc\u05d6\u05db\u05d5\u05e8 \u05e9\u05d4\u05d2\u05e8\u05d3 \u05e0\u05de\u05e6\u05d0 \u05d1\u05e6\u05d3 \u05d0\u05d7\u05d3, \u05d5\u05dc\u05e1\u05de\u05df \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05de\u05d0\u05d9\u05d6\u05d4 \u05e6\u05d3 \u05d4\u05d5\u05d0 \u05de\u05d5\u05ea\u05e8."],[156.0,"\u05d2\u05dd \u05d1\u05e0\u05d9\u05e7\u05d5\u05d1 \u05d9\u05e9 \u05d1\u05e2\u05d9\u05d5\u05ea \u05d0\u05d5\u05e4\u05d9\u05d9\u05e0\u05d9\u05d5\u05ea."],[159.0,"\u05d2\u05e8\u05d3 \u05d2\u05d3\u05d5\u05dc, \u05de\u05db\u05dc\u05d9 \u05e9\u05d7\u05d5\u05e7 \u05d0\u05d5 \u05de\u05de\u05e8\u05d5\u05d5\u05d7 \u05dc\u05d0 \u05e0\u05db\u05d5\u05df."],[163.0,"\u05e2\u05d9\u05d5\u05d5\u05ea \u05e9\u05dc \u05d4\u05dc\u05d5\u05d7, \u05db\u05e9\u05d9\u05e9 \u05d4\u05e8\u05d1\u05d4 \u05e7\u05d3\u05d7\u05d9\u05dd \u05e6\u05e4\u05d5\u05e4\u05d9\u05dd."],[167.0,"pulling 0\u05d8\u05d55: \u05d4\u05d7\u05ea\u05d9\u05db\u05d4 \u05e9\u05e0\u05d7\u05ea\u05db\u05d4 \u05e2\u05d5\u05dc\u05d4 \u05d7\u05d6\u05e8\u05d4 \u05e2\u05dd \u05d4\u05e1\u05db\u05d9\u05df \u05d5\u05e0\u05d5\u05e4\u05dc\u05ea \u05e2\u05dc \u05d4\u05dc\u05d5\u05d7."],[173.0,"\u05d5\u05db\u05dc\u05d9 \u05e9\u05d1\u05d5\u05e8, \u05d1\u05e2\u05d9\u05e7\u05e8 \u05d1\u05e7\u05d3\u05d7\u05d9\u05dd \u05e7\u05d8\u05e0\u05d9\u05dd \u05d1\u05e4\u05d7 \u05e2\u05d1\u05d4."],[177.0,"\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8 \u05e0\u05d9\u05e7\u05d5\u05d1?"],[179.0,"\u05db\u05dc\u05d9\u05dd: \u05db\u05dc\u05d9 \u05e1\u05d8\u05e0\u05d3\u05e8\u05d8\u05d9\u05d6\u05d5\u05dc, \u05d0\u05d1\u05dc \u05e6\u05d5\u05e8\u05d4 \u05de\u05d9\u05d5\u05d7\u05d3\u05ea \u05d3\u05d5\u05e8\u05e9\u05d5\u05ea \u05db\u05dc\u05d9 \u05de\u05d9\u05d5\u05d7\u05d3."],[184.0,"\u05d6\u05de\u05df \u05d4\u05db\u05e0\u05d4 \u05d5\u05d4\u05d7\u05dc\u05e4\u05ea \u05db\u05dc\u05d9\u05dd."],[187.0,"nibbling \u05e9\u05dc \u05e6\u05d5\u05e8\u05d5\u05ea \u05d2\u05d3\u05d5\u05dc\u05d5\u05ea, \u05e9\u05dc\u05d5\u05e7\u05d7 \u05d4\u05e8\u05d1\u05d4 \u05de\u05db\u05d5\u05ea."],[191.0,"\u05d5\u05d4\u05e1\u05e8\u05ea \u05d2\u05e8\u05d3, \u05d5\u05e2\u05d9\u05e6\u05d5\u05d1\u05d9\u05dd \u05e9\u05d3\u05d5\u05e8\u05e9\u05d9\u05dd \u05db\u05dc\u05d9\u05dd \u05d9\u05d9\u05e2\u05d5\u05d3\u05d9\u05d9\u05dd."],[195.0,"\u05d0\u05d6 \u05de\u05ea\u05d9 \u05e0\u05d9\u05e7\u05d5\u05d1 \u05d5\u05de\u05ea\u05d9 \u05dc\u05d9\u05d9\u05d6\u05e8?"],[198.0,"\u05e0\u05d9\u05e7\u05d5\u05d1 \u05de\u05ea\u05d0\u05d9\u05dd \u05dc\u05d4\u05e8\u05d1\u05d4 \u05e7\u05d3\u05d7\u05d9\u05dd \u05d6\u05d4\u05d9\u05dd, \u05dc\u05e1\u05d3\u05e8\u05d5\u05ea, \u05d5\u05dc\u05d7\u05dc\u05e7\u05d9\u05dd \u05e9\u05e6\u05e8\u05d9\u05db\u05d9\u05dd \u05e2\u05d9\u05e6\u05d5\u05d1."],[204.0,"\u05dc\u05d9\u05d9\u05d6\u05e8 \u05de\u05ea\u05d0\u05d9\u05dd \u05dc\u05e6\u05d5\u05e8\u05d5\u05ea \u05de\u05d5\u05e8\u05db\u05d1\u05d5\u05ea \u05d5\u05dc\u05d0\u05d1\u05d8\u05d9\u05e4\u05d5\u05e1\u05d9\u05dd, \u05d1\u05dc\u05d9 \u05db\u05dc\u05d9\u05dd."],[208.0,"\u05d5\u05d9\u05e9 \u05de\u05db\u05d5\u05e0\u05d5\u05ea \u05de\u05e9\u05d5\u05dc\u05d1\u05d5\u05ea, \u05e9\u05de\u05e0\u05e7\u05d1\u05d5\u05ea \u05d5\u05d7\u05d5\u05ea\u05db\u05d5\u05ea \u05d1\u05dc\u05d9\u05d9\u05d6\u05e8 \u05d1\u05d0\u05d5\u05ea\u05d4 \u05ea\u05e4\u05d9\u05e1\u05d4."],[213.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0: \u05db\u05d9\u05e4\u05d5\u05e3."]]};
window.MH_TR["\u05e4\u05e8\u05e713_\u05db\u05d9\u05e4\u05d5\u05e3"]={"t":"\u05db\u05d9\u05e4\u05d5\u05e3","l":[[1.0,"\u05db\u05de\u05e2\u05d8 \u05d1\u05db\u05dc \u05d7\u05dc\u05e7 \u05de\u05e4\u05d7 \u05d9\u05e9 \u05db\u05d9\u05e4\u05d5\u05e4\u05d9\u05dd."],[4.0,"\u05de\u05ea\u05db\u05d5\u05e4\u05e3 \u05d1\u05d9\u05d3, \u05d0\u05d1\u05dc \u05d0\u05d7\u05e8\u05d9 \u05db\u05d9\u05e4\u05d5\u05e3 \u05d0\u05d7\u05d3 \u05d4\u05d5\u05d0 \u05db\u05d1\u05e8 \u05d4\u05e8\u05d1\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05e7\u05e9\u05d9\u05d7."],[14.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d6\u05d4 \u05e0\u05db\u05d9\u05e8 \u05d0\u05ea \u05de\u05db\u05d1\u05e9\u05d5 \u05d4\u05db\u05d9\u05e4\u05d5\u05e3, \u05d0\u05d9\u05da \u05de\u05d2\u05d9\u05e2\u05d9\u05dd \u05dc\u05d6\u05d5\u05d5\u05d9\u05ea \u05de\u05d3\u05d5\u05d9\u05e7\u05ea, \u05d5\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8 \u05db\u05d9\u05e4\u05d5\u05e3."],[21.0,"\u05d1\u05de\u05db\u05d1\u05e9 \u05db\u05d9\u05e4\u05d5\u05e3 \u05d9\u05e9 \u05e1\u05db\u05d9\u05df \u05de\u05dc\u05de\u05e2\u05dc\u05d4, \u05d5\u05de\u05d8\u05e8\u05d9\u05e6\u05d4 \u05d1\u05e6\u05d5\u05e8\u05ea V \u05de\u05dc\u05de\u05d8\u05d4."],[27.0,"\u05d4\u05e9\u05d9\u05d8\u05d4 \u05d4\u05e0\u05e4\u05d5\u05e6\u05d4 \u05d4\u05d9\u05d0 bending \u05d6\u05d54: \u05d4\u05e1\u05db\u05d9\u05df \u05d3\u05d5\u05d7\u05e4\u05ea \u05d0\u05ea \u05d4\u05e4\u05d7 \u05dc\u05ea\u05d5\u05da \u05d4-), \u05d1\u05dc\u05d9 \u05dc\u05dc\u05d7\u05d5\u05e5 \u05d0\u05d5\u05ea\u05d5 \u05e2\u05d3 \u05d4\u05ea\u05d7\u05ea\u05d9\u05ea."],[34.0,"\u05d4\u05d6\u05d5\u05d5\u05d9\u05ea \u05e0\u05e7\u05d1\u05e2\u05ea \u05dc\u05e4\u05d9 \u05d4\u05e2\u05d5\u05de\u05e7 \u05e9\u05d4\u05e1\u05db\u05d9\u05df \u05d9\u05d5\u05e8\u05d3\u05ea, \u05d5\u05dc\u05db\u05df \u05e2\u05dd \u05d0\u05d5\u05ea\u05d4 \u05de\u05d8\u05e8\u05d9\u05e6\u05d4 \u05d0\u05e4\u05e9\u05e8 \u05dc\u05e7\u05d1\u05dc \u05d4\u05e8\u05d1\u05d4 \u05d6\u05d5\u05d5\u05d9\u05d5\u05ea."],[42.0,"\u05d4\u05de\u05d8\u05e8\u05d9\u05e6\u05d4. \u05d4\u05d6\u05d5\u05d5\u05d9\u05ea \u05de\u05d3\u05d5\u05d9\u05e7\u05ea \u05d9\u05d5\u05ea\u05e8, \u05d0\u05d1\u05dc \u05e6\u05e8\u05d9\u05da \u05d4\u05e8\u05d1\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05db\u05d5\u05d7."],[50.0,"\u05de\u05d0\u05d7\u05d5\u05e8\u05d9 \u05d4\u05e4\u05d7 \u05d9\u05e9 \u2026, \u05de\u05e2\u05e6\u05d5\u05e8 \u05e9\u05d6\u05d6 \u05d0\u05d5\u05d8\u05d5\u05de\u05d8\u05d9\u05ea \u05d5\u05e7\u05d5\u05d1\u05e2 \u05d0\u05d9\u05e4\u05d4 \u05d9\u05d4\u05d9\u05d4 \u05e7\u05d5 \u05d4\u05db\u05d9\u05e4\u05d5\u05e3."],[58.0,"\u05db\u05dc\u05dc \u05d0\u05e6\u05d1\u05e2: \u05e4\u05ea\u05d7 V-N \u05d4\u05d5\u05d0 \u05d1\u05e2\u05e8\u05da \u05e4\u05d9 8 \u05de\u05e2\u05d5\u05d1\u05d9 \u05d4\u05e4\u05d7."],[62.0,"\u2026 \u05d6\u05d52, \u05d4\u05e8\u05d3\u05d9\u05d5\u05e1 \u05d4\u05e4\u05e0\u05d9\u05de\u05d9 \u05e0\u05e7\u05d1\u05e2 \u05d1\u05e2\u05d9\u05e7\u05e8 \u05dc\u05e4\u05d9 \u05e4\u05ea\u05d7 \u05d4- \u05e5, \u05d5\u05dc\u05d0 \u05dc\u05e4\u05d9 \u05d4\u05e1\u05db\u05d9\u05df."],[68.0,"\u05db\u05db\u05dc \u05e9\u05d4\u05e4\u05d7 \u05e2\u05d1\u05d4 \u05d9\u05d5\u05ea\u05e8, \u05d4\u05db\u05d5\u05d7 \u05d2\u05d3\u05dc \u05de\u05d4\u05e8 \u05de\u05d0\u05d5\u05d3, \u05d5\u05db\u05db\u05dc \u05e9\u05d4-\\ \u05e8\u05d7\u05d1 \u05d9\u05d5\u05ea\u05e8, \u05d4\u05db\u05d5\u05d7 \u05e7\u05d8\u05df."],[76.0,"\u05dc\u05db\u05df \u05dc\u05e4\u05d7 \u05e2\u05d1\u05d4 \u05d1\u05d5\u05d7\u05e8\u05d9\u05dd \u05e5\\ \u05e8\u05d7\u05d1, \u05d5\u05de\u05e7\u05d1\u05dc\u05d9\u05dd \u05e8\u05d3\u05d9\u05d5\u05e1 \u05d2\u05d3\u05d5\u05dc \u05d9\u05d5\u05ea\u05e8."],[82.0,"\u05d0\u05d7\u05e8\u05d9 \u05e9\u05d4\u05e1\u05db\u05d9\u05df \u05e2\u05d5\u05dc\u05d4, \u05d4\u05e4\u05d7 \u05e7\u05d5\u05e4\u05e5 \u05de\u05e2\u05d8 \u05d7\u05d6\u05e8\u05d4."],[86.0,"\u05d1\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05d5\u05d1\u05e0\u05d9\u05e8\u05d5\u05e1\u05d8\u05d4 \u05d4\u05e7\u05e4\u05d9\u05e6\u05d4 \u05d2\u05d3\u05d5\u05dc\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05de\u05d0\u05e9\u05e8 \u05d1\u05e4\u05dc\u05d3\u05d4 \u05e8\u05d2\u05d9\u05dc\u05d4."],[91.0,"CNC \u05d4\u05de\u05db\u05d5\u05e0\u05d4 \u05de\u05ea\u05e7\u05e0\u05ea \u05d0\u05ea \u05d6\u05d4 \u05dc\u05d1\u05d3, \u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d2\u05dd \u05de\u05d5\u05d3\u05d3\u05ea \u05d0\u05ea \u05d4\u05d6\u05d5\u05d5\u05d9\u05ea \u05ea\u05d5\u05da \u05db\u05d3\u05d9."],[101.0,"\u05d4\u05d0\u05d5\u05d2\u05df \u05d7\u05d9\u05d9\u05d1 \u05dc\u05d4\u05d9\u05d5\u05ea \u05d0\u05e8\u05d5\u05da \u05de\u05e1\u05e4\u05d9\u05e7 \u05db\u05d3\u05d9 \u05dc\u05d4\u05d9\u05e9\u05e2\u05df \u05e2\u05dc \u05e9\u05ea\u05d9 \u05d4\u05e9\u05e4\u05d5\u05ea \u05e9\u05dc \u05d4-\u05e5."],[106.0,"\u05db\u05db\u05dc \u05e9\u05d4-\u05e5 \u05e8\u05d7\u05d1 \u05d9\u05d5\u05ea\u05e8, \u05d4\u05d0\u05d5\u05d2\u05df \u05d4\u05de\u05d9\u05e0\u05d9\u05de\u05dc\u05d9 \u05d0\u05e8\u05d5\u05da \u05d9\u05d5\u05ea\u05e8."],[111.0,"\u05d1\u05d7\u05dc\u05e7 \u05e2\u05dd \u05db\u05de\u05d4 \u05db\u05d9\u05e4\u05d5\u05e4\u05d9\u05dd, \u05d4\u05e1\u05d3\u05e8 \u05d7\u05e9\u05d5\u05d1: \u05db\u05d9\u05e4\u05d5\u05e3 \u05de\u05d5\u05e7\u05d3\u05dd \u05e2\u05dc\u05d5\u05dc \u05dc\u05d4\u05ea\u05e0\u05d2\u05e9 \u05d1\u05e1\u05db\u05d9\u05df \u05d0\u05d5 \u05d1\u05de\u05db\u05d5\u05e0\u05d4 \u05d1\u05db\u05d9\u05e4\u05d5\u05e3 \u05d4\u05d1\u05d0."],[119.0,"\u05dc\u05e7\u05d5\u05e4\u05e1\u05d0\u05d5\u05ea \u05d5\u05dc\u05ea\u05e2\u05dc\u05d5\u05ea \u05e2\u05de\u05d5\u05e7\u05d5\u05ea \u05de\u05e9\u05d5\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05e1\u05db\u05d9\u05df 60 \u05e2\u05d9\u05e9 \u05d1\u05d4 \u05de\u05e7\u05d5\u05dd \u05dc\u05d0\u05d5\u05d2\u05df."],[125.0,"\u05d5\u05d1\u05e7\u05d5\u05e4\u05e1\u05d0\u05d5\u05ea \u05d5\u05d1\u05e4\u05d0\u05e0\u05dc\u05d9\u05dd \u05d1\u05db\u05de\u05d5\u05d9\u05d5\u05ea, \u05d9\u05e9 \u05de\u05db\u05d5\u05e0\u05d5\u05ea panel \u2026, \u05e9\u05de\u05db\u05d5\u05e4\u05e4\u05d5\u05ea \u05d0\u05ea \u05db\u05dc \u05d4\u05e6\u05d3\u05d3\u05d9\u05dd \u05d1\u05d0\u05d5\u05d8\u05d5\u05de\u05e6\u05d9\u05d4."],[133.0,"\u05db\u05de\u05d5 \u05e9\u05e8\u05d0\u05d9\u05e0\u05d5 \u05d1\u05e4\u05e8\u05e7 11, \u05d0\u05d5\u05e8\u05da \u05d4\u05e4\u05e8\u05d9\u05e1\u05d4 \u05e7\u05e6\u05e8 \u05de\u05e1\u05db\u05d5\u05dd \u05d4\u05de\u05d9\u05d3\u05d5\u05ea \u05d4\u05d7\u05d9\u05e6\u05d5\u05e0\u05d9\u05d5\u05ea."],[138.0,"\u05ea\u05d5\u05db\u05e0\u05ea \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05de\u05d7\u05e9\u05d1\u05ea \u05d0\u05d5\u05ea\u05d5 \u05dc\u05e4\u05d9 \u05de\u05e7\u05d3\u05dd \u05d0, \u05d5\u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05d7\u05dc\u05e7 \u05e8\u05d0\u05e9\u05d5\u05df \u05d5\u05de\u05ea\u05e7\u05e0\u05d9\u05dd."],[145.0,"\u05d2\u05dd \u05d1\u05db\u05d9\u05e4\u05d5\u05e3 \u05d9\u05e9 \u05d1\u05e2\u05d9\u05d5\u05ea \u05d0\u05d5\u05e4\u05d9\u05d9\u05e0\u05d9\u05d5\u05ea."],[147.0,"\u05e1\u05d3\u05e7 \u05d1\u05e6\u05d3 \u05d4\u05d7\u05d9\u05e6\u05d5\u05e0\u05d9, \u05db\u05e9\u05d4\u05e8\u05d3\u05d9\u05d5\u05e1 \u05e7\u05d8\u05df \u05de\u05d3\u05d9, \u05d0\u05d5 \u05db\u05e9\u05e7\u05d5 \u05d4\u05db\u05d9\u05e4\u05d5\u05e3 \u05de\u05e7\u05d1\u05d9\u05dc \u05dc\u05db\u05d9\u05d5\u05d5\u05df \u05d4\u05d2\u05dc\u05d2\u05d5\u05dc."],[154.0,"\u05d6\u05d5\u05d5\u05d9\u05ea \u05e9\u05de\u05e9\u05ea\u05e0\u05d4 \u05dc\u05d0\u05d5\u05e8\u05da \u05d4\u05db\u05d9\u05e4\u05d5\u05e3, \u05db\u05d9 \u05d4\u05de\u05db\u05d5\u05e0\u05d4 \u05de\u05ea\u05db\u05d5\u05e4\u05e4\u05ea \u05d1\u05d0\u05de\u05e6\u05e2. \u05d6\u05d4 \u05de\u05ea\u05d5\u05e7\u05df \u2026."],[161.0,"\u05e1\u05d9\u05de\u05e0\u05d9\u05dd \u05e9\u05dc \u05d4\u05de\u05d8\u05e8\u05d9\u05e6\u05d4 \u05e2\u05dc \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7. \u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05e0\u05e8\u05d0\u05d9\u05dd \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05e0\u05d9\u05d9\u05dc\u05d5\u05df \u05de\u05d2\u05df \u05d0\u05d5 \u05d1\u05de\u05d8\u05e8\u05d9\u05e6\u05d4 \u05de\u05d9\u05d5\u05d7\u05d3\u05ea."],[168.0,"\u05d5\u05e7\u05d3\u05d7 \u05e7\u05e8\u05d5\u05d1 \u05dc\u05e7\u05d5 \u05d4\u05db\u05d9\u05e4\u05d5\u05e3, \u05e9\u05de\u05ea\u05e2\u05d5\u05d5\u05ea."],[172.0,"\u05d6\u05d5\u05d5\u05d9\u05ea \u05db\u05d9\u05e4\u05d5\u05e3 \u05de\u05d2\u05d9\u05e2\u05d4 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05dc\u05d3\u05d9\u05d5\u05e7 \u05e9\u05dc \u05d7\u05e6\u05d9 \u05de\u05e2\u05dc\u05d4 \u05e2\u05d3 \u05de\u05e2\u05dc\u05d4."],[177.0,"\u05de\u05d9\u05d3\u05d4 \u05d1\u05d9\u05df \u05e9\u05e0\u05d9 \u05db\u05d9\u05e4\u05d5\u05e4\u05d9\u05dd \u05e4\u05d7\u05d5\u05ea \u05de\u05d3\u05d5\u05d9\u05e7\u05ea \u05de\u05de\u05d9\u05d3\u05d4 \u05e9\u05dc \u05d7\u05d9\u05ea\u05d5\u05da \u05d1\u05dc\u05d9\u05d9\u05d6\u05e8."],[181.0,"\u05d5\u05de\u05d9\u05d3\u05d4 \u05e9\u05e2\u05d5\u05d1\u05e8\u05ea \u05d3\u05e8\u05da \u05db\u05de\u05d4 \u05db\u05d9\u05e4\u05d5\u05e4\u05d9\u05dd \u05de\u05e6\u05d8\u05d1\u05e8\u05ea, \u05d5\u05dc\u05db\u05df \u05db\u05d3\u05d0\u05d9 \u05dc\u05de\u05d3\u05d5\u05d3 \u05de\u05d0\u05d5\u05ea\u05d5 \u05e6\u05d3, \u05d5\u05dc\u05d0 \u05dc\u05d3\u05e8\u05d5\u05e9 \u05d3\u05d9\u05d5\u05e7 \u05e9\u05dc \u05e2\u05d9\u05d1\u05d5\u05d3 \u05e9\u05d1\u05d1\u05d9."],[190.0,"\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8 \u05db\u05d9\u05e4\u05d5\u05e3?"],[192.0,"\u05de\u05e1\u05e4\u05e8 \u05d4\u05db\u05d9\u05e4\u05d5\u05e4\u05d9\u05dd: \u05db\u05dc \u05db\u05d9\u05e4\u05d5\u05e3 \u05d4\u05d5\u05d0 \u05e2\u05d5\u05d3 \u05e4\u05e2\u05d5\u05dc\u05d4."],[196.0,"\u05d4\u05d7\u05dc\u05e4\u05ea \u05db\u05dc\u05d9\u05dd, \u05d5\u05e8\u05e6\u05e3 \u05db\u05d9\u05e4\u05d5\u05e4\u05d9\u05dd \u05de\u05e1\u05d5\u05d1\u05da."],[199.0,"\u05d0\u05d5\u05d2\u05e0\u05d9\u05dd \u05d2\u05d1\u05d5\u05d4\u05d9\u05dd \u05d5\u05e7\u05d5\u05e4\u05e1\u05d0\u05d5\u05ea \u05e2\u05de\u05d5\u05e7\u05d5\u05ea, \u05e9\u05d3\u05d5\u05e8\u05e9\u05d5\u05d9\u05dd \u05db\u05dc\u05d9\u05dd \u05de\u05d9\u05d5\u05d7\u05d3\u05d9\u05dd."],[204.0,"\u05d8\u05d5\u05dc\u05e8\u05e0\u05e1\u05d9\u05dd \u05d4\u05d3\u05d5\u05e7\u05d9\u05dd, \u05d5\u05d1\u05d3\u05d9\u05e7\u05d5\u05ea."],[207.0,"\u05d5\u05dc\u05d5\u05d7\u05d5\u05ea \u05d2\u05d3\u05d5\u05dc\u05d9\u05dd, \u05e9\u05e6\u05e8\u05d9\u05db\u05d9\u05dd \u05e9\u05e0\u05d9 \u05de\u05e4\u05e2\u05d9\u05dc\u05d9\u05dd."],[210.0,"\u05db\u05d9\u05e4\u05d5\u05e3 \u05d4\u05d5\u05e4\u05da \u05e4\u05d7 \u05e9\u05d8\u05d5\u05d7 \u05dc\u05d7\u05dc\u05e7 \u05e7\u05e9\u05d9\u05d7, \u05d1\u05d6\u05d5\u05d5\u05d9\u05ea \u05d5\u05d1\u05e6\u05d5\u05e8\u05d4 \u05d4\u05e0\u05d3\u05e8\u05e9\u05d5\u05ea."],[216.0,"\u05d4\u05ea\u05db\u05e0\u05d5\u05df \u05d4\u05e0\u05db\u05d5\u05df, \u05e8\u05d3\u05d9\u05d5\u05e1 \u05d0\u05d7\u05d9\u05d3, \u05d0\u05d5\u05d2\u05e0\u05d9\u05dd \u05de\u05e1\u05e4\u05d9\u05e7\u05d9\u05dd \u05d5\u05e8\u05e6\u05e3 \u05d0\u05e4\u05e9\u05e8\u05d9 \u05d7\u05d5\u05e1\u05da \u05d0\u05ea \u05e8\u05d5\u05d1 \u05d4\u05d1\u05e2\u05d9\u05d5\u05ea."],[223.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0: \u05e2\u05e8\u05d2\u05d5\u05dc."]]};
window.MH_TR["\u05e4\u05e8\u05e714_\u05e2\u05e8\u05d2\u05d5\u05dc"]={"t":"\u05e2\u05e8\u05d2\u05d5\u05dc","l":[[1.0,"\u05de\u05db\u05dc\u05d9\u05dd, \u05e6\u05d9\u05e0\u05d5\u05e8\u05d5\u05ea \u05d2\u05d3\u05d5\u05dc\u05d9\u05dd, \u05d8\u05d1\u05e2\u05d5\u05ea \u05d5\u05e7\u05d5\u05e0\u05d5\u05e1\u05d9\u05dd \u05de\u05ea\u05d7\u05d9\u05dc\u05d9\u05dd \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05db\u05dc\u05d5\u05d7 \u05e9\u05d8\u05d5\u05d7."],[7.0,"\u05d1\u05e2\u05e8\u05d2\u05d5\u05dc, \u05d4\u05dc\u05d5\u05d7 \u05e2\u05d5\u05d1\u05e8 \u05d1\u05d9\u05df \u05d2\u05dc\u05d9\u05dc\u05d9\u05dd, \u05d5\u05de\u05ea\u05e2\u05e7\u05dd \u05d1\u05d4\u05d3\u05e8\u05d2\u05d4 \u05e2\u05d3 \u05e9\u05d4\u05d5\u05d0 \u05e0\u05e1\u05d2\u05e8 \u05dc\u05d2\u05dc\u05d9\u05dc."],[14.0,"\u05d1\u05de\u05db\u05d5\u05e0\u05ea \u05e2\u05e8\u05d2\u05d5\u05dc \u05e2\u05dd \u05e9\u05dc\u05d5\u05e9\u05d4 \u05d2\u05dc\u05d9\u05dc\u05d9\u05dd \u05d9\u05e9 \u05d2\u05dc\u05d9\u05dc \u05e2\u05dc\u05d9\u05d5\u05df \u05d5\u05e9\u05e0\u05d9 \u05d2\u05dc\u05d9\u05dc\u05d9\u05dd \u05ea\u05d7\u05ea\u05d5\u05e0\u05d9\u05dd."],[20.0,"\u05d4\u05dc\u05d5\u05d7 \u05e2\u05d5\u05d1\u05e8 \u05d1\u05d9\u05e0\u05d9\u05d4\u05dd, \u05d5\u05d1\u05db\u05dc \u05de\u05e2\u05d1\u05e8 \u05de\u05d5\u05e8\u05d9\u05d3\u05d9\u05dd \u05de\u05e2\u05d8 \u05d0\u05ea \u05d4\u05d2\u05dc\u05d9\u05dc \u05d4\u05e2\u05dc\u05d9\u05d5\u05df, \u05d5\u05d4\u05e7\u05d5\u05d8\u05e8 \u05e7\u05d8\u05df."],[26.0,"\u05d1\u05de\u05db\u05d5\u05e0\u05d4 \u05e2\u05dd \u05d0\u05e8\u05d1\u05e2\u05d4 \u05d2\u05dc\u05d9\u05dc\u05d9\u05dd, \u05d2\u05dc\u05d9\u05dc \u05e0\u05d5\u05e1\u05e3 \u05de\u05d7\u05d6\u05d9\u05e7 \u05d0\u05ea \u05d4\u05dc\u05d5\u05d7, \u05d5\u05d4\u05e2\u05d1\u05d5\u05d3\u05d4 \u05de\u05d4\u05d9\u05e8\u05d4 \u05d5\u05de\u05d3\u05d5\u05d9\u05e7\u05ea \u05d9\u05d5\u05ea\u05e8."],[33.0,"\u05d1\u05de\u05db\u05d5\u05e0\u05d4 \u05e2\u05dd \u05e9\u05dc\u05d5\u05e9\u05d4 \u05d2\u05dc\u05d9\u05dc\u05d9\u05dd, \u05d4\u05e7\u05e6\u05d5\u05d5\u05ea \u05e9\u05dc \u05d4\u05dc\u05d5\u05d7 \u05e0\u05e9\u05d0\u05e8\u05d9\u05dd \u05d9\u05e9\u05e8\u05d9\u05dd, \u05db\u05d9 \u05d4\u05dd \u05dc\u05d0 \u05e2\u05d5\u05d1\u05e8\u05d9\u05dd \u05d1\u05d9\u05df \u05db\u05dc \u05d4\u05d2\u05dc\u05d9\u05dc\u05d9\u05dd."],[40.0,"\u05dc\u05db\u05df \u05de\u05db\u05d5\u05e4\u05e4\u05d9\u05dd \u05d0\u05ea \u05d4\u05e7\u05e6\u05d5\u05d5\u05ea \u05de\u05e8\u05d0\u05e9, \u05d1\u05de\u05db\u05d1\u05e9 \u05db\u05d9\u05e4\u05d5\u05e3 \u05d0\u05d5 \u05d1\u05de\u05db\u05d5\u05e0\u05d4 \u05e2\u05dd \u05d0\u05e8\u05d1\u05e2\u05d4 \u05d2\u05dc\u05d9\u05dc\u05d9\u05dd."],[46.0,"\u05d1\u05dc\u05d9 \u05d6\u05d4, \u05d0\u05d7\u05e8\u05d9 \u05d4\u05e8\u05d9\u05ea\u05d5\u05da \u05e0\u05e9\u05d0\u05e8 \u05e4\u05e1 \u05d9\u05e9\u05e8 \u05dc\u05d0\u05d5\u05e8\u05da \u05d4\u05ea\u05e4\u05e8, \u05d5\u05d4\u05d2\u05dc\u05d9\u05dc \u05dc\u05d0 \u05e2\u05d2\u05d5\u05dc."],[53.0,"\u05db\u05d3\u05d9 \u05dc\u05e2\u05e8\u05d2\u05dc \u05e7\u05d5\u05e0\u05d5\u05e1, \u05d4\u05e4\u05e8\u05d9\u05e1\u05d4 \u05d4\u05d9\u05d0 \u05e7\u05e9\u05ea \u05d5\u05dc\u05d0 \u05de\u05dc\u05d1\u05df, \u05d5\u05d4\u05d2\u05dc\u05d9\u05dc\u05d9\u05dd \u05de\u05d5\u05d8\u05d9\u05dd \u05d6\u05d4 \u05d1\u05d9\u05d7\u05e1 \u05dc\u05d6\u05d4."],[59.0,"\u05d6\u05d4 \u05d3\u05d5\u05e8\u05e9 \u05d9\u05d5\u05ea\u05e8 \u05e0\u05d9\u05e1\u05d9\u05d5\u05df, \u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05de\u05db\u05d5\u05e0\u05d4 \u05de\u05d9\u05d5\u05d7\u05d3\u05ea."],[64.0,"\u05d2\u05dd \u05db\u05d0\u05df \u05d4\u05e4\u05d7 \u05e7\u05d5\u05e4\u05e5 \u05d7\u05d6\u05e8\u05d4, \u05d5\u05dc\u05db\u05df \u05de\u05e2\u05e8\u05d2\u05dc\u05d9\u05dd \u05d1\u05d4\u05d3\u05e8\u05d2\u05d4 \u05d5\u05d1\u05d5\u05d3\u05e7\u05d9\u05dd."],[70.0,"\u05d0\u05ea \u05d4\u05e7\u05d5\u05d8\u05e8 \u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05d1\u05e9\u05d1\u05dc\u05d5\u05e0\u05d4, \u05d0\u05d5 \u05d1\u05de\u05d3\u05d9\u05d3\u05d4 \u05e9\u05dc \u05d4\u05d4\u05d9\u05e7\u05e3."],[74.0,"\u05d1\u05e1\u05d5\u05e3 \u05de\u05e8\u05ea\u05db\u05d9\u05dd \u05d0\u05ea \u05d4\u05ea\u05e4\u05e8 \u05dc\u05d0\u05d5\u05e8\u05da \u05d4\u05d2\u05dc\u05d9\u05dc."],[77.0,"\u05d4\u05e8\u05d9\u05ea\u05d5\u05da \u05de\u05e2\u05d5\u05d5\u05ea \u05de\u05e2\u05d8, \u05d5\u05dc\u05db\u05df \u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05de\u05e2\u05e8\u05d2\u05dc\u05d9\u05dd \u05e9\u05d5\u05d1 \u05d0\u05d7\u05e8\u05d9 \u05d4\u05e8\u05d9\u05ea\u05d5\u05da, \u05db\u05d3\u05d9 \u05dc\u05d4\u05d7\u05d6\u05d9\u05e8 \u05d0\u05ea \u05d4\u05e2\u05d2\u05d9\u05dc\u05d5\u05ea."],[84.0,"\u05d4\u05e7\u05d5\u05d8\u05e8 \u05d4\u05de\u05d9\u05e0\u05d9\u05de\u05dc\u05d9 \u05ea\u05dc\u05d5\u05d9 \u05d1\u05e7\u05d5\u05d8\u05e8 \u05d4\u05d2\u05dc\u05d9\u05dc \u05d4\u05e2\u05dc\u05d9\u05d5\u05df \u05d5\u05d1\u05e2\u05d5\u05d1\u05d9 \u05d4\u05dc\u05d5\u05d7."],[89.0,"\u05dc\u05d5\u05d7\u05d5\u05ea \u05e2\u05d1\u05d9\u05dd \u05d5\u05e8\u05d7\u05d1\u05d9\u05dd \u05d3\u05d5\u05e8\u05e9\u05d9\u05dd \u05de\u05db\u05d5\u05e0\u05d4 \u05d2\u05d3\u05d5\u05dc\u05d4 \u05d5\u05d7\u05d6\u05e7\u05d4 \u05de\u05d0\u05d5\u05d3."],[93.0,"\u05d5\u05d7\u05d5\u05de\u05e8\u05d9\u05dd \u05e7\u05e9\u05d9\u05dd \u05e7\u05d5\u05e4\u05e6\u05d9\u05dd \u05d7\u05d6\u05e8\u05d4 \u05d9\u05d5\u05ea\u05e8, \u05d5\u05e7\u05e9\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05dc\u05e7\u05d1\u05dc \u05d0\u05d9\u05ea\u05dd \u05e7\u05d5\u05d8\u05e8 \u05de\u05d3\u05d5\u05d9\u05e7."],[99.0,"\u05d2\u05dd \u05d1\u05e2\u05e8\u05d2\u05d5\u05dc \u05d9\u05e9 \u05d1\u05e2\u05d9\u05d5\u05ea \u05d0\u05d5\u05e4\u05d9\u05d9\u05e0\u05d9\u05d5\u05ea."],[102.0,"\u05e7\u05e6\u05d5\u05d5\u05ea \u05d9\u05e9\u05e8\u05d9\u05dd, \u05db\u05e9\u05dc\u05d0 \u05de\u05db\u05d5\u05e4\u05e4\u05d9\u05dd \u05d0\u05d5\u05ea\u05dd \u05de\u05e8\u05d0\u05e9."],[106.0,"\u05d2\u05dc\u05d9\u05dc \u05d1\u05e6\u05d5\u05e8\u05ea \u05d7\u05d1\u05d9\u05ea \u05d0\u05d5 \u05de\u05d5\u05ea\u05df, \u05db\u05e9\u05d4\u05d2\u05dc\u05d9\u05dc\u05d9\u05dd \u05de\u05ea\u05db\u05d5\u05e4\u05e4\u05d9\u05dd \u05d1\u05d0\u05de\u05e6\u05e2."],[110.0,"\u05d0\u05d5\u05d1\u05dc\u05d9\u05d5\u05ea, \u05db\u05e9\u05d4\u05e7\u05d5\u05d8\u05e8 \u05dc\u05d0 \u05d0\u05d7\u05d9\u05d3 \u05e1\u05d1\u05d9\u05d1 \u05d4\u05d4\u05d9\u05e7\u05e3."],[114.0,"\u05d5\u05e7\u05e6\u05d5\u05d5\u05ea \u05e9\u05dc\u05d0 \u05e0\u05e4\u05d2\u05e9\u05d9\u05dd \u05d1\u05d3\u05d9\u05d5\u05e7 \u05d1\u05ea\u05e4\u05e8."],[118.0,"\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8 \u05e2\u05e8\u05d2\u05d5\u05dc?"],[119.0,"\u05e2\u05d5\u05d1\u05d9 \u05d5\u05e8\u05d5\u05d7\u05d1 \u05d4\u05dc\u05d5\u05d7, \u05e9\u05e7\u05d5\u05d1\u05e2\u05d9\u05dd \u05d0\u05d9\u05d6\u05d5 \u05de\u05db\u05d5\u05e0\u05d4 \u05e6\u05e8\u05d9\u05da."],[123.0,"\u05db\u05d9\u05e4\u05d5\u05e3 \u05de\u05d5\u05e7\u05d3\u05dd \u05e9\u05dc \u05d4\u05e7\u05e6\u05d5\u05d5\u05ea, \u05d5\u05de\u05e1\u05e4\u05e8 \u05d4\u05de\u05e2\u05d1\u05e8\u05d9\u05dd."],[127.0,"\u05e8\u05d9\u05ea\u05d5\u05da \u05d4\u05ea\u05e4\u05e8, \u05d5\u05e2\u05e8\u05d2\u05d5\u05dc \u05d7\u05d5\u05d6\u05e8 \u05d0\u05d7\u05e8\u05d9\u05d5."],[130.0,"\u05d5\u05d1\u05d3\u05d9\u05e7\u05d5\u05ea \u05e2\u05d2\u05d9\u05dc\u05d5\u05ea \u05d5\u05e7\u05d5\u05d8\u05e8."],[133.0,"\u05e2\u05e8\u05d2\u05d5\u05dc \u05d4\u05d5\u05e4\u05da \u05dc\u05d5\u05d7 \u05e9\u05d8\u05d5\u05d7 \u05dc\u05d2\u05dc\u05d9\u05dc \u05d0\u05d5 \u05dc\u05e7\u05d5\u05e0\u05d5\u05e1, \u05d1\u05db\u05de\u05d4 \u05de\u05e2\u05d1\u05e8\u05d9\u05dd \u05d4\u05d3\u05e8\u05d2\u05ea\u05d9\u05d9\u05dd."],[139.0,"\u05db\u05d9\u05e4\u05d5\u05e3 \u05de\u05d5\u05e7\u05d3\u05dd \u05e9\u05dc \u05d4\u05e7\u05e6\u05d5\u05d5\u05ea \u05d5\u05e2\u05e8\u05d2\u05d5\u05dc \u05d0\u05d7\u05e8\u05d9 \u05d4\u05e8\u05d9\u05ea\u05d5\u05da \u05d4\u05dd \u05d4\u05de\u05e4\u05ea\u05d7 \u05dc\u05e2\u05d2\u05d9\u05dc\u05d5\u05ea \u05d8\u05d5\u05d1\u05d4."],[144.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0: \u05db\u05d1\u05d9\u05e9\u05d4 \u05d5\u05d4\u05d8\u05d1\u05e2\u05d4."]]};
window.MH_TR["\u05e4\u05e8\u05e715_\u05db\u05d1\u05d9\u05e9\u05d4_\u05d5\u05d4\u05d8\u05d1\u05e2\u05d4"]={"t":"\u05db\u05d1\u05d9\u05e9\u05d4 \u05d5\u05d4\u05d8\u05d1\u05e2\u05d4","l":[[1.0,"\u05d3\u05dc\u05ea\u05d5\u05ea \u05e9\u05dc \u05e8\u05db\u05d1, \u05e4\u05d7\u05d9\u05d5\u05ea, \u05db\u05d9\u05d5\u05e8\u05d9\u05dd, \u05ea\u05d5\u05e9\u05d1\u05d5\u05ea \u05d5\u05de\u05d2\u05e2\u05d9\u05dd \u05d7\u05e9\u05de\u05dc\u05d9\u05d9\u05dd."],[7.0,"\u05d0\u05ea \u05db\u05d5\u05dc\u05dd \u05de\u05d9\u05d9\u05e6\u05e8\u05d9\u05dd \u05d1\u05dc\u05db\u05d1\u05d9\u05e9\u05d4: \u05de\u05db\u05d1\u05e9\u05d5 \u05e1\u05d5\u05d2\u05e8 \u05ea\u05d1\u05e0\u05d9\u05ea \u05e2\u05dc \u05d4\u05e4\u05d7, \u05d5\u05ea\u05d5\u05da \u05e9\u05e0\u05d9\u05d9\u05d4 \u05d9\u05d5\u05e6\u05d0 \u05d7\u05dc\u05e7 \u05de\u05d5\u05db\u05df."],[13.0,"\u05db\u05d1\u05d9\u05e9\u05d4 \u05d4\u05d9\u05d0 \u05d4\u05e9\u05d9\u05d8\u05d4 \u05d4\u05d6\u05d5\u05dc\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05dc\u05d7\u05dc\u05e7 \u05de\u05e4\u05d7, \u05d0\u05d1\u05dc \u05e8\u05e7 \u05d1\u05db\u05de\u05d5\u05d9\u05d5\u05ea \u05d2\u05d3\u05d5\u05dc\u05d5\u05ea."],[19.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d6\u05d4 \u05e0\u05db\u05d9\u05e8 \u05d0\u05ea \u05d4\u05de\u05db\u05d1\u05e9\u05d9\u05dd, \u05d0\u05ea \u05d4\u05ea\u05d1\u05e0\u05d9\u05d5\u05ea, \u05d0\u05ea \u05d4\u05de\u05e9\u05d9\u05db\u05d4 \u05d4\u05e2\u05de\u05d5\u05e7\u05d4 \u05d5\u05d0\u05ea \u05d4\u05d4\u05d8\u05d1\u05e2\u05d4, \u05d5\u05e0\u05d1\u05d9\u05df \u05de\u05ea\u05d9 \u05d6\u05d4 \u05de\u05e9\u05ea\u05dc\u05dd."],[28.0,"\u05de\u05db\u05d1\u05e9 \u05de\u05db\u05e0\u05d9 \u05de\u05e0\u05d9\u05e2 \u05d0\u05ea \u05d4\u05db\u05dc\u05d9 \u05d1\u05e2\u05d6\u05e8\u05ea \u05d2\u05dc\u05d2\u05dc \u05ea\u05e0\u05d5\u05e4\u05d4. \u05d4\u05d5\u05d0 \u05de\u05d4\u05d9\u05e8 \u05de\u05d0\u05d5\u05d3, \u05d5\u05de\u05ea\u05d0\u05d9\u05dd \u05dc\u05d9\u05d9\u05e6\u05d5\u05e8 \u05d4\u05de\u05d5\u05e0\u05d9."],[35.0,"\u05de\u05db\u05d1\u05e9 \u05d4\u05d9\u05d3\u05e8\u05d0\u05d5\u05dc\u05d9 \u05d0\u05d9\u05d8\u05d9 \u05d9\u05d5\u05ea\u05e8, \u05d0\u05d1\u05dc \u05e0\u05d5\u05ea\u05df \u05d0\u05ea \u05de\u05dc\u05d5\u05d0 \u05d4\u05db\u05d5\u05d7 \u05dc\u05d0\u05d5\u05e8\u05da \u05db\u05dc \u05d4\u05de\u05d4\u05dc\u05da, \u05d5\u05dc\u05db\u05df \u05d4\u05d5\u05d0 \u05d8\u05d5\u05d1 \u05dc\u05de\u05e9\u05d9\u05db\u05d4 \u05e2\u05de\u05d5\u05e7\u05d4."],[43.0,"\u05de\u05db\u05d1\u05e9 \u05e1\u05e8\u05d5\u05d5 \u05de\u05d0\u05e4\u05e9\u05e8 \u05dc\u05ea\u05db\u05e0\u05ea \u05d0\u05ea \u05d4\u05ea\u05e0\u05d5\u05e2\u05d4: \u05de\u05d4\u05e8 \u05d1\u05d0\u05d5\u05d5\u05d9\u05e8, \u05d5\u05dc\u05d0\u05d8 \u05d1\u05d3\u05d9\u05d5\u05e7 \u05d1\u05e8\u05d2\u05e2 \u05e9\u05d4\u05db\u05dc\u05d9 \u05e4\u05d5\u05d2\u05e9 \u05d0\u05ea \u05d4\u05e4\u05d7."],[50.0,"\u05d2\u05d5\u05d3\u05dc \u05d4\u05de\u05db\u05d1\u05e9 \u05e0\u05de\u05d3\u05d3 \u05d1\u05d8\u05d5\u05e0\u05d5\u05ea, \u05dc\u05e4\u05d9 \u05d4\u05db\u05d5\u05d7 \u05d4\u05de\u05e7\u05e1\u05d9\u05de\u05dc\u05d9 \u05e9\u05d4\u05d5\u05d0 \u05de\u05e4\u05e2\u05d9\u05dc."],[56.0,"\u05d4\u05ea\u05d1\u05e0\u05d9\u05ea \u05d4\u05d9\u05d0 \u05d4\u05dc\u05d1 \u05e9\u05dc \u05d4\u05ea\u05d4\u05dc\u05d9\u05da."],[58.0,"\u05d9\u05e9 \u05d1\u05d4 \u05e1\u05db\u05d9\u05df \u05de\u05dc\u05de\u05e2\u05dc\u05d4 \u05d5\u05de\u05d8\u05e8\u05d9\u05e6\u05d4 \u05de\u05dc\u05de\u05d8\u05d4, \u05e2\u05dd \u05e2\u05de\u05d5\u05d3\u05d9 \u05d4\u05d5\u05d1\u05dc\u05d4 \u05e9\u05de\u05d9\u05d9\u05e9\u05e8\u05d9\u05dd \u05d1\u05d9\u05e0\u05d9\u05d4\u05df \u05d1\u05d3\u05d9\u05d5\u05e7."],[65.0,"\u05dc\u05d5\u05d7\u05d9\u05ea \u05de\u05e4\u05e9\u05d5\u05d8\u05ea \u05de\u05d7\u05d6\u05d9\u05e7\u05d4 \u05d0\u05ea \u05d4\u05e4\u05d7 \u05d5\u05de\u05e9\u05d7\u05e8\u05e8\u05ea \u05d0\u05d5\u05ea\u05d5 \u05de\u05d4\u05e1\u05db\u05d9\u05df \u05d0\u05d7\u05e8\u05d9 \u05db\u05dc \u05de\u05db\u05d4."],[70.0,"\u05db\u05dc \u05ea\u05d1\u05e0\u05d9\u05ea \u05de\u05ea\u05d5\u05db\u05e0\u05e0\u05ea \u05dc\u05d7\u05dc\u05e7 \u05d0\u05d7\u05d3 \u05d1\u05dc\u05d1\u05d3. \u05d4\u05d9\u05d0 \u05d9\u05e7\u05e8\u05d4, \u05d5\u05dc\u05d5\u05e7\u05d7 \u05e9\u05d1\u05d5\u05e2\u05d5\u05ea \u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d7\u05d5\u05d3\u05e9\u05d9\u05dd \u05dc\u05d9\u05d9\u05e6\u05e8 \u05d0\u05d5\u05ea\u05d4 \u05d5\u05dc\u05db\u05d9\u05d9\u05dc \u05d0\u05d5\u05ea\u05d4."],[79.0,"\u05ea\u05d1\u05e0\u05d9\u05ea \u05e4\u05e9\u05d5\u05d8\u05d4 \u05de\u05d1\u05e6\u05e2\u05ea \u05e4\u05e2\u05d5\u05dc\u05d4 \u05d0\u05d7\u05ea \u05d1\u05db\u05dc \u05de\u05db\u05d4."],[83.0,"\u2026 , \u05e8\u05e6\u05d5\u05e2\u05ea \u05e4\u05d7 \u05e2\u05d5\u05d1\u05e8\u05ea \u05d1\u05d9\u05df \u05db\u05de\u05d4 \u05ea\u05d7\u05e0\u05d5\u05ea \u05d1\u05ea\u05d5\u05da \u05d0\u05d5\u05ea\u05d4 \u05ea\u05d1\u05e0\u05d9\u05ea."],[89.0,"\u05d1\u05db\u05dc \u05ea\u05d7\u05e0\u05d4 \u05de\u05ea\u05d1\u05e6\u05e2\u05ea \u05e4\u05e2\u05d5\u05dc\u05d4 \u05d0\u05d7\u05e8\u05ea: \u05e0\u05d9\u05e7\u05d5\u05d1, \u05db\u05d9\u05e4\u05d5\u05e3, \u05e2\u05d9\u05e6\u05d5\u05d1, \u05d5\u05d1\u05e1\u05d5\u05e3 \u05e0\u05d9\u05ea\u05d5\u05e7 \u05d4\u05d7\u05dc\u05e7."],[96.0,"\u05d4\u05d7\u05dc\u05e7 \u05e0\u05e9\u05d0\u05e8 \u05de\u05d7\u05d5\u05d1\u05e8 \u05dc\u05e8\u05e6\u05d5\u05e2\u05d4 \u05e2\u05d3 \u05d4\u05ea\u05d7\u05e0\u05d4 \u05d4\u05d0\u05d7\u05e8\u05d5\u05e0\u05d4, \u05d5\u05e7\u05d3\u05d7\u05d9 \u05d4\u05d5\u05d1\u05dc\u05d4 \u05d3\u05d5\u05d0\u05d2\u05d9\u05dd \u05e9\u05d4\u05e8\u05e6\u05d5\u05e2\u05d4 \u05ea\u05ea\u05e7\u05d3\u05dd \u05d1\u05d3\u05d9\u05d5\u05e7."],[104.0,"\u05db\u05da \u05d1\u05db\u05dc \u05de\u05db\u05d4 \u05e9\u05dc \u05d4\u05de\u05db\u05d1\u05e9 \u05d9\u05d5\u05e6\u05d0 \u05d7\u05dc\u05e7 \u05de\u05d5\u05db\u05df."],[108.0,"\u05db\u05dc \u05d7\u05dc\u05e7 \u05de\u05e0\u05d5\u05ea\u05e7 \u05d1\u05d4\u05ea\u05d7\u05dc\u05d4, \u05d5\u05d6\u05e8\u05d5\u05e2\u05d5\u05ea \u05de\u05e2\u05d1\u05d9\u05e8\u05d5\u05ea \u05d0\u05d5\u05ea\u05d5 \u05d1\u05d9\u05df \u05d4\u05ea\u05d7\u05e0\u05d5\u05ea."],[117.0,"\u05d1\u05de\u05e9\u05d9\u05db\u05d4 \u05e2\u05de\u05d5\u05e7\u05d4 \u05d4\u05d5\u05e4\u05db\u05d9\u05dd \u05d3\u05e1\u05e7\u05d9\u05ea \u05e9\u05d8\u05d5\u05d7\u05d4 \u05dc\u05db\u05d5\u05e1, \u05dc\u05e7\u05d5\u05e4\u05e1\u05d4 \u05d0\u05d5 \u05dc\u05d2\u05d5\u05e3 \u05e9\u05dc \u05de\u05db\u05dc."],[123.0,"\u05d4\u05e1\u05db\u05d9\u05df \u05d3\u05d5\u05d7\u05e4\u05ea \u05d0\u05ea \u05d4\u05e4\u05d7 \u05dc\u05ea\u05d5\u05da \u05d4\u05de\u05d8\u05e8\u05d9\u05e6\u05d4, \u05d5\u05d4\u05d7\u05d5\u05de\u05e8 \u05de\u05d4\u05e9\u05d5\u05dc\u05d9\u05d9\u05dd \u05d6\u05d5\u05e8\u05dd \u05e4\u05e0\u05d9\u05de\u05d4 \u05d5\u05d9\u05d5\u05e6\u05e8 \u05d0\u05ea \u05d4\u05d3\u05e4\u05e0\u05d5\u05ea."],[130.0,"\u05db\u05d3\u05d9 \u05e9\u05d4\u05e9\u05d5\u05dc\u05d9\u05d9\u05dd \u05dc\u05d0 \u05d9\u05ea\u05e7\u05de\u05d8\u05d5, blank holder \u05dc\u05d5\u05d7\u05e5 \u05e2\u05dc\u05d9\u05d4\u05dd \u05d1\u05d6\u05de\u05df \u05d4\u05de\u05e9\u05d9\u05db\u05d4."],[135.0,"\u05dc\u05d7\u05e5 \u05e0\u05de\u05d5\u05da \u05de\u05d3\u05d9 \u05d9\u05d5\u05e6\u05e8 \u05e7\u05de\u05d8\u05d9\u05dd, \u05d5\u05dc\u05d7\u05e5 \u05d2\u05d1\u05d5\u05d4 \u05de\u05d3\u05d9 \u05e7\u05d5\u05e8\u05e2 \u05d0\u05ea \u05d4\u05e4\u05d7 \u05dc\u05d9\u05d3 \u05d4\u05e8\u05d3\u05d9\u05d5\u05e1 \u05e9\u05dc \u05d4\u05e1\u05db\u05d9\u05df."],[142.0,"\u05db\u05dc\u05dc \u05d0\u05e6\u05d1\u05e2: \u05d1\u05de\u05e9\u05d9\u05db\u05d4 \u05d4\u05e8\u05d0\u05e9\u05d5\u05e0\u05d4, \u05e7\u05d5\u05d8\u05e8 \u05d4\u05d3\u05e1\u05e7\u05d9\u05ea \u05d9\u05db\u05d5\u05dc \u05dc\u05d4\u05d9\u05d5\u05ea \u05d1\u05e2\u05e8\u05da \u05e4\u05d9 2 \u05de\u05e7\u05d5\u05d8\u05e8 \u05d4\u05db\u05d5\u05e1, \u05dc\u05d0 \u05d9\u05d5\u05ea\u05e8."],[150.0,"\u05dc\u05db\u05d5\u05e1 \u05d2\u05d1\u05d5\u05d4\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05e6\u05e8\u05d9\u05da \u05db\u05de\u05d4 \u05de\u05e9\u05d9\u05db\u05d5\u05ea, \u05d0\u05d7\u05ea \u05d0\u05d7\u05e8\u05d9 \u05d4\u05e9\u05e0\u05d9\u05d9\u05d4."],[154.0,"\u05d5\u05d1\u05e4\u05d7\u05d9\u05d5\u05ea \u05e9\u05ea\u05d9\u05d9\u05d4 \u05de\u05d5\u05e1\u05d9\u05e4\u05d9\u05dd \u2026: \u05de\u05e2\u05d1\u05e8 \u05d3\u05e8\u05da \u05d8\u05d1\u05e2\u05d5\u05ea \u05e6\u05e8\u05d5\u05ea \u05e9\u05d5\u05de\u05d3\u05e7\u05d5\u05ea \u05d0\u05ea \u05d4\u05d3\u05d5\u05e4\u05df \u05d5\u05de\u05d0\u05e8\u05d9\u05db\u05d5\u05ea \u05d0\u05d5\u05ea\u05d4."],[162.0,"\u05d1\u05d4\u05d8\u05d1\u05e2\u05d4 \u05dc\u05d5\u05d7\u05e6\u05d9\u05dd \u05e6\u05d5\u05e8\u05d4 \u05dc\u05ea\u05d5\u05da \u05d4\u05e4\u05d7 \u05d1\u05dc\u05d9 \u05dc\u05d7\u05ea\u05d5\u05da \u05d0\u05d5\u05ea\u05d5."],[166.0,"embossing \u05d9\u05d5\u05e6\u05e8 \u05d1\u05dc\u05d9\u05d8\u05d5\u05ea \u05d5\u05e9\u05e7\u05e2\u05d9\u05dd: \u05e6\u05dc\u05e2\u05d5\u05ea \u05d7\u05d9\u05d6\u05d5\u05e7, \u05e1\u05d9\u05de\u05d5\u05e0\u05d9\u05dd, \u05dc\u05d5\u05d2\u05d5."],[172.0,"\u05e6\u05dc\u05e2 \u05d0\u05d7\u05ea \u05dc\u05d0\u05d5\u05e8\u05da \u05dc\u05d5\u05d7 \u05e9\u05d8\u05d5\u05d7 \u05de\u05d2\u05d3\u05d9\u05dc\u05d4 \u05de\u05d0\u05d5\u05d3 \u05d0\u05ea \u05d4\u05e7\u05e9\u05d9\u05d7\u05d5\u05ea \u05e9\u05dc\u05d5, \u05db\u05de\u05e2\u05d8 \u05d1\u05dc\u05d9 \u05dc\u05d4\u05d5\u05e1\u05d9\u05e3 \u05de\u05e9\u05e7\u05dc."],[178.0,"\u05e1\u05d7\u05d5\u05d7\u05d5\u05e1\u05e1 \u05dc\u05d5\u05d7\u05e5 \u05d0\u05ea \u05d4\u05d7\u05d5\u05de\u05e8 \u05d1\u05db\u05d5\u05d7 \u05d2\u05d1\u05d5\u05d4 \u05de\u05d0\u05d5\u05d3 \u05d1\u05ea\u05d5\u05da \u05ea\u05d1\u05e0\u05d9\u05ea \u05e1\u05d2\u05d5\u05e8\u05d4, \u05d5\u05de\u05e7\u05d1\u05dc \u05e4\u05e8\u05d8\u05d9\u05dd \u05d7\u05d3\u05d9\u05dd \u05d5\u05e2\u05d5\u05d1\u05d9 \u05de\u05d3\u05d5\u05d9\u05e7, \u05db\u05de\u05d5 \u05d1\u05de\u05d8\u05d1\u05e2\u05d5\u05ea."],[188.0,"\u05dc\u05d0 \u05db\u05dc \u05e4\u05d7 \u05de\u05ea\u05d0\u05d9\u05dd \u05dc\u05db\u05d1\u05d9\u05e9\u05d4: \u05dc\u05e2\u05d9\u05e6\u05d5\u05d1 \u05e2\u05de\u05d5\u05e7 \u05d1\u05d5\u05d7\u05e8\u05d9\u05dd \u05e4\u05d7 \u05e8\u05da \u05d5\u05e8\u05e7\u05d9\u05e2, \u05e9\u05de\u05d9\u05d5\u05e2\u05d3 \u05dc\u05d6\u05d4."],[194.0,"\u05e0\u05d9\u05e8\u05d5\u05e1\u05d8\u05d4 \u05d5\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05e7\u05e9\u05d9\u05dd \u05d9\u05d5\u05ea\u05e8 \u05dc\u05e2\u05d9\u05e6\u05d5\u05d1, \u05d5\u05e0\u05d5\u05d8\u05d9\u05dd \u05dc\u05d4\u05d9\u05d3\u05d1\u05e7 \u05dc\u05ea\u05d1\u05e0\u05d9\u05ea."],[199.0,"\u05dc\u05db\u05df \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05e9\u05de\u05df \u05d0\u05d5 \u05d1\u05d7\u05d5\u05de\u05e8 \u05e1\u05d9\u05db\u05d4, \u05e9\u05de\u05e4\u05d7\u05d9\u05ea\u05d9\u05dd \u05d7\u05d9\u05db\u05d5\u05da \u05d5\u05de\u05d5\u05e0\u05e2\u05d9\u05dd \u05e9\u05e8\u05d9\u05d8\u05d5\u05ea."],[205.0,"\u05d5\u05d2\u05dd \u05db\u05d0\u05df \u05d4\u05e4\u05d7 \u05e7\u05d5\u05e4\u05e5 \u05d7\u05d6\u05e8\u05d4, \u05d5\u05de\u05ea\u05e7\u05e0\u05d9\u05dd \u05d0\u05ea \u05d6\u05d4 \u05d1\u05ea\u05db\u05e0\u05d5\u05df \u05d4\u05ea\u05d1\u05e0\u05d9\u05ea."],[211.0,"\u05d2\u05dd \u05dc\u05db\u05d1\u05d9\u05e9\u05d4 \u05d9\u05e9 \u05db\u05dc\u05dc\u05d9 \u05ea\u05db\u05e0\u05d5\u05df."],[213.0,"\u05e8\u05d3\u05d9\u05d5\u05e1\u05d9\u05dd \u05e0\u05d3\u05d9\u05d1\u05d9\u05dd \u05d1\u05db\u05dc \u05e4\u05d9\u05e0\u05d4 \u05d5\u05d1\u05db\u05dc \u05de\u05e2\u05d1\u05e8 \u05d1\u05d9\u05df \u05d3\u05d5\u05e4\u05df \u05dc\u05ea\u05d7\u05ea\u05d9\u05ea."],[218.0,"\u05d1\u05d7\u05dc\u05e7 \u05de\u05e9\u05d5\u05da, \u05e2\u05d3\u05d9\u05e3 \u05e2\u05d5\u05de\u05e7 \u05e1\u05d1\u05d9\u05e8 \u05d5\u05e4\u05d9\u05e0\u05d5\u05ea \u05de\u05e2\u05d5\u05d2\u05dc\u05d5\u05ea, \u05d5\u05dc\u05d0 \u05e7\u05d5\u05e4\u05e1\u05d4 \u05e2\u05de\u05d5\u05e7\u05d4 \u05e2\u05dd \u05e4\u05d9\u05e0\u05d5\u05ea \u05d7\u05d3\u05d5\u05ea."],[225.0,"\u05e7\u05d3\u05d7\u05d9\u05dd \u05e8\u05d7\u05d5\u05e7\u05d9\u05dd \u05de\u05e1\u05e4\u05d9\u05e7 \u05de\u05d0\u05d6\u05d5\u05e8\u05d9\u05dd \u05e9\u05de\u05ea\u05e2\u05e6\u05d1\u05d9\u05dd, \u05d0\u05d7\u05e8\u05ea \u05d4\u05dd \u05de\u05ea\u05e2\u05d5\u05d5\u05ea\u05d9\u05dd."],[230.0,"\u05d5\u05db\u05d3\u05d0\u05d9 \u05dc\u05ea\u05db\u05e0\u05df \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7 \u05db\u05da \u05e9\u05db\u05dc \u05d4\u05e4\u05e2\u05d5\u05dc\u05d5\u05ea \u05e0\u05e2\u05e9\u05d5\u05d5\u05ea \u05de\u05d0\u05d5\u05ea\u05d5 \u05db\u05d9\u05d5\u05d5\u05df."],[234.0,"\u05db\u05d1\u05d9\u05e9\u05d4 \u05e0\u05d5\u05ea\u05e0\u05ea \u05d7\u05d6\u05e8\u05ea\u05d9\u05d5\u05ea \u05de\u05e6\u05d5\u05d9\u05e0\u05ea: \u05d2\u05dd \u05d0\u05d7\u05e8\u05d9 \u05d0\u05dc\u05e3 \u05d7\u05dc\u05e7\u05d9\u05dd, \u05d4\u05d7\u05dc\u05e7 \u05d6\u05d4\u05d4 \u05db\u05de\u05e2\u05d8 \u05dc\u05d2\u05de\u05e8\u05d9 \u05dc\u05e8\u05d0\u05e9\u05d5\u05df."],[242.0,"\u05d2\u05dd \u05d1\u05db\u05d1\u05d9\u05e9\u05d4 \u05d9\u05e9 \u05d1\u05e2\u05d9\u05d5\u05ea \u05d0\u05d5\u05e4\u05d9\u05d9\u05e0\u05d9\u05d5\u05ea."],[245.0,"\u05e7\u05de\u05d8\u05d9\u05dd \u05d1\u05e9\u05d5\u05dc\u05d9\u05d9\u05dd, \u05db\u05e9\u05d4\u05dc\u05d7\u05e5 \u05e2\u05dc \u05d4\u05e9\u05d5\u05dc\u05d9\u05d9\u05dd \u05e0\u05de\u05d5\u05da \u05de\u05d3\u05d9."],[249.0,"\u05e7\u05e8\u05d9\u05e2\u05d4 \u05d1\u05d3\u05d5\u05e4\u05df \u05d0\u05d5 \u05d1\u05ea\u05d7\u05ea\u05d9\u05ea, \u05db\u05e9\u05d4\u05de\u05e9\u05d9\u05db\u05d4 \u05e2\u05de\u05d5\u05e7\u05d4 \u05de\u05d3\u05d9 \u05d0\u05d5 \u05e9\u05d4\u05e8\u05d3\u05d9\u05d5\u05e1 \u05e7\u05d8\u05df \u05de\u05d3\u05d9."],[255.0,"\u05d0\u05d5\u05d6\u05e0\u05d9\u05d9\u05dd \u05d1\u05e9\u05e4\u05d4 \u05e9\u05dc \u05db\u05d5\u05e1 \u05de\u05e9\u05d5\u05db\u05d4, \u05db\u05d9 \u05d4\u05e4\u05d7 \u05dc\u05d0 \u05d6\u05d4\u05d4 \u05d1\u05db\u05dc \u05d4\u05db\u05d9\u05d5\u05d5\u05e0\u05d9\u05dd."],[260.0,"\u05e9\u05e8\u05d9\u05d8\u05d5\u05ea \u05d5\u05de\u05e8\u05d9\u05d7\u05d5\u05ea, \u05db\u05e9\u05d7\u05e1\u05e8\u05d4 \u05e1\u05d9\u05db\u05d4."],[263.0,"\u05d5\u05d2\u05e8\u05d3 \u05d5\u05e9\u05d9\u05e0\u05d5\u05d9 \u05de\u05d9\u05d3\u05d5\u05ea, \u05db\u05e9\u05d4\u05ea\u05d1\u05e0\u05d9\u05ea \u05e0\u05e9\u05d7\u05e7\u05ea."],[267.0,"\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8 \u05db\u05d1\u05d9\u05e9\u05d4?"],[269.0,"\u05e7\u05d5\u05d3\u05dd \u05db\u05dc \u05d4\u05ea\u05d1\u05e0\u05d9\u05ea: \u05ea\u05db\u05e0\u05d5\u05df, \u05d9\u05d9\u05e6\u05d5\u05e8 \u05d5\u05db\u05d9\u05d5\u05dc, \u05dc\u05e4\u05e0\u05d9 \u05e9\u05d9\u05d5\u05e6\u05d0 \u05d4\u05d7\u05dc\u05e7 \u05d4\u05e8\u05d0\u05e9\u05d5\u05df."],[275.0,"\u05de\u05db\u05d1\u05e9 \u05d2\u05d3\u05d5\u05dc \u05de\u05e1\u05e4\u05d9\u05e7 \u05dc\u05db\u05d5\u05d7 \u05d4\u05e0\u05d3\u05e8\u05e9\u05d5."],[278.0,"\u05d4\u05d7\u05dc\u05e4\u05ea \u05ea\u05d1\u05e0\u05d9\u05d5\u05ea \u05d5\u05d6\u05de\u05df \u05d4\u05db\u05e0\u05d4."],[281.0,"\u05d5\u05d0\u05d7\u05d6\u05e7\u05d4 \u05e9\u05dc \u05d4\u05ea\u05d1\u05e0\u05d9\u05ea, \u05db\u05d9 \u05d4\u05d9\u05d0 \u05e0\u05e9\u05d7\u05e7\u05ea \u05e2\u05dd \u05d4\u05d6\u05de\u05df."],[284.0,"\u05de\u05e6\u05d3 \u05e9\u05e0\u05d9, \u05d4\u05de\u05d7\u05d9\u05e8 \u05e9\u05dc \u05db\u05dc \u05d7\u05dc\u05e7 \u05e0\u05de\u05d5\u05da \u05de\u05d0\u05d5\u05d3, \u05d5\u05dc\u05db\u05df \u05d1\u05db\u05de\u05d5\u05d9\u05d5\u05ea \u05e9\u05dc \u05d0\u05dc\u05e4\u05d9\u05dd \u05d5\u05de\u05e2\u05dc\u05d4 \u05db\u05d1\u05d9\u05e9\u05d4 \u05db\u05de\u05e2\u05d8 \u05ea\u05de\u05d9\u05d3 \u05de\u05e0\u05e6\u05d7\u05ea."],[293.0,"\u05dc\u05d0\u05d1\u05d8\u05d9\u05e4\u05d5\u05e1 \u05d5\u05dc\u05db\u05de\u05d5\u05d9\u05d5\u05ea \u05e7\u05d8\u05e0\u05d5\u05ea, \u05e2\u05d3\u05d9\u05e3 \u05dc\u05d9\u05d9\u05d6\u05e8 \u05d5\u05de\u05db\u05d1\u05e9 \u05db\u05d9\u05e4\u05d5\u05e3."],[298.0,"\u05db\u05d1\u05d9\u05e9\u05d4 \u05d4\u05d5\u05e4\u05db\u05ea \u05e4\u05d7 \u05dc\u05d7\u05dc\u05e7 \u05de\u05d5\u05db\u05df \u05d1\u05e9\u05e0\u05d9\u05d9\u05d4, \u05d1\u05e2\u05d6\u05e8\u05ea \u05ea\u05d1\u05e0\u05d9\u05ea \u05e9\u05de\u05ea\u05d5\u05db\u05e0\u05e0\u05ea \u05dc\u05d7\u05dc\u05e7 \u05d0\u05d7\u05d3."],[304.0,"\u05d4\u05ea\u05d1\u05e0\u05d9\u05ea \u05d9\u05e7\u05e8\u05d4, \u05d0\u05d1\u05dc \u05d1\u05db\u05de\u05d5\u05d9\u05d5\u05ea \u05d2\u05d3\u05d5\u05dc\u05d5\u05ea \u05d0\u05d9\u05df \u05e9\u05d9\u05d8\u05d4 \u05d6\u05d5\u05dc\u05d4 \u05de\u05de\u05e0\u05d4."],[309.0,"\u05d1\u05d6\u05d4 \u05e1\u05d9\u05d9\u05de\u05e0\u05d5 \u05d0\u05ea \u05e7\u05d1\u05d5\u05e6\u05ea \u05e2\u05d9\u05d1\u05d5\u05d3 \u05d4\u05e4\u05d7."],[312.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0 \u05e0\u05ea\u05d7\u05d9\u05dc \u05d1\u05ea\u05d4\u05dc\u05d9\u05db\u05d9\u05dd \u05d4\u05dc\u05d0 \u05e7\u05d5\u05e0\u05d1\u05e0\u05e6\u05d9\u05d5\u05e0\u05dc\u05d9\u05d9\u05dd, \u05e2\u05dd EDM \u05d7\u05d5\u05d8."]]};
window.MH_TR["\u05e4\u05e8\u05e716_EDM_\u05d7\u05d5\u05d8"]={"t":"EDM \u05d7\u05d5\u05d8","l":[[1.0,"\u05e1\u05db\u05d9\u05e0\u05d9\u05dd \u05d5\u05de\u05d8\u05e8\u05d9\u05e6\u05d5\u05ea \u05dc\u05db\u05d1\u05d9\u05e9\u05d4, \u05ea\u05d1\u05e0\u05d9\u05d5\u05ea \u05e9\u05d9\u05d7\u05d5\u05dc, \u05d2\u05dc\u05d2\u05dc\u05d9 \u05e9\u05d9\u05e0\u05d9\u05d9\u05dd \u05de\u05d5\u05e7\u05e9\u05d9\u05dd, \u05d5\u05e4\u05d9\u05e0\u05d5\u05ea \u05e4\u05e0\u05d9\u05de\u05d9\u05d5\u05ea \u05db\u05de\u05e2\u05d8 \u05d7\u05d3\u05d5\u05ea."],[9.0,"\u05d0\u05ea \u05db\u05dc \u05d0\u05dc\u05d4 \u05d0\u05e4\u05e9\u05e8 \u05dc\u05d7\u05ea\u05d5\u05da \u05d1\u05d7\u05d5\u05d8 \u05d3\u05e7, \u05d1\u05dc\u05d9 \u05e9\u05d4\u05db\u05dc\u05d9 \u05e0\u05d5\u05d2\u05e2 \u05d1\u05d7\u05dc\u05e7 \u05d5\u05d1\u05dc\u05d9 \u05db\u05d5\u05d7\u05d5\u05ea \u05d7\u05d9\u05ea\u05d5\u05da."],[15.0,"\u05d6\u05d4 EDM \u05d7\u05d5\u05d8: \u05e2\u05d9\u05d1\u05d5\u05d3 \u05d1\u05e4\u05e8\u05d9\u05e7\u05d4 \u05d7\u05e9\u05de\u05dc\u05d9\u05ea."],[18.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d6\u05d4 \u05e0\u05d1\u05d9\u05df \u05d0\u05d9\u05da \u05e0\u05d9\u05e6\u05d5\u05e5 \u05d7\u05e9\u05de\u05dc\u05d9 \u05de\u05d5\u05e8\u05d9\u05d3 \u05de\u05ea\u05db\u05ea, \u05de\u05d4 \u05d4\u05ea\u05d4\u05dc\u05d9\u05da \u05e0\u05d5\u05ea\u05df, \u05d5\u05ea\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8 \u05d0\u05d5\u05ea\u05d5."],[26.0,"\u05d4\u05d7\u05d5\u05d8 \u05d4\u05d5\u05d0 \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05d0\u05d7\u05ea, \u05d5\u05d4\u05d7\u05dc\u05e7 \u05d4\u05d5\u05d0 \u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05d4\u05e9\u05e0\u05d9\u05d9\u05d4."],[31.0,"\u05d1\u05d9\u05e0\u05d9\u05d4\u05dd \u05d9\u05e9 \u05de\u05e8\u05d5\u05d5\u05d7 \u05d6\u05e2\u05d9\u05e8, \u05de\u05dc\u05d0 \u05d1\u05de\u05d9\u05dd \u05e0\u05d8\u05d5\u05dc\u05d9 \u05d9\u05d5\u05e0\u05d9\u05dd, \u05e9\u05dc\u05d0 \u05de\u05d5\u05dc\u05d9\u05db\u05d9\u05dd \u05d7\u05e9\u05de\u05dc."],[37.0,"\u05d4\u05de\u05db\u05d5\u05e0\u05d4 \u05e9\u05d5\u05dc\u05d7\u05ea \u05e4\u05d5\u05dc\u05e1 \u05e9\u05dc \u05de\u05ea\u05d7, \u05d5\u05d1\u05d9\u05df \u05d4\u05d7\u05d5\u05d8 \u05dc\u05d7\u05dc\u05e7 \u05e7\u05d5\u05e4\u05e5 \u05e0\u05d9\u05e6\u05d5\u05e5."],[42.0,"\u05d4\u05e0\u05d9\u05e6\u05d5\u05e5 \u05de\u05ea\u05d9\u05da \u05d5\u05de\u05d0\u05d3\u05d4 \u05db\u05de\u05d5\u05ea \u05de\u05d9\u05e7\u05e8\u05d5\u05e1\u05e7\u05d5\u05e4\u05d9\u05ea \u05e9\u05dc \u05de\u05ea\u05db\u05ea, \u05d5\u05d4\u05de\u05d9\u05dd \u05e9\u05d5\u05d8\u05e1\u05e4\u05d9\u05dd \u05d0\u05d5\u05ea\u05d4 \u05d4\u05d7\u05d5\u05e6\u05d4."],[48.0,"\u05d6\u05d4 \u05e7\u05d5\u05e8\u05d4 \u05de\u05d0\u05d5\u05ea \u05d0\u05dc\u05dc\u05d9 \u05e4\u05e2\u05de\u05d9\u05dd \u05d1\u05e9\u05e0\u05d9\u05d9\u05d4, \u05d5\u05db\u05da \u05d4\u05d7\u05d5\u05d8 \u05de\u05ea\u05e7\u05d3\u05dd \u05d5\u05d7\u05d5\u05ea\u05da."],[54.0,"\u05d2\u05dd \u05d4\u05d7\u05d5\u05d8 \u05e0\u05e9\u05d7\u05e7 \u05de\u05d4\u05e0\u05d9\u05e6\u05d5\u05e6\u05d5\u05ea, \u05d5\u05dc\u05db\u05df \u05d4\u05d5\u05d0 \u05e0\u05de\u05e9\u05da \u05db\u05dc \u05d4\u05d6\u05de\u05df \u05de\u05e1\u05dc\u05d9\u05dc, \u05d5\u05de\u05d7\u05e9\u05de\u05e9 \u05e4\u05e2\u05dd \u05d0\u05d7\u05ea \u05d1\u05dc\u05d1\u05d3."],[61.0,"\u05d4\u05d7\u05d5\u05d8 \u05e2\u05e9\u05d5\u05d9 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05e4\u05dc\u05d9\u05d6, \u05d5\u05d1\u05e7\u05d5\u05d8\u05e8 \u05e0\u05e4\u05d5\u05e5 \u05e9\u05dc \u05e8\u05d1\u05e2 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8."],[66.0,"\u05d4\u05ea\u05e0\u05d0\u05d9 \u05d4\u05d9\u05d7\u05d9\u05d3: \u05d4\u05d7\u05d5\u05de\u05e8 \u05d7\u05d9\u05d9\u05d1 \u05dc\u05d4\u05d5\u05dc\u05d9\u05da \u05d7\u05e9\u05de\u05dc."],[70.0,"\u05e4\u05dc\u05d3\u05d5\u05ea, \u05e4\u05dc\u05d3\u05ea \u05db\u05dc\u05d9\u05dd \u05de\u05d5\u05e7\u05e9\u05d9\u05ea, \u05e7\u05e8\u05d1\u05d9\u05d3, \u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd, \u05d0\u05d9\u05e0\u05e7\u05d5\u05e0\u05dc, \u05e0\u05d7\u05d5\u05e9\u05ea \u05d5\u05d2\u05e8\u05e4\u05d9\u05d8 \u05de\u05ea\u05d0\u05d9\u05de\u05d9\u05dd \u05db\u05d5\u05dc\u05dd."],[77.0,"\u05d4\u05e7\u05e9\u05d9\u05d5\u05ea \u05dc\u05d0 \u05de\u05e9\u05e0\u05d4 \u05d1\u05db\u05dc\u05dc: \u05d7\u05d5\u05de\u05e8 \u05de\u05d5\u05e7\u05e9\u05e9\u05d5\u05d4 \u05e0\u05d7\u05ea\u05da \u05db\u05de\u05e2\u05d8 \u05db\u05de\u05d5 \u05d7\u05d5\u05de\u05e8 \u05e8\u05da."],[83.0,"\u05d0 \u05d1\u05dc \u05df \u05e7\u05e8 \u05de\u05d9\u05e7 i \u05d4\u05d5\u05e4\u05dc\u05e1\u05d8 \u05d9\u05e7, \u05e9\u05dc\u05d0 \u05de\u05d5 \u05d9\u05dd \u05dc\u05d9\u05db\u05d9\u05dd, \u05d0 \u05d9 \u05d0\u05e4 \u05e9\u05e8 \u05dc\u05d7 \u05ea\u05d5\u05da"],[88.0,"\u05d4\u05e9\u05d5\u05dc\u05d7\u05df \u05d6\u05d6 \u05d1\u05e9\u05e0\u05d9 \u05e6\u05d9\u05e8\u05d9\u05dd, \u05d5\u05d4\u05d7\u05d5\u05d8 \u05e2\u05d5\u05d1\u05e8 \u05d1\u05d9\u05df \u05de\u05d5\u05d1\u05d9\u05dc \u05e2\u05dc\u05d9\u05d5\u05df \u05dc\u05de\u05d5\u05d1\u05d9\u05dc \u05ea\u05d7\u05ea\u05d5\u05df."],[94.0,"\u05db\u05e9\u05de\u05d6\u05d9\u05d6\u05d9\u05dd \u05d0\u05ea \u05d4\u05de\u05d5\u05d1\u05d9\u05dc \u05d4\u05e2\u05dc\u05d9\u05d5\u05df \u05d1\u05d9\u05d7\u05e1 \u05dc\u05ea\u05d7\u05ea\u05d5\u05df, \u05d4\u05d7\u05d5\u05d8 \u05e0\u05d5\u05d8\u05d4, \u05d5\u05d0\u05e4\u05e9\u05e8 \u05dc\u05d7\u05ea\u05d5\u05da \u05e9\u05d9\u05e4\u05d5\u05e2, \u05d0\u05d5 \u05e6\u05d5\u05e8\u05d4 \u05e9\u05d5\u05e0\u05d4 \u05dc\u05de\u05e2\u05dc\u05d4 \u05d5\u05dc\u05de\u05d8\u05d4."],[103.0,"\u05db\u05d3\u05d9 \u05dc\u05d7\u05ea\u05d5\u05da \u05e6\u05d5\u05e8\u05d4 \u05e4\u05e0\u05d9\u05de\u05d9\u05ea \u05e1\u05d2\u05d5\u05e8\u05d4, \u05e7\u05d5\u05d3\u05d7\u05d9\u05dd \u05e7\u05d5\u05d3\u05dd \u05e7\u05d3\u05d7 \u05d4\u05ea\u05d7\u05dc\u05d4 \u05e7\u05d8\u05df, \u05d5\u05de\u05e9\u05d7\u05d9\u05dc\u05d9\u05dd \u05d3\u05e8\u05db\u05d5 \u05d0\u05ea \u05d4\u05d7\u05d5\u05d8."],[109.0,"\u05de\u05db\u05d5\u05e0\u05d5\u05ea \u05de\u05d5\u05d3\u05e8\u05e0\u05d9\u05d5\u05ea \u05de\u05e9\u05d7\u05d9\u05dc\u05d5\u05ea \u05d0\u05ea \u05d4\u05d7\u05d5\u05d8 \u05dc\u05d1\u05d3, \u05d5\u05db\u05da \u05d9\u05db\u05d5\u05dc\u05d5\u05ea \u05dc\u05e2\u05d1\u05d5\u05e8 \u05de\u05e6\u05d5\u05e8\u05d4 \u05dc\u05e6\u05d5\u05e8\u05d4 \u05d1\u05dc\u05d9 \u05de\u05e4\u05e2\u05d9\u05dc."],[116.0,"\u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05e2\u05d5\u05e9\u05d9\u05dd \u05d7\u05d9\u05ea\u05d5\u05da \u05d2\u05e1 \u05d0\u05d7\u05d3, \u05d5\u05d0\u05d7\u05e8\u05d9\u05d5 \u05db\u05de\u05d4 \u05d7\u05d9\u05ea\u05d5\u05db\u05d9 \u201cskim cuts \u05d2\u05d9\u05de\u05d5\u05e8,"],[122.0,"\u05d4\u05d7\u05d9\u05ea\u05d5\u05da \u05d4\u05d2\u05e1 \u05de\u05d4\u05d9\u05e8 \u05d9\u05d7\u05e1\u05d9\u05ea, \u05d5\u05d7\u05d9\u05ea\u05d5\u05db\u05d9 \u05d4\u05d2\u05d9\u05de\u05d5\u05e8 \u05de\u05d5\u05e8\u05d9\u05d3\u05d9\u05dd \u05e9\u05db\u05d1\u05d4 \u05d3\u05e7\u05d4 \u05d5\u05de\u05e9\u05e4\u05e8\u05d9\u05dd \u05d0\u05ea \u05d4\u05d3\u05d9\u05d5\u05e7 \u05d5\u05d0\u05ea \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7."],[130.0,"\u05e2\u05dd \u05db\u05de\u05d4 \u05d7\u05d9\u05ea\u05d5\u05db\u05d9 \u05d2\u05d9\u05de\u05d5\u05e8 \u05de\u05d2\u05d9\u05e2\u05d9\u05dd \u05dc\u05d3\u05d9\u05d5\u05e7 \u05e9\u05dc \u05db\u05de\u05d4 \u05de\u05d9\u05e7\u05e8\u05d5\u05e0\u05d9\u05dd."],[134.0,"\u05d4\u05d7\u05e8\u05d9\u05e5 \u05e9\u05d4\u05d7\u05d5\u05d8 \u05de\u05e9\u05d0\u05d9\u05e8 \u05e8\u05d7\u05d1 \u05de\u05e2\u05d8 \u05de\u05d4\u05d7\u05d5\u05d8 \u05e2\u05e6\u05de\u05d5, \u05d1\u05d2\u05dc\u05dc \u2026 \u05d4\u05e0\u05d9\u05e6\u05d5\u05e5."],[139.0,"\u05d5\u05dc\u05db\u05df \u05e4\u05d9\u05e0\u05d4 \u05e4\u05e0\u05d9\u05de\u05d9\u05ea \u05ea\u05de\u05d9\u05d3 \u05ea\u05d4\u05d9\u05d4 \u05e2\u05dd \u05e8\u05d3\u05d9\u05d5\u05e1 \u05e7\u05d8\u05df, \u05d1\u05e2\u05e8\u05da \u05d7\u05e6\u05d9 \u05de\u05e8\u05d5\u05d7\u05d1 \u05d4\u05d7\u05e8\u05d9\u05e5."],[145.0,"\u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05d4\u05d7\u05d9\u05ea\u05d5\u05da \u05e0\u05de\u05d3\u05d3\u05ea \u05d1\u05e9\u05d8\u05d7: \u05d0\u05d5\u05e8\u05da \u05d4\u05d7\u05d9\u05ea\u05d5\u05da \u05db\u05e4\u05d5\u05dc \u05d2\u05d5\u05d1\u05d4 \u05d4\u05d7\u05dc\u05e7, \u05d1\u05de\u05de\"\u05e8 \u05dc\u05d3\u05e7\u05d4. \u05d7\u05dc\u05e7 \u05d2\u05d1\u05d5\u05d4 \u05d7\u05d5\u05ea\u05db\u05d9\u05dd \u05dc\u05d0\u05d8 \u05d9\u05d5\u05ea\u05e8."],[156.0,"\u05d4\u05d7\u05d5\u05dd \u05e9\u05dc \u05d4\u05e0\u05d9\u05e6\u05d5\u05e6\u05d5\u05ea \u05de\u05e9\u05d0\u05d9\u05e8 \u05e2\u05dc \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05e9\u05db\u05d1\u05d4 \u05d3\u05e7\u05d4 \u05e9\u05d4\u05d5\u05ea\u05db\u05d4 \u05d5\u05d4\u05ea\u05e7\u05e9\u05d5\u05ea\u05d4 \u05de\u05d7\u05d3\u05e9: recast layer."],[163.0,"\u05d4\u05e9\u05db\u05d1\u05d4 \u05d4\u05d6\u05d5 \u05e7\u05e9\u05d4 \u05d5\u05e9\u05d1\u05d9\u05e8\u05d4, \u05d5\u05d9\u05db\u05d5\u05dc\u05d4 \u05dc\u05d4\u05db\u05d9\u05dc \u05e1\u05d3\u05e7\u05d9\u05dd \u05d6\u05e2\u05d9\u05e8\u05d9\u05dd."],[168.0,"\u05d7\u05d9\u05ea\u05d5\u05db\u05d9 \u05d4\u05d2\u05d9\u05de\u05d5\u05e8 \u05de\u05e1\u05d9\u05e8\u05d9\u05dd \u05d0\u05ea \u05e8\u05d5\u05d1\u05d4, \u05d7\u05d4 \u05d7\u05e9\u05d5\u05d1 \u05d1\u05de\u05d9\u05d5\u05d7\u05d3 \u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05e9\u05e2\u05d5\u05d1\u05d3\u05d9\u05dd \u05d1\u05e2\u05d9\u05d9\u05e4\u05d5\u05ea, \u05db\u05de\u05d5 \u05d1\u05ea\u05e2\u05d5\u05e4\u05d4."],[175.0,"\u05d4\u05e9\u05d9\u05de\u05d5\u05e9 \u05d4\u05e7\u05dc\u05d0\u05e1\u05d9: \u05e1\u05db\u05d9\u05e0\u05d9\u05dd \u05d5\u05de\u05d8\u05e8\u05d9\u05e6\u05d5\u05ea \u05dc\u05db\u05d1\u05d9\u05e9\u05d4, \u05db\u05de\u05d5 \u05e9\u05e8\u05d0\u05d9\u05e0\u05d5 \u05d1\u05e4\u05e8\u05e7 15."],[181.0,"\u05d2\u05dd \u05ea\u05d1\u05e0\u05d9\u05d5\u05ea \u05e9\u05d9\u05d7\u05d5\u05dc, \u05d2\u05dc\u05d2\u05dc\u05d9 \u05e9\u05d9\u05e0\u05d9\u05d9\u05dd \u05d5\u05e1\u05e4\u05dc\u05d9\u05d9\u05e0\u05d9\u05dd \u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05de\u05d5\u05e7\u05e9\u05e9\u05d9\u05dd."],[186.0,"\u05d7\u05e8\u05d9\u05e6\u05d9 \u05e9\u05d2\u05dd \u05d1\u05d7\u05dc\u05e7 \u05e9\u05db\u05d1\u05e8 \u05e2\u05d1\u05e8 \u05d4\u05e7\u05e9\u05d9\u05d4."],[189.0,"\u05d7\u05dc\u05e7\u05d9\u05dd \u05e7\u05d8\u05e0\u05d9\u05dd \u05d5\u05de\u05d3\u05d5\u05d9\u05e7\u05d9\u05dd, \u05d5\u05d3\u05e4\u05e0\u05d5\u05ea \u05d3\u05e7\u05d5\u05ea \u05de\u05d0\u05d5\u05d3, \u05db\u05d9 \u05d0\u05d9\u05df \u05db\u05d5\u05d7\u05d5\u05ea \u05e9\u05de\u05db\u05d5\u05e4\u05e4\u05d9\u05dd \u05d0\u05d5\u05ea\u05df."],[195.0,"\u05d5\u05e4\u05d9\u05e0\u05d5\u05ea \u05e4\u05e0\u05d9\u05de\u05d9\u05d5\u05ea \u05db\u05de\u05e2\u05d8 \u05d7\u05d3\u05d5\u05ea, \u05e9\u05db\u05e8\u05e1\u05d5\u05dd \u05dc\u05d0 \u05d9\u05db\u05d5\u05dc \u05dc\u05ea\u05ea."],[200.0,"\u05d2\u05dd EDM-7 \u05d7\u05d5\u05d8 \u05d9\u05e9 \u05db\u05dc\u05dc\u05d9 \u05ea\u05db\u05e0\u05d5\u05df."],[203.0,"\u05d4\u05d7\u05d5\u05d8 \u05d7\u05d9\u05d9\u05d1 \u05dc\u05e2\u05d1\u05d5\u05e8 \u05d3\u05e8\u05da \u05db\u05dc \u05d4\u05d7\u05dc\u05e7, \u05d5\u05dc\u05db\u05df \u05d0\u05e4\u05e9\u05e8 \u05dc\u05d7\u05ea\u05d5\u05da \u05e8\u05e7 \u05e6\u05d5\u05e8\u05d5\u05ea \u05e2\u05d5\u05d1\u05e8\u05d5\u05ea. \u05db\u05d9\u05e1 \u05e2\u05d9\u05d5\u05d5\u05e8 \u05d3\u05d5\u05e8\u05e9 EDM \u05e9\u05d9\u05e7\u05d5\u05e2, \u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0."],[213.0,"\u05e6\u05d5\u05e8\u05d4 \u05e4\u05e0\u05d9\u05de\u05d9\u05ea \u05e6\u05e8\u05d9\u05db\u05d4 \u05e7\u05d3\u05d7 \u05d4\u05ea\u05d7\u05dc\u05d4, \u05d5\u05de\u05e7\u05d5\u05dd \u05d1\u05e9\u05d1\u05d9\u05dc\u05d5."],[217.0,"\u05dc\u05d4\u05d9\u05ea\u05e7\u05e2. \u05dc\u05db\u05df \u05de\u05e9\u05d0\u05d9\u05e8\u05d9\u05dd \u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d7\u05d9\u05d1\u05d5\u05e8 \u05e7\u05d8\u05df, \u05d5\u05de\u05e1\u05d9\u05e8\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5 \u05d1\u05e1\u05d5\u05e3."],[226.0,"\u05d5\u05db\u05de\u05d5 \u05ea\u05de\u05d9\u05d3, , \u05dc\u05ea\u05ea \u05d8\u05d5\u05dc\u05e8\u05e0\u05e1 . \u05d4\u05d3\u05d5\u05e7 \u05e8\u05e7 \u05d0\u05d9\u05e4\u05d4 . \u05e9\u05e6\u05e8\u05d9\u05da, , \u05db\u05d9 \u05db\u05dc \u05d7\u05d9\u05ea\u05d5\u05da \u05d2\u05d9\u05de\u05d5\u05e8 \u05e0\u05d5\u05e1\u05e3 \u05d4\u05d5\u05d0 \u05e2\u05d5\u05d3 \u05d6\u05de\u05df."],[234.0,"\u05d2\u05dd EDM-2 \u05d7\u05d5\u05d8 \u05d9\u05e9 \u05d1\u05e2\u05d9\u05d5\u05ea \u05d0\u05d5\u05e4\u05d9\u05d9\u05e0\u05d9\u05d5\u05ea."],[237.0,"\u05d7\u05d5\u05d8 \u05e9\u05e0\u05e7\u05e8\u05e2, \u05d1\u05d2\u05dc\u05dc \u05e9\u05d8\u05d9\u05e4\u05d4 \u05dc\u05d0 \u05d8\u05d5\u05d1\u05d4 \u05d0\u05d5 \u05d4\u05e1\u05e4\u05e7 \u05d2\u05d1\u05d5\u05d4 \u05de\u05d3\u05d9."],[241.0,"\u05d7\u05dc\u05e7 \u05e9\u05d6\u05d6 \u05ea\u05d5\u05da \u05db\u05d3\u05d9 \u05d7\u05d9\u05ea\u05d5\u05da, \u05db\u05d9 \u05de\u05e9\u05ea\u05d7\u05e8\u05e8\u05d9\u05dd \u05d1\u05d5 \u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05e4\u05e0\u05d9\u05de\u05d9\u05d9\u05dd, \u05d1\u05e2\u05d9\u05e7\u05e8 \u05d1\u05d7\u05d5\u05de\u05e8 \u05de\u05d5\u05e7\u05e9\u05d4."],[248.0,"\u05e1\u05d8\u05d9\u05d9\u05d4 \u05dc\u05d0\u05d5\u05e8\u05da \u05d4\u05d2\u05d5\u05d1\u05d4, \u05db\u05e9\u05d4\u05d7\u05d5\u05d8 \u05e8\u05d5\u05d8\u05d8 \u05d0\u05d5 \u05dc\u05d0 \u05de\u05ea\u05d5\u05d7 \u05de\u05e1\u05e4\u05d9\u05e7."],[252.0,"\u05d5\u05e9\u05db\u05d1\u05d4 \u05de\u05d5\u05ea\u05db\u05ea \u05e9\u05dc\u05d0 \u05d4\u05d5\u05e1\u05e8\u05d4, \u05e9\u05de\u05d7\u05dc\u05d9\u05e9\u05d4 \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7."],[257.0,"\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8 EDM \u05d7\u05d5\u05d8?"],[259.0,"\u05d1\u05e2\u05d9\u05e7\u05e8 \u05d4\u05d6\u05de\u05df: \u05d4\u05ea\u05d4\u05dc\u05d9\u05da \u05d0\u05d9\u05d8\u05d9, \u05d5\u05d7\u05dc\u05e7 \u05d0\u05d7\u05d3 \u05d9\u05db\u05d5\u05dc \u05dc\u05e7\u05d7\u05ea \u05e9\u05e2\u05d5\u05ea."],[265.0,"\u05d4\u05e9\u05d8\u05d7 \u05dc\u05d7\u05d9\u05ea\u05d5\u05da, \u05db\u05dc\u05d5\u05de\u05e8 \u05d4\u05d0\u05d5\u05e8\u05da \u05db\u05e4\u05d5\u05dc \u05d4\u05d2\u05d5\u05d1\u05d4, \u05d5\u05de\u05e1\u05e4\u05e8 \u05d7\u05d9\u05ea\u05d5\u05db\u05d9 \u05d4\u05d2\u05d9\u05de\u05d5\u05e8."],[271.0,"\u05d7\u05d5\u05d8, \u05de\u05d9\u05dd, \u05d5\u05d0\u05d7\u05d6\u05e7\u05d4 \u05e9\u05dc \u05d4\u05de\u05db\u05d5\u05e0\u05d4."],[274.0,"\u05d5\u05e7\u05d3\u05d7\u05d9 \u05d4\u05ea\u05d7\u05dc\u05d4 \u05d5\u05d4\u05db\u05e0\u05d4."],[276.0,"\u05de\u05e6\u05d3 \u05e9\u05e0\u05d9, \u05d4\u05de\u05db\u05d5\u05e0\u05d4 \u05d9\u05db\u05d5\u05dc\u05d4 \u05dc\u05e2\u05d1\u05d5\u05d3 \u05dc\u05d1\u05d3 \u05db\u05dc \u05d4\u05dc\u05d9\u05dc\u05d4, \u05d5\u05d6\u05d4 \u05de\u05d5\u05d6\u05d9\u05dc \u05de\u05d0\u05d5\u05d3."],[282.0,"\u05d5\u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05de\u05d5\u05e7\u05e9\u05d9\u05dd \u05d0\u05d5 \u05de\u05e1\u05d5\u05d1\u05db\u05d9\u05dd, , \u05d0\u05d9\u05df \u05dc\u05d4 . \u05ea\u05d7\u05dc\u05d9\u05e3 \u05d0\u05de\u05d9\u05ea\u05d9 ."],[286.0,"EDM \u05d7\u05d5\u05d8 \u05d7\u05d5\u05ea\u05da \u05db\u05dc \u05d7\u05d5\u05de\u05e8 \u05de\u05d5\u05dc\u05d9\u05da, \u05d1\u05db\u05dc \u05e7\u05e9\u05d9\u05d5\u05ea, \u05d1\u05d3\u05d9\u05d5\u05e7 \u05e9\u05dc \u05de\u05d9\u05e7\u05e8\u05d5\u05e0\u05d9\u05dd \u05d5\u05d1\u05dc\u05d9 \u05db\u05d5\u05d7\u05d5\u05ea."],[294.0,"\u05d4\u05d5\u05d0 \u05d0\u05d9\u05d8\u05d9, \u05d5\u05dc\u05db\u05df \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05d5 \u05d0\u05d9\u05e4\u05d4 \u05e9\u05ea\u05d4\u05dc\u05d9\u05db\u05d9\u05dd \u05d0\u05d7\u05e8\u05d9\u05dd \u05dc\u05d0 \u05de\u05e1\u05d5\u05d2\u05dc\u05d9\u05dd."],[299.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0: EDM \u05e9\u05d9\u05e7\u05d5\u05e2."]]};
window.MH_TR["\u05e4\u05e8\u05e717_EDM_\u05e9\u05d9\u05e7\u05d5\u05e2"]={"t":"EDM \u05e9\u05d9\u05e7\u05d5\u05e2","l":[[1.0,"\u05d7\u05dc\u05dc \u05e9\u05dc \u05ea\u05d1\u05e0\u05d9\u05ea \u05d4\u05d6\u05e8\u05e7\u05d4, \u05e6\u05dc\u05e2\u05d5\u05ea \u05e2\u05de\u05d5\u05e7\u05d5\u05ea \u05d5\u05e6\u05e8\u05d5\u05ea, \u05d5\u05db\u05d9\u05e1 \u05e2\u05d9\u05d5\u05d5\u05e8 \u05e2\u05dd \u05e1\u05d9\u05e0\u05d5\u05ea \u05d7\u05d3\u05d5\u05ea \u05d1\u05e4\u05dc\u05d3\u05d4 \u05de\u05d5\u05e7\u05e9\u05d9\u05ea."],[8.0,"\u05db\u05e8\u05e1\u05d5\u05dd \u05dc\u05d0 \u05de\u05d2\u05d9\u05e2 \u05dc\u05e9\u05dd, EDM-1 \u05d7\u05d5\u05d8 \u05dc\u05d0 \u05d9\u05db\u05d5\u05dc \u05dc\u05d7\u05ea\u05d5\u05da \u05db\u05d9\u05e1 \u05e2\u05d9\u05d5\u05d5\u05e8."],[14.0,"\u05db\u05d0\u05df \u05e0\u05db\u05e0\u05e1 EDM \u05e9\u05d9\u05e7\u05d5\u05e2: \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05d1\u05e6\u05d5\u05e8\u05d4 \u05d4\u05e8\u05e6\u05d5\u05d9\u05d4 \u05e9\u05d5\u05e7\u05e2\u05ea \u05dc\u05ea\u05d5\u05da \u05d4\u05d7\u05dc\u05e7, \u05d5\u05e0\u05d9\u05e6\u05d5\u05e6\u05d5\u05ea \u05de\u05d5\u05e8\u05d9\u05d3\u05d9\u05dd \u05d0\u05ea \u05d4\u05d7\u05d5\u05de\u05e8."],[22.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d6\u05d4 \u05e0\u05db\u05d9\u05e8 \u05d0\u05ea \u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4, \u05d0\u05ea \u05d4\u05ea\u05d4\u05dc\u05d9\u05da, \u05d5\u05d0\u05ea \u05de\u05d4 \u05e9\u05de\u05d9\u05d9\u05e7\u05e8 \u05d0\u05d5\u05ea\u05d5."],[28.0,"\u05d4\u05e2\u05d9\u05e7\u05e8\u05d5\u05df \u05d6\u05d4\u05d4 EDM-7 \u05d7\u05d5\u05d8: \u05e0\u05d9\u05e6\u05d5\u05e6\u05d5\u05ea \u05d1\u05de\u05e8\u05d5\u05d5\u05d7 \u05d6\u05e2\u05d9\u05e8 \u05de\u05ea\u05d9\u05db\u05d9\u05dd \u05d5\u05de\u05d0\u05d3\u05d9\u05dd \u05d0\u05ea \u05d4\u05d7\u05d5\u05de\u05d5."],[35.0,"\u05d0\u05d1\u05dc \u05db\u05d0\u05df \u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05d4\u05d9\u05d0 \u05e6\u05d5\u05e8\u05d4 \u05de\u05dc\u05d0\u05d4, \u05d4\u05ea\u05de\u05d5\u05e0\u05d4 \u05d4\u05d4\u05e4\u05d5\u05db\u05d4 \u05e9\u05dc \u05d4\u05d7\u05dc\u05dc \u05e9\u05e8\u05d5\u05e6\u05d9\u05dd \u05dc\u05e7\u05d1\u05dc."],[41.0,"\u05d4\u05d7\u05dc\u05e7 \u05d8\u05d1\u05d5\u05dc \u05d1\u05e9\u05de\u05df \u05de\u05d9\u05d5\u05d7\u05d3 \u05e9\u05dc\u05d0 \u05de\u05d5\u05dc\u05d9\u05da \u05d7\u05e9\u05de\u05dc, \u05d5\u05d4\u05e9\u05de\u05df \u05e9\u05d5\u05d8\u05e3 \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7\u05d9\u05e7\u05d9\u05dd \u05d4\u05d7\u05d5\u05e6\u05d4."],[47.0,"\u05de\u05e2\u05e8\u05db\u05ea \u05e1\u05e8\u05d5\u05d5 \u05e9\u05d5\u05de\u05e8\u05ea \u05e2\u05dc \u05d4\u05de\u05e8\u05d5\u05d5\u05d7, \u05d5\u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05d9\u05d5\u05e8\u05d3\u05ea \u05dc\u05d0\u05d8 \u05dc\u05ea\u05d5\u05da \u05d4\u05d7\u05d5\u05de\u05e8."],[53.0,"\u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05e0\u05e2\u05d4 \u05d1\u05de\u05e2\u05d2\u05dc \u05e7\u05d8\u05df, \u05de\u05e8\u05d7\u05d9\u05d1\u05d4 \u05d0\u05ea \u05d4\u05d7\u05dc\u05dc \u05d1\u05e9\u05dc\u05d9\u05d8\u05d4 \u05d5\u05de\u05e9\u05e4\u05e8\u05ea \u05d0\u05ea \u05d4\u05e9\u05d8\u05d9\u05e4\u05d4."],[63.0,"\u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05e2\u05e9\u05d5\u05d9\u05d4 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d2\u05e8\u05e4\u05d9\u05d8 \u05d0\u05d5 \u05e0\u05d7\u05d5\u05e9\u05ea."],[67.0,"\u05d2\u05e8\u05e4\u05d9\u05d8 \u05e7\u05dc, \u05d6\u05d5\u05dc \u05d9\u05d7\u05e1\u05d9\u05ea, \u05d5\u05de\u05ea\u05e2\u05d1\u05d3 \u05de\u05d4\u05e8 \u05d1\u05db\u05e8\u05e1\u05d5\u05dd, \u05d5\u05dc\u05db\u05df \u05d4\u05d5\u05d0 \u05e0\u05e4\u05d5\u05e5 \u05d1\u05ea\u05d1\u05e0\u05d9\u05d5\u05ea \u05d2\u05d3\u05d5\u05dc\u05d5\u05ea."],[74.0,"\u05e0\u05d7\u05d5\u05e9\u05ea \u05e0\u05d5\u05ea\u05e0\u05ea \u05e4\u05e0\u05d9 \u05e9\u05d8\u05d7 \u05d8\u05d5\u05d1\u05d9\u05dd \u05d9\u05d5\u05ea\u05e8 \u05d5\u05e4\u05e8\u05d8\u05d9\u05dd \u05e2\u05d3\u05d9\u05e0\u05d9\u05dd \u05d9\u05d5\u05ea\u05e8."],[79.0,"\u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05e7\u05d8\u05e0\u05d4 \u05de\u05d4\u05d7\u05dc\u05dc \u05d1\u05de\u05e8\u05d5\u05d5\u05d7 \u05d4\u05e0\u05d9\u05e6\u05d5\u05e5, \u05d5\u05d4\u05de\u05e8\u05d5\u05d5\u05d7 \u05d4\u05d6\u05d4 \u05e9\u05d5\u05e0\u05d4 \u05d1\u05d7\u05d9\u05ea\u05d5\u05da \u05d2\u05e1 \u05d5\u05d1\u05d2\u05d9\u05de\u05d5\u05e8."],[85.0,"\u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05dc\u05d7\u05d9\u05ea\u05d5\u05da \u05d2\u05e1, \u05d5\u05e2\u05d5\u05d3 \u05d0\u05d7\u05ea \u05d0\u05d5 \u05e9\u05ea\u05d9\u05d9\u05dd \u05dc\u05d2\u05d9\u05de\u05d5\u05e8."],[95.0,"\u05db\u05d9\u05e1\u05d9\u05dd \u05e2\u05d9\u05d5\u05d5\u05e8\u05d9\u05dd \u05d1\u05db\u05dc \u05e6\u05d5\u05e8\u05d4, \u05d1\u05dc\u05dc \u05e2\u05d5\u05de\u05e7 \u05e1\u05d1\u05d9\u05e8, \u05d1\u05d7\u05d5\u05de\u05e8 \u05de\u05d5\u05e7\u05e9\u05d4."],[100.0,"\u05e4\u05d9\u05e0\u05d5\u05ea \u05e4\u05e0\u05d9\u05de\u05d9\u05d5\u05ea \u05d7\u05d3\u05d5\u05ea, \u05db\u05de\u05d5 \u05e9\u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05de\u05d0\u05e4\u05e9\u05e8\u05ea."],[104.0,"\u05e6\u05dc\u05e2\u05d5\u05ea \u05e2\u05de\u05d5\u05e7\u05d5\u05ea \u05d5\u05e6\u05e8\u05d5\u05ea, \u05e9\u05d0\u05e3 \u05db\u05e8\u05e1\u05dd \u05dc\u05d0 \u05d9\u05db\u05d5\u05dc \u05dc\u05d4\u05d2\u05d9\u05e2 \u05d0\u05dc\u05d9\u05d4\u05df."],[108.0,"\u05d5\u05e4\u05e0\u05d9 \u05e9\u05d8\u05d7 \u05de\u05d8 \u05d0\u05d7\u05d9\u05d3\u05d9\u05dd, \u05e9\u05de\u05e9\u05de\u05e9\u05d9\u05dd \u05d1\u05ea\u05d1\u05e0\u05d9\u05d5\u05ea \u05db\u05d2\u05d9\u05de\u05d5\u05e8 \u05e1\u05d5\u05e4\u05d9 \u05e9\u05dc \u05d4\u05de\u05d5\u05e6\u05e8."],[114.0,"\u05d2\u05e8\u05e1\u05d4 \u05de\u05d9\u05d5\u05d7\u05d3\u05ea \u05d4\u05d9\u05d0 \u05e7\u05d9\u05d3\u05d5\u05d7 \u05d5\u05d0\u05e1\u05dd: \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05d1\u05e6\u05d5\u05e8\u05ea \u05e6\u05d9\u05e0\u05d5\u05e8 \u05d3\u05e7, \u05e2\u05dd \u05de\u05d9\u05dd \u05e9\u05d6\u05d5\u05e8\u05de\u05d9\u05dd \u05d3\u05e8\u05db\u05d4."],[121.0,"\u05db\u05da \u05e7\u05d5\u05d3\u05d7\u05d9\u05dd \u05de\u05d4\u05e8 \u05e7\u05d3\u05d7\u05d9\u05dd \u05e7\u05d8\u05e0\u05d9\u05dd \u05d5\u05e2\u05de\u05d5\u05e7\u05d9\u05dd \u05d1\u05d7\u05d5\u05de\u05e8\u05d9\u05dd \u05e7\u05e9\u05d9\u05dd."],[126.0,"\u05d6\u05d4 \u05de\u05e9\u05de\u05e9 \u05dc\u05e7\u05d3\u05d7\u05d9 \u05d4\u05ea\u05d7\u05dc\u05d4 EDM-7 \u05d7\u05d5\u05d8, \u05d5\u05dc\u05e7\u05d3\u05d7\u05d9 \u05e7\u05d9\u05e8\u05d5\u05e8 \u05d1\u05dc\u05d4\u05d1\u05d9 \u05d8\u05d5\u05e8\u05d1\u05d9\u05e0\u05d4."],[132.0,"\u05d2\u05dd \u05db\u05d0\u05df \u05e0\u05e9\u05d0\u05e8\u05ea \u05e2\u05dc \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05e9\u05db\u05d1\u05d4 \u05de\u05d5\u05ea\u05db\u05ea \u05d3\u05e7\u05d4, \u05e2\u05dd \u05e1\u05d3\u05e7\u05d9\u05dd \u05d6\u05e2\u05d9\u05e8\u05d9\u05dd."],[137.0,"\u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05e8\u05d2\u05d9\u05e9\u05d9\u05dd \u05de\u05e1\u05d9\u05e8\u05d9\u05dd \u05d0\u05d5\u05ea\u05d4 \u05d1\u05d2\u05d9\u05de\u05d5\u05e8 \u05e2\u05d3\u05d9\u05df \u05d0\u05d5 \u05d1\u05dc\u05d9\u05d8\u05d5\u05e9."],[142.0,"\u05ea\u05d1\u05e0\u05d9\u05d5\u05ea \u05dc\u05d4\u05d6\u05e8\u05e7\u05ea \u05e4\u05dc\u05e1\u05d8\u05d9\u05e7, \u05d4\u05e9\u05d9\u05de\u05d5\u05e9 \u05d4\u05e0\u05e4\u05d5\u05e5 \u05d1\u05d9\u05d5\u05ea\u05e8."],[146.0,"\u05ea\u05d1\u05e0\u05d9\u05d5\u05ea \u05dc\u05d9\u05e6\u05d9\u05e7\u05ea \u05dc\u05d7\u05e5 \u05d5\u05dc\u05d7\u05d9\u05e9\u05d5\u05dc, \u05db\u05de\u05d5 \u05e9\u05e8\u05d0\u05d9\u05e0\u05d5 \u05d1\u05e4\u05e8\u05e7\u05d9\u05dd 1 2-1"],[151.0,"\u05db\u05d9\u05e1\u05d9\u05dd \u05d5\u05d7\u05e8\u05d9\u05e6\u05d9\u05dd \u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05de\u05d5\u05e7\u05e9\u05d9\u05dd, \u05d0\u05d7\u05e8\u05d9 \u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd."],[155.0,"\u05d5\u05d1\u05ea\u05e2\u05e9\u05d9\u05d9\u05ea \u05d4\u05ea\u05e2\u05d5\u05e4\u05d4, \u05d7\u05dc\u05e7\u05d9\u05dd \u05de\u05e1\u05d2\u05e1\u05d5\u05d2\u05d5\u05ea \u05e7\u05e9\u05d5\u05ea \u05d1\u05de\u05d9\u05d5\u05d7\u05d3."],[160.0,"\u05d2\u05dd \u05dc-\u05d5\u05d0\u05e1\u05dd \u05e9\u05d9\u05e7\u05d5\u05e2 \u05d9\u05e9 \u05db\u05dc\u05dc\u05d9 \u05ea\u05db\u05e0\u05d5\u05df."],[163.0,"\u05db\u05dc \u05e4\u05d9\u05e0\u05d4 \u05d7\u05d3\u05d4 \u05d0\u05d5 \u05e6\u05dc\u05e2 \u05e2\u05de\u05d5\u05e7\u05d4 \u05d3\u05d5\u05e8\u05e9\u05ea \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05e0\u05d5\u05e1\u05e4\u05ea, \u05d5\u05dc\u05db\u05df \u05db\u05d3\u05d0\u05d9 \u05dc\u05ea\u05ea \u05e8\u05d3\u05d9\u05d5\u05e1 \u05d0\u05d9\u05e4\u05d4 \u05e9\u05d0\u05e4\u05e9\u05e8."],[171.0,"\u05db\u05d3\u05d0\u05d9 \u05dc\u05d7\u05e9\u05d5\u05d1 \u05d0\u05d9\u05da \u05d5 \u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05ea\u05d9\u05db\u05e0\u05e1, \u05d5\u05d0\u05d9\u05da \u05d4\u05e9\u05de \u05d9\u05e9\u05d8\u05d5\u05e3 \u05d0\u05ea \u05d4\u05d7\u05dc\u05dc."],[176.0,"\u05d5\u05dc\u05e6\u05d9\u05d9\u05df \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d0\u05ea \u05d2\u05d9\u05de\u05d5\u05e8 \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05d4\u05e0\u05d3\u05e8\u05e9, \u05db\u05d9 \u05d2\u05d9\u05de\u05d5\u05e8 \u05e2\u05d3\u05d9\u05df \u05d9\u05d5\u05ea\u05e8 \u05d3\u05d5\u05e8\u05e9 \u05d9\u05d5\u05ea\u05e8 \u05d6\u05de\u05df \u05d5\u05d9\u05d5\u05ea\u05e8 \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d5\u05ea."],[184.0,"\u05d2\u05dd EDM-2 \u05e9\u05d9\u05e7\u05d5\u05e2 \u05d9\u05e9 \u05d1\u05e2\u05d9\u05d5\u05ea \u05d0\u05d5\u05e4\u05d9\u05d9\u05e0\u05d9\u05d5\u05ea."],[187.0,"\u05e9\u05d7\u05d9\u05e7\u05ea \u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4, \u05e9\u05de\u05e2\u05d2\u05dc\u05ea \u05e4\u05d9\u05e0\u05d5\u05ea \u05d5\u05de\u05e9\u05e0\u05d4 \u05de\u05d9\u05d3\u05d5\u05ea."],[191.0,"\u05e9\u05d8\u05d9\u05e4\u05d4 \u05dc\u05d0 \u05d8\u05d5\u05d1\u05d4 \u05d1\u05d7\u05dc\u05dc \u05e2\u05de\u05d5\u05e7, \u05e9\u05d2\u05d5\u05e8\u05de\u05ea \u05dc\u05ea\u05d4\u05dc\u05d9\u05da \u05dc\u05d0 \u05d9\u05e6\u05d9\u05d1 \u05d5\u05dc\u05db\u05d5\u05d5\u05d9\u05d5\u05ea \u05e2\u05dc \u05e4\u05e0\u05d9\u05d4\u05e9\u05d8\u05d7."],[198.0,"\u05d5\u05de\u05d9\u05d3\u05d5\u05ea \u05dc\u05d0 \u05e0\u05db\u05d5\u05e0\u05d5\u05ea, \u05db\u05e9\u05de\u05e8\u05d5\u05d5\u05d7 \u05d4\u05e0\u05d9\u05e6\u05d5\u05e5 \u05dc\u05d0 \u05d7\u05d5\u05e9\u05d1 \u05e0\u05db\u05d5\u05df."],[202.0,"\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8 \u05d5\u05d0\u05e1\u05dd \u05e9\u05d9\u05e7\u05d5\u05e2?"],[204.0,"\u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d5\u05ea: \u05ea\u05db\u05e0\u05d5\u05df, \u05db\u05e8\u05e1\u05d5\u05dd \u05d5\u05d1\u05d3\u05d9\u05e7\u05d4, \u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d6\u05d4 \u05d4\u05d7\u05dc\u05e7 \u05d4\u05d9\u05e7\u05e8 \u05d1\u05d9\u05d5\u05ea\u05e8."],[211.0,"\u05d4\u05d6\u05de\u05df: \u05d4\u05ea\u05d4\u05dc\u05d9\u05da \u05d0\u05d9\u05d8\u05d9, \u05d5\u05d7\u05dc\u05dc \u05d0\u05d7\u05d3 \u05d9\u05db\u05d5\u05dc \u05dc\u05e7\u05d7\u05ea \u05e9\u05e2\u05d5\u05ea \u05d5\u05d0\u05e3 \u05d9\u05de\u05d9\u05dd."],[217.0,"\u05de\u05e1\u05e4\u05e8 \u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d5\u05ea, \u05dc\u05e4\u05d9 \u05de\u05e1\u05e4\u05e8 \u05d4\u05e4\u05d9\u05e0\u05d5\u05ea \u05d5\u05d4\u05d2\u05d9\u05de\u05d5\u05e8 \u05d4\u05e0\u05d3\u05e8\u05e9\u05e9."],[221.0,"\u05de\u05e6\u05d3 \u05e9\u05e0\u05d9, \u05d4\u05de\u05db\u05d5\u05e0\u05d4 \u05e2\u05d5\u05d1\u05d3\u05ea \u05dc\u05d1\u05d3, \u05d5\u05d1\u05d7\u05dc\u05e7 \u05de\u05d5\u05e7\u05e9\u05d4 \u05d0\u05d9\u05df \u05dc\u05e8 \u05ea\u05d7\u05dc\u05d9\u05e3."],[227.0,"\u05d5\u05d0\u05e1\u05dd \u05e9\u05d9\u05e7\u05d5\u05e2 \u05de\u05e2\u05ea\u05d9\u05e7 \u05d0\u05ea \u05e6\u05d5\u05e8\u05ea \u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05dc\u05ea\u05d5\u05da \u05d4\u05d7\u05d5\u05de\u05e8, \u05d1\u05db\u05dc \u05e7\u05e9\u05d9\u05d5\u05ea."],[233.0,"\u05d4\u05d5\u05d0 \u05d0\u05d9\u05d8\u05d9, \u05d5\u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d5\u05ea \u05d9\u05e7\u05e8\u05d5\u05ea, \u05d0\u05d1\u05dc \u05d1\u05db\u05d9\u05e1\u05d9\u05dd \u05e2\u05d9\u05d5\u05d5\u05e8\u05d9\u05dd \u05d5\u05d1\u05e4\u05d9\u05e0\u05d5\u05ea \u05d7\u05d3\u05d5\u05ea \u05d1\u05d7\u05d5\u05de\u05e8 \u05de\u05d5\u05e7\u05e9\u05d4, \u05d0\u05d9\u05df \u05dc\u05d5 \u05ea\u05d7\u05dc\u05d9\u05e3."],[241.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0: \u05dc\u05d9\u05d9\u05d6\u05e8."]]};
window.MH_TR["\u05e4\u05e8\u05e718_\u05dc\u05d9\u05d9\u05d6\u05e8"]={"t":"\u05dc\u05d9\u05d9\u05d6\u05e8","l":[[1.0,"\u05d7\u05dc\u05e7\u05d9 \u05e4\u05d7 \u05d1\u05db\u05dc \u05e6\u05d5\u05e8\u05d4, \u05d9\u05e9\u05e8 \u05de\u05d4\u05e9\u05e8\u05d8\u05d5\u05d8, \u05d1\u05dc\u05d9 \u05db\u05dc\u05d9 \u05d5\u05d1\u05dc\u05d9 \u05ea\u05d1\u05e0\u05d9\u05ea."],[6.0,"\u05d6\u05d4 \u05d7\u05d9\u05ea\u05d5\u05da \u05d1\u05dc\u05d9\u05d9\u05d6\u05e8, \u05d0\u05d7\u05d3 \u05d4\u05ea\u05d4\u05dc\u05d9\u05db\u05d9\u05dd \u05d4\u05e0\u05e4\u05d5\u05e6\u05d9\u05dd \u05d1\u05d9\u05d5\u05ea\u05e8 \u05d4\u05d9\u05d5\u05dd \u05d1\u05d1\u05ea\u05d9 \u05de\u05dc\u05d0\u05db\u05d4."],[11.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d6\u05d4 \u05e0\u05d1\u05d9\u05df \u05d0\u05d9\u05da \u05e7\u05e8\u05df \u05d0\u05d5\u05e8 \u05d7\u05d5\u05ea\u05db\u05ea \u05de\u05ea\u05db\u05ea, \u05de\u05d4 \u05d4\u05dc\u05d9\u05d9\u05d6\u05e8 \u05e0\u05d5\u05ea\u05df, \u05d5\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8 \u05d0\u05d5\u05ea\u05d5."],[19.0,"\u05e7\u05e8\u05df \u05dc\u05d9\u05d9\u05d6\u05e8 \u05de\u05de\u05d5\u05e7\u05d3\u05ea \u05dc\u05e0\u05e7\u05d5\u05d3\u05d4 \u05d6\u05e2\u05d9\u05e8\u05d4, \u05d5\u05e9\u05dd \u05e6\u05e4\u05d9\u05e4\u05d5\u05ea \u05d4\u05d0\u05e0\u05e8\u05d2\u05d9\u05d4 \u05e2\u05e6\u05d5\u05de\u05d4."],[24.0,"\u05d4\u05de\u05ea\u05db\u05ea \u05e0\u05de\u05e1\u05d4, \u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05de\u05ea\u05d0\u05d3\u05d4, \u05dc\u05d0\u05d5\u05e8\u05da \u05e7\u05d5 \u05d4\u05d7\u05d9\u05ea\u05d5\u05da."],[29.0,"\u05d2 \u05e2\u05d6\u05e8 \u05e0\u05d5\u05e9\u05e3 \u05d0\u05ea \u05d4\u05de\u05ea\u05db\u05ea \u05d4\u05de\u05d5\u05ea\u05db\u05ea \u05d4\u05d7\u05d5\u05e6\u05d4 \u05d3\u05e8\u05da \u05d4\u05d7\u05e8\u05d9\u05e5."],[34.0,"\u05d1\u05e4\u05dc\u05d3\u05d4 \u05e8\u05d2\u05d9\u05dc\u05d4 \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05d7\u05de\u05e6\u05df: \u05d4\u05d5\u05d0 \u05de\u05d2\u05d9\u05d1 \u05e2\u05dd \u05d4\u05de\u05ea\u05db\u05ea \u05d5\u05de\u05d5\u05e1\u05d9\u05e3 \u05d7\u05d5\u05dd, \u05d5\u05dc\u05db\u05df \u05d4\u05d7\u05d9\u05ea\u05d5\u05da \u05de\u05d4\u05d9\u05e8, \u05d0\u05d1\u05dc \u05d4\u05e9\u05e4\u05d4 \u05de\u05ea\u05d7\u05de\u05e6\u05e0\u05ea."],[43.0,"\u05d1\u05e0\u05d9\u05e8\u05d5\u05e1\u05d8\u05d4 \u05d5\u05d1\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05d7\u05e0\u05e7\u05df \u05d1\u05dc\u05d7\u05e5 \u05d2\u05d1\u05d5\u05d4: \u05d4\u05e9\u05e4\u05d4 \u05e0\u05e7\u05d9\u05d9\u05d4 \u05d5\u05de\u05d1\u05e8\u05d9\u05e7\u05d4, \u05d0\u05d1\u05dc \u05e6\u05e8\u05d9\u05db\u05ea \u05d4\u05d2\u05d6 \u05d2\u05d3\u05d5\u05dc\u05d4."],[51.0,"\u05d5\u05d0\u05d5\u05d5\u05d9\u05e8 \u05d3\u05d7\u05d5\u05e1 \u05d4\u05d5\u05d0 \u05e4\u05e9\u05e8\u05d4 \u05d6\u05d5\u05dc\u05d4, \u05d1\u05e4\u05d7 \u05d3\u05e7."],[55.0,"\u05d4\u05d9\u05d5\u05dd \u05e8\u05d5\u05d1 \u05d7\u05d9\u05ea\u05d5\u05da \u05d4\u05de\u05ea\u05db\u05d5\u05ea \u05e0\u05e2\u05e9\u05d4 \u05d1\u05dc\u05d9\u05d9\u05d6\u05e8 fiber: \u05d9\u05e2\u05d9\u05dc, \u05de\u05d4\u05d9\u05e8, \u05d5\u05de\u05e1\u05d5\u05d2\u05dc \u05dc\u05d7\u05ea\u05d5\u05da \u05d2\u05dd \u05e0\u05d7\u05d5\u05e9\u05ea \u05d5\u05e4\u05dc\u05d9\u05d6, \u05e9\u05de\u05d7\u05d6\u05d9\u05e8\u05d9\u05dd \u05d0\u05d5\u05e8."],[64.0,"\u05dc\u05d9\u05d9\u05d6\u05e8 602 \u05d4\u05d5\u05d0 \u05d4\u05d3\u05d5\u05e8 \u05d4\u05e7\u05d5\u05d3\u05dd, \u05d5\u05d4\u05d5\u05d0 \u05e2\u05d3\u05d9\u05d9\u05df \u05e0\u05e4\u05d5\u05e5 \u05dc\u05d7\u05d9\u05ea\u05d5\u05da \u05e2\u05e5, \u05d0\u05e7\u05e8\u05d9\u05dc\u05d9\u05e7 \u05d5\u05d7\u05d5\u05de\u05e8\u05d9\u05dd \u05dc\u05d0 \u05de\u05ea\u05db\u05ea\u05d9\u05d9\u05dd."],[72.0,"\u05e4\u05dc\u05d3\u05d4, \u05e0\u05d9\u05e8\u05d5\u05e1\u05d8\u05d4 \u05d5\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd, \u05de\u05e4\u05d7 \u05d3\u05e7 \u05e9\u05dc \u05d7\u05e6\u05d9 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8 \u05d5\u05e2\u05d3 \u05dc\u05d5\u05d7\u05d5\u05ea \u05e2\u05d1\u05d9\u05dd."],[78.0,"\u05de\u05db\u05d5\u05e0\u05d5\u05ea \u05d7\u05d6\u05e7\u05d5\u05ea \u05d7\u05d5\u05ea\u05db\u05d5\u05ea \u05e4\u05dc\u05d3\u05d4 \u05d1\u05e2\u05d5\u05d1\u05d9 \u05e9\u05dc 25 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8 \u05d5\u05d9\u05d5\u05ea\u05e8."],[83.0,"\u05d4\u05d7\u05e8\u05d9\u05e5 \u05e6\u05e8 \u05de\u05d0\u05d5\u05d3, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05e2\u05e9\u05d9\u05e8\u05d9\u05d5\u05ea \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8."],[87.0,"\u05d4\u05d3\u05d9\u05d5\u05e7 \u05d8\u05d5\u05d1, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1\u05e1\u05d1\u05d9\u05d1\u05d5\u05ea \u05e2\u05e9\u05d9\u05e8\u05d9\u05ea \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8."],[91.0,"\u05d5\u05d0\u05d6\u05d5\u05e8 \u05d4\u05d4\u05e9\u05e4\u05e2\u05d4 \u05d4\u05ea\u05e8\u05de\u05d9\u05ea \u05e6\u05e8, \u05db\u05d9 \u05d4\u05d7\u05d5\u05dd \u05de\u05e8\u05d5\u05db\u05d6."],[96.0,"\u05d1\u05de\u05db\u05d5\u05e0\u05d4 \u05e9\u05d8\u05d5\u05d7\u05d4, \u05e8\u05d0\u05e9 \u05d4\u05d7\u05d9\u05ea\u05d5\u05da \u05d6\u05d6 \u05de\u05e2\u05dc \u05d4\u05dc\u05d5\u05d7, \u05d5\u05d4\u05ea\u05e0\u05d5\u05e2\u05d4 \u05e0\u05e9\u05dc\u05d8\u05ea CNC-2."],[102.0,"\u05ea\u05d5\u05db\u05e0\u05ea \u2026 \u05de\u05e1\u05d3\u05e8\u05ea \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05e2\u05dc \u05d4\u05dc\u05d5\u05d7 \u05db\u05da \u05e9\u05d9\u05d9\u05e9\u05d0\u05e8 \u05db\u05de\u05d4 \u05e9\u05e4\u05d7\u05d5\u05ea \u05e4\u05d7\u05ea."],[107.0,"\u05de\u05d7\u05dc\u05d9\u05e3 \u05dc\u05d5\u05d7\u05d5\u05ea \u05de\u05d0\u05e4\u05e9\u05e8 \u05dc\u05d8\u05e2\u05d5\u05df \u05dc\u05d5\u05d7 \u05d7\u05d3\u05e9\u05d5 \u05d1\u05d6\u05de\u05df \u05e9\u05d4\u05de\u05db\u05d5\u05e0\u05d4 \u05d7\u05d5\u05ea\u05db\u05ea."],[112.0,"\u05d5\u05d9\u05e9 \u05de\u05db\u05d5\u05e0\u05d5\u05ea \u05dc\u05d9\u05d9\u05d6\u05e8 \u05dc\u05e6\u05d9\u05e0\u05d5\u05e8\u05d5\u05ea \u05d5\u05dc\u05e4\u05e8\u05d5\u05e4\u05d9\u05dc\u05d9\u05dd, \u05e9\u05d7\u05d5\u05ea\u05db\u05d5\u05ea \u05d2\u05dd \u05e7\u05d3\u05d7\u05d9\u05dd \u05d5\u05d7\u05e8\u05d9\u05e6\u05d9\u05dd \u05d1\u05d3\u05e4\u05e0\u05d5\u05ea."],[119.0,"\u05e2\u05dc \u05d4\u05e9\u05e4\u05d4 \u05e8\u05d5\u05d0\u05d9\u05dd \u05e4\u05e1\u05d9\u05dd \u05d3\u05e7\u05d9\u05dd, \u05d5\u05d1\u05e4\u05d7 \u05e2\u05d1\u05d4 \u05d4\u05dd \u05d1\u05d5\u05dc\u05d8\u05d9\u05dd \u05d9\u05d5\u05ea\u05e8."],[124.0,"\u05d1\u05ea\u05d7\u05ea\u05d9\u05ea \u05d9\u05db\u05d5\u05dc\u05d4 \u05dc\u05d4\u05d9\u05e9\u05d0\u05e8 \u05de\u05ea\u05db\u05ea \u05de\u05d5\u05ea\u05db\u05ea \u05e9\u05d4\u05ea\u05e7\u05e9\u05ea\u05d4, dross."],[129.0,"\u05d1\u05e0\u05e7\u05d5\u05d3\u05d4 \u05e9\u05d1\u05d4 \u05d4\u05e7\u05e8\u05df \u05d7\u05d5\u05d3\u05e8\u05ea \u05dc\u05e4\u05d7 \u05e0\u05e9\u05d0\u05e8 \u05e1\u05d9\u05de\u05df \u05e7\u05d8\u05df."],[133.0,"\u05d5\u05d1\u05e4\u05d7 \u05e2\u05d1\u05d4 \u05d4\u05e9\u05e4\u05d4 \u05de\u05e2\u05d8 \u05de\u05e9\u05d5\u05e4\u05e2\u05ea."],[136.0,"\u05e1\u05d9\u05de\u05d5\u05df \u05d5\u05d7\u05e8\u05d9\u05d8\u05d4: \u05de\u05e1\u05e4\u05e8\u05d9\u05dd \u05e1\u05d9\u05d3\u05d5\u05e8\u05d9\u05d9\u05dd, \u05dc\u05d5\u05d2\u05d5 \u05d5\u05e7\u05d5\u05d3\u05d9\u05dd, \u05d1\u05dc\u05d9 \u05de\u05d2\u05e2 \u05d5\u05d1\u05dc\u05d9 \u05d3\u05d9\u05d5."],[143.0,"\u05e8\u05d9\u05ea\u05d5\u05da \u05d1\u05dc\u05d9\u05d9\u05d6\u05e8: \u05ea\u05e4\u05e8 \u05e6\u05e8 \u05d5\u05e2\u05de\u05d5\u05e7, \u05e2\u05dd \u05de\u05e2\u05d8 \u05e2\u05d9\u05d5\u05d5\u05ea."],[147.0,"\u05d5\u05e9\u05d9\u05de\u05d5\u05e9\u05d9\u05dd \u05de\u05ea\u05e7\u05d3\u05de\u05d9\u05dd, \u05db\u05de\u05d5 \u05e6\u05d9\u05e4\u05d5\u05d9 \u05d5\u05d4\u05d3\u05e4\u05e1\u05d4 \u05d1\u05ea\u05dc\u05ea \u05de\u05de\u05d3 \u05de\u05de\u05ea\u05db\u05ea."],[153.0,"\u05d2\u05dd \u05dc\u05d7\u05d9\u05ea\u05d5\u05da \u05d1\u05dc\u05d9\u05d9\u05d6\u05e8 \u05d9\u05e9 \u05db\u05dc\u05dc\u05d9 \u05ea\u05db\u05e0\u05d5\u05df."],[156.0,"\u05e7\u05d3\u05d7 \u05e7\u05d8\u05df \u05de\u05e2\u05d5\u05d1\u05d9 \u05d4\u05e4\u05d7 \u05d9\u05d5\u05e6\u05d0 \u05e4\u05d7\u05d5\u05ea \u05d0\u05d9\u05db\u05d5\u05ea\u05d9, \u05d5\u05d1\u05e4\u05d7 \u05e2\u05d1\u05d4 \u05e2\u05d3\u05d9\u05e3 \u05dc\u05e7\u05d3\u05d5\u05d7 \u05d0\u05d5\u05ea\u05d5."],[161.0,"\u05e4\u05e8\u05d8\u05d9\u05dd \u05e7\u05d8\u05e0\u05d9\u05dd \u05de\u05d0\u05d5\u05d3 \u05de\u05ea\u05d7\u05de\u05de\u05d9\u05dd \u05d5\u05e2\u05dc\u05d5\u05dc\u05d9\u05dd \u05dc\u05d4\u05d9\u05e9\u05e8\u05e3."],[165.0,"\u05de\u05e9\u05d0\u05d9\u05e8\u05d9\u05dd \u05d7\u05d9\u05d1\u05d5\u05e8\u05d9\u05dd \u05d6\u05e2\u05d9\u05e8\u05d9\u05dd, 5\u05d6\u05d7\u05d5\u05e1\u05df\u05e1\u05d6\u05e1\u05d5\u05e8\u05d7, \u05e9\u05de\u05d7\u05d6\u05d9\u05e7\u05d9\u05dd \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05d1\u05dc\u05d5\u05d7 \u05e2\u05d3 \u05e1\u05d5\u05e3 \u05d4\u05d7\u05d9\u05ea\u05d5\u05da."],[172.0,"\u05d7\u05dc\u05e7\u05d9\u05dd \u05e2\u05dd \u05e7\u05d5 \u05de\u05e9\u05d5\u05ea\u05e3 \u05d0\u05e4\u05e9\u05e8 \u05dc\u05d7\u05ea\u05d5\u05da \u05d1\u05d7\u05d9\u05ea\u05d5\u05da \u05d0\u05d7\u05d3, \u05d5\u05dc\u05d7\u05e1\u05d5\u05da \u05d6\u05de\u05df \u05d5\u05d7\u05d5\u05de\u05e8."],[177.0,"\u05d5\u05db\u05d3\u05d0\u05d9 \u05dc\u05d6\u05db\u05d5\u05e8 \u05e9\u05d1\u05d7\u05d9\u05ea\u05d5\u05da \u05d1\u05d7\u05de\u05e6\u05df \u05e0\u05e9\u05d0\u05e8\u05ea \u05e9\u05db\u05d1\u05ea \u05ea\u05d7\u05de\u05d5\u05e6\u05ea \u05e2\u05dc \u05d4\u05e9\u05e4\u05d4, \u05e9\u05d9\u05db\u05d5\u05dc\u05d4 \u05dc\u05d4\u05e4\u05e8\u05d9\u05e2 \u05dc\u05e6\u05d1\u05e2 \u05d5\u05dc\u05e8\u05d9\u05ea\u05d5\u05da."],[185.0,"\u05d2\u05dd \u05d1\u05dc\u05d9\u05d9\u05d6\u05e8 \u05d9\u05e9 \u05d1\u05e2\u05d9\u05d5\u05ea \u05d0\u05d5\u05e4\u05d9\u05d9\u05e0\u05d9\u05d5\u05ea."],[188.0,"5 \u05d1\u05ea\u05d7\u05ea\u05d9\u05ea \u05d4\u05d7\u05d9\u05ea\u05d5\u05da, \u05db\u05e9\u05d4\u05d2\u05d6 \u05d0\u05d5 \u05d4\u05de\u05d9\u05e7\u05d5\u05d3 \u05dc\u05d0 \u05e0\u05db\u05d5\u05e0\u05d9\u05dd."],[192.0,"\u05e9\u05e8\u05d9\u05e4\u05d4 \u05d1\u05e4\u05d9\u05e0\u05d5\u05ea \u05d7\u05d3\u05d5\u05ea \u05d1\u05e4\u05d7 \u05e2\u05d1\u05d4."],[195.0,"\u05e2\u05d9\u05d5\u05d5\u05ea \u05e9\u05dc \u05d7\u05dc\u05e7\u05d9\u05dd \u05d3\u05e7\u05d9\u05dd \u05d0\u05d5 \u05e7\u05d8\u05e0\u05d9\u05dd \u05de\u05d4\u05d7\u05d5\u05dd."],[198.0,"\u05d5\u05d7\u05d5\u05de\u05e8\u05d9\u05dd \u05de\u05d7\u05d6\u05d9\u05e8\u05d9 \u05d0\u05d5\u05e8, \u05e9\u05d3\u05d5\u05e8\u05e9\u05d5\u05d9\u05dd \u05dc\u05d9\u05d9\u05d6\u05e8 \u05de\u05ea\u05d0\u05d9\u05dd."],[203.0,"\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8 \u05d7\u05d9\u05ea\u05d5\u05da \u05d1\u05dc\u05d9\u05d9\u05d6\u05e8?"],[205.0,"\u05d6\u05de\u05df \u05d4\u05de\u05db\u05d5\u05e0\u05d4: \u05d0\u05d5\u05e8\u05da \u05d4\u05d7\u05d9\u05ea\u05d5\u05da, \u05e2\u05d5\u05d1\u05d9 \u05d4\u05e4\u05d7 \u05d5\u05de\u05e1\u05e4\u05e8\u05e0\u05e7\u05d5\u05d3\u05d5\u05ea \u05d4\u05d7\u05d3\u05d9\u05e8\u05d4."],[210.0,"\u05d2\u05d6, \u05d1\u05e2\u05d9\u05e7\u05e8 \u05d7\u05e0\u05e7\u05df \u05d1\u05db\u05de\u05d5\u05d9\u05d5\u05ea \u05d2\u05d3\u05d5\u05dc\u05d5\u05ea."],[214.0,"\u05e0\u05d9\u05e6\u05d5\u05dc \u05d4\u05dc\u05d5\u05d7: \u05db\u05de\u05d4 \u05d8\u05d5\u05d1 \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05de\u05e1\u05d5\u05d3\u05e8\u05d9\u05dd \u05e2\u05dc\u05d9\u05d5."],[218.0,"\u05d5\u05d4\u05e1\u05e8\u05ea dross \u05d5\u05d2\u05e8\u05d3, \u05d0\u05dd \u05e6\u05e8\u05d9\u05da."],[221.0,"\u05de\u05e6\u05d3 \u05e9\u05e0\u05d9, \u05d0\u05d9\u05df \u05db\u05dc\u05d9\u05dd \u05d5\u05d0\u05d9\u05df \u05ea\u05d1\u05e0\u05d9\u05d5\u05ea, \u05d5\u05dc\u05db\u05df \u05dc\u05d9\u05d9\u05d6\u05e8 \u05de\u05d5\u05e9\u05dc\u05dd \u05dc\u05d0\u05d1\u05d8\u05d9\u05e4\u05d5\u05e1\u05d9\u05dd \u05d5\u05dc\u05e1\u05d3\u05e8\u05d5\u05ea \u05e7\u05d8\u05e0\u05d5\u05ea \u05d5\u05d1\u05d9\u05e0\u05d5\u05e0\u05d9\u05d5\u05ea."],[229.0,"\u05dc\u05d9\u05d9\u05d6\u05e8 \u05d7\u05d5\u05ea\u05da \u05db\u05de\u05e2\u05d8 \u05db\u05dc \u05e6\u05d5\u05e8\u05d4 \u05de\u05e4\u05d7, \u05de\u05d4\u05e8, \u05d1\u05d3\u05d9\u05d5\u05e7 \u05d8\u05d5\u05d1 \u05d5\u05d1\u05dc\u05d9 \u05db\u05dc\u05d9\u05dd."],[235.0,"\u05d4\u05e2\u05d5\u05d1\u05d9, \u05d4\u05d2\u05d6 \u05d5\u05d0\u05d5\u05e8\u05da \u05d4\u05d7\u05d9\u05ea\u05d5\u05da \u05e7\u05d5\u05d1\u05e2\u05d9\u05dd \u05d0\u05ea \u05d4\u05de\u05d7\u05d9\u05e8."],[239.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0: \u05d7\u05d9\u05ea\u05d5\u05da \u05d1\u05de\u05d9\u05dd."]]};
window.MH_TR["\u05e4\u05e8\u05e719_\u05d7\u05d9\u05ea\u05d5\u05da_\u05d1\u05de\u05d9\u05dd"]={"t":"\u05d7\u05d9\u05ea\u05d5\u05da \u05d1\u05de\u05d9\u05dd","l":[[1.0,"\u05d2\u05d5\u05de\u05d9, \u05d0\u05d1\u05df, \u05d6\u05db\u05d5\u05db\u05d9\u05ea, \u05d7\u05d5\u05de\u05e8\u05d9\u05dd \u05de\u05e8\u05d5\u05db\u05d1\u05d9\u05dd, \u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd \u05d5\u05dc\u05d5\u05d7\u05d5\u05ea \u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05e2\u05d1\u05d9\u05dd."],[7.0,"\u05d0\u05ea \u05db\u05d5\u05dc\u05dd \u05d0\u05e4\u05e9\u05d5\u05e8 \u05dc\u05d7\u05ea\u05d5\u05da \u05d1\u05d0\u05d5\u05ea\u05d4 \u05de\u05db\u05d5\u05e0\u05d4, \u05d1\u05e2\u05d6\u05e8\u05ea \u05de\u05d9\u05dd."],[11.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d6\u05d4 \u05e0\u05d1\u05d9\u05df \u05d0\u05d9\u05da \u05e1\u05d9\u05dc\u05d5\u05df \u05de\u05d9\u05dd \u05d7\u05d5\u05ea\u05da, \u05de\u05d4 \u05d4\u05d5\u05d0 \u05e0\u05d5\u05ea\u05df \u05e9\u05e9\u05d5\u05dd \u05ea\u05d4\u05dc\u05d9\u05da \u05d0\u05d7\u05e8 \u05dc\u05d0 \u05e0\u05d5\u05ea\u05df, \u05d5\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8 \u05d0\u05d5\u05ea\u05d5."],[19.0,"\u05de\u05e9\u05d0\u05d1\u05d4 \u05d3\u05d5\u05d7\u05e1\u05ea \u05de\u05d9\u05dd \u05dc\u05dc\u05d7\u05e5 \u05e2\u05e6\u05d5\u05dd, \u05d1\u05e1\u05d1\u05d9\u05d1\u05d5\u05ea 4,000 \u05d1\u05e8."],[24.0,"\u05d4\u05de\u05d9\u05dd \u05d9\u05d5\u05e6\u05d0\u05d9\u05dd \u05d3\u05e8\u05da \u05e4\u05ea\u05d7 \u05d6\u05e2\u05d9\u05e8 \u05d1\u05d0\u05d1\u05df \u05d7\u05df, \u05d5\u05e0\u05d4\u05d9\u05d9\u05dd \u05e1\u05d9\u05dc\u05d5\u05df \u05d3\u05e7 \u05d5\u05ea\u05d7\u05d4\u05d9\u05e8 \u05de\u05d0\u05d5\u05d3."],[30.0,"\u05e1\u05d9\u05dc\u05d5\u05df \u05de\u05d9\u05dd \u05e0\u05e7\u05d9 \u05d7\u05d5\u05ea\u05da \u05d7\u05d5\u05de\u05e8\u05d9\u05dd \u05e8\u05db\u05d9\u05dd: \u05d2\u05d5\u05de\u05d9, \u05e1\u05e4\u05d5\u05d2, \u05d0\u05d8\u05de\u05d9\u05dd \u05d5\u05d0\u05e4\u05d9\u05dc\u05d5 \u05de\u05d6\u05d5\u05df."],[37.0,"\u05db\u05d3\u05d9 \u05dc\u05d7\u05ea\u05d5\u05da \u05de\u05ea\u05db\u05ea, \u05d0\u05d1\u05df \u05d0\u05d5 \u05d6\u05db\u05d5\u05db\u05d9\u05ea, \u05de\u05d5\u05e1\u05d9\u05e4\u05d9\u05dd \u05dc\u05e1\u05d9\u05dc\u05d5\u05df \u05d7\u05d5\u05dc \u05e9\u05d5\u05d7\u05e7, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc garnet."],[44.0,"\u05d4\u05d7\u05d5\u05dc \u05de\u05ea\u05e2\u05e8\u05d1\u05d1 \u05e2\u05dd \u05d4\u05de\u05d9\u05dd \u05d1\u05e6\u05d9\u05e0\u05d5\u05e8 \u05e6\u05e8, \u05d5\u05d4\u05d2\u05e8\u05d2\u05d9\u05e8\u05d9\u05dd \u05d4\u05dd \u05d0\u05dc\u05d4 \u05e9\u05d7\u05d5\u05ea\u05e0\u05d9\u05dd."],[50.0,"\u05d6\u05d4 \u05ea\u05d4\u05dc\u05d9\u05da \u05e7\u05e8: \u05d0\u05d9\u05df \u05d0\u05d6\u05d5\u05e8 \u05de\u05d5\u05e9\u05e4\u05e2 \u05d7\u05d5\u05dd, \u05d0\u05d9\u05df \u05d4\u05ea\u05e7\u05e2\u05d5\u05d5\u05ea, \u05d5\u05d0\u05d9\u05df \u05e2\u05d9\u05d5\u05d5\u05ea \u05de\u05d7\u05d5\u05dd."],[56.0,"\u05dc\u05db\u05df \u05d4\u05d5\u05d0 \u05de\u05ea\u05d0\u05d9\u05dd \u05dc\u05d7\u05d5\u05de\u05e8\u05d9\u05dd \u05e8\u05d2\u05d9\u05e9\u05d9\u05dd \u05dc\u05d7\u05d5\u05dd, \u05db\u05de\u05d5 \u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd, \u05e4\u05dc\u05d3\u05d4 \u05de\u05d5\u05e7\u05e9\u05d9\u05ea \u05d5\u05de\u05e8\u05d5\u05db\u05d1\u05d9\u05dd."],[62.0,"\u05d4\u05d5\u05d0 \u05d7\u05d5\u05ea\u05da \u05db\u05de\u05e2\u05d8 \u05db\u05dc \u05d7\u05d5\u05de\u05e8, \u05d2\u05dd \u05e2\u05d1\u05d4 \u05de\u05d0\u05d5\u05d3, \u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d9\u05d5\u05ea\u05e8 \u05de-100 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8."],[68.0,"\u05d5\u05d0\u05d9\u05df \u05db\u05dc\u05d9\u05dd: \u05db\u05de\u05d5 \u05d1\u05dc\u05d9\u05d9\u05d6\u05e8, \u05e2\u05d5\u05d1\u05e8\u05d9\u05dd \u05d9\u05e9\u05e8 \u05de\u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05dc\u05d7\u05d9\u05ea\u05d5\u05da."],[73.0,"\u05d1\u05e4\u05d7 \u05d3\u05e7, \u05d7\u05d9\u05ea\u05d5\u05da \u05d1\u05de\u05d9\u05dd \u05d0\u05d9\u05d8\u05d9 \u05d1\u05d4\u05e8\u05d1\u05d4 \u05de\u05dc\u05d9\u05d9\u05d6\u05e8."],[78.0,"\u05d4\u05d7\u05e8\u05d9\u05e5 \u05e8\u05d7\u05d1 \u05d9\u05d5\u05ea\u05e8, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1\u05e1\u05d1\u05d9\u05d1\u05d5\u05ea \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8."],[82.0,"\u05d1\u05d7\u05d5\u05de\u05e8 \u05e2\u05d1\u05d4 \u05d4\u05e1\u05d9\u05dc\u05d5\u05df \u05de\u05ea\u05e4\u05d6\u05e8: \u05d4\u05d3\u05d5\u05e4\u05df \u05d9\u05d5\u05e6\u05d0\u05ea \u05de\u05e9\u05d5\u05e4\u05e2\u05ea, \u05d5\u05d4\u05e1\u05d9\u05dc\u05d5\u05df \u05e0\u05d2\u05e8\u05e8 \u05de\u05d0\u05d7\u05d5\u05e8 \u05d5\u05de\u05e2\u05d2\u05dc \u05e4\u05d9\u05e0\u05d5\u05ea \u05d1\u05ea\u05d7\u05ea\u05d9\u05ea."],[90.0,"\u05e8\u05d0\u05e9\u05d9\u05dd \u05de\u05ea\u05e7\u05d3\u05de\u05d9\u05dd \u05de\u05d8\u05d9\u05dd \u05d0\u05ea \u05d4\u05e1\u05d9\u05dc\u05d5\u05df \u05d5\u05de\u05ea\u05e7\u05e0\u05d9\u05dd \u05d0\u05ea \u05d4\u05e9\u05d9\u05e4\u05d5\u05e2."],[94.0,"\u05d4\u05d3\u05d9\u05d5\u05e7 \u05d4\u05d8\u05d5\u05d1 \u05d4\u05d5\u05d0 \u05d1\u05e1\u05d1\u05d9\u05d1\u05d5\u05ea \u05e2\u05e9\u05d9\u05e8\u05d9\u05ea \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8."],[98.0,"\u05d5\u05d7\u05d4 \u05ea\u05d4\u05dc\u05d9\u05da \u05e8\u05d8\u05d5\u05d1 \u05d5\u05e8\u05d5\u05e2\u05e9, \u05e2\u05dd \u05d7\u05d5\u05dc \u05e9\u05e6\u05e8\u05d9\u05da \u05dc\u05e4\u05e0\u05d5\u05ea."],[102.0,"\u05d4\u05d7\u05dc\u05e7 \u05de\u05d5\u05e0\u05d7 \u05de\u05e2\u05dc \u05d0\u05de\u05d1\u05d8 \u05de\u05d9\u05dd, \u05e9\u05d1\u05d5\u05dc\u05dd \u05d0\u05ea \u05d4\u05e1\u05d9\u05dc\u05d5\u05df \u05d0\u05d7\u05e8\u05d9 \u05e9\u05e2\u05d1\u05e8."],[107.0,"\u05e8\u05d0\u05e9 \u05d4\u05d7\u05d9\u05ea\u05d5\u05da \u05d6\u05d6 CNC-2, \u05d5\u05d1\u05de\u05db\u05d5\u05e0\u05d5\u05ea \u05de\u05e1\u05d5\u05d9\u05de\u05d5\u05ea \u05d2\u05dd \u05e0\u05d5\u05d8\u05d4, \u05db\u05d3\u05d9 \u05dc\u05d7\u05ea\u05d5\u05da \u05e9\u05d9\u05e4\u05d5\u05e2\u05d9\u05dd."],[113.0,"\u05d5\u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05d4\u05d7\u05d9\u05ea\u05d5\u05da \u05e0\u05d1\u05d7\u05e8\u05ea \u05dc\u05e4\u05d9 \u05d4\u05d7\u05d5\u05de\u05e8, \u05d4\u05e2\u05d5\u05d1\u05d9 \u05d5\u05d0\u05d9\u05db\u05d5\u05ea \u05d4\u05e9\u05e4\u05d4 \u05d4\u05e0\u05d3\u05e8\u05e9\u05ea."],[119.0,"\u05d0\u05d8\u05de\u05d9\u05dd, \u05d2\u05d5\u05de\u05d9 \u05d5\u05e1\u05e4\u05dc\u05d5\u05d2."],[122.0,"\u05de\u05e9\u05d8\u05d7\u05d9\u05d0\u05d1\u05df \u05d4\u05db\u05d5\u05db\u05d9\u05ea."],[124.0,"\u05dc\u05d5\u05d7\u05d5\u05ea \u05e2\u05d1\u05d9\u05dd \u05e9\u05dc \u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05d5\u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd."],[127.0,"\u05d7\u05d5\u05de\u05e8\u05d9\u05dd \u05de\u05e8\u05d5\u05db\u05d1\u05d9\u05dd \u05d1\u05ea\u05e2\u05d5\u05e4\u05dc\u05d4."],[129.0,"\u05d5\u05d7\u05dc\u05e7\u05d9\u05dd \u05de\u05e4\u05dc\u05d3\u05d4 \u05de\u05d5\u05e7\u05e9\u05d9\u05ea, \u05e9\u05d0\u05e1\u05d5\u05e8 \u05dc\u05d7\u05de\u05dd."],[133.0,"\u05d2\u05dd \u05dc\u05d7\u05d9\u05ea\u05d5\u05da \u05d1\u05de\u05d9\u05dd \u05d9\u05e9 \u05db\u05dc\u05dc\u05d9 \u05ea\u05db\u05e0\u05d5\u05df."],[136.0,"\u05e4\u05d9\u05e0\u05d4 \u05e4\u05e0\u05d9\u05de\u05d9\u05ea \u05ea\u05de\u05d9\u05d3 \u05ea\u05d4\u05d9\u05d4 \u05e2\u05dd \u05e8\u05d3\u05d9\u05d5\u05e1, \u05d1\u05e2\u05e8\u05da \u05d7\u05e6\u05d9 \u05de\u05e8\u05d5\u05d7\u05d1 \u05d4\u05d7\u05e8\u05d9\u05e5."],[141.0,"\u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05e2\u05d1\u05d9\u05dd \u05e6\u05e8\u05d9\u05da \u05dc\u05e7\u05d7\u05ea \u05d1\u05d7\u05e9\u05d1\u05d5\u05df \u05e9\u05d9\u05e4\u05d5\u05e2, \u05d0\u05d5 \u05dc\u05d1\u05e7\u05e9\u05d5 \u05ea\u05d9\u05e7\u05d5\u05df \u05e9\u05d9\u05e4\u05d5\u05e2."],[146.0,"\u05d1\u05d6\u05db\u05d5\u05db\u05d9\u05ea \u05d5\u05d1\u05d7\u05d5\u05de\u05e8\u05d9\u05dd \u05e9\u05d1\u05d9\u05e8\u05d9\u05dd, \u05e7\u05d3\u05d7\u05d9\u05dd \u05e7\u05d8\u05e0\u05d9\u05dd \u05de\u05e1\u05d5\u05db\u05e0\u05d9\u05dd, \u05db\u05d9 \u05d4\u05d7\u05d5\u05de\u05e8 \u05e2\u05dc\u05d5\u05dc \u05dc\u05d4\u05d9\u05e1\u05d3\u05e7 \u05d1\u05e0\u05e7\u05d5\u05d3\u05ea \u05d4\u05d7\u05d3\u05d9\u05e8\u05d4."],[153.0,"\u05d5\u05d7\u05dc\u05e7\u05d9\u05dd \u05e7\u05d8\u05e0\u05d9\u05dd \u05e2\u05dc\u05d5\u05dc\u05d9\u05dd \u05dc\u05d9\u05e4\u05d5\u05dc \u05d0\u05d5 \u05dc\u05d4\u05ea\u05d4\u05e4\u05da, \u05d5\u05dc\u05db\u05df \u05de\u05e9\u05d0\u05d9\u05e8\u05d9\u05dd \u05d7\u05d9\u05d1\u05d5\u05e8\u05d9\u05dd \u05d6\u05e2\u05d9\u05e8\u05d9\u05dd."],[160.0,"\u05d2\u05dd \u05d1\u05d7\u05d9\u05ea\u05d5\u05da \u05d1\u05de\u05d9\u05dd \u05d9\u05e9 \u05d1\u05e2\u05d9\u05d5\u05ea \u05d0\u05d5\u05e4\u05d9\u05d9\u05e0\u05d9\u05d5\u05ea."],[163.0,"\u05e9\u05d9\u05e4\u05d5\u05e2 \u05d5\u05e4\u05d9\u05e0\u05d5\u05ea \u05de\u05e2\u05d5\u05d2\u05dc\u05d5\u05ea \u05d1\u05ea\u05d7\u05ea\u05d9\u05ea, \u05db\u05e9\u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05d4\u05d7\u05d9\u05ea\u05d5\u05da \u05d2\u05d1\u05d5\u05d4\u05d4 \u05de\u05d3\u05d9."],[168.0,"\u05e9\u05e4\u05d4 \u05e2\u05db\u05d5\u05e8\u05d4 \u05d1\u05e6\u05d3 \u05d4\u05db\u05e0\u05d9\u05e1\u05d4 \u05e9\u05dc \u05d4\u05e1\u05d9\u05dc\u05d5\u05df."],[171.0,"\u05d4\u05d9\u05e4\u05e8\u05d3\u05d5\u05ea \u05e9\u05db\u05d1\u05d5\u05ea \u05d1\u05d7\u05d5\u05de\u05e8\u05d9\u05dd \u05de\u05e8\u05d5\u05db\u05d1\u05d9\u05dd, \u05d1\u05e0\u05e7\u05d5\u05d3\u05ea \u05d4\u05d7\u05d3\u05d9\u05e8\u05d4."],[175.0,"\u05d5\u05d7\u05dc\u05d5\u05d3\u05d4 \u05de\u05d4\u05d9\u05e8\u05d4 \u05e2\u05dc \u05e4\u05dc\u05d3\u05d4, \u05e9\u05d9\u05e9\u05d1\u05d4 \u05d1\u05de\u05d9\u05dd."],[179.0,"\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8 \u05d7\u05d9\u05ea\u05d5\u05da \u05d1\u05de\u05d9\u05dd?"],[181.0,"\u05d6\u05de\u05df \u05d4\u05de\u05db\u05d5\u05e0\u05d4, \u05e9\u05ea\u05dc\u05d5\u05d9 \u05de\u05d0\u05d5\u05d3 \u05d1\u05e2\u05d5\u05d1\u05d9 \u05d5\u05d1\u05d0\u05d9\u05db\u05d5\u05ea \u05d4\u05e9\u05e4\u05d4."],[185.0,"\u05d4\u05d7\u05d5\u05dc \u05d4\u05e9\u05d5\u05d7\u05e7, \u05e9\u05d4\u05d5\u05d0 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d4\u05d4\u05d5\u05e6\u05d0\u05d4 \u05d4\u05e9\u05d5\u05d8\u05e4\u05ea \u05d4\u05d2\u05d3\u05d5\u05dc\u05d4."],[190.0,"\u05d0\u05d7\u05d6\u05e7\u05d4 \u05e9\u05dc \u05d4\u05de\u05e9\u05d0\u05d1\u05d4, \u05d4\u05d0\u05d8\u05de\u05d9\u05dd \u05d5\u05d4\u05e4\u05ea\u05d7\u05d9\u05dd, \u05e9\u05e2\u05d5\u05d1\u05d3\u05d9\u05dd \u05d1\u05dc\u05d7\u05e5 \u05e2\u05e6\u05d5\u05dd."],[195.0,"\u05de\u05e6\u05d3 \u05e9\u05e0\u05d9, \u05d0\u05d9\u05df \u05db\u05dc\u05d9\u05dd, \u05d5\u05dc\u05db\u05df \u05d6\u05d4 \u05de\u05ea\u05d0\u05d9\u05dd \u05d2\u05dd \u05dc\u05d7\u05dc\u05e7 \u05d1\u05d5\u05d3\u05d3."],[200.0,"\u05d7\u05d9\u05ea\u05d5\u05da \u05d1\u05de\u05d9\u05dd \u05de\u05ea\u05d0\u05d9\u05dd \u05db\u05de\u05e2\u05d8 \u05dc\u05db\u05dc \u05d7\u05d5\u05de\u05e8, \u05d1\u05db\u05dc \u05e2\u05d5\u05d1\u05d9 \u05e1\u05d1\u05d9\u05e8, \u05d1\u05dc\u05d9 \u05d7\u05d5\u05dd."],[205.0,"\u05d4\u05d5\u05d0 \u05d0\u05d9\u05d8\u05d9 \u05d9\u05d5\u05ea\u05e8 \u05de\u05dc\u05d9\u05d9\u05d6\u05e8 \u05d1\u05e4\u05d7 \u05d3\u05e7, \u05d0\u05d1\u05dc \u05d0\u05d9\u05e4\u05d4 \u05e9\u05d7\u05d5\u05dd \u05d0\u05e1\u05d5\u05e8, \u05d0\u05d5 \u05e9\u05d4\u05d7\u05d5\u05de\u05e8 \u05de\u05d9\u05d5\u05d7\u05d3, \u05d4\u05d5\u05d0 \u05d4\u05d1\u05d7\u05d9\u05e8\u05d4."],[212.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0: \u05e4\u05dc\u05d6\u05de\u05d4."]]};
window.MH_TR["\u05e4\u05e8\u05e720_\u05e4\u05dc\u05d6\u05de\u05d4"]={"t":"\u05e4\u05dc\u05d6\u05de\u05d4","l":[[1.0,"\u05dc\u05d5\u05d7\u05d5\u05ea \u05e4\u05dc\u05d3\u05d4 \u05e2\u05d1\u05d9\u05dd \u05dc\u05d2\u05e9\u05e8\u05d9\u05dd, \u05dc\u05d0\u05d5\u05e0\u05d9\u05d5\u05ea \u05d5\u05dc\u05de\u05db\u05d5\u05e0\u05d5\u05ea \u05db\u05d1\u05d3\u05d5\u05ea."],[6.0,"\u05db\u05d3\u05d9 \u05dc\u05d7\u05ea\u05d5\u05da \u05d0\u05d5\u05ea\u05dd \u05de\u05d4\u05e8 \u05d5\u05d1\u05d6\u05d5\u05dc, \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05e4\u05dc\u05d6\u05de\u05d4."],[9.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d6\u05d4 \u05e0\u05d1\u05d9\u05df \u05de\u05d4 \u05d6\u05d5 \u05e4\u05dc\u05d6\u05de\u05d4, \u05de\u05d4 \u05d4\u05d9\u05d0 \u05e0\u05d5\u05ea\u05e0\u05ea, \u05d5\u05d0\u05d9\u05e4\u05d4 \u05d4\u05d9\u05d0 \u05e2\u05d3\u05d9\u05e4\u05d4 \u05e2\u05dc \u05dc\u05d9\u05d9\u05d6\u05e8 \u05d5\u05e2\u05dc \u05d7\u05d9\u05ea\u05d5\u05da \u05d1\u05de\u05d9\u05dd."],[17.0,"\u05d1\u05ea\u05d5\u05da \u05d4\u05e8\u05d0\u05e9 \u05d9\u05e9 \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4, \u05d5\u05e7\u05e9\u05ea \u05d7\u05e9\u05d5\u05de\u05dc\u05d9\u05ea \u05e0\u05d5\u05e6\u05e8\u05ea \u05d1\u05d9\u05e0\u05d4 \u05dc\u05d1\u05d9\u05df \u05d4\u05d7\u05dc\u05e7."],[22.0,"\u05d2\u05d6 \u05e0\u05d3\u05d7\u05e1 \u05d3\u05e8\u05da \u05e4\u05ea\u05d7 \u05e6\u05e8, \u05d5\u05d4\u05e7\u05e9\u05d5\u05ea \u05de\u05d7\u05de\u05de\u05ea \u05d0\u05d5\u05ea\u05d5 \u05dc\u05d9\u05d5\u05ea\u05e8 \u05de\u05e2\u05e9\u05e8\u05d9\u05dd \u05d0\u05dc\u05e3 \u05de\u05e2\u05dc\u05d5\u05ea."],[28.0,"\u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05db\u05d6\u05d5 \u05d4\u05d2\u05d6 \u05d4\u05d5\u05e4\u05da \u05dc\u05e4\u05dc\u05d6\u05de\u05d4: \u05d2\u05d6 \u05de\u05d9\u05d5\u05e0\u05df \u05e9\u05de\u05d5\u05dc\u05d9\u05da \u05d7\u05e9\u05de\u05dc."],[34.0,"\u05d4\u05e4\u05dc\u05d6\u05de\u05d4 \u05de\u05ea\u05d9\u05db\u05d4 \u05d0\u05ea \u05d4\u05de\u05ea\u05db\u05ea, \u05d5\u05d4\u05d6\u05e8\u05dd \u05d4\u05d7\u05d6\u05e7 \u05e9\u05dc \u05d4\u05d2\u05d6 \u05e0\u05d5\u05e9\u05e3 \u05d0\u05d5\u05ea\u05d4 \u05d4\u05d7\u05d5\u05e6\u05d4."],[40.0,"\u05de\u05db\u05d9\u05d5\u05d5\u05df \u05e9\u05d4\u05e7\u05e9\u05ea \u05e2\u05d5\u05d1\u05e8\u05ea \u05d3\u05e8\u05da \u05d4\u05d7\u05dc\u05e7, \u05d4\u05d7\u05d5\u05de\u05e8 \u05d7\u05d9\u05d9\u05d1 \u05dc\u05d4\u05d5\u05dc\u05d9\u05da \u05d7\u05e9\u05de\u05dc."],[45.0,"\u05d4\u05d2\u05d6 \u05d9\u05db\u05d5\u05dc \u05dc\u05d4\u05d9\u05d5\u05ea \u05d0\u05d5\u05d5\u05d9\u05e8, \u05d7\u05de\u05e6\u05df, \u05d7\u05e0\u05e7\u05df, \u05d0\u05d5 \u05ea\u05e2\u05e8\u05d5\u05d1\u05d5\u05ea \u05de\u05d9\u05d5\u05d7\u05d3\u05d5\u05ea, \u05dc\u05e4\u05d9 \u05d4\u05d7\u05d5\u05de\u05e8."],[51.0,"\u05e4\u05dc\u05d6\u05de\u05d4 \u05e8\u05d2\u05d9\u05dc\u05d4 \u05e2\u05dd \u05d0\u05d5\u05d5\u05d9\u05e8 \u05d3\u05d7\u05d5\u05e1 \u05d4\u05d9\u05d0 \u05d6\u05d5\u05dc\u05d4 \u05d5\u05e4\u05e9\u05d5\u05d8\u05d4, \u05d5\u05d9\u05e9 \u05d2\u05dd \u05de\u05db\u05e9\u05d9\u05e8\u05d9\u05dd \u05d9\u05d3\u05e0\u05d9\u05d9\u05dd."],[57.0,"\u05e4\u05dc\u05d6\u05de\u05d4 \u05de\u05d3\u05d5\u05d9\u05e7\u05ea, high definition \u05de\u05e6\u05de\u05e6\u05de\u05ea \u05d0\u05ea \u05d4\u05e7\u05e9\u05d5\u05ea, \u05d5\u05e0\u05d5\u05ea\u05e0\u05ea \u05e9\u05e4\u05d4 \u05d8\u05d5\u05d1\u05d4 \u05d5\u05d3\u05d9\u05d5\u05e7 \u05d2\u05d1\u05d5\u05d4 \u05d9\u05d5\u05ea\u05e8."],[64.0,"\u05d5\u05d9\u05e9 \u05d2\u05dd \u05d7\u05d9\u05ea\u05d5\u05da \u05de\u05ea\u05d7\u05ea \u05dc\u05de\u05d9\u05dd, \u05e9\u05de\u05e4\u05d7\u05d9\u05ea \u05e8\u05e2\u05e2, \u05e2\u05e9\u05df \u05d5\u05e2\u05d9\u05d5\u05d5\u05ea."],[69.0,"\u05e4\u05dc\u05d3\u05d4, \u05e0\u05d9\u05e8\u05d5\u05e1\u05d8\u05d4 \u05d5\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd."],[72.0,"\u05d4\u05d9\u05d0 \u05e2\u05d5\u05d1\u05d3\u05ea \u05d4\u05db\u05d9 \u05d8\u05d5\u05d1 \u05d1\u05dc\u05d5\u05d7\u05d5\u05ea \u05e9\u05dc \u05db\u05de\u05d4 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8\u05d9\u05dd \u05d5\u05e2\u05d3 \u05db\u05de\u05d4 \u05e2\u05e9\u05e8\u05d5\u05ea \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8\u05d9\u05dd."],[77.0,"\u05d1\u05dc\u05d5\u05d7\u05d5\u05ea \u05e2\u05d1\u05d9\u05dd \u05d4\u05d9\u05d0 \u05de\u05d4\u05d9\u05e8\u05d4 \u05d1\u05d4\u05e8\u05d1\u05d4 \u05de\u05dc\u05d9\u05d9\u05d6\u05e8 \u05d5\u05de\u05d7\u05d9\u05ea\u05d5\u05da \u05d1\u05de\u05d9\u05dd, \u05d5\u05d4\u05de\u05db\u05d5\u05e0\u05d4 \u05d6\u05d5\u05dc\u05d4 \u05d9\u05d5\u05ea\u05e8."],[83.0,"\u05d1\u05e4\u05d7 \u05d3\u05e7, \u05dc\u05d9\u05d9\u05d6\u05e8 \u05e0\u05d5\u05ea\u05df \u05ea\u05d5\u05e6\u05d0\u05d4 \u05d8\u05d5\u05d1\u05d4 \u05d9\u05d5\u05ea\u05e8."],[87.0,"\u05d4\u05e9\u05e4\u05d4 \u05d9\u05d5\u05e6\u05d0\u05ea \u05de\u05e2\u05d8 \u05de\u05e9\u05d5\u05e4\u05e2\u05ea, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05db\u05de\u05d4 \u05de\u05e2\u05dc\u05d5\u05ea."],[92.0,"\u05d0\u05d6\u05d5\u05e8 \u05d4\u05d4\u05e9\u05e4\u05e2\u05d4 \u05d4\u05ea\u05e8\u05de\u05d9\u05ea \u05e8\u05d7\u05d1 \u05d9\u05d5\u05ea\u05e8 \u05de\u05d0\u05e9\u05e8 \u05d1\u05dc\u05d9\u05d9\u05d6\u05e8."],[96.0,"\u05d1\u05ea\u05d7\u05ea\u05d9\u05ea \u05d9\u05db\u05d5\u05dc \u05dc\u05d4\u05d9\u05e9\u05d0\u05e8 dross."],[99.0,"\u05d4\u05d3\u05d9\u05d5\u05e7 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1\u05e1\u05d1\u05d9\u05d1\u05d5\u05ea \u05d7\u05e6\u05d9 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8, \u05d5\u05d1\u05e4\u05dc\u05d6\u05de\u05d4 \u05de\u05d3\u05d5\u05d9\u05e7\u05ea \u05d8\u05d5\u05d1 \u05d9\u05d5\u05ea\u05e8."],[104.0,"\u05d5\u05e7\u05d3\u05d7 \u05e7\u05d8\u05df \u05de\u05e2\u05d5\u05d1\u05d9 \u05d4\u05dc\u05d5\u05d7 \u05dc\u05d0 \u05d9\u05d5\u05e6\u05d0 \u05d8\u05d5\u05d1, \u05d5\u05e2\u05d3\u05d9\u05e3 \u05dc\u05e7\u05d3\u05d5\u05d7 \u05d0\u05d5\u05ea\u05d5."],[109.0,"\u05e7\u05d5\u05e0\u05e1\u05d8\u05e8\u05d5\u05e7\u05e6\u05d9\u05d5\u05ea \u05e4\u05dc\u05d3\u05d4 \u05d5\u05d2\u05e9\u05e8\u05d9\u05dd."],[112.0,"\u05d1\u05e0\u05d9\u05d9\u05ea \u05d0\u05d5\u05e0\u05d9\u05d5\u05ea \u05d5\u05e6\u05d9\u05d5\u05d3 \u05db\u05d1\u05d5."],[114.0,"\u05d4\u05db\u05e0\u05ea \u05e9\u05d9\u05e4\u05d5\u05e2\u05d9\u05dd \u05dc\u05e8\u05d9\u05ea\u05d5\u05da, \u05e2\u05dd \u05e8\u05d0\u05e9 \u05e9\u05e0\u05d5\u05d8\u05d4."],[118.0,"\u05d5\u05d7\u05d9\u05ea\u05d5\u05da \u05e6\u05d9\u05e0\u05d5\u05e8\u05d5\u05ea \u05d5\u05e4\u05e8\u05d5\u05e4\u05d9\u05dc\u05d9\u05dd."],[121.0,"\u05d2\u05dd \u05dc\u05e4\u05dc\u05d6\u05de\u05d4 \u05d9\u05e9 \u05db\u05dc\u05dc\u05d9 \u05ea\u05db\u05e0\u05d5\u05df."],[123.0,"\u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05e9\u05e6\u05e8\u05d9\u05db\u05d9\u05dd \u05dc\u05d4\u05d9\u05d5\u05ea \u05de\u05d3\u05d5\u05d9\u05e7\u05d9\u05dd, \u05de\u05e9\u05d0\u05d9\u05e8\u05d9\u05dd \u05dc\u05d4\u05dd \u05ea\u05d5\u05e1\u05e4\u05ea \u05dc\u05e2\u05d9\u05d1\u05d5\u05d3 \u05e9\u05d1\u05d1\u05d9."],[128.0,"\u05d4\u05e9\u05e4\u05d4 \u05d4\u05d7\u05ea\u05d5\u05db\u05d4 \u05de\u05ea\u05e7\u05e9\u05d4 \u05de\u05d4\u05d7\u05d5\u05dd, \u05d5\u05d6\u05d4 \u05d9\u05db\u05d5\u05dc | \u05dc\u05d4\u05e7\u05e9\u05d5\u05ea \u05e2\u05dc \u05e2\u05d9\u05d1\u05d5\u05d3 \u05d0\u05d5 \u05db\u05d9\u05e4\u05d5\u05e3 \u05d0\u05d7\u05e8 \u05db\u05da."],[134.0,"\u05e7\u05d3\u05d7\u05d9\u05dd \u05e7\u05d8\u05e0\u05d9\u05dd \u05d5\u05de\u05d3\u05d5\u05d9\u05e7\u05d9\u05dd \u05e7\u05d5\u05d3\u05d7\u05d9\u05dd, \u05d5\u05dc\u05d0 \u05d7\u05d5\u05ea\u05db\u05d9\u05dd \u05d1\u05e4\u05dc\u05d6\u05de\u05d4."],[139.0,"\u05d2\u05dd \u05d1\u05e4\u05dc\u05d6\u05de\u05d4 \u05d9\u05e9 \u05d1\u05e2\u05d9\u05d5\u05ea \u05d0\u05d5\u05e4\u05d9\u05d9\u05e0\u05d9\u05d5\u05ea."],[141.0,"\u05e9\u05e4\u05d4 \u05de\u05e9\u05d5\u05e4\u05e2\u05ea, \u05db\u05e9\u05d4\u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05d0\u05d5 \u05d4\u05d2\u05d5\u05d1\u05d4 \u05e9\u05dc \u05d4\u05e8\u05d0\u05e9 \u05dc\u05d0 \u05e0\u05db\u05d5\u05e0\u05d9\u05dd."],[146.0,"5 \u05d1\u05ea\u05d7\u05ea\u05d9\u05ea, \u05db\u05e9\u05d5\u05d4\u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05e0\u05de\u05d5\u05db\u05d4 \u05d0\u05d5 \u05d2\u05d1\u05d5\u05d4\u05d4 \u05de\u05d3\u05d9."],[151.0,"\u05d9\u05e8\u05d9\u05d3\u05d4 \u05d1\u05d0\u05d9\u05db\u05d5\u05ea, \u05db\u05e9\u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d4 \u05d5\u05d4\u05e4\u05d9\u05d4 \u05e0\u05e9\u05d7\u05e7\u05d5\u05ea."],[155.0,"\u05d5\u05e2\u05d9\u05d5\u05d5\u05ea \u05e9\u05dc \u05dc\u05d5\u05d7\u05d5\u05ea \u05d3\u05e7\u05d9\u05dd \u05de\u05d4\u05d7\u05d5\u05dd."],[158.0,"\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8 \u05d7\u05d9\u05ea\u05d5\u05da \u05d1\u05e4\u05dc\u05d6\u05de\u05d4?"],[160.0,"\u05d7\u05dc\u05e7\u05d9\u05dd \u05de\u05ea\u05db\u05dc\u05d9\u05dd: \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d5\u05ea \u05d5\u05e4\u05d9\u05d5\u05ea, \u05e9\u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05d7\u05dc\u05d9\u05e3 \u05d4\u05e8\u05d1\u05d4."],[165.0,"\u05d2\u05d6\u05d5\u05d7\u05e9\u05de\u05dc."],[166.0,"\u05e0\u05d9\u05e7\u05d5\u05d9 dross \u2026 \u05e9\u05dc \u05d4\u05e9\u05e4\u05d4."],[169.0,"\u05d5\u05ea\u05d5\u05e1\u05e4\u05ea \u05dc\u05e2\u05d9\u05d1\u05d5\u05d3, \u05db\u05e9\u05e6\u05e8\u05d9\u05da \u05d3\u05d9\u05d5\u05e7."],[172.0,"\u05de\u05e6\u05d3 \u05e9\u05e0\u05d9, \u05d1\u05dc\u05d5\u05d7\u05d5\u05ea \u05e4\u05dc\u05d3\u05d4 \u05e2\u05d1\u05d9\u05dd, \u05d6\u05d5 \u05d4\u05d3\u05e8\u05da \u05d4\u05d6\u05d5\u05dc\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05dc\u05d7\u05ea\u05d5\u05da."],[178.0,"\u05e4\u05dc\u05d6\u05de\u05d4 \u05d7\u05d5\u05ea\u05db\u05ea \u05dc\u05d5\u05d7\u05d5\u05ea \u05de\u05ea\u05db\u05ea \u05e2\u05d1\u05d9\u05dd \u05de\u05d4\u05e8 \u05d5\u05d1\u05d6\u05d5\u05dc, \u05d1\u05d3\u05d9\u05d5\u05e7 \u05d1\u05d9\u05e0\u05d5\u05e0\u05d9."],[183.0,"\u05d1\u05d6\u05d4 \u05e1\u05d9\u05d9\u05de\u05e0\u05d5 \u05d0\u05ea \u05e7\u05d1\u05d5\u05e6\u05ea \u05d4\u05ea\u05d4\u05dc\u05d9\u05db\u05d9\u05dd \u05d4\u05dc\u05d0 \u05e7\u05d5\u05e0\u05d1\u05e0\u05e6\u05d9\u05d5\u05e0\u05dc\u05d9\u05d9\u05dd."],[186.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0 \u05e0\u05ea\u05d7\u05d9\u05dc \u05d1\u05e7\u05d1\u05d5\u05e6\u05ea \u05d4\u05ea\u05d4\u05dc\u05d9\u05db\u05d9\u05dd \u05d4\u05de\u05ea\u05e7\u05d3\u05de\u05d9\u05dd: \u05db\u05e8\u05e1\u05d5\u05dd 5 \u05e6\u05d9\u05e8\u05d9\u05dd."]]};
window.MH_TR["\u05e4\u05e8\u05e721_\u05db\u05e8\u05e1\u05d5\u05dd_5_\u05e6\u05d9\u05e8\u05d9\u05dd"]={"t":"\u05db\u05e8\u05e1\u05d5\u05dd 5 \u05e6\u05d9\u05e8\u05d9\u05dd","l":[[1.0,"\u05d0\u05d9\u05de\u05e4\u05dc\u05e8\u05d9\u05dd, \u05dc\u05d4\u05d1\u05d9 \u05d8\u05d5\u05e8\u05d1\u05d9\u05e0\u05d4, \u05d7\u05dc\u05e7\u05d9 \u05de\u05d1\u05e0\u05d4 \u05dc\u05de\u05d8\u05d5\u05e1\u05d9\u05dd, \u05ea\u05d1\u05e0\u05d9\u05d5\u05ea \u05d5\u05e9\u05ea\u05dc\u05d9\u05dd \u05e8\u05e4\u05d5\u05d0\u05d9\u05d9\u05dd."],[7.0,"\u05dc\u05d7\u05dc\u05e7\u05d9\u05dd \u05db\u05d0\u05dc\u05d4 \u05d9\u05e9 \u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05de\u05d5\u05e8\u05db\u05d1\u05d9\u05dd, \u05e9\u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05d2\u05d9\u05e2 \u05d0\u05dc\u05d9\u05d4\u05dd \u05de\u05db\u05dc \u05d4\u05e6\u05d3\u05d3\u05d9\u05dd \u05d5\u05d1\u05db\u05dc \u05d6\u05d5\u05d5\u05d9\u05ea."],[14.0,"\u05d1\u05db\u05e8\u05e1\u05d5\u05de\u05ea \u05e8\u05d2\u05d9\u05dc\u05d4 \u05d6\u05d4 \u05d3\u05d5\u05e8\u05e9 \u05d4\u05e8\u05d1\u05d4 \u05ea\u05e4\u05d9\u05e1\u05d5\u05ea, \u05d4\u05e8\u05d1\u05d4 \u05de\u05ea\u05e7\u05e0\u05d9\u05dd, \u05d5\u05db\u05dc\u05d9\u05dd \u05d0\u05e8\u05d5\u05db\u05d9\u05dd."],[20.0,"\u05d1\u05db\u05e8\u05e1\u05d5\u05dd 5 \u05e6\u05d9\u05e8\u05d9\u05dd \u05e2\u05d5\u05e9\u05d9\u05dd \u05d0\u05ea \u05e8\u05d5\u05d1 \u05d4\u05e2\u05d1\u05d5\u05d3\u05d4 \u05d1\u05ea\u05e4\u05d9\u05e1\u05d4 \u05d0\u05d7\u05ea, \u05d1\u05db\u05dc\u05d9\u05dd \u05e7\u05e6\u05e8\u05d9\u05dd \u05d5\u05d1\u05d3\u05d9\u05d5\u05e7 \u05d2\u05d1\u05d5\u05d4."],[26.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d6\u05d4 \u05e0\u05db\u05d9\u05e8 \u05d0\u05ea \u05d4\u05de\u05db\u05d5\u05e0\u05d5\u05ea, \u05d0\u05ea \u05e9\u05ea\u05d9 \u05e9\u05d9\u05d8\u05d5\u05ea \u05d4\u05e2\u05d1\u05d5\u05d3\u05d4, \u05d0\u05ea \u05de\u05d4 \u05e9\u05e7\u05d5\u05e8\u05d4 \u05de\u05d0\u05d7\u05d5\u05e8\u05d9 \u05d4\u05e7\u05dc\u05e2\u05d9\u05dd, \u05d5\u05d0\u05ea \u05de\u05d4 \u05e9\u05d6\u05d4 \u05e2\u05d5\u05dc\u05d4."],[35.0,"\u05d1\u05db\u05e8\u05e1\u05d5\u05de\u05ea \u05e8\u05d2\u05d9\u05dc\u05d4 \u05d9\u05e9 \u05e9\u05dc\u05d5\u05e9\u05d4 \u05e6\u05d9\u05e8\u05d9\u05dd \u05d9\u05e9\u05e8\u05d9\u05dd: \u05e5 ,\u05d0 \u05d5-7."],[40.0,"\u05d1\u05db\u05e8\u05e1\u05d5\u05dd 5 \u05e6\u05d9\u05e8\u05d9\u05dd \u05de\u05d5\u05e1\u05d9\u05e4\u05d9\u05dd \u05e9\u05e0\u05d9 \u05e6\u05d9\u05e8\u05d9\u05dd \u05e1\u05d9\u05d1\u05d5\u05d1\u05d9\u05d9\u05dd."],[45.0,"\u05e6\u05d9\u05e8 A \u05de\u05e1\u05ea\u05d5\u05d1\u05d1 \u05e1\u05d1\u05d9\u05d1 \u05d0, \u05e6\u05d9\u05e8 8 \u05de\u05e1\u05ea\u05d5\u05d1\u05d1 \u05e1\u05d1\u05d9\u05d1 \u05e5, \u05d5\u05e6\u05d9\u05e8:) \u05de\u05e1\u05ea\u05d5\u05d1\u05d1 \u05e1\u05d1\u05d9\u05d1 7."],[52.0,"\u05d1\u05db\u05dc \u05de\u05db\u05d5\u05e0\u05d4 \u05d9\u05e9 \u05e9\u05e0\u05d9\u05d9\u05dd \u05de\u05d4\u05dd, \u05dc\u05e4\u05d9 \u05d4\u05ea\u05e6\u05d5\u05e8\u05d4 \u05e9\u05dc\u05d4."],[56.0,"\u05d1\u05e9\u05d5\u05dc\u05d7\u05df: \u05d4\u05e9\u05d5\u05dc\u05d7\u05df \u05e0\u05d5\u05d8\u05d4, \u05d5\u05e2\u05dc\u05d9\u05d5 \u05e9\u05d5\u05dc\u05d7\u05df \u05e9\u05de\u05e1\u05ea\u05d5\u05d1\u05d1, \u05d4\u05e1\u05d5\u05d7\u05d7\u05e9\u05d6\u05d6."],[65.0,"\u05d6\u05d5 \u05d4\u05ea\u05e6\u05d5\u05e8\u05d4 \u05d4\u05e0\u05e4\u05d5\u05e6\u05d4 \u05dc\u05d7\u05dc\u05e7\u05d9\u05dd \u05e7\u05d8\u05e0\u05d9\u05dd \u05d5\u05d1\u05d9\u05e0\u05d5\u05e0\u05d9\u05d9\u05dd: \u05d4\u05d9\u05d0 \u05e7\u05e9\u05d9\u05d7\u05d4, \u05de\u05d3\u05d5\u05d9\u05e7\u05ea, \u05d5\u05d4\u05d7\u05dc\u05e7 \u05de\u05e1\u05ea\u05d5\u05d1\u05d1 \u05d0\u05dc \u05de\u05d5\u05dc \u05d4\u05db\u05dc\u05d9."],[73.0,"\u05d4\u05d7\u05d9\u05e1\u05e8\u05d5\u05df: \u05d4\u05e9\u05d5\u05dc\u05d7\u05df \u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05d8\u05d5\u05ea \u05d0\u05ea \u05db\u05dc \u05de\u05e9\u05e7\u05dc \u05d4\u05d7\u05dc\u05e7, \u05d5\u05dc\u05db\u05df \u05d4\u05d9\u05d0 \u05de\u05d5\u05d2\u05d1\u05dc\u05ea \u05d1\u05d2\u05d5\u05d3\u05dc."],[80.0,"\u05d1\u05ea\u05e6\u05d5\u05e8\u05d4 \u05d4\u05e9\u05e0\u05d9\u05d9\u05d4, \u05e9\u05e0\u05d9 \u05d4\u05e6\u05d9\u05e8\u05d9\u05dd \u05e0\u05de\u05e6\u05d0\u05d9\u05dd \u05d1\u05e8\u05d0\u05e9: \u05d4\u05e8\u05d0\u05e9 \u05e0\u05d5\u05d8\u05d4 \u05d5\u05de\u05e1\u05ea\u05d5\u05d1\u05d1, \u05d5\u05d4\u05d7\u05dc\u05e7 \u05e0\u05e9\u05d0\u05e8 \u05d1\u05de\u05e7\u05d5\u05dd."],[88.0,"\u05d6\u05d5 \u05d4\u05ea\u05e6\u05d5\u05e8\u05d4 \u05dc\u05d7\u05dc\u05e7\u05d9\u05dd \u05d2\u05d3\u05d5\u05dc\u05d9\u05dd \u05d5\u05db\u05d1\u05d3\u05d9\u05dd, \u05db\u05de\u05d5 \u05d7\u05dc\u05e7\u05d9 \u05de\u05d1\u05e0\u05d4 \u05dc\u05de\u05d8\u05d5\u05e1\u05d9\u05dd \u05d5\u05ea\u05d1\u05e0\u05d9\u05d5\u05ea \u05d2\u05d3\u05d5\u05dc\u05d5\u05ea."],[94.0,"\u05d1\u05ea\u05e6\u05d5\u05e8\u05d4 \u05d4\u05e9\u05d5\u05dc\u05d9\u05e9\u05d9\u05ea, \u05e6\u05d9\u05e8 \u05d0\u05d7\u05d3 \u05d1\u05e9\u05d5\u05dc\u05d7\u05df \u05d5\u05e6\u05d9\u05e8 \u05d0\u05d7\u05d3 \u05d1\u05e8\u05d0\u05e9, \u05e9\u05d9\u05dc\u05d5\u05d1 \u05e9\u05dc \u05e9\u05ea\u05d9 \u05d4\u05d2\u05d9\u05e9\u05d5\u05ea."],[101.0,"\u05d4\u05e9\u05d9\u05d8\u05d4 \u05d4\u05e0\u05e4\u05d5\u05e6\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05e0\u05e7\u05e8\u05d0\u05ea 3+2."],[105.0,"\u05d4\u05de\u05db\u05d5\u05e0\u05d4 \u05de\u05d8\u05d4 \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7 \u05dc\u05d6\u05d5\u05d5\u05d9\u05ea \u05d4\u05e0\u05d3\u05e8\u05e2\u05d5\u05ea, \u05e0\u05d5\u05e2\u05dc\u05ea \u05d0\u05ea \u05d4\u05e6\u05d9\u05e8\u05d9\u05dd \u05d4\u05e1\u05d9\u05d1\u05d5\u05d1\u05d9\u05d9\u05dd, \u05d5\u05de\u05db\u05e8\u05e1\u05de\u05ea \u05d1\u05e9\u05dc\u05d5\u05e9\u05d4 \u05e6\u05d9\u05e8\u05d9\u05dd \u05e8\u05d2\u05d9\u05dc\u05d9\u05dd."],[113.0,"\u05d0\u05d7\u05e8 \u05db\u05da \u05d4\u05d9\u05d0 \u05de\u05d8\u05d4 \u05dc\u05d6\u05d5\u05d5\u05d9\u05ea \u05d4\u05d1\u05d0\u05d4, \u05d5\u05de\u05de\u05e9\u05d9\u05db\u05d4."],[117.0,"\u05db\u05da \u05de\u05d2\u05d9\u05e2\u05d9\u05dd \u05dc\u05d7\u05de\u05d9\u05e9\u05d4 \u05e6\u05d3\u05d3\u05d9\u05dd \u05e9\u05dc \u05d4\u05d7\u05dc\u05e7 \u05d1\u05ea\u05e4\u05d9\u05e1\u05d4 \u05d0\u05d7\u05ea, \u05d5\u05e8\u05e7 \u05d4\u05e6\u05d3 \u05e9\u05e2\u05dc\u05d9\u05d5 \u05d4\u05d7\u05dc\u05e7 \u05ea\u05e4\u05d5\u05e1 \u05e0\u05e9\u05d0\u05e8."],[124.0,"2 \u05de\u05ea\u05d0\u05d9\u05dd \u05de\u05d0\u05d5\u05d3 \u05dc\u05e7\u05d3\u05d7\u05d9\u05dd \u05de\u05e9\u05d5\u05d5\u05e4\u05e2\u05d9\u05dd, \u05dc\u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05d1\u05d6\u05d5\u05d5\u05d9\u05d5\u05ea, \u05d5\u05dc\u05d7\u05dc\u05e7\u05d9 \u05ea\u05d9\u05d1\u05d4 \u05e2\u05dd \u05d4\u05e8\u05d1\u05d4 \u05e6\u05d3\u05d3\u05d9\u05dd."],[132.0,"\u05d4\u05ea\u05db\u05e0\u05d5\u05ea \u05e4\u05e9\u05d5\u05d8 \u05d9\u05d7\u05e1\u05d9\u05ea, \u05d5\u05d4\u05de\u05db\u05d5\u05e0\u05d4 \u05e7\u05e9\u05d9\u05d7\u05d4, \u05db\u05d9 \u05d4\u05e6\u05d9\u05e8\u05d9\u05dd \u05d4\u05e1\u05d9\u05d1\u05d5\u05d1\u05d9\u05d9\u05dd \u05e0\u05e2\u05d5\u05dc\u05d9\u05dd \u05d1\u05d6\u05de\u05df \u05d4\u05d7\u05d9\u05ea\u05d5\u05da."],[139.0,"\u05d1\u05e9\u05d9\u05d8\u05d4 \u05d4\u05e1\u05d9\u05de\u05d5\u05dc\u05d8\u05e0\u05d9\u05ea, \u05db\u05dc \u05d7\u05de\u05e9\u05ea \u05d4\u05e6\u05d9\u05e8\u05d9\u05dd \u05d6\u05d6\u05d9\u05dd \u05d9\u05d7\u05d3, \u05d1\u05e8\u05e6\u05d9\u05e4\u05d5\u05ea, \u05ea\u05d5\u05da \u05db\u05d3\u05d9 \u05d7\u05d9\u05ea\u05d5\u05df."],[145.0,"\u05db\u05da \u05d4\u05db\u05dc\u05d9 \u05e2\u05d5\u05e7\u05d1 \u05d0\u05d7\u05e8\u05d9 \u05de\u05e9\u05d8\u05d7 \u05de\u05e2\u05d5\u05e7\u05dc, \u05d5\u05e9\u05d5\u05de\u05e8 \u05e2\u05dc \u05d6\u05d5\u05d5\u05d9\u05ea \u05e7\u05d1\u05d5\u05e2\u05d4 \u05d1\u05d9\u05d7\u05e1 \u05d0\u05dc\u05d9\u05d5 \u05dc\u05d0\u05d5\u05e8\u05da \u05db\u05dc \u05d4\u05d3\u05e8\u05da."],[151.0,"\u05d6\u05d4 \u05d4\u05db\u05e8\u05d7\u05d9 \u05d1\u05d0\u05d9\u05de\u05e4\u05dc\u05e8\u05d9\u05dd, \u05d1\u05dc\u05d4\u05d1\u05d9\u05dd, \u05d5\u05d1\u05db\u05dc \u05de\u05e9\u05d8\u05d7 \u05d7\u05d5\u05e4\u05e9\u05d9."],[156.0,"\u05d0\u05e4\u05e1. \u05db\u05e9\u05de\u05d8\u05d9\u05dd \u05d0\u05ea \u05d4\u05db\u05dc\u05d9, \u05d4\u05d7\u05d9\u05ea\u05d5\u05da \u05e2\u05d5\u05d1\u05e8 \u05dc\u05d0\u05d6\u05d5\u05e8 \u05d8\u05d5\u05d1 \u05d9\u05d5\u05ea\u05e8 \u05e9\u05dc \u05d4\u05db\u05d3\u05d5\u05e8, \u05d5\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05de\u05e9\u05ea\u05e4\u05e8\u05d9\u05dd."],[167.0,"\u05d0\u05e4\u05e9\u05e8 \u05d2\u05dd \u05dc\u05d7\u05ea\u05d5\u05da \u05d1\u05e6\u05d3 \u05e9\u05dc \u05d4\u05db\u05dc\u05d9, \u05dc\u05d0\u05d5\u05e8\u05da \u05db\u05dc \u05d4\u05d2\u05d5\u05d1\u05d4 \u05e9\u05dc \u05d4\u05d3\u05d5\u05e4\u05df, \u05d5\u05dc\u05e7\u05d1\u05dc \u05d3\u05d5\u05e4\u05df \u05d7\u05dc\u05e7\u05d4 \u05d1\u05de\u05e2\u05d1\u05e8 \u05d0\u05d7\u05d3."],[174.0,"\u05d5\u05d9\u05e9 \u05db\u05dc\u05d9\u05dd \u05de\u05d9\u05d5\u05d7\u05d3\u05d9\u05dd \u05d1\u05e6\u05d5\u05e8\u05ea \u05e7\u05d8\u05e2 \u05e9\u05dc \u05e2\u05d9\u05d2\u05d5\u05dc \u05d2\u05d3\u05d5\u05dc, barrel 5 \u05e2\u05d5\u05de\u05d0\u05e4\u05e9\u05e8\u05d9\u05dd \u05de\u05e2\u05d1\u05e8\u05d9\u05dd \u05e8\u05d7\u05d1\u05d9\u05dd \u05e2\u05dd \u05d2\u05d9\u05de\u05d5\u05e8 \u05d8\u05d5\u05d1."],[183.0,"\u05db\u05e9\u05e6\u05d9\u05e8 \u05e1\u05d9\u05d1\u05d5\u05d1\u05d9 \u05d7, \u05e7\u05e6\u05d4 \u05d4\u05db\u05dc\u05d9 \u05d6\u05d6 \u05d0\u05d9\u05ea\u05d5 \u05d1\u05de\u05e8\u05d7\u05d1."],[187.0,"\u05db\u05d3\u05d9 \u05e9\u05d4\u05db\u05dc\u05d9 \u05d9\u05d9\u05e9\u05d0\u05e8 \u05d1\u05d3\u05d9\u05d5\u05e7 \u05e2\u05dc \u05d4\u05de\u05e1\u05dc\u05d5\u05dc, \u05d4\u05d1\u05e7\u05e8 \u05de\u05d7\u05e9\u05d1 \u05db\u05dc \u05d4\u05d6\u05de\u05df \u05d0\u05ea \u05d4\u05ea\u05e0\u05d5\u05e2\u05d5\u05ea \u05d4\u05d9\u05e9\u05e8\u05d5\u05ea \u05e9\u05de\u05e4\u05e6\u05d5\u05ea \u05e2\u05dc \u05d4\u05e1\u05d9\u05d1\u05d5\u05d1."],[194.0,"\u05d4\u05db\u05dc\u05d9, \u05d5\u05d4\u05d9\u05d0 \u05de\u05d0\u05e4\u05e9\u05e8\u05ea \u05dc\u05ea\u05db\u05e0\u05ea \u05d0\u05ea \u05d4\u05de\u05e1\u05dc\u05d5\u05dc \u05dc\u05e4\u05d9 \u05e7\u05e6\u05d4 \u05d4\u05db\u05dc\u05d9, \u05d5\u05dc\u05d0 \u05dc\u05e4\u05d9 \u05d4\u05de\u05db\u05d5\u05e0\u05d4."],[205.0,"\u05db\u05d3\u05d9 \u05e9\u05d6\u05d4 \u05d9\u05e2\u05d1\u05d5\u05d3, \u05d4\u05de\u05db\u05d5\u05e0\u05d4 \u05e6\u05e8\u05d9\u05db\u05d4 \u05dc\u05d3\u05e2\u05ea \u05d1\u05d3\u05d9\u05d5\u05e7 \u05d0\u05d9\u05e4\u05d4 \u05e0\u05de\u05e6\u05d0\u05d9\u05dd \u05de\u05e8\u05db\u05d6\u05d9 \u05d4\u05e1\u05d9\u05d1\u05d5\u05d1, \u05d5\u05dc\u05db\u05df \u05de\u05db\u05d9\u05d9\u05dc\u05d9\u05dd \u05d0\u05d5\u05ea\u05d4 \u05d1\u05d0\u05d5\u05e4\u05df \u05e7\u05d1\u05d5\u05e2."],[213.0,"\u05d0\u05ea \u05d4\u05de\u05e1\u05dc\u05d5\u05dc\u05d9\u05dd \u05de\u05ea\u05db\u05e0\u05ea\u05d9\u05dd \u05d1\u05ea\u05d5\u05db\u05e0\u05ea CAM, \u05d5\u05d4\u05ea\u05db\u05e0\u05d5\u05ea \u05d1-5 \u05e6\u05d9\u05e8\u05d9\u05dd \u05de\u05d5\u05e8\u05db\u05d1 \u05d9\u05d5\u05ea\u05e8 \u05d5\u05d3\u05d5\u05e8\u05e9 \u05e0\u05d9\u05e1\u05d9\u05d5\u05df."],[220.0,"\u05dc\u05db\u05dc \u05de\u05db\u05d5\u05e0\u05d4 \u05d9\u05e9 \u2026 \u05de\u05e9\u05d5\u05dc\u05d4, \u05e9\u05de\u05ea\u05e8\u05d2\u05dd \u05d0\u05ea \u05d4\u05de\u05e1\u05dc\u05d5\u05dc \u05dc\u05e4\u05e7\u05d5\u05d3\u05d5\u05ea \u05e9\u05d4\u05de\u05db\u05d5\u05e0\u05d4 \u05d4\u05e1\u05e4\u05e6\u05d9\u05e4\u05d9\u05ea \u05de\u05d1\u05d9\u05e0\u05d4."],[227.0,"\u05d9\u05e9 \u05e1\u05db\u05e0\u05ea \u05d4\u05ea\u05e0\u05d2\u05e9\u05d5\u05d5\u05ea \u05d1\u05d9\u05df \u05d4\u05db\u05dc\u05d9, \u05d4\u05de\u05d7\u05d6\u05d9\u05e7, \u05d4\u05e8\u05d0\u05e9, \u05d4\u05e9\u05d5\u05dc\u05d7\u05df, \u05d4\u05d7\u05dc\u05e7 \u05d5\u05d4\u05de\u05ea\u05e7\u05df."],[234.0,"\u05dc\u05db\u05df \u05de\u05e8\u05d9\u05e6\u05d9\u05dd \u05e1\u05d9\u05de\u05d5\u05dc\u05e6\u05d9\u05d4 \u05de\u05dc\u05d0\u05d4 \u05e9\u05dc \u05d4\u05de\u05db\u05d5\u05e0\u05d4, \u05e2\u05dd \u05d4\u05de\u05d5\u05d3\u05dc \u05d4\u05d0\u05de\u05d9\u05ea\u05d9 \u05e9\u05dc\u05d4, \u05dc\u05e4\u05e0\u05d9 \u05db\u05dc \u05d7\u05d9\u05ea\u05d5\u05da."],[241.0,"\u05d4\u05e1\u05d9\u05d1\u05d5\u05d1\u05d9\u05d9\u05dd, \u05d5\u05dc\u05d0\u05d6\u05d5\u05e8\u05d9\u05dd \u05e9\u05d1\u05d4\u05dd \u05d4\u05de\u05db\u05d5\u05e0\u05d4 \u05e6\u05e8\u05d9\u05db\u05d4 \u05dc\u05d4\u05e1\u05ea\u05d5\u05d1\u05d1 \u05de\u05d4\u05e8 \u05de\u05d0\u05d5\u05d3 \u05db\u05d3\u05d9 \u05dc\u05e2\u05d1\u05d5\u05e8 \u05e0\u05e7\u05d5\u05d3\u05d4 \u05de\u05e1\u05d5\u05d9\u05de\u05ea."],[251.0,"\u05d1\u05db\u05e8\u05e1\u05d5\u05dd 5 \u05e6\u05d9\u05e8\u05d9\u05dd, \u05d4\u05ea\u05e4\u05d9\u05e1\u05d4 \u05e6\u05e8\u05d9\u05db\u05d4 \u05dc\u05d4\u05e9\u05d0\u05d9\u05e8 \u05d2\u05d9\u05e9\u05d4 \u05de\u05db\u05dc \u05d4\u05db\u05d9\u05d5\u05d5\u05e0\u05d9\u05dd."],[256.0,"\u05dc\u05db\u05df \u05de\u05d2\u05d1\u05d9\u05d4\u05d9\u05dd \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7 \u05e2\u05dc \u05de\u05ea\u05e7\u05df \u05e6\u05e8, \u05db\u05da \u05e9\u05d4\u05e8\u05d0\u05e9 \u05d5\u05d4\u05db\u05dc\u05d9 \u05dc\u05d0 \u05d9\u05ea\u05e0\u05d2\u05e9\u05d5 \u05d1\u05e9\u05d5\u05dc\u05d7\u05df."],[262.0,"\u05de\u05e2\u05e8\u05db\u05d5\u05ea \u05ea\u05e4\u05d9\u05e1\u05d4 \u05de\u05d4\u05d9\u05e8\u05d5\u05ea, Zero point, \u05de\u05d0\u05e4\u05e9\u05e8\u05d5\u05ea \u05dc\u05d4\u05e2\u05d1\u05d9\u05e8 \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7 \u05d1\u05d9\u05df \u05de\u05db\u05d5\u05e0\u05d5\u05ea \u05d1\u05dc\u05d9 \u05dc\u05d0\u05d1\u05d3 \u05d0\u05ea \u05d4\u05de\u05d9\u05e7\u05d5\u05dd."],[269.0,"\u05d5\u05dc\u05e2\u05ea\u05d9\u05dd \u05e7\u05e8\u05d5\u05d1\u05d5\u05ea \u05de\u05e2\u05d1\u05d3\u05d9\u05dd \u05de\u05ea\u05d5\u05da \u05d2\u05d5\u05e9, \u05d5\u05de\u05e9\u05d0\u05d9\u05e8\u05d9\u05dd \u05d1\u05e1\u05d9\u05e1 \u05e7\u05d8\u05df \u05e9\u05e0\u05d7\u05ea\u05da \u05d1\u05e1\u05d5\u05e3."],[275.0,"\u05de\u05db\u05d9\u05d5\u05d5\u05df \u05e9\u05d4\u05db\u05d5\u05dc \u05e0\u05e2\u05e9\u05d4 \u05d1\u05ea\u05e4\u05d9\u05e1\u05d4 \u05d0\u05d7\u05ea, \u05d4\u05d9\u05d7\u05e1 \u05d1\u05d9\u05df \u05d4\u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05de\u05d3\u05d5\u05d9\u05e7 \u05d9\u05d5\u05ea\u05e8."],[280.0,"\u05d0\u05d1\u05dc \u05d4\u05e9\u05d2\u05d9\u05d0\u05d5\u05ea \u05e9\u05dc \u05d4\u05e6\u05d9\u05e8\u05d9\u05dd \u05d4\u05e1\u05d9\u05d1\u05d5\u05d1\u05d9\u05d9\u05dd \u05de\u05e6\u05d8\u05d1\u05e8\u05d5\u05ea, \u05d5\u05dc\u05db\u05df \u05d4\u05db\u05d9\u05d5\u05dc \u05d7\u05e9\u05d5\u05d1."],[285.0,"\u05d7\u05d5\u05dd \u05de\u05e9\u05e0\u05d4 \u05d0\u05ea \u05d4\u05de\u05db\u05d5\u05e0\u05d4 \u05d1\u05de\u05d4\u05dc\u05da \u05d4\u05e2\u05d1\u05d5\u05d3\u05d4, \u05d5\u05de\u05db\u05d5\u05e0\u05d5\u05ea \u05de\u05ea\u05e7\u05d3\u05de\u05d5\u05ea \u05de\u05e4\u05e6\u05d5\u05ea \u05e2\u05dc \u05d6\u05d4."],[291.0,"\u05de\u05d2\u05e9 \u05de\u05d3\u05d9\u05d3\u05d4 \u05d1\u05de\u05db\u05d5\u05e0\u05d4 \u05de\u05d5\u05e6\u05d0 \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7 \u05dc\u05e4\u05e0\u05d9 \u05d4\u05e2\u05d9\u05d1\u05d5\u05d3, \u05d5\u05d1\u05d5\u05d3\u05e7 \u05de\u05d9\u05d3\u05d5\u05ea \u05ea\u05d5\u05da \u05db\u05d3\u05d9, \u05d1\u05dc\u05d9 \u05dc\u05d4\u05d5\u05e6\u05d9\u05d0 \u05d0\u05d5\u05ea\u05d5."],[298.0,"\u05e4\u05d7\u05d5\u05ea \u05ea\u05e4\u05d9\u05e1\u05d5\u05ea: \u05db\u05dc \u05ea\u05e4\u05d9\u05e1\u05d4 \u05e0\u05d5\u05e1\u05e4\u05ea \u05d9\u05db\u05d5\u05dc\u05d4 \u05dc\u05d4\u05d5\u05e1\u05d9\u05e3 \u05e9\u05d2\u05d9\u05d0\u05d4, \u05db\u05de\u05d5 \u05e9\u05e8\u05d0\u05d9\u05e0\u05d5 \u05d1\u05e4\u05e8\u05e7 5."],[305.0,"\u05dc\u05d4\u05d9\u05d5\u05ea \u05d0\u05e8\u05d5\u05da \u05db\u05d3\u05d9 \u05dc\u05d4\u05d2\u05d9\u05e2 \u05dc\u05e2\u05d5\u05de\u05e7, \u05d5\u05dc\u05db\u05df \u05d4\u05d5\u05d0 \u05e7\u05e9\u05d9\u05d7 \u05d9\u05d5\u05ea\u05e8 \u05d5\u05e4\u05d7\u05d5\u05ea \u05e8\u05d5\u05e2\u05d3."],[314.0,"\u05d2\u05d9\u05e9\u05d4 \u05dc\u05e9\u05e7\u05e2\u05d9\u05dd \u05d5\u05dc\u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05de\u05e9\u05d5\u05e4\u05e2\u05d9\u05dd, \u05e9\u05d0\u05d9 \u05d0\u05e4\u05e9\u05e8 \u05dc\u05d4\u05d2\u05d9\u05e2 \u05d0\u05dc\u05d9\u05d4\u05dd \u05d1\u05e9\u05dc\u05d5\u05e9\u05d4 \u05e6\u05d9\u05e8\u05d9\u05dd."],[320.0,"\u05e4\u05e0\u05d9 \u05e9\u05d8\u05d7 \u05d8\u05d5\u05d1\u05d9\u05dd \u05d9\u05d5\u05ea\u05d4 \u05d5\u05e4\u05d7\u05d5\u05ea \u05e2\u05d1\u05d5\u05d3\u05ea \u05d2\u05d9\u05de\u05d5\u05e8 \u05d9\u05d3\u05e0\u05d9\u05ea."],[324.0,"\u05d5\u05e4\u05d7\u05d5\u05ea \u05de\u05ea\u05e7\u05e0\u05d9\u05dd, \u05e4\u05d7\u05d5\u05ea \u05d4\u05e2\u05d1\u05e8\u05d5\u05ea \u05d1\u05d9\u05df \u05de\u05db\u05d5\u05e0\u05d5\u05ea, \u05d4\u05d7\u05de\u05df \u05d0\u05e1\u05e4\u05e7\u05d4 \u05e7\u05e6\u05e8 \u05d9\u05d5\u05ea\u05e8."],[330.0,"\u05d0\u05d9\u05de\u05e4\u05dc\u05e8\u05d9\u05dd \u05d5-5\u05d0\u05e4\u05d5\u05d5\u05dd: \u05d3\u05d9\u05e1\u05e7\u05d4 \u05d5\u05dc\u05d4\u05d1\u05d9\u05dd \u05de\u05d2\u05d5\u05e9 \u05d0\u05d7\u05d3."],[334.0,"\u05dc\u05d4\u05d1\u05d9 \u05d8\u05d5\u05e8\u05d1\u05d9\u05e0\u05d4, \u05e2\u05dd \u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05de\u05e2\u05d5\u05e7\u05dc\u05d9\u05dd \u05d5\u05d3\u05e4\u05e0\u05d5\u05ea \u05d3\u05e7\u05d5\u05ea."],[338.0,"\u05d7\u05dc\u05e7\u05d9 \u05de\u05d1\u05e0\u05d4 \u05dc\u05de\u05d8\u05d5\u05e1\u05d9\u05dd, \u05e2\u05dd \u05db\u05d9\u05e1\u05d9\u05dd \u05e2\u05de\u05d5\u05e7\u05d9\u05dd \u05d5\u05d3\u05e4\u05e0\u05d5\u05ea \u05d1\u05d6\u05d5\u05d5\u05d9\u05d5\u05ea."],[343.0,"\u05ea\u05d1\u05e0\u05d9\u05d5\u05ea \u05e2\u05dd \u05d7\u05dc\u05dc\u05d9\u05dd \u05e2\u05de\u05d5\u05e7\u05d9\u05dd, \u05e9\u05d1\u05d4\u05dd \u05db\u05dc\u05d9 \u05e7\u05e6\u05e8 \u05d5\u05de\u05d5\u05d8\u05d4 \u05de\u05d7\u05dc\u05d9\u05e3 \u05db\u05dc\u05d9 \u05d0\u05e8\u05d5\u05da \u05d5\u05e8\u05d5\u05e2\u05d3."],[349.0,"\u05e9\u05ea\u05dc\u05d9\u05dd \u05e8\u05e4\u05d5\u05d0\u05d9\u05d9\u05dd, \u05d5\u05d2\u05d5\u05e4\u05d9\u05dd \u05e2\u05dd \u05e7\u05d3\u05d7\u05d9\u05dd \u05d1\u05d4\u05e8\u05d1\u05d4 \u05d6\u05d5\u05d5\u05d9\u05d5\u05ea."],[354.0,"\u05d2\u05dd \u05dc\u05db\u05e8\u05e1\u05d5\u05dd 5 \u05e6\u05d9\u05e8\u05d9\u05dd \u05d9\u05e9 \u05db\u05dc\u05dc\u05d9 \u05ea\u05db\u05e0\u05d5\u05df."],[357.0,"\u05dc\u05d0 \u05db\u05dc \u05d7\u05dc\u05e7 \u05e6\u05e8\u05d9\u05da 5 \u05e6\u05d9\u05e8\u05d9\u05dd: \u05d0\u05dd \u05e9\u05dc\u05d5\u05e9\u05d4 \u05e6\u05d9\u05e8\u05d9\u05dd \u05de\u05e1\u05e4\u05d9\u05e7\u05d9\u05dd, \u05d6\u05d4 \u05d6\u05d5\u05dc \u05d9\u05d5\u05ea\u05e8."],[363.0,"\u05db\u05d3\u05d0\u05d9 \u05dc\u05d7\u05e9\u05d5\u05d1 \u05de\u05d0\u05d9\u05d6\u05d4 \u05db\u05d9\u05d5\u05d5\u05df \u05d4\u05db\u05dc\u05d9 \u05d9\u05d2\u05d9\u05e2 \u05dc\u05db\u05dc \u05de\u05e9\u05d8\u05d7, \u05d5\u05dc\u05d0 \u05dc\u05d9\u05e6\u05d5\u05e8 \u05de\u05e9\u05d8\u05d7 \u05e9\u05d0\u05e3 \u05db\u05dc\u05d9 \u05dc\u05d0 \u05d9\u05d2\u05d9\u05e2 \u05d0\u05dc\u05d9\u05d5."],[370.0,"\u05db\u05d3\u05d0\u05d9 \u05dc\u05ea\u05db\u05e0\u05df \u05d0\u05ea \u05de\u05e9\u05d8\u05d7\u05d9 \u05d4\u05d9\u05d9\u05d7\u05d5\u05e1 \u05d5\u05d4\u05d8\u05d5\u05dc\u05e8\u05e0\u05e1\u05d9\u05dd \u05db\u05da \u05e9\u05d0\u05e4\u05e9\u05e8 \u05dc\u05e2\u05d1\u05d3 \u05d0\u05d5\u05ea\u05dd \u05d1\u05d0\u05d5\u05ea\u05d4 \u05ea\u05e4\u05d9\u05e1\u05d4."],[376.0,"\u05d5\u05de\u05e9\u05d8\u05d7 \u05d7\u05d5\u05e4\u05e9\u05d9 \u05e8\u05e7 \u05db\u05e9\u05d4\u05d5\u05d0 \u05d1\u05d0\u05de\u05ea \u05e0\u05d3\u05e8\u05e9, \u05db\u05d9 \u05d4\u05d5\u05d0 \u05d4\u05db\u05d9\u05d9\u05e7\u05e8 \u05dc\u05ea\u05db\u05e0\u05ea \u05d5\u05dc\u05d1\u05d3\u05d5\u05e7."],[382.0,"\u05d2\u05dd \u05d1\u05db\u05e8\u05e1\u05d5\u05dd 5 \u05e6\u05d9\u05e8\u05d9\u05dd \u05d9\u05e9 \u05d1\u05e2\u05d9\u05d5\u05ea \u05d0\u05d5\u05e4\u05d9\u05d9\u05e0\u05d9\u05d5\u05ea."],[386.0,"\u05d4\u05ea\u05e0\u05d2\u05e9\u05d5\u05ea, \u05db\u05e9\u05d4\u05e1\u05d9\u05de\u05d5\u05dc\u05e6\u05d9\u05d4 \u05dc\u05d0 \u05ea\u05d5\u05d0\u05de\u05ea \u05dc\u05de\u05db\u05d5\u05e0\u05d4 \u05d4\u05d0\u05de\u05d9\u05ea\u05d9\u05ea."],[390.0,"\u05e1\u05d9\u05de\u05e0\u05d9\u05dd \u05e2\u05dc \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7, \u05db\u05e9\u05d4\u05e6\u05d9\u05e8\u05d9\u05dd \u05d4\u05e1\u05d9\u05d1\u05d5\u05d1\u05d9\u05d9\u05dd \u05d6\u05d6\u05d9\u05dd \u05d1\u05e7\u05e4\u05d9\u05e6\u05d5\u05ea."],[395.0,"\u05e9\u05d2\u05d9\u05d0\u05d5\u05ea \u05de\u05d9\u05d3\u05d4, \u05db\u05e9\u05d4\u05de\u05db\u05d5\u05e0\u05d4 \u05dc\u05d0 \u05de\u05db\u05d5\u05d9\u05dc\u05ea."],[398.0,"\u05d5\u05e8\u05e2\u05d9\u05d3\u05d5\u05ea \u05d1\u05d3\u05e4\u05e0\u05d5\u05ea \u05d3\u05e7\u05d5\u05ea, \u05d2\u05dd \u05db\u05e9\u05d4\u05db\u05dc\u05d9 \u05e7\u05e6\u05e8."],[402.0,"\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8 \u05db\u05e8\u05e1\u05d5\u05dd 5 \u05e6\u05d9\u05e8\u05d9\u05dd?"],[405.0,"\u05d4\u05ea\u05e2\u05e8\u05d9\u05e3 \u05dc\u05e9\u05e2\u05d4 \u05d2\u05d1\u05d5\u05d4 \u05d9\u05d5\u05ea\u05e8, \u05db\u05d9 \u05d4\u05de\u05db\u05d5\u05e0\u05d4 \u05d9\u05e7\u05e8\u05d4 \u05d1\u05d4\u05e8\u05d1\u05d4."],[409.0,"\u05d6\u05de\u05df \u05ea\u05db\u05e0\u05d5\u05ea \u05d5\u05e1\u05d9\u05de\u05d5\u05dc\u05e6\u05d9\u05d4, \u05e9\u05d9\u05db\u05d5\u05dc \u05dc\u05d4\u05d9\u05d5\u05ea \u05d0\u05e8\u05d5\u05da \u05de\u05d6\u05de\u05df \u05d4\u05e2\u05d9\u05d1\u05d5\u05d3 \u05e2\u05e6\u05de\u05d5 \u05d1\u05d7\u05dc\u05e7 \u05e8\u05d0\u05e9\u05d5\u05df."],[415.0,"\u05d7\u05dc\u05e7 \u05e8\u05d0\u05e9\u05d5\u05df \u05e9\u05e6\u05e8\u05d9\u05da \u05dc\u05d1\u05d3\u05d5\u05e7 \u05d5\u05dc\u05db\u05d5\u05d5\u05df."],[418.0,"\u05db\u05dc\u05d9\u05dd \u05d5\u05de\u05d7\u05d6\u05d9\u05e7\u05d9\u05dd \u05de\u05d9\u05d5\u05d7\u05d3\u05d9\u05dd."],[421.0,"\u05de\u05e6\u05d3 \u05e9\u05e0\u05d9, \u05d7\u05d5\u05e1\u05db\u05d9\u05dd \u05ea\u05e4\u05d9\u05e1\u05d5\u05ea, \u05de\u05ea\u05e7\u05e0\u05d9\u05dd, \u05d4\u05d5\u05d1\u05dc\u05d4 \u05d1\u05d9\u05df \u05de\u05db\u05d5\u05e0\u05d5\u05ea \u05d4\u05de\u05df \u05d4\u05de\u05ea\u05e0\u05d4."],[426.0,"\u05dc\u05db\u05df \u05d4\u05d5\u05d0 \u05de\u05e9\u05ea\u05dc\u05dd \u05d1\u05e2\u05d9\u05e7\u05e8 \u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05de\u05d5\u05e8\u05db\u05d1\u05d9\u05dd \u05d5\u05d9\u05e7\u05e8\u05d9\u05dd, \u05d1\u05db\u05de\u05d5\u05d9\u05d5\u05ea \u05e7\u05d8\u05e0\u05d5\u05ea \u05d5\u05d1\u05d9\u05e0\u05d5\u05e0\u05d9\u05d5\u05ea."],[433.0,"\u05db\u05e8\u05e1\u05d5\u05dd 5 \u05e6\u05d9\u05e8\u05d9\u05dd \u05de\u05d2\u05d9\u05e2 \u05db\u05de\u05e2\u05d8 \u05dc\u05db\u05dc \u05de\u05e9\u05d8\u05d7, \u05d1\u05ea\u05e4\u05d9\u05e1\u05d4 \u05d0\u05d7\u05ea \u05d5\u05d1\u05db\u05dc\u05d9\u05dd \u05e7\u05e6\u05e8\u05d9\u05dd."],[439.0,"2 \u05dc\u05d7\u05dc\u05e7\u05d9\u05dd \u05e2\u05dd \u05d4\u05e8\u05d1\u05d4 \u05e6\u05d3\u05d3\u05d9\u05dd \u05d5\u05d6\u05d5\u05d5\u05d9\u05d5\u05ea, \u05d5\u05e1\u05d9\u05de\u05d5\u05dc\u05d8\u05e0\u05d9 \u05dc\u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05de\u05e2\u05d5\u05e7\u05dc\u05d9\u05dd."],[445.0,"\u05d4\u05d4\u05e6\u05dc\u05d7\u05d4 \u05ea\u05dc\u05d5\u05d9\u05d4 \u05d1\u05ea\u05db\u05e0\u05d5\u05ea, \u05d1\u05e1\u05d9\u05de\u05d5\u05dc\u05e6\u05d9\u05d4, \u05d1\u05db\u05d9\u05d5\u05dc \u05d5\u05d1\u05ea\u05e4\u05d9\u05e1\u05d4, \u05dc\u05d0 \u05e8\u05e7 \u05d1\u05de\u05db\u05d5\u05e0\u05d4."],[451.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0: \u05de\u05d7\u05e8\u05d8\u05d4 \u05de\u05db\u05e8\u05e1\u05de\u05ea \u2026 Swiss"]]};
window.MH_TR["\u05e4\u05e8\u05e722_\u05de\u05d7\u05e8\u05d8\u05d4_\u05de\u05db\u05e8\u05e1\u05de\u05ea_\u05d5-Swiss_type"]={"t":"\u05de\u05d7\u05e8\u05d8\u05d4 \u05de\u05db\u05e8\u05e1\u05de\u05ea \u05d5-Swiss type","l":[[1.0,"\u05d2\u05dc \u05e2\u05dd \u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05e9\u05d8\u05d5\u05d7\u05d9\u05dd, \u05d7\u05e8\u05d9\u05e5 \u05e9\u05d2\u05dd \u05d5\u05e7\u05d3\u05d7\u05d9\u05dd \u05e8\u05d5\u05d7\u05d1\u05d9\u05d9\u05dd. \u05d1\u05d5\u05e8\u05d2 \u05e8\u05e4\u05d5\u05d0\u05d9 \u05d6\u05e2\u05d9\u05e8. \u05e4\u05d9\u05df \u05d4\u05d9\u05d3\u05e8\u05d0\u05d5\u05dc\u05d9 \u05d0\u05e8\u05d5\u05da \u05d5\u05d3\u05e7."],[10.0,"\u05d0\u05dc\u05d4 \u05d7\u05dc\u05e7\u05d9\u05dd \u05e1\u05d9\u05d1\u05d5\u05d1\u05d9\u05d9\u05dd, \u05d0\u05d1\u05dc \u05d9\u05e9 \u05d1\u05d4\u05dd \u05d2\u05dd \u05db\u05e8\u05e1\u05d5\u05dd \u05d5\u05e7\u05d9\u05d3\u05d5\u05d7."],[15.0,"\u05d1\u05de\u05e7\u05d5\u05dd \u05dc\u05d4\u05e2\u05d1\u05d9\u05e8 \u05d0\u05d5\u05ea\u05dd \u05d1\u05d9\u05df \u05de\u05d7\u05e8\u05d8\u05d4 \u05dc\u05db\u05e8\u05e1\u05d5\u05de\u05ea, \u05de\u05d9\u05d9\u05e6\u05e8\u05d9\u05dd \u05d0\u05d5\u05ea\u05dd \u05d1\u05de\u05db\u05d5\u05e0\u05d4 \u05d0\u05d7\u05ea."],[20.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d6\u05d4 \u05e0\u05db\u05d9\u05e8 \u05e9\u05ea\u05d9 \u05de\u05db\u05d5\u05e0\u05d5\u05ea \u05db\u05d0\u05dc\u05d4: \u05de\u05d7\u05e8\u05d8\u05d4 \u05de\u05db\u05e8\u05e1\u05de\u05ea, \u05d5- Swiss type."],[27.0,"\u05de\u05d7\u05e8\u05d8\u05d4 \u05de\u05db\u05e8\u05e1\u05de\u05ea \u05d4\u05d9\u05d0 \u05de\u05d7\u05e8\u05d8\u05ea CNC \u05e2\u05dd \u2018live tools \u05db\u05dc\u05d9\u05dd \u05de\u05e1\u05ea\u05d5\u05d1\u05d1\u05d9\u05dd, \u05e9\u05de\u05d5\u05e0\u05e2\u05d9\u05dd \u05d1\u05de\u05e0\u05d5\u05e2 \u05de\u05e9\u05dc\u05d4\u05dd \u05d1\u05ea\u05d5\u05da \u05d4\u05e6\u05e8\u05d9\u05d7."],[36.0,"\u05e6\u05d9\u05e8 6 \u05de\u05d0\u05e4\u05e9\u05e8 \u05dc\u05e2\u05e6\u05d5\u05e8 \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7 \u05d1\u05d6\u05d5\u05d5\u05d9\u05ea \u05de\u05d3\u05d5\u05d9\u05e7\u05ea, \u05d0\u05d5 \u05dc\u05e1\u05d5\u05d1\u05d1 \u05d0\u05d5\u05ea\u05d5 \u05dc\u05d0\u05d8 \u05d1\u05d6\u05de\u05df \u05d4\u05db\u05e8\u05e1\u05d5\u05dd."],[43.0,"\u05db\u05da \u05d0\u05e4\u05e9\u05e8 \u05dc\u05db\u05e8\u05e1\u05dd \u05de\u05e9\u05d5\u05d8\u05d7\u05d9\u05dd \u05e9\u05d8\u05d5\u05d7\u05d9\u05dd \u05d5\u05de\u05e9\u05d5\u05e9\u05d9\u05dd, \u05d5\u05dc\u05e7\u05d3\u05d5\u05d7 \u05e7\u05d3\u05d7\u05d9\u05dd \u05e6\u05d3\u05d3\u05d9\u05d9\u05dd \u05d5\u05e7\u05d3\u05d7\u05d9\u05dd \u05de\u05d7\u05d5\u05e5 \u05dc\u05de\u05e8\u05db\u05d6."],[50.0,"\u05e6\u05d9\u05e8 \u05dc \u05de\u05d5\u05e1\u05d9\u05e3 \u05ea\u05e0\u05d5\u05e2\u05d4 \u05d4\u05e6\u05d9\u05d3\u05d4, \u05d5\u05de\u05d0\u05e4\u05e9\u05e8 \u05dc\u05db\u05e8\u05e1\u05dd \u05d7\u05e8\u05d9\u05e6\u05d9\u05dd \u05d5\u05db\u05d9\u05e1\u05d9\u05dd \u05e9\u05dc\u05d0 \u05e2\u05d5\u05d1\u05e8\u05d9\u05dd \u05d3\u05e8\u05da \u05de\u05e8\u05db\u05d6 \u05d4\u05d7\u05dc\u05e7."],[57.0,"\u05e6\u05d9\u05e8 \u05e0\u05d2\u05d3\u05d9, spindle 5\u05e95, \u05ea\u05d5\u05e4\u05e1 \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7 \u05d0\u05d7\u05e8\u05d9 \u05d4\u05e0\u05d9\u05ea\u05d5\u05e7, \u05d5\u05de\u05e2\u05d1\u05d3 \u05d0\u05ea \u05d4\u05e6\u05d3 \u05d4\u05d0\u05d7\u05d5\u05e8\u05d9."],[63.0,"\u05db\u05da \u05d9\u05d5\u05e6\u05d0 \u05d7\u05dc\u05e7 \u05d2\u05de\u05d5\u05e8 \u05dc\u05d2\u05de\u05e8\u05d9, \u05d1\u05dc\u05d9 \u05e9\u05d0\u05e3 \u05d0\u05d7\u05d3 \u05e0\u05d2\u05e2 \u05d1\u05d5."],[68.0,"\u05d1\u05de\u05db\u05d5\u05e0\u05d5\u05ea \u05d4\u05d2\u05d3\u05d5\u05dc\u05d5\u05ea \u05d9\u05e9 \u05d2\u05dd \u05e8\u05d0\u05e9 \u05db\u05e8\u05e1\u05d5\u05dd \u05e9\u05e0\u05d5\u05d8\u05d4, \u05e6\u05d9\u05e8 \u05dd, \u05d5\u05d4\u05df \u05de\u05e9\u05dc\u05d1\u05d5\u05ea \u05de\u05d7\u05e8\u05d8\u05d4 \u05e2\u05dd \u05db\u05e8\u05e1\u05d5\u05dd 5 \u05e6\u05d9\u05e8\u05d9\u05dd."],[76.0,"\u05ea\u05e4\u05d9\u05e1\u05d4 \u05d0\u05d7\u05ea, \u05d5\u05dc\u05db\u05df \u05d4\u05e7\u05d3\u05d7\u05d9\u05dd \u05d5\u05d4\u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05de\u05d3\u05d5\u05d9\u05e7\u05d9\u05dd \u05d1\u05d9\u05d7\u05e1 \u05dc\u05e6\u05d9\u05e8 \u05d4\u05e1\u05d9\u05d1\u05d5\u05d1."],[82.0,"\u05e4\u05d7\u05d5\u05ea \u05d4\u05e2\u05d1\u05e8\u05d5\u05ea \u05d1\u05d9\u05df \u05de\u05db\u05d5\u05e0\u05d5\u05ea, \u05e4\u05d7\u05d5\u05ea \u05de\u05ea\u05e7\u05e0\u05d9\u05dd, \u05d5\u05e4\u05d7\u05d5\u05ea \u05d7\u05dc\u05e7\u05d9\u05dd \u05e9\u05de\u05d7\u05db\u05d9\u05dd \u05d1\u05d9\u05df \u05ea\u05d7\u05e0\u05d5\u05ea."],[88.0,"\u05e2\u05dd \u05de\u05d6\u05d9\u05df \u05de\u05d5\u05d8\u05d5\u05ea, feeder \u05d6\u05d4\u05e1, \u05d4\u05de\u05db\u05d5\u05e0\u05d4 \u05d9\u05db\u05d5\u05dc\u05d4 \u05dc\u05e2\u05d1\u05d5\u05d3 \u05dc\u05d1\u05d3 \u05e9\u05e2\u05d5\u05ea \u05d0\u05e8\u05d5\u05db\u05d5\u05ea."],[94.0,"\u2026 live \u05d7\u05dc\u05e9\u05d9\u05dd \u05d5\u05e7\u05e9\u05d9\u05d7\u05d9\u05dd \u05e4\u05d7\u05d5\u05ea \u05de\u05d4\u05e6\u05d9\u05e8 \u05e9\u05dc \u05de\u05e8\u05db\u05d6 \u05e2\u05d9\u05d1\u05d5\u05d3."],[99.0,"\u05dc\u05db\u05df \u05db\u05e8\u05e1\u05d5\u05dd \u05db\u05d1\u05d3 \u05d5\u05d7\u05d5\u05de\u05e8\u05d9\u05dd \u05e7\u05e9\u05d9\u05dd \u05e2\u05d3\u05d9\u05e3 \u05dc\u05e2\u05e9\u05d5\u05d5\u05ea \u05d1\u05db\u05e8\u05e1\u05d5\u05de\u05ea."],[104.0,"\u05d4\u05ea\u05db\u05e0\u05d5\u05ea \u05de\u05d5\u05e8\u05db\u05d1, \u05d5\u05d9\u05e9 \u05e1\u05db\u05e0\u05ea \u05d4\u05ea\u05e0\u05d2\u05e9\u05d5\u05ea \u05d1\u05d9\u05df \u05d4\u05e6\u05e8\u05d9\u05d7, \u05d4\u05e6\u05d9\u05e8\u05d9\u05dd \u05d5\u05d4\u05d7\u05dc\u05e7."],[110.0,"\u05d5\u05d4\u05de\u05db\u05d5\u05e0\u05d4 \u05d9\u05e7\u05e8\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05de\u05de\u05d7\u05e8\u05d8\u05d4 \u05e8\u05d2\u05d9\u05dc\u05d4."],[114.0,"Swiss type \u05d4\u05d9\u05d0 \u05de\u05d7\u05e8\u05d8\u05d4 \u05de\u05e1\u05d5\u05d2 \u05d0\u05d7\u05e8, \u05e9\u05e0\u05d5\u05dc\u05d3\u05d4 \u05d1\u05ea\u05e2\u05e9\u05d5\u05d9\u05d9\u05ea \u05d4\u05e9\u05e2\u05d5\u05e0\u05d9\u05dd \u05d1\u05e9\u05d5\u05d9\u05d9\u05e5."],[119.0,"\u05d1\u05de\u05d7\u05e8\u05d8\u05d4 \u05e8\u05d2\u05d9\u05dc\u05d4, \u05d4\u05d7\u05dc\u05e7 \u05de\u05e1\u05ea\u05d5\u05d1\u05d1 \u05d1\u05de\u05e7\u05d5\u05dd \u05d5\u05d4\u05db\u05dc\u05d9 \u05d6\u05d6 \u05dc\u05d0\u05d5\u05e8\u05db\u05d5."],[124.0,"\u05d1-6\u05e7\u05e2\u05d6 Swiss, \u05d4\u05de\u05d5\u05d8 \u05e2\u05e6\u05de\u05d5 \u05d6\u05d6 \u05e7\u05d3\u05d9\u05de\u05d4 \u05d5\u05d0\u05d7\u05d5\u05e8\u05d4 \u05d3\u05e8\u05da guide bushing, \u05ea\u05d5\u05ea\u05d1 \u05de\u05d5\u05d1\u05d9\u05dc \u05e9\u05ea\u05d5\u05de\u05da \u05d1\u05d5."],[131.0,"\u05d4\u05db\u05dc\u05d9 \u05d7\u05d5\u05ea\u05da \u05ea\u05de\u05d9\u05d3 \u05de\u05de\u05e9 \u05dc\u05d9\u05d3 \u05d4\u05ea\u05d5\u05ea\u05d1, \u05db\u05da \u05e9\u05d4\u05d7\u05dc\u05e7 \u05e0\u05ea\u05de\u05da \u05d1\u05de\u05e8\u05d7\u05e7 \u05e9\u05dc \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8\u05d9\u05dd \u05e1\u05e4\u05d5\u05e8\u05d9\u05dd \u05de\u05e0\u05e7\u05d5\u05d3\u05ea \u05d4\u05d7\u05d9\u05ea\u05d5\u05da."],[138.0,"\u05d4\u05db\u05d3\u05d9\u05d7\u05d5\u05ea\u05da \u05ea\u05de\u05d9\u05d3 \u05de\u05de\u05e9 \u05dc\u05d9\u05d3 \u05d4\u05ea\u05d5\u05ea\u05d1, \u05db\u05da \u2026 1 \u05e0\u05ea\u05de \u05e8\u05d7\u05e7 / / \u05d5 \u05d5 \u05e7\u05d5\u05d3\u05ea \u05d5"],[139.0,"\u05dc\u05db\u05df \u05d0\u05e4\u05e9\u05e8 \u05dc\u05d7\u05e8\u05d5\u05d8 \u05d7\u05dc\u05e7\u05d9\u05dd \u05d0\u05e8\u05d5\u05db\u05d9\u05dd \u05d5\u05d3\u05e7\u05d9\u05dd \u05de\u05d0\u05d5\u05d3, \u05d2\u05dd \u05d1\u05d0\u05d5\u05e8\u05da \u05e9\u05dc \u05e4\u05d9 \u05e2\u05e9\u05e8\u05d9\u05dd \u05de\u05d4\u05e7\u05d5\u05d8\u05e8, \u05d1\u05dc\u05d9 \u05e9\u05d9\u05ea\u05db\u05d5\u05e4\u05e1\u05e4\u05d5."],[146.0,"\u05de\u05db\u05d5\u05e0\u05d5\u05ea Swiss \u05e2\u05d5\u05d1\u05d3\u05d5\u05ea \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05e2\u05dd \u05de\u05d5\u05d8\u05d5\u05ea \u05d1\u05e7\u05d5\u05d8\u05e8 \u05e9\u05dc \u05e2\u05d3 32 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8."],[152.0,"\u05d9\u05e9 \u05d1\u05d4\u05df \u05d4\u05e8\u05d1\u05d4 \u05db\u05dc\u05d9\u05dd \u05e7\u05d1\u05d5\u05e2\u05d9\u05dd, tools \u05e4\u05d8\u05d5\u05d5, \u05e6\u05d9\u05e8 \u05e0\u05d2\u05d3\u05d9, \u05d5\u05d4\u05e8\u05d1\u05d4 \u05e6\u05d9\u05e8\u05d9\u05dd \u05e9\u05e2\u05d5\u05d1\u05d3\u05d9\u05dd \u05d1\u05d5 \u05d6\u05de\u05e0\u05d9\u05ea."],[159.0,"\u05d5\u05d4\u05df \u05de\u05d2\u05d9\u05e2\u05d5\u05ea \u05dc\u05d3\u05d9\u05d5\u05e7 \u05e9\u05dc \u05de\u05d9\u05e7\u05e8\u05d5\u05e0\u05d9\u05dd, \u05d1\u05d9\u05d9\u05e6\u05d5\u05e8 \u05d4\u05de\u05d5\u05e0\u05d9."],[163.0,"\u05d4\u05de\u05d5\u05d8 \u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05d9\u05d5\u05ea \u05de\u05d5\u05e9\u05d7\u05d6 \u05d5\u05d1\u05e7\u05d5\u05d8\u05e8 \u05de\u05d3\u05d5\u05d9\u05e7, \u05db\u05d3\u05d9 \u05e9\u05d9\u05e0\u05d5\u05e2 \u05d7\u05dc\u05e7 \u05d1\u05ea\u05d5\u05da \u05d4\u05ea\u05d5\u05ea\u05d1."],[168.0,"\u05d4\u05d7\u05d5\u05de\u05e8 \u05e9\u05e0\u05e9\u05d0\u05e8 \u05d1\u05ea\u05d5\u05da \u05d4\u05ea\u05d5\u05ea\u05d1 \u05d1\u05e1\u05d5\u05e3 \u05d4\u05de\u05d5\u05d8 \u05d4\u05d5\u05dc\u05da \u05dc\u05e4\u05d7\u05ea."],[173.0,"\u05dc\u05d7\u05dc\u05e7\u05d9\u05dd \u05e7\u05e6\u05e8\u05d9\u05dd \u05d9\u05e9 \u05de\u05e6\u05d1 \u05e2\u05d1\u05d5\u05d3\u05d4 \u05d1\u05dc\u05d9 \u05ea\u05d5\u05ea\u05d1, \u05e9\u05d7\u05d5\u05e1\u05da \u05e4\u05d7\u05ea."],[177.0,"\u05d5\u05d4\u05e7\u05d5\u05d8\u05e8 \u05d4\u05de\u05e7\u05e1\u05d9\u05de\u05dc\u05d9 \u05e9\u05dc \u05d4\u05d7\u05dc\u05e7 \u05d4\u05d5\u05d0 \u05e7\u05d5\u05d8\u05e8 \u05d4\u05de\u05d5\u05d8: \u05d0\u05d5\u05d2\u05df \u05d2\u05d3\u05d5\u05dc \u05d1\u05de\u05d9\u05d5\u05d7\u05d3 \u05dc\u05d0 \u05de\u05ea\u05d0\u05d9\u05dd \u2026."],[185.0,"\u05d1\u05e8\u05d2\u05d9\u05dd \u05d5\u05e9\u05ea\u05dc\u05d9\u05dd \u05e8\u05e4\u05d5\u05d0\u05d9\u05d9\u05dd \u05d5\u05d3\u05e0\u05d8\u05dc\u05d9\u05d9\u05dd."],[188.0,"\u05de\u05d7\u05d1\u05e8\u05d9\u05dd \u05d5\u05e4\u05d9\u05e0\u05d9\u05dd \u05dc\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05e0\u05d9\u05e7\u05d4."],[190.0,"\u05d7\u05dc\u05e7\u05d9\u05dd \u05dc\u05e9\u05e2\u05d5\u05e0\u05d9\u05dd \u05d5\u05dc\u05de\u05db\u05e9\u05d9\u05e8\u05d9\u05dd \u05de\u05d3\u05d5\u05d9\u05e7\u05d9\u05dd."],[194.0,"\u05e4\u05d9\u05e0\u05d9\u05dd, \u05e6\u05d9\u05e8\u05d9\u05dd \u05d5\u05e9\u05e1\u05ea\u05d5\u05de\u05d9\u05dd \u05d4\u05d9\u05d3\u05e8\u05d0\u05d5\u05dc\u05d9\u05d9\u05dd."],[197.0,"\u05d5\u05d1\u05de\u05d7\u05e8\u05d8\u05d4 \u05d4\u05de\u05db\u05e8\u05e1\u05de\u05ea: \u05d2\u05dc\u05d9\u05dd, \u05ea\u05d5\u05ea\u05d1\u05d9\u05dd, \u05d2\u05d5\u05e4\u05d9 \u05e9\u05e1\u05ea\u05d5\u05de\u05d9\u05dd, \u05d5\u05e4\u05dc\u05e0\u05d2'\u05d9\u05dd \u05e2\u05dd \u05e7\u05d3\u05d7\u05d9\u05dd."],[204.0,"\u05d7\u05dc\u05e7 \u05e1\u05d9\u05d1\u05d5\u05d1\u05d9 \u05e4\u05e9\u05d5\u05d8, \u05d1\u05dc\u05d9 \u05db\u05e8\u05e1\u05d5\u05dd: \u05de\u05d7\u05e8\u05d8\u05d4 \u05e8\u05d2\u05d9\u05dc\u05d4."],[209.0,"\u05d7\u05dc\u05e7 \u05e1\u05d9\u05d1\u05d5\u05d1\u05d9 \u05e2\u05dd \u05de\u05e9\u05d8\u05d7\u05d9\u05dd, \u05d7\u05e8\u05d9\u05e6\u05d9\u05dd \u05d5\u05e7\u05d3\u05d7\u05d9\u05dd: \u05de\u05d7\u05e8\u05d8\u05d4 \u05de\u05db\u05e8\u05e1\u05de\u05ea."],[214.0,"\u05d7\u05dc\u05e7 \u05e7\u05d8\u05df, \u05d0\u05e8\u05d5\u05da \u05d5\u05d3\u05e7, \u05d1\u05db\u05de\u05d5\u05d9\u05d5\u05ea \u05d2\u05d3\u05d5\u05dc\u05d5\u05ea: Swiss type"],[220.0,"\u05d5\u05d7\u05dc\u05e7 \u05d2\u05d3\u05d5\u05dc, \u05de\u05e1\u05d5\u05d1\u05da \u05de\u05db\u05dc \u05d4\u05db\u05d9\u05d5\u05d5\u05e0\u05d9\u05dd: \u05de\u05d7\u05e8\u05d8\u05d4 \u05de\u05db\u05e8\u05e1\u05de\u05ea \u05e2\u05dd \u05e6\u05d9\u05e8 \u05dd, \u05d0\u05d5 \u05db\u05e8\u05e1\u05d5\u05dd 5 \u05e6\u05d9\u05e8\u05d9\u05dd."],[229.0,"\u05d2\u05dd \u05db\u05d0\u05df \u05d9\u05e9 \u05db\u05dc\u05dc\u05d9 \u05ea\u05db\u05e0\u05d5\u05df."],[231.0,"\u05db\u05d3\u05d0\u05d9 \u05dc\u05ea\u05db\u05e0\u05df \u05d0\u05ea \u05d4\u05e7\u05d3\u05d7\u05d9\u05dd \u05d5\u05d4\u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05db\u05da \u05e9\u05d4-100!5 live \u05d9\u05d5\u05db\u05dc\u05d5 \u05dc\u05d4\u05d2\u05d9\u05e2 \u05d0\u05dc\u05d9\u05d4\u05dd."],[236.0,"\u05db\u05d3\u05d0\u05d9 \u05dc\u05d4\u05e9\u05ea\u05de\u05e9 \u05d1\u05d2\u05d3\u05dc\u05d9\u05dd \u05e1\u05d8\u05e0\u05d3\u05e8\u05d8\u05d9\u05d9\u05dd \u05e9\u05dc \u05e7\u05d3\u05d7\u05d9\u05dd, \u05d4\u05d1\u05e8\u05d2\u05d5\u05ea \u05d5\u05d7\u05e8\u05d9\u05e6\u05d9\u05dd."],[241.0,"\u2026, \u05db\u05d3\u05d0\u05d9 \u05e9\u05d4\u05e7\u05d5\u05d8\u05e8 \u05d4\u05d2\u05d3\u05d5\u05dc \u05e9\u05dc \u05d4\u05d7\u05dc\u05e7 \u05d9\u05d4\u05d9\u05d4 \u05e7\u05e8\u05d5\u05d1 \u05dc\u05e7\u05d5\u05d8\u05e8 \u05d4\u05de\u05d5\u05d8."],[246.0,"\u05d5\u05e7\u05d3\u05d7\u05d9\u05dd \u05e8\u05d5\u05d7\u05d1\u05d9\u05d9\u05dd \u05e9\u05e0\u05e4\u05d2\u05e9\u05d9\u05dd \u05d1\u05ea\u05d5\u05da \u05d4\u05d7\u05dc\u05e7 \u05de\u05e9\u05d0\u05d9\u05e8\u05d9\u05dd \u05d2\u05e8\u05d3, \u05e9\u05e6\u05e8\u05d9\u05da \u05dc\u05ea\u05db\u05e0\u05df \u05d0\u05d9\u05da \u05dc\u05d4\u05e1\u05d9\u05e8."],[253.0,"\u05d2\u05dd \u05d1\u05de\u05db\u05d5\u05e0\u05d5\u05ea \u05d4\u05d0\u05dc\u05d4 \u05d9\u05e9 \u05d1\u05e2\u05d9\u05d5\u05ea \u05d0\u05d5\u05e4\u05d9\u05d9\u05e0\u05d9\u05d5\u05ea."],[256.0,"\u05d1\u05d7\u05d5\u05de\u05e8\u05d9\u05dd \u05e8\u05db\u05d9\u05dd. \u05dc\u05db\u05df \u05e6\u05e8\u05d9\u05da \u05e9\u05d1\u05d9\u05e8\u05ea \u05e9\u05d1\u05d1 \u05d8\u05d5\u05d1\u05d4, \u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05e7\u05d9\u05e8\u05d5\u05e8 \u05d1\u05dc\u05d7\u05e5 \u05d2\u05d1\u05d5\u05d4."],[266.0,"\u05e8\u05e2\u05d9\u05d3\u05d5\u05ea \u05d1\u05db\u05e8\u05e1\u05d5\u05dd \u05e2\u05dd live tools \u05d7\u05dc\u05e2\u05d5\u05d9\u05dd."],[270.0,"\u2026: \u05ea\u05d5\u05ea\u05d1 \u05e9\u05d7\u05d5\u05e7, \u05d0\u05d5 \u05de\u05d5\u05d8 \u05dc\u05d0 \u05de\u05d3\u05d5\u05d9\u05e7, \u05e9\u05d2\u05d5\u05e8\u05de\u05d9\u05dd \u05dc\u05e9\u05d2\u05d9\u05d0\u05d5\u05ea \u05d1\u05e7\u05d5\u05d8\u05e8."],[276.0,"\u05d5\u05e9\u05d9\u05e0\u05d5\u05d9\u05d9 \u05de\u05d9\u05d3\u05d5\u05ea \u05d1\u05e8\u05d9\u05e6\u05d4 \u05d0\u05e8\u05d5\u05db\u05d4, \u05d1\u05d2\u05dc\u05dc \u05d7\u05d5\u05dd."],[280.0,"\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8 \u05e2\u05d1\u05d5\u05d3\u05d4 \u05d1\u05de\u05db\u05d5\u05e0\u05d5\u05ea \u05d4\u05d0\u05dc\u05d4?"],[282.0,"\u05de\u05d7\u05d9\u05e8 \u05d4\u05de\u05db\u05d5\u05e0\u05d4 \u05d5\u05d4\u05ea\u05e2\u05e8\u05d9\u05e3 \u05dc\u05e9\u05e2\u05d4."],[285.0,"\u05ea\u05db\u05e0\u05d5\u05ea \u05d5\u05d6\u05de\u05df \u05d4\u05db\u05e0\u05d4, \u05d1\u05de\u05d9\u05d5\u05d7\u05d3 \u05d1-55\u05d5\u05d0\\5, \u05e9\u05d1\u05d4 \u05d9\u05e9 \u05d4\u05e8\u05d1\u05d4 \u05db\u05dc\u05d9\u05dd \u05dc\u05db\u05d5\u05d5\u05df."],[290.0,"\u05d5\u05dc\u05db\u05df, \u05d1\u05db\u05de\u05d5\u05d9\u05d5\u05ea \u05e7\u05d8\u05e0\u05d5\u05ea, \u05d4\u05d4\u05db\u05e0\u05d4 \u05d9\u05db\u05d5\u05dc\u05d4 \u05dc\u05e2\u05dc\u05d5\u05ea \u05d9\u05d5\u05ea\u05e8 \u05de\u05d4\u05e2\u05d9\u05d1\u05d5\u05d3."],[295.0,"\u05de\u05e6\u05d3 \u05e9\u05e0\u05d9, \u05d6\u05de\u05df \u05d4\u05de\u05d7\u05d6\u05d5\u05e8 \u05e7\u05e6\u05e8, \u05d0\u05d9\u05df \u05e4\u05e2\u05d5\u05dc\u05d5\u05ea \u05de\u05e9\u05e0\u05d9\u05d5\u05ea, \u05d5\u05d1\u05db\u05de\u05d5\u05d9\u05d5\u05ea \u05d2\u05d3\u05d5\u05dc\u05d5\u05ea \u05d4\u05de\u05d7\u05d9\u05e8 \u05dc\u05d7\u05dc\u05e7 \u05e0\u05de\u05d5\u05da \u05de\u05d0\u05d5\u05d3."],[303.0,"\u05de\u05d7\u05e8\u05d8\u05d4 \u05de\u05db\u05e8\u05e1\u05de\u05ea \u05de\u05d9\u05d9\u05e6\u05e8\u05ea \u05d7\u05dc\u05e7 \u05e1\u05d9\u05d1\u05d5\u05d1\u05d9 \u05de\u05d5\u05e8\u05db\u05d1, \u05d2\u05de\u05d5\u05e8 \u05dc\u05d2\u05de\u05e8\u05d9, \u05d1\u05ea\u05e4\u05d9\u05e1\u05d4 \u05d0\u05d7\u05ea."],[310.0,"Swiss type \u05de\u05d9\u05d9\u05e6\u05e8\u05ea \u05d7\u05dc\u05e7\u05d9\u05dd \u05e7\u05d8\u05e0\u05d9\u05dd, \u05d0\u05e8\u05d5\u05db\u05d9\u05dd \u05d5\u05d3\u05e7\u05d9\u05dd, \u05d1\u05d3\u05d9\u05d5\u05e7 \u05e9\u05dc \u05de\u05d9\u05e7\u05e8\u05d5\u05e0\u05d9\u05dd \u05d5\u05d1\u05db\u05de\u05d5\u05d9\u05d5\u05ea \u05d2\u05d3\u05d5\u05dc\u05d5\u05ea."],[317.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0: \u05d4\u05d5\u05e0\u05d9\u05e0\u05d2 \u05d5\u05dc\u05d0\u05e4\u05d9\u05e0\u05d2."]]};
window.MH_TR["\u05e4\u05e8\u05e723_\u05d4\u05d5\u05e0\u05d9\u05e0\u05d2_\u05d5\u05dc\u05d0\u05e4\u05d9\u05e0\u05d2"]={"t":"\u05d4\u05d5\u05e0\u05d9\u05e0\u05d2 \u05d5\u05dc\u05d0\u05e4\u05d9\u05e0\u05d2","l":[[1.0,"\u05e6\u05d9\u05dc\u05d9\u05e0\u05d3\u05e8 \u05d4\u05d9\u05d3\u05e8\u05d0\u05d5\u05dc\u05d9, \u05e6\u05d9\u05dc\u05d9\u05e0\u05d3\u05e8 \u05e9\u05dc \u05de\u05e0\u05d5\u05e2, \u05d0\u05d1\u05df \u05de\u05d3\u05d9\u05d3\u05d4, \u05d5\u05de\u05e9\u05d8\u05d7 \u05d0\u05d8\u05d9\u05de\u05d4 \u05e9\u05dc \u05e9\u05e1\u05ea\u05d5\u05dd."],[8.0,"\u05d1\u05db\u05dc \u05d0\u05dc\u05d4 \u05e6\u05e8\u05d9\u05da \u05de\u05e9\u05d8\u05d7 \u05de\u05d3\u05d5\u05d9\u05e7 \u05d5\u05d7\u05dc\u05e7 \u05d9\u05d5\u05ea\u05e8 \u05de\u05de\u05d4 \u05e9\u05d4\u05e9\u05d7\u05d6\u05d4 \u05e8\u05d2\u05d9\u05dc\u05d4 \u05e0\u05d5\u05ea\u05e0\u05ea."],[13.0,"\u05db\u05d0\u05df \u05e0\u05db\u05e0\u05e1\u05d9\u05dd \u05e9\u05e0\u05d9 \u05ea\u05d4\u05dc\u05d9\u05db\u05d9 \u05d2\u05d9\u05de\u05d5\u05e8 \u05e2\u05d3\u05d9\u05e0\u05d9\u05dd: \u05d4\u05d5\u05e0\u05d9\u05e0\u05d2 \u05d5\u05dc\u05d0\u05e4\u05d9\u05e0\u05d2."],[19.0,"\u05d4\u05d5\u05e0\u05d9\u05e0\u05d2 \u05de\u05e9\u05de\u05e9 \u05d1\u05e2\u05d9\u05e7\u05e8 \u05dc\u05d2\u05d9\u05de\u05d5\u05e8 \u05e9\u05dc \u05e7\u05d3\u05d7\u05d9\u05dd."],[22.0,"\u05e8\u05d0\u05e9 \u05d4\u05d4\u05d5\u05e0\u05d9\u05e0\u05d2 \u05e0\u05d5\u05e9\u05d0 \u05db\u05de\u05d4 \u05d0\u05d1\u05e0\u05d9\u05dd \u05e9\u05d5\u05d7\u05e7\u05d5\u05ea, \u05e9\u05e0\u05e4\u05ea\u05d7\u05d5\u05ea \u05d4\u05d7\u05d5\u05e6\u05d4 \u05d5\u05dc\u05d5\u05d7\u05e6\u05d5\u05ea \u05e2\u05dc \u05d3\u05d5\u05e4\u05df \u05d4\u05e7\u05d3\u05d7."],[28.0,"\u05d4\u05e8\u05d0\u05e9 \u05de\u05e1\u05ea\u05d5\u05d1\u05d1 \u05d5\u05d1\u05d0\u05d5\u05ea\u05d5 \u05d6\u05de\u05df \u05e0\u05e2 \u05dc\u05de\u05e2\u05dc\u05d4 \u05d5\u05dc\u05de\u05d8\u05d4."],[32.0,"\u05d4\u05e9\u05d9\u05dc\u05d5\u05d1 \u05d9\u05d5\u05e6\u05e8 \u05e2\u05dc \u05d4\u05d3\u05d5\u05e4\u05df \u05d3\u05d5\u05d2\u05de\u05d4 \u05e9\u05dc \u05e7\u05d5\u05d5\u05d9\u05dd \u05de\u05d5\u05e6\u05dc\u05d1\u05d9\u05dd, crosshatch."],[37.0,"\u05d1\u05e6\u05d9\u05dc\u05d9\u05e0\u05d3\u05e8 \u05e9\u05dc \u05de\u05e0\u05d5\u05e2, \u05d4\u05e7\u05d5\u05d5\u05d9\u05dd \u05d4\u05d0\u05dc\u05d4 \u05de\u05d7\u05d6\u05d9\u05e7\u05d9\u05dd \u05e9\u05de\u05df, \u05d5\u05e2\u05d5\u05d6\u05e8\u05d9\u05dd \u05dc\u05d1\u05d5\u05db\u05e0\u05d4 \u05dc\u05e0\u05d5\u05e2 \u05d1\u05d7\u05d5\u05e4\u05e9\u05d9\u05d5\u05ea."],[43.0,"\u05d4\u05d5\u05e0\u05d9\u05e0\u05d2 \u05de\u05d5\u05e8\u05d9\u05d3 \u05de\u05e2\u05d8 \u05de\u05d0\u05d5\u05d3 \u05d7\u05d5\u05de\u05e8, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05db\u05de\u05d4 \u05de\u05d0\u05d9\u05d5\u05ea \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8, \u05d5\u05d1\u05d7\u05d5\u05dd \u05e0\u05de\u05d5\u05da."],[50.0,"\u05d4\u05d5\u05e0\u05d9\u05e0\u05d2 \u05de\u05ea\u05e7\u05df \u05d0\u05ea \u05d4\u05d2\u05d0\u05d5\u05de\u05d8\u05e8\u05d9\u05d4 \u05e9\u05dc \u05d4\u05e7\u05d3\u05d7: \u05e2\u05d2\u05d9\u05dc\u05d5\u05ea, \u05d2\u05dc\u05d9\u05dc\u05d9\u05d5\u05ea \u05d5\u05d9\u05e9\u05e8\u05d5\u05ea."],[55.0,"\u05d4\u05d5\u05d0 \u05e0\u05d5\u05ea\u05df \u05e7\u05d5\u05d8\u05e8 \u05de\u05d3\u05d5\u05d9\u05e7 \u05de\u05d0\u05d5\u05d3, \u05d5\u05e4\u05e0\u05d9 \u05e9\u05d8\u05d7 \u05d7\u05dc\u05e7\u05d9\u05dd, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc Ra \u05e9\u05dc 0.1 \u05e2\u05d3 0.4 \u05de\u05d9\u05e7\u05e8\u05d5\u05df."],[65.0,"\u05d0\u05d1\u05dc, \u05db\u05de\u05d5 \u05e8\u05d9\u05de\u05e8, \u05d4\u05d5\u05d0 \u05e2\u05d5\u05e7\u05d1 \u05d0\u05d7\u05e8\u05d9 \u05d4\u05e6\u05d9\u05e8 \u05e9\u05dc \u05d4\u05e7\u05d3\u05d7, \u05d5\u05dc\u05d0 \u05de\u05ea\u05e7\u05df \u05d0\u05ea \u05d4\u05de\u05d9\u05e7\u05d5\u05dd \u05e9\u05dc\u05d5."],[70.0,"\u05d9\u05e9 \u05d2\u05dd honing \u2026: \u05e9\u05dc\u05d1 \u05e9\u05e0\u05d9 \u05e2\u05d3\u05d9\u05df, \u05e9\u05de\u05e9\u05d8\u05d9\u05d7 \u05d0\u05ea \u05d4\u05e4\u05e1\u05d2\u05d5\u05ea \u05d5\u05de\u05e9\u05d0\u05d9\u05e8 \u05d0\u05ea \u05d4\u05e2\u05de\u05e7\u05d9\u05dd \u05dc\u05e9\u05de\u05df."],[78.0,"\u05d5\u05d1\u05de\u05db\u05d5\u05e0\u05d5\u05ea \u05de\u05d5\u05d3\u05e8\u05e0\u05d9\u05d5\u05ea, \u05de\u05d5\u05d3\u05d3\u05d9\u05dd \u05d0\u05ea \u05d4\u05e7\u05d5\u05d8\u05e8 \u05ea\u05d5\u05da \u05db\u05d3\u05d9 \u05d4\u05e2\u05d1\u05d5\u05d3\u05d4, \u05d5\u05e2\u05d5\u05e6\u05e8\u05d9\u05dd \u05d1\u05d3\u05d9\u05d5\u05e7 \u05d1\u05de\u05d9\u05d3\u05d4."],[84.0,"\u05e9\u05e6\u05e8\u05d9\u05db\u05d9\u05dd \u05dc\u05d4\u05d9\u05d5\u05ea \u05de\u05d9\u05e9\u05d5\u05e8\u05d9\u05d9\u05dd \u05d5\u05de\u05e7\u05d1\u05d9\u05dc\u05d9\u05dd \u05d1\u05e8\u05de\u05d4 \u05d4\u05d2\u05d1\u05d5\u05d4\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8."],[92.0,"\u05d1\u05d9\u05df \u05d4\u05d7\u05dc\u05e7 \u05dc\u05d1\u05d9\u05df \u05e6\u05dc\u05d7\u05ea \u05dc\u05d0\u05e4\u05d9\u05e0\u05d2, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05de\u05d1\u05e8\u05d6\u05dc \u05d9\u05e6\u05d9\u05e7\u05d4, \u05d9\u05e9 \u05ea\u05e8\u05d7\u05d9\u05e3 \u05e9\u05dc \u05d2\u05e8\u05d2\u05e8\u05d9\u05dd \u05e9\u05d5\u05d7\u05e7\u05d9\u05dd \u05d1\u05e0\u05d5\u05d6\u05dc, \u05e5\u05d6\u05d8\u05d55."],[100.0,"\u05d4\u05d7\u05dc\u05e7 \u05e0\u05e2 \u05e2\u05dc \u05d4\u05e6\u05dc\u05d7\u05ea \u05d1\u05de\u05e1\u05dc\u05d5\u05dc \u05e9\u05de\u05e9\u05ea\u05e0\u05d4 \u05db\u05dc \u05d4\u05d6\u05de\u05df, \u05db\u05da \u05e9\u05db\u05dc \u05e0\u05e7\u05d5\u05d3\u05d4 \u05e0\u05e9\u05d7\u05e7\u05ea \u05d1\u05d0\u05d5\u05e4\u05df \u05d0\u05d7\u05d9\u05d3."],[107.0,"\u05d4\u05d2\u05e8\u05d2\u05e8\u05d9\u05dd \u05de\u05ea\u05d2\u05dc\u05d2\u05dc\u05d9\u05dd \u05d5\u05de\u05d5\u05e8\u05d9\u05d3\u05d9\u05dd \u05d7\u05d5\u05de\u05e8 \u05d1\u05e8\u05de\u05d4 \u05e9\u05dc \u05de\u05d9\u05e7\u05e8\u05d5\u05e0\u05d9\u05dd."],[111.0,"\u05d4\u05ea\u05d5\u05e6\u05d0\u05d4: \u05de\u05d9\u05e9\u05d5\u05e8\u05d9\u05d5\u05ea \u05e9\u05e0\u05de\u05d3\u05d3\u05ea \u05d1\u05e9\u05d1\u05e8\u05d9\u05e8\u05d9 \u05de\u05d9\u05e7\u05e8\u05d5\u05df, \u05d5\u05e4\u05e0\u05d9 \u05e9\u05d8\u05d7 \u05d7\u05dc\u05e7\u05d9\u05dd \u05de\u05d0\u05d5\u05d3."],[118.0,"\u05d0\u05ea \u05d4\u05de\u05d9\u05e9\u05d5\u05e8\u05d9\u05d5\u05ea \u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05d1\u05de\u05e9\u05d8\u05d7 \u05d6\u05db\u05d5\u05db\u05d9\u05ea \u05d0\u05d5\u05e4\u05d8\u05d9, optical \u05d6, \u05e2\u05d5\u05de\u05e8\u05d0\u05d4 \u05e4\u05e1\u05d9 \u05d0\u05d5\u05e8 \u05e2\u05dc \u05e4\u05e0\u05d9 \u05d4\u05d7\u05dc\u05e7."],[124.0,"\u05d1\u05dc\u05d0\u05e4\u05d9\u05e0\u05d2 \u05d3\u05d5 \u05e6\u05d3\u05d3\u05d9, \u05e9\u05e0\u05d9 \u05d4\u05e6\u05d3\u05d3\u05d9\u05dd \u05e9\u05dc \u05d4\u05d7\u05dc\u05e7 \u05de\u05e2\u05d5\u05d1\u05d3\u05d9\u05dd \u05d9\u05d7\u05d3, \u05d5\u05de\u05e7\u05d1\u05dc\u05d9\u05dd \u05de\u05e7\u05d1\u05d9\u05dc\u05d9\u05d5\u05ea \u05de\u05e6\u05d5\u05d9\u05e0\u05ea."],[132.0,"\u05d7\u05e9\u05d5\u05d1 \u05dc\u05d4\u05d1\u05d3\u05d9\u05dc \u05d1\u05d9\u05df \u05dc\u05d0\u05e4\u05d9\u05e0\u05d2 \u05dc\u05dc\u05d9\u05d8\u05d5\u05e9."],[135.0,"\u05dc\u05d9\u05d8\u05d5\u05e9 \u05de\u05e9\u05e4\u05e8 \u05d0\u05ea \u05d4\u05d1\u05e8\u05e7 \u05d5\u05d0\u05ea \u05d4\u05d7\u05dc\u05e7\u05d5\u05ea, \u05d0\u05d1\u05dc \u05dc\u05d0 \u05de\u05ea\u05e7\u05df \u05d0\u05ea \u05d4\u05e6\u05d5\u05e8\u05d4."],[140.0,"\u05dc\u05d0\u05e4\u05d9\u05e0\u05d2 \u05de\u05e9\u05e4\u05e8 \u05d0\u05ea \u05d4\u05e6\u05d5\u05e8\u05d4 \u05e2\u05e6\u05de\u05d4: \u05de\u05d9\u05e9\u05d5\u05e8\u05d9\u05d5\u05ea, \u05de\u05e7\u05d1\u05d9\u05dc\u05d9\u05d5\u05ea \u05d5\u05de\u05d9\u05d3\u05d4."],[146.0,"\u05d4\u05d5\u05e0\u05d9\u05e0\u05e2 \u05e6\u05d9\u05dc\u05d9\u05e0\u05d3\u05e8\u05d9\u05dd \u05d4\u05d9\u05d3\u05e8\u05d0\u05d5\u05dc\u05d9\u05d9\u05dd, \u05e6\u05d9\u05dc\u05d9\u05e0\u05d3\u05e8\u05d9\u05dd \u05e9\u05dc \u05de\u05e0\u05d5\u05e2\u05d9\u05dd, \u05e7\u05d3\u05d7\u05d9\u05dd \u05d1\u05d2\u05dc\u05d2\u05dc\u05d9 \u05e9\u05d9\u05e0\u05d9\u05d9\u05dd, \u05d5\u05d7\u05dc\u05e7\u05d9 \u05de\u05d6\u05e8\u05e7\u05d9\u05dd."],[154.0,"\u05dc\u05d0\u05e4\u05d9\u05e0\u05d2: \u05de\u05e9\u05d8\u05d7\u05d9 \u05d0\u05d8\u05d9\u05de\u05d4 \u05e9\u05dc \u05d0\u05d8\u05de\u05d9\u05dd \u05de\u05db\u05e0\u05d9\u05d9\u05dd, \u05de\u05d5\u05e9\u05d1\u05d9 \u05e9\u05e1\u05ea\u05d5\u05de\u05d9\u05dd, \u05d0\u05d1\u05e0\u05d9 \u05de\u05d3\u05d9\u05d3\u05d4, \u05d5\u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05d0\u05d5\u05e4\u05d8\u05d9\u05d9\u05dd."],[162.0,"\u05de\u05e9\u05d0\u05d9\u05e8\u05d9\u05dd \u05ea\u05d5\u05e1\u05e4\u05ea \u05e7\u05d8\u05e0\u05d4, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05db\u05de\u05d4 \u05de\u05d0\u05d9\u05d5\u05ea \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8."],[166.0,"\u05d4\u05ea\u05d4\u05dc\u05d9\u05da \u05d4\u05e7\u05d5\u05d3\u05dd \u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05d9\u05d5\u05ea \u05d8\u05d5\u05d1: \u05d4\u05d5\u05e0\u05d9\u05e0\u05d2 \u05d5\u05dc\u05d0\u05e4\u05d9\u05e0\u05d2 \u05de\u05ea\u05e7\u05e0\u05d9\u05dd \u05de\u05e2\u05d8, \u05d5\u05dc\u05d0 \u05d9\u05db\u05d5\u05dc\u05d9\u05dd \u05dc\u05d4\u05e6\u05d9\u05dc \u05d7\u05dc\u05e7 \u05d2\u05e8\u05d5\u05e2."],[174.0,"\u05de\u05e6\u05d9\u05d9\u05e0\u05d9\u05dd \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d0\u05ea \u05d4\u05d7\u05e1\u05e4\u05dc\u05d5\u05e1 \u05d5\u05d0\u05ea \u05d4\u05d2\u05d0\u05d5\u05de\u05d8\u05e8\u05d9\u05d4 \u05d4\u05e0\u05d3\u05e8\u05e9\u05d9\u05dd, \u05d5\u05d1\u05d4\u05d5\u05e0\u05d9\u05e0\u05d2 \u05d2\u05dd \u05d0\u05ea \u05d6\u05d5\u05d5\u05d9\u05ea \u05d4\u05e7\u05d5\u05d5\u05d9\u05dd \u05d0\u05dd \u05d4\u05d9\u05d0 \u05d7\u05e9\u05d5\u05d1\u05d4."],[181.0,"\u05d5\u05e0\u05d9\u05e7\u05d5\u05d9 \u05d7\u05e9\u05d5\u05d1 \u05de\u05d0\u05d5\u05d3: \u05d2\u05e8\u05d2\u05e8\u05d9\u05dd \u05e9\u05e0\u05e9\u05d0\u05e8\u05d9\u05dd \u05e2\u05dc \u05d4\u05d7\u05dc\u05e7 \u05d9\u05db\u05d5\u05dc\u05d9\u05dd \u05dc\u05d4\u05e8\u05d5\u05e1 \u05d0\u05ea \u05d4\u05de\u05db\u05dc\u05d5\u05dc."],[187.0,"\u05d2\u05dd \u05db\u05d0\u05df \u05d9\u05e9 \u05d1\u05e2\u05d9\u05d5\u05ea \u05d0\u05d5\u05e4\u05d9\u05d9\u05e0\u05d9\u05d5\u05ea."],[189.0,"\u05e7\u05d3\u05d7 \u05e9\u05e0\u05e4\u05ea\u05d7 \u05d1\u05e7\u05e6\u05d5\u05d5\u05ea, \u05d7\u05d6\u05d8\u05e1\u05d7\u05d7 bell, \u05db\u05e9\u05d4\u05de\u05d4\u05dc\u05da \u05d9\u05d5\u05e6\u05d0 \u05d9\u05d5\u05ea\u05e8 \u05de\u05d3\u05d9 \u05de\u05d4\u05e7\u05d3\u05d7."],[195.0,"\u05e7\u05d3\u05d7 \u05e7\u05d5\u05e0\u05d9, \u05db\u05e9\u05d4\u05de\u05d4\u05dc\u05da \u05dc\u05d0 \u05de\u05d0\u05d5\u05d6\u05df."],[198.0,"\u05d2\u05e8\u05d2\u05e8\u05d9\u05dd \u05e9\u05e0\u05ea\u05e7\u05e2\u05d9\u05dd \u05d1\u05d7\u05d5\u05de\u05e8\u05e8\u05df."],[201.0,"\u05d1\u05dc\u05d0\u05e4\u05d9\u05e0\u05d2: \u05e7\u05e6\u05d5\u05d5\u05ea \u05de\u05e2\u05d5\u05d2\u05dc\u05d9\u05dd, \u05d5\u05e9\u05e8\u05d9\u05d8\u05d5\u05ea \u05de\u05d2\u05e8\u05d2\u05e8 \u05d2\u05d3\u05d5\u05dc \u05e9\u05e0\u05db\u05e0\u05e1 \u05dc\u05ea\u05e8\u05d7\u05d9\u05e3."],[207.0,"\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8 \u05d4\u05d5\u05e0\u05d9\u05e0\u05d2 \u05d5\u05dc\u05d0\u05e1\u05d9\u05e0\u05d2?"],[210.0,"\u05d4\u05ea\u05d4\u05dc\u05d9\u05db\u05d9\u05dd \u05d0\u05d9\u05d8\u05d9\u05d9\u05dd, \u05d5\u05de\u05d5\u05e8\u05d9\u05d3\u05d9\u05dd \u05de\u05e2\u05d8 \u05de\u05d0\u05d5\u05d3 \u05d1\u05db\u05dc \u05e4\u05e2\u05dd."],[214.0,"\u05de\u05d3\u05d9\u05d3\u05d4 \u05de\u05d3\u05d5\u05d9\u05e7\u05ea, \u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d1\u05d7\u05d3\u05e8 \u05de\u05de\u05d5\u05d6\u05d2."],[218.0,"\u05e0\u05d9\u05e7\u05d5\u05d9 \u05d9\u05e1\u05d5\u05d3\u05d9 \u05e9\u05dc \u05d4\u05d7\u05dc\u05e7 \u05d0\u05d7\u05e8\u05d9 \u05d4\u05e2\u05d1\u05d5\u05d3\u05d4."],[221.0,"\u05de\u05e6\u05d3 \u05e9\u05e0\u05d9, \u05dc\u05d0\u05e4\u05d9\u05e0\u05d2 \u05e9\u05dc \u05d4\u05e8\u05d1\u05d4 \u05d7\u05dc\u05e7\u05d9\u05dd \u05d9\u05d7\u05d3 \u05e2\u05dc \u05e6\u05dc\u05d7\u05ea \u05d0\u05d7\u05ea \u05de\u05d5\u05d6\u05d9\u05dc \u05de\u05d0\u05d5\u05d3."],[226.0,"\u05d5\u05dc\u05e2\u05ea\u05d9\u05dd \u05e7\u05e8\u05d5\u05d1\u05d5\u05ea, \u05d6\u05d5 \u05d4\u05d3\u05e8\u05da \u05d4\u05d9\u05d7\u05d9\u05d3\u05d4 \u05dc\u05d4\u05d2\u05d9\u05e2 \u05dc\u05d2\u05d0\u05d5\u05de\u05d8\u05e8\u05d9\u05d4 \u05d5\u05dc\u05d2\u05d9\u05de\u05d5\u05e8 \u05d4\u05e0\u05d3\u05e8\u05e9\u05d5\u05d9\u05dd."],[232.0,"\u05d4\u05d5\u05e0\u05d9\u05e0\u05d2 \u05de\u05d2\u05de\u05e8 \u05e7\u05d3\u05d7\u05d9\u05dd, \u05d5\u05e0\u05d5\u05ea\u05df \u05dc\u05d4\u05dd \u05d2\u05d0\u05d5\u05de\u05d8\u05e8\u05d9\u05d4 \u05de\u05d3\u05d5\u05d9\u05e7\u05ea \u05d5 \u05d5\u05d2\u05de\u05d4 \u05e9\u05de\u05d7\u05d6\u05d9\u05e7\u05d4 \u05e9\u05de\u05df."],[238.0,"\u05dc\u05d0\u05e4\u05d9\u05e0\u05d2 \u05de\u05d2\u05de\u05e8 \u05de\u05e9\u05d8\u05d7\u05d9\u05dd, \u05d5\u05e0\u05d5\u05ea\u05df \u05de\u05d9\u05e9\u05d5\u05e8\u05d9\u05d5\u05ea \u05d5\u05de\u05e7\u05d1\u05d9\u05dc\u05d9\u05d5\u05ea \u05d1\u05e8\u05de\u05d4 \u05e9\u05dc \u05e9\u05d1\u05e8\u05d9\u05e8\u05d9 \u05de\u05d9\u05e7\u05e8\u05d5\u05df."],[244.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0, \u05d4\u05e4\u05e8\u05e7 \u05d4\u05d0\u05d7\u05e8\u05d5\u05df \u05d1\u05e1\u05d3\u05e8\u05d4: \u05d9\u05d9\u05e6\u05d5\u05e8 \u05ea\u05d5\u05e1\u05e4\u05ea\u05d9."]]};
window.MH_TR["\u05e4\u05e8\u05e724_\u05d9\u05d9\u05e6\u05d5\u05e8_\u05ea\u05d5\u05e1\u05e4\u05ea\u05d9"]={"t":"\u05d9\u05d9\u05e6\u05d5\u05e8 \u05ea\u05d5\u05e1\u05e4\u05ea\u05d9","l":[[1.0,"\u05e2\u05d3 \u05e2\u05db\u05e9\u05d9\u05d5 \u05e8\u05d0\u05d9\u05e0\u05d5 \u05ea\u05d4\u05dc\u05d9\u05db\u05d9\u05dd \u05e9\u05de\u05d5\u05e8\u05d9\u05d3\u05d9\u05dd \u05d7\u05d5\u05de\u05e8, \u05de\u05e2\u05e6\u05d1\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5 \u05d0\u05d5 \u05d9\u05d5\u05e6\u05e7\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5."],[7.0,"\u05d1\u05d9\u05d9\u05e6\u05d5\u05e8 \u05ea\u05d5\u05e1\u05e4\u05ea\u05d9, \u05d1\u05d5\u05e0\u05d9\u05dd \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7 \u05e9\u05db\u05d1\u05d4 \u05d0\u05d7\u05e8\u05d9 \u05e9\u05db\u05d1\u05d4, \u05d5\u05de\u05d5\u05e1\u05d9\u05e4\u05d9\u05dd \u05d7\u05d5\u05de\u05e8 \u05e8\u05e7 \u05d0\u05d9\u05e4\u05d4 \u05e9\u05e6\u05e8\u05d9\u05df."],[14.0,"\u05ea\u05e2\u05dc\u05d5\u05ea \u05e4\u05e0\u05d9\u05de\u05d9\u05d5\u05ea \u05de\u05e4\u05d5\u05ea\u05dc\u05d5\u05ea, \u05de\u05d1\u05e0\u05d9 \u05e1\u05e8\u05d9\u05d2, \u05d5\u05d7\u05dc\u05e7\u05d9\u05dd \u05e9\u05dc\u05de\u05d9\u05dd \u05d1\u05de\u05e7\u05d5\u05dd \u05de\u05db\u05dc\u05d5\u05dc."],[23.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d6\u05d4 \u05e0\u05db\u05d9\u05e8 \u05d0\u05ea \u05d4\u05e9\u05d9\u05d8\u05d5\u05ea \u05d4\u05e2\u05d9\u05e7\u05e8\u05d9\u05d5\u05ea, \u05d0\u05ea \u05d4\u05e2\u05d9\u05d1\u05d5\u05d3 \u05e9\u05d0\u05d7\u05e8\u05d9 \u05d4\u05d4\u05d3\u05e4\u05e1\u05d4, \u05d5\u05d0\u05ea \u05de\u05d4 \u05e9\u05de\u05d9\u05d9\u05e7\u05e8 \u05d0\u05ea \u05d6\u05d4."],[31.0,"\u05de\u05ea\u05d7\u05d9\u05dc\u05d9\u05dd \u05de\u05de\u05d5\u05d3\u05dc \u05ea\u05dc\u05ea \u05de\u05de\u05d3\u05d9 \u05e9\u05dc \u05d4\u05d7\u05dc\u05e7."],[34.0,"\u05d4\u05ea\u05d5\u05db\u05e0\u05d4 \u05e4\u05d5\u05e8\u05e1\u05ea \u05d0\u05ea \u05d4\u05de\u05d5\u05d3\u05dc \u05dc\u05e9\u05db\u05d1\u05d5\u05ea \u05d3\u05e7\u05d5\u05ea, \u05d5\u05de\u05d7\u05e9\u05d1\u05ea \u05dc\u05db\u05dc \u05e9\u05db\u05d1\u05d4 \u05d0\u05ea \u05d4\u05e6\u05d5\u05e8\u05d4 \u05e9\u05dc\u05d4."],[40.0,"\u05d4\u05de\u05db\u05d5\u05e0\u05d4 \u05d1\u05d5\u05e0\u05d4 \u05e9\u05db\u05d1\u05d4 \u05d0\u05d7\u05ea, \u05de\u05d5\u05e8\u05d9\u05d3\u05d4 \u05d0\u05d5 \u05de\u05d6\u05d9\u05d6\u05d4 \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7, \u05d5\u05d1\u05d5\u05e0\u05d4 \u05d0\u05ea \u05d4\u05e9\u05db\u05d1\u05d4 \u05d4\u05d1\u05d0\u05d4 \u05e2\u05dc\u05d9\u05d4."],[47.0,"\u05d9\u05e9 \u05db\u05de\u05d4 \u05de\u05e9\u05e4\u05d7\u05d5\u05ea \u05e9\u05dc \u05e9\u05d9\u05d8\u05d5\u05ea, \u05d5\u05d1\u05de\u05ea\u05db\u05d5\u05ea \u05e9\u05dc\u05d5\u05e9 \u05e2\u05d9\u05e7\u05e8\u05d9\u05d5\u05ea: \u05d4\u05d9\u05ea\u05d5\u05da \u05d1\u05de\u05d9\u05d8\u05ea \u05d0\u05d1\u05e7\u05d4, \u05d4\u05e8\u05d1\u05e6\u05d4 \u05d9\u05e9\u05d9\u05e8\u05d4, \u05d5\u05d4\u05d3\u05d1\u05e7\u05ea \u05d0\u05d1\u05e7\u05d4."],[56.0,"\u05d6\u05d5 \u05d4\u05e9\u05d9\u05d8\u05d4 \u05d4\u05e0\u05e4\u05d5\u05e6\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05dc\u05d7\u05dc\u05e7\u05d9 \u05de\u05ea\u05db\u05ea \u05de\u05d3\u05d5\u05d9\u05e7\u05d9\u05dd."],[60.0,"\u05d6\u05e8\u05d5\u05e2 \u05e4\u05d5\u05e8\u05e9\u05ea \u05e9\u05db\u05d1\u05d4 \u05d3\u05e7\u05d4 \u05e9\u05dc \u05d0\u05d1\u05e7\u05ea \u05de\u05ea\u05db\u05ea, \u05d1\u05e2\u05d5\u05d1\u05d9 \u05e9\u05dc \u05db\u05de\u05d4 \u05e2\u05e9\u05e8\u05d5\u05ea \u05de\u05d9\u05e7\u05e8\u05d5\u05e0\u05d9\u05dd."],[66.0,"\u05e7\u05e8\u05df \u05dc\u05d9\u05d9\u05d6\u05e8 \u05de\u05ea\u05d9\u05db\u05d4 \u05d0\u05ea \u05d4\u05d0\u05d1\u05e7\u05d4 \u05e8\u05e7 \u05d1\u05e6\u05d5\u05e8\u05d4 \u05e9\u05dc \u05d4\u05e9\u05d5\u05db\u05d1\u05d4 \u05d4\u05e0\u05d5\u05db\u05d7\u05d9\u05ea."],[70.0,"\u05de\u05e9\u05d8\u05d7 \u05d4\u05d1\u05e0\u05d9\u05d9\u05d4 \u05d9\u05d5\u05e8\u05d3 \u05d1\u05e2\u05d5\u05d1\u05d9 \u05e9\u05dc \u05e9\u05db\u05d1\u05d4, \u05e0\u05e4\u05e8\u05e9\u05d5\u05ea \u05e9\u05db\u05d1\u05d4 \u05d7\u05d3\u05e9\u05d4, \u05d5\u05d7\u05d5\u05d6\u05e8 \u05d7\u05dc\u05d9\u05dc\u05d4."],[76.0,"\u05d4\u05db\u05d5\u05dc \u05e7\u05d5\u05e8\u05d4 \u05d1\u05d0\u05d5\u05d5\u05d9\u05e8\u05d4 \u05e9\u05dc \u05d2\u05d6 \u05d0\u05d9\u05e0\u05e8\u05d8\u05d9, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d0\u05e8\u05d2\u05d5\u05df, \u05db\u05d3\u05d9 \u05e9\u05d4\u05de\u05ea\u05db\u05ea \u05dc\u05d0 \u05ea\u05ea\u05d7\u05de\u05e6\u05df."],[82.0,"\u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05e9\u05d1\u05d5\u05dc\u05d8\u05d9\u05dd \u05d4\u05d7\u05d5\u05e6\u05d4 \u05d1\u05d6\u05d5\u05d5\u05d9\u05ea \u05d7\u05d3\u05d4 \u05de\u05d3\u05d9 \u05e6\u05e8\u05d9\u05db\u05d9\u05dd \u05ea\u05de\u05d9\u05db\u05d5\u05ea, supports"],[88.0,"\u05d4\u05ea\u05de\u05d9\u05db\u05d5\u05ea \u05d2\u05dd \u05de\u05d5\u05dc\u05d9\u05db\u05d5\u05ea \u05d7\u05d5\u05dd \u05d4\u05d7\u05d5\u05e6\u05d4, \u05d5\u05de\u05d7\u05d6\u05d9\u05e7\u05d5\u05ea \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7 \u05e9\u05dc\u05d0 \u05d9\u05ea\u05e2\u05e7\u05dd."],[92.0,"\u05d4\u05d7\u05dc\u05e7 \u05de\u05e8\u05d5\u05ea\u05da \u05dc\u05de\u05e9\u05d8\u05d7 \u05d4\u05d1\u05e0\u05d9\u05d9\u05d4, \u05d5\u05d1\u05e1\u05d5\u05e3 \u05de\u05e0\u05ea\u05e7\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5, \u05dc\u05e2\u05ea\u05d9\u05dd \u05e7\u05e8\u05d5\u05d1\u05d5\u05ea EDM-2 \u05d7\u05d5\u05d8."],[99.0,"\u05d9\u05e9 \u05d2\u05dd \u05d2\u05e8\u05e1\u05d4 \u05e2\u05dd \u05e7\u05e8\u05df \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05e0\u05d9\u05dd \u05d1\u05d5\u05d5\u05d0\u05e7\u05d5\u05dd, \u05e9\u05de\u05ea\u05d0\u05d9\u05de\u05d4 \u05d1\u05de\u05d9\u05d5\u05d7\u05d3 \u05dc\u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd."],[105.0,"\u05d1\u05d4\u05e8\u05d1\u05e6\u05d4 \u05d9\u05e9\u05d9\u05e8\u05d4, \u2026, \u05de\u05d6\u05d9\u05e0\u05d9\u05dd \u05d7\u05d5\u05d8 \u05d0\u05d5 \u05d0\u05d1\u05e7\u05d4 \u05d9\u05e9\u05e8 \u05dc\u05ea\u05d5\u05da \u05d1\u05e8\u05d9\u05db\u05ea \u05d4\u05ea\u05db\u05d4, \u05e9\u05e0\u05d5\u05e6\u05e8\u05ea \u05d1\u05dc\u05d9\u05d9\u05d6\u05e8 \u05d0\u05d5 \u05d1\u05e7\u05e9\u05d5\u05ea \u05d7\u05e9\u05de\u05dc\u05d9\u05ea."],[114.0,"\u05d4\u05e8\u05d0\u05e9 \u05e0\u05e2 \u05d5\u05d1\u05d5\u05e0\u05d4 \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7, \u05db\u05de\u05d5 \u05e8\u05d9\u05ea\u05d5\u05da \u05e9\u05db\u05d1\u05d4 \u05e2\u05dc \u05e9\u05db\u05d1\u05d4."],[119.0,"\u05d4\u05e9\u05d9\u05d8\u05d4 \u05de\u05d4\u05d9\u05e8\u05d4 \u05d5\u05de\u05ea\u05d0\u05d9\u05de\u05d4 \u05dc\u05d7\u05dc\u05e7\u05d9\u05dd \u05d2\u05d3\u05d5\u05dc\u05d9\u05dd, \u05d0\u05d1\u05dc \u05e4\u05d7\u05d5\u05ea \u05de\u05d3\u05d5\u05d9\u05e7\u05ea."],[124.0,"\u05dc\u05db\u05df \u05d1\u05d5\u05e0\u05d9\u05dd \u05e7\u05e8\u05d5\u05d1 \u05dc\u05e6\u05d5\u05e8\u05d4 \u05d4\u05e1\u05d5\u05e4\u05d9\u05ea, \u05d5\u05d0\u05d7\u05e8 \u05db\u05da \u05de\u05e2\u05d1\u05d3\u05d9\u05dd \u05d1\u05e2\u05d9\u05d1\u05d5\u05d3 \u05e9\u05d1\u05d1\u05d9."],[129.0,"\u05d4\u05d9\u05d0 \u05de\u05e9\u05de\u05e9\u05ea \u05d2\u05dd \u05dc\u05ea\u05d9\u05e7\u05d5\u05df \u05e9\u05dc \u05d7\u05dc\u05e7\u05d9\u05dd \u05d9\u05e7\u05e8\u05d9\u05dd, \u05db\u05de\u05d5 \u05dc\u05d4\u05d1\u05d9 \u05d8\u05d5\u05e8\u05d1\u05d9\u05e0\u05d4 \u05d5\u05ea\u05d1\u05e0\u05d9\u05d5\u05ea."],[135.0,"\u2026 , \u05e8\u05d0\u05e9\u05d5 \u05d4\u05d3\u05e4\u05e1\u05d4 \u05de\u05d8\u05e4\u05d8\u05e3 \u05d3\u05d1\u05e7 \u05e2\u05dc \u05e9\u05db\u05d1\u05ea \u05d0\u05d1\u05e7\u05d4, \u05d5\u05dc\u05d0 \u05de\u05ea\u05d9\u05da \u05d0\u05d5\u05ea\u05d4."],[141.0,"\u05d0\u05d7\u05e8 \u05dc\u05da \u05d4\u05d7\u05dc\u05e7 \u05e2\u05d5\u05d1\u05e8 \u05e1\u05d9\u05e0\u05d8\u05d5\u05e8 \u05d1\u05ea\u05e0\u05d5\u05e8, \u05d5\u05d4\u05d7\u05dc\u05e7\u05d9\u05e7\u05d9\u05dd \u05de\u05ea\u05d0\u05d7\u05d9\u05dd."],[146.0,"\u05d1\u05e1\u05d9\u05e0\u05d8\u05d5\u05e8 \u05d4\u05d7\u05dc\u05e7 \u05de\u05ea\u05db\u05d5\u05d5\u05e5, \u05d1\u05e1\u05d1\u05d9\u05d1\u05d5\u05ea 20 \u05d0\u05d7\u05d5\u05d6, \u05d5\u05e6\u05e8\u05d9\u05da \u05dc\u05e4\u05e6\u05d5\u05ea \u05e2\u05dc \u05d6\u05d4 \u05d1\u05ea\u05db\u05e0\u05d5\u05df."],[153.0,"\u05d4\u05e9\u05d9\u05d8\u05d4 \u05de\u05d4\u05d9\u05e8\u05d4 \u05d5\u05d6\u05d5\u05dc\u05d4 \u05d9\u05d5\u05ea\u05e8, \u05d5\u05de\u05ea\u05d0\u05d9\u05de\u05d4 \u05dc\u05e1\u05d3\u05e8\u05d5\u05ea \u05e9\u05dc \u05d7\u05dc\u05e7\u05d9\u05dd \u05e7\u05d8\u05e0\u05d9\u05dd."],[158.0,"\u05d2\u05dd \u05d1\u05e4\u05dc\u05e1\u05d8\u05d9\u05e7 \u05d9\u05e9 \u05db\u05de\u05d4 \u05e9\u05d9\u05d8\u05d5\u05ea."],[160.0,"\u05d5\u05d0\u05e1 \u05de\u05d6\u05e8\u05d9\u05de\u05d4 \u05d7\u05d5\u05d8 \u05e4\u05dc\u05e1\u05d8\u05d9\u05e7 \u05de\u05d5\u05ea\u05da, \u05d5\u05d4\u05d9\u05d0 \u05e0\u05e4\u05d5\u05e6\u05d4 \u05d1\u05db\u05dc \u05e1\u05d3\u05e0\u05d4."],[165.0,"SLA \u05de\u05e7\u05e9\u05d4 \u05e9\u05e8\u05e3 \u05e0\u05d5\u05d6\u05dc\u05d9 \u05d1\u05d0\u05d5\u05e8, \u05d5\u05e0\u05d5\u05ea\u05e0\u05ea \u05e4\u05e8\u05d8\u05d9\u05dd \u05e2\u05d3\u05d9\u05e0\u05d9\u05dd."],[170.0,"SLS-1 \u05de\u05ea\u05d9\u05db\u05d4 \u05d0\u05d1\u05e7\u05ea \u05e0\u05d9\u05d9\u05dc\u05d5\u05df, \u05d5\u05e0\u05d5\u05ea\u05e0\u05ea \u05d7\u05dc\u05e7\u05d9\u05dd \u05d7\u05d6\u05e7\u05d9\u05dd \u05d1\u05dc\u05d9 \u05ea\u05de\u05d9\u05db\u05d5\u05ea."],[175.0,"\u05d1\u05e1\u05d3\u05e0\u05d4, \u05d4\u05e9\u05d9\u05de\u05d5\u05e9 \u05d4\u05e0\u05e4\u05d5\u05e5 \u05d4\u05d5\u05d0 \u05d0\u05d1\u05d8\u05d9\u05e4\u05d5\u05e1\u05d9\u05dd, \u05d5\u05de\u05ea\u05e7\u05e0\u05d9\u05dd \u05d5\u05de\u05d3\u05d9\u05d3\u05d9\u05dd \u05dc\u05d9\u05d9\u05e6\u05d5\u05e8."],[181.0,"\u05d4\u05d7\u05dc\u05e7 \u05e9\u05d9\u05d5\u05e6\u05d0 \u05de\u05d4\u05de\u05db\u05d5\u05e0\u05d4 \u05e2\u05d5\u05d3 \u05dc\u05d0 \u05d2\u05de\u05d5\u05e8."],[184.0,"\u05e7\u05d5\u05d3\u05dd \u05e2\u05d5\u05e9\u05d9\u05dd \u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd \u05dc\u05e9\u05d7\u05e8\u05d5\u05e8 \u05de\u05d0\u05de\u05e6\u05d9\u05dd, \u05e2\u05d5\u05d3 \u05dc\u05e4\u05e0\u05d9 \u05e9\u05de\u05e0\u05ea\u05e7\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5 \u05de\u05d4\u05de\u05e9\u05d8\u05d7."],[189.0,"\u05d0\u05d7\u05e8 \u05db\u05da \u05de\u05e1\u05d9\u05e8\u05d9\u05dd \u05d0\u05ea \u05d4\u05ea\u05de\u05d9\u05db\u05d5\u05ea, \u05d9\u05d3\u05e0\u05d9\u05ea \u05d0\u05d5 \u05d1\u05e2\u05d9\u05d1\u05d5\u05d3."],[193.0,"\u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05e7\u05e8\u05d9\u05d8\u05d9\u05d9\u05dd \u05e2\u05d5\u05e9\u05d9\u05dd \u05e1\u05d5\u05d5: \u05dc\u05d7\u05e5 \u05d2\u05d1\u05d5\u05d4 \u05d5\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d2\u05d1\u05d5\u05d4\u05d4, \u05e9\u05e1\u05d5\u05d2\u05e8\u05d9\u05dd \u05e0\u05e7\u05d1\u05d5\u05d1\u05d9\u05d5\u05ea \u05e4\u05e0\u05d9\u05de\u05d9\u05d5\u05ea."],[201.0,"\u05de\u05d9\u05e7\u05e8\u05d5\u05df, \u05d5\u05dc\u05db\u05df \u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05e4\u05d5\u05e0\u05e7\u05e6\u05d9\u05d5\u05e0\u05dc\u05d9\u05d9\u05dd \u05de\u05e2\u05d1\u05d3\u05d9\u05dd \u05d1\u05e2\u05d9\u05d1\u05d5\u05d3 \u05e9\u05d1\u05d1\u05d9."],[211.0,"\u05d5\u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7, \u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d1\u05e1\u05e8\u05d9\u05e7\u05ea \u05d6\u05e1, \u05e9\u05e8\u05d5\u05d0\u05d4 \u05d2\u05dd \u05e0\u05e7\u05d1\u05d5\u05d1\u05d9\u05d5\u05ea \u05d5\u05ea\u05e2\u05dc\u05d5\u05ea \u05e4\u05e0\u05d9\u05de\u05d9\u05d5\u05ea."],[218.0,"\u05d7\u05d5\u05e4\u05e9 \u05e6\u05d5\u05e8\u05d4 \u05db\u05de\u05e2\u05d8 \u05de\u05dc\u05d0: \u05ea\u05e2\u05dc\u05d5\u05ea \u05e4\u05e0\u05d9\u05de\u05d9\u05d5\u05ea, \u05e1\u05e8\u05d9\u05d2\u05d9\u05dd, \u05d5\u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05e9\u05d0\u05d9 \u05d0\u05e4\u05e9\u05e8 \u05dc\u05e2\u05d1\u05d3."],[224.0,"\u05d0\u05d5\u05e4\u05d8\u05d9\u05de\u05d9\u05d6\u05e6\u05d9\u05d4 \u05d8\u05d5\u05e4\u05d5\u05dc\u05d5\u05d2\u05d9\u05ea: \u05d4\u05ea\u05d5\u05db\u05e0\u05d4 \u05de\u05d5\u05e6\u05d9\u05d0\u05d4 \u05d7\u05d5\u05de\u05e8 \u05de\u05db\u05dc \u05de\u05e7\u05d5\u05dd \u05e9\u05dc\u05d0 \u05e0\u05d5\u05e9\u05d0 \u05e2\u05d5\u05de\u05e1, \u05d5\u05d4\u05d7\u05dc\u05e7 \u05e7\u05dc \u05d9\u05d5\u05ea\u05e8."],[232.0,"\u05d0\u05d9\u05d7\u05d5\u05d3 \u05d7\u05dc\u05e7\u05d9\u05dd: \u05de\u05db\u05dc\u05d5\u05dc \u05e9\u05dc \u05e2\u05e9\u05e8\u05d4 \u05d7\u05dc\u05e7\u05d9\u05dd \u05d9\u05db\u05d5\u05dc \u05dc\u05d4\u05e4\u05d5\u05da \u05dc\u05d7\u05dc\u05e7 \u05d0\u05d7\u05d3."],[237.0,"\u05d0\u05d9\u05df \u05db\u05dc\u05d9\u05dd \u05d5\u05d0\u05d9\u05df \u05ea\u05d1\u05e0\u05d9\u05d5\u05ea, \u05d5\u05dc\u05db\u05df \u05d0\u05e4\u05e9\u05e8 \u05dc\u05e9\u05e0\u05d5\u05ea \u05d5\u05dc\u05e0\u05e1\u05d5\u05ea \u05de\u05d4\u05e8."],[242.0,"\u05d5\u05d1\u05ea\u05d1\u05e0\u05d9\u05d5\u05ea \u05d4\u05d6\u05e8\u05e7\u05d4, \u05ea\u05e2\u05dc\u05d5\u05ea \u05e7\u05d9\u05e8\u05d5\u05e8 \u05e9\u05e2\u05d5\u05e7\u05d1\u05d5\u05ea \u05d0\u05d7\u05e8\u05d9 \u05e6\u05d5\u05e8\u05ea \u05d4\u05d7\u05dc\u05e7 \u05de\u05e7\u05e6\u05e8\u05d5\u05ea \u05de\u05d0\u05d5\u05d3 \u05d0\u05ea \u05d6\u05de\u05df \u05d4\u05de\u05d7\u05d6\u05d5\u05e8."],[250.0,"\u05d4\u05ea\u05d4\u05dc\u05d9\u05da \u05d0\u05d9\u05d8\u05d9, \u05d5\u05d2\u05d5\u05d3\u05dc \u05d4\u05d7\u05dc\u05e7 \u05de\u05d5\u05d2\u05d1\u05dc \u05d1\u05d2\u05d5\u05d3\u05dc \u05d4\u05de\u05db\u05d5\u05e0\u05d4."],[254.0,"\u05d4\u05de\u05d7\u05d9\u05e8 \u05dc\u05d7\u05dc\u05e7 \u05d2\u05d1\u05d5\u05d4, \u05d5\u05dc\u05d0 \u05d9\u05d5\u05e8\u05d3 \u05d4\u05e8\u05d1\u05d4 \u05d1\u05db\u05de\u05d5\u05d9\u05d5\u05ea."],[258.0,"\u05d4\u05ea\u05db\u05d5\u05e0\u05d5\u05ea \u05d9\u05db\u05d5\u05dc\u05d5\u05ea \u05dc\u05d4\u05d9\u05d5\u05ea \u05e9\u05d5\u05e0\u05d5\u05ea \u05d1\u05db\u05d9\u05d5\u05d5\u05e0\u05d9\u05dd \u05e9\u05d5\u05e0\u05d9\u05dd, \u05dc\u05e4\u05d9 \u05db\u05d9\u05d5\u05d5\u05df \u05d4\u05e9\u05db\u05d1\u05d5\u05ea."],[263.0,"\u05d9\u05e9 \u05e1\u05d9\u05db\u05d5\u05df \u05dc\u05e0\u05e7\u05d1\u05d5\u05d1\u05d9\u05d5\u05ea, \u05dc\u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05e4\u05e0\u05d9\u05de\u05d9\u05d9\u05dd \u05d5\u05dc\u05e2\u05d9\u05d5\u05d5\u05ea."],[267.0,"\u05d5\u05d1\u05ea\u05e2\u05d5\u05e4\u05d4 \u05d5\u05d1\u05e8\u05e4\u05d5\u05d0\u05d4, \u05d4\u05d0\u05d9\u05e9\u05d5\u05d5\u05e8 \u05e9\u05dc \u05d7\u05dc\u05e7 \u05de\u05d5\u05d3\u05e4\u05e1 \u05d3\u05d5\u05e8\u05e9\u05d5 \u05d4\u05e8\u05d1\u05d4 \u05d1\u05d3\u05d9\u05e7\u05d5\u05ea."],[273.0,"\u05d2\u05dd \u05dc\u05d9\u05d9\u05e6\u05d5\u05e8 \u05ea\u05d5\u05e1\u05e4\u05ea\u05d9 \u05d9\u05e9 \u05db\u05dc\u05dc\u05d9 \u05ea\u05db\u05e0\u05d5\u05df \u05de\u05e9\u05dc\u05d5."],[276.0,"\u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05d1\u05d6\u05d5\u05d5\u05d9\u05ea \u05e9\u05dc \u05d9\u05d5\u05ea\u05e8 \u05de\u05d1\u05e2\u05e8\u05da 45 \u05de\u05e2\u05dc\u05d5\u05ea \u05de\u05d4\u05d0\u05e0\u05da \u05e0\u05d1\u05e0\u05d9\u05dd \u05d1\u05dc\u05d9 \u05ea\u05de\u05d9\u05db\u05d5\u05ea."],[282.0,"\u05db\u05d3\u05d0\u05d9 \u05dc\u05d4\u05d9\u05de\u05e0\u05e2 \u05de\u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05e9\u05d8\u05d5\u05d7\u05d9\u05dd \u05d2\u05d3\u05d5\u05dc\u05d9\u05dd \u05e9\u05ea\u05dc\u05d5\u05d9\u05d9\u05dd \u05d1\u05d0\u05d5\u05d5\u05d9\u05e8."],[286.0,"\u05d1\u05d7\u05dc\u05dc\u05d9\u05dd \u05e4\u05e0\u05d9\u05de\u05d9\u05d9\u05dd \u05e6\u05e8\u05d9\u05da \u05e7\u05d3\u05d7\u05d9\u05dd \u05dc\u05d4\u05d5\u05e6\u05d0\u05ea \u05d4\u05d0\u05d1\u05e7\u05d4."],[290.0,"\u05e2\u05d3\u05d9\u05e3 \u05e2\u05d5\u05d1\u05d9 \u05d3\u05d5\u05e4\u05df \u05d0\u05d7\u05d9\u05d3, \u05db\u05d3\u05d9 \u05e9\u05d4\u05d7\u05d5\u05dd \u05d9\u05ea\u05e4\u05d6\u05e8 \u05d1\u05d0\u05d5\u05e4\u05df \u05e9\u05d5\u05d5\u05d4."],[294.0,"\u05db\u05d9\u05d5\u05d5\u05df \u05d4\u05d7\u05dc\u05e7 \u05d1\u05de\u05db\u05d5\u05e0\u05d4 \u05de\u05e9\u05e4\u05d9\u05e2 \u05e2\u05dc \u05d4\u05d6\u05de\u05df, \u05e2\u05dc \u05d4\u05ea\u05de\u05d9\u05db\u05d5\u05ea, \u05e2\u05dc \u05e4\u05e0\u05d9\u05d9\u05d4\u05e9\u05d8\u05d7\u05d5\u05e2\u05dc \u05d4\u05d7\u05d5\u05d6\u05e7."],[301.0,"\u05d5\u05d1\u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05e4\u05d5\u05e0\u05e7\u05e6\u05d9\u05d5\u05e0\u05dc\u05d9\u05d9\u05dd \u05de\u05e9\u05d0\u05d9\u05e8\u05d9\u05dd \u05ea\u05d5\u05e1\u05e4\u05ea \u05dc\u05e2\u05d9\u05d1\u05d5\u05d3 \u05e9\u05d1\u05d1\u05d9."],[305.0,"\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8 \u05d9\u05d9\u05e6\u05d5\u05e8 \u05ea\u05d5\u05e1\u05e4\u05ea\u05d9?"],[308.0,"\u05d6\u05de\u05df \u05d4\u05de\u05db\u05d5\u05e0\u05d4, \u05e9\u05e0\u05e7\u05d1\u05e2 \u05d1\u05e2\u05d9\u05e7\u05e8 \u05dc\u05e4\u05d9 \u05d4\u05d2\u05d5\u05d1\u05d4 \u05e9\u05dc \u05d4\u05d1\u05e0\u05d9\u05d9\u05d4, \u05db\u05dc\u05d5\u05de\u05e8 \u05de\u05e1\u05e4\u05e8 \u05d4\u05e9\u05db\u05d1\u05d5\u05ea."],[314.0,"\u05d4\u05d0\u05d1\u05e7\u05d4, \u05d5\u05d4\u05d2\u05d6 \u05d4\u05d0\u05d9\u05e0\u05e8\u05d8\u05d9."],[316.0,"\u05d4\u05e2\u05d9\u05d1\u05d5\u05d3 \u05e9\u05d0\u05d7\u05e8\u05d9 \u05d4\u05d4\u05d3\u05e4\u05e1\u05d4, \u05e9\u05d9\u05db\u05d5\u05dc \u05dc\u05d4\u05d2\u05d9\u05e2 \u05dc\u05d7\u05e6\u05d9 \u05de\u05d4\u05de\u05d7\u05d9\u05e8."],[320.0,"\u05d5\u05d1\u05d3\u05d9\u05e7\u05d5\u05ea, \u05d1\u05de\u05d9\u05d5\u05d7\u05d3 \u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05e7\u05e8\u05d9\u05d8\u05d9\u05d9\u05dd."],[323.0,"\u05de\u05e6\u05d3 \u05e9\u05e0\u05d9, \u05db\u05de\u05d4 \u05d7\u05dc\u05e7\u05d9\u05dd \u05d1\u05d0\u05d5\u05ea\u05d4 \u05d1\u05e0\u05d9\u05d9\u05d4 \u05d7\u05d5\u05dc\u05e7\u05d9\u05dd \u05d0\u05ea \u05d6\u05de\u05df \u05d4\u05de\u05db\u05d5\u05e0\u05d4."],[328.0,"\u05d5\u05d9\u05d9\u05e6\u05d5\u05e8 \u05ea\u05d5\u05e1\u05e4\u05ea\u05d9 \u05de\u05e9\u05ea\u05dc\u05dd \u05d1\u05e2\u05d9\u05e7\u05e8 \u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05de\u05d5\u05e8\u05db\u05d1\u05d9\u05dd, \u05d1\u05db\u05de\u05d5\u05d9\u05d5\u05ea \u05e7\u05d8\u05e0\u05d5\u05ea, \u05d0\u05d5 \u05db\u05e9\u05d0\u05d9\u05df \u05d3\u05e8\u05da \u05d0\u05d7\u05e8\u05ea \u05dc\u05d9\u05d9\u05e6\u05e8 \u05d0\u05ea \u05d4\u05e6\u05d5\u05e8\u05d4."],[336.0,"\u05d9\u05d9\u05e6\u05d5\u05e8 \u05ea\u05d5\u05e1\u05e4\u05ea\u05d9 \u05dc\u05d0 \u05de\u05d7\u05dc\u05d9\u05e3 \u05d0\u05ea \u05d4\u05ea\u05d4\u05dc\u05d9\u05db\u05d9\u05dd \u05e9\u05dc\u05de\u05d3\u05e0\u05d5, \u05d0\u05dc\u05d0 \u05de\u05e6\u05d8\u05e8\u05e3 \u05d0\u05dc\u05d9\u05d4\u05dd."],[341.0,"\u05d4\u05e9\u05d9\u05dc\u05d5\u05d1 \u05d4\u05e0\u05e4\u05d5\u05e5: \u05de\u05d3\u05e4\u05d9\u05e1\u05d9\u05dd \u05e7\u05e8\u05d5\u05d1 \u05dc\u05e6\u05d5\u05e8\u05d4 \u05d4\u05e1\u05d5\u05e4\u05d9\u05ea, \u05d5\u05de\u05d2\u05de\u05e8\u05d9\u05dd \u05d1\u05db\u05e8\u05e1\u05d5\u05dd 5 \u05e6\u05d9\u05e8\u05d9\u05dd, \u05d1\u05d7\u05e8\u05d9\u05d8\u05d4, \u05d1\u05d4\u05e9\u05d7\u05d6\u05d4 \u05d0\u05d5 EDM-2"],[352.0,"\u05d9\u05d9\u05e6\u05d5\u05e8 \u05ea\u05d5\u05e1\u05e4\u05ea\u05d9 \u05d1\u05d5\u05e0\u05d4 \u05d7\u05dc\u05e7 \u05e9\u05db\u05d1\u05d4 \u05d0\u05d7\u05e8\u05d9 \u05e9\u05db\u05d1\u05d4, \u05d5\u05e0\u05d5\u05ea\u05df \u05d7\u05d5\u05e4\u05e9 \u05e6\u05d5\u05e8\u05d4 \u05e9\u05d0\u05d9\u05df \u05dc\u05d0\u05e3 \u05ea\u05d4\u05dc\u05d9\u05da \u05d0\u05d7\u05e8."],[359.0,"\u05d4\u05d5\u05d0 \u05d0\u05d9\u05d8\u05d9 \u05d5\u05d9\u05e7\u05e8 \u05dc\u05d7\u05dc\u05e7, \u05d0\u05d1\u05dc \u05d1\u05d7\u05dc\u05e7 \u05d4\u05e0\u05db\u05d5\u05df \u05d4\u05d5\u05d0 \u05de\u05e9\u05e0\u05d4 \u05d0\u05ea \u05db\u05dc \u05d4\u05ea\u05de\u05d5\u05e0\u05d4."],[365.0,"\u05d1\u05d6\u05d4 \u05d4\u05d2\u05e2\u05e0\u05d5 \u05dc\u05e1\u05d5\u05e3 \u05d4\u05e1\u05d3\u05e8\u05d4: \u05de\u05d9\u05e6\u05d9\u05e7\u05d4 \u05d5\u05d7\u05d9\u05e9\u05d5\u05dc, \u05d3\u05e8\u05da \u05e2\u05d9\u05d1\u05d5\u05d3 \u05e9\u05d1\u05d1\u05d9 \u05d5\u05e2\u05d9\u05d1\u05d5\u05d3 \u05e4\u05d7, \u05d5\u05e2\u05d3 \u05d4\u05ea\u05d4\u05dc\u05d9\u05db\u05d9\u05dd \u05d4\u05de\u05ea\u05e7\u05d3\u05de\u05d9\u05dd."],[373.0,"\u05d1\u05db\u05dc \u05ea\u05d4\u05dc\u05d9\u05da \u05e8\u05d0\u05d9\u05e0\u05d5 \u05de\u05d4 \u05d4\u05d5\u05d0 \u05e0\u05d5\u05ea\u05df, \u05d0\u05d9\u05da \u05de\u05ea\u05db\u05e0\u05e0\u05d9\u05dd \u05dc\u05d5, \u05d5\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8 \u05d0\u05d5\u05ea\u05d5."],[379.0,"\u05d5\u05d4\u05d1\u05d7\u05d9\u05e8\u05d4 \u05d4\u05e0\u05db\u05d5\u05e0\u05d4 \u05d4\u05d9\u05d0 \u05ea\u05de\u05d9\u05d3 \u05d4\u05e9\u05d9\u05dc\u05d5\u05d1 \u05d1\u05d9\u05df \u05d4\u05e6\u05d5\u05e8\u05d4, \u05d4\u05d7\u05d5\u05de\u05e8, \u05d4\u05d3\u05d9\u05d5\u05e7, \u05d4\u05db\u05de\u05d5\u05ea \u05d5\u05d4\u05de\u05d7\u05d9\u05e8."]]};
